                </div>
            );
        }

        return (
            <div className="max-w-4xl animate-fade-in pb-20">
                {renderSectionHeader("Employee Settings", "Configure staff roles, access levels and security policies.")}
                <div className="grid grid-cols-1 gap-4">
                    <SettingCard 
                        icon={Users} 
                        title="Employee roles" 
                        description="Define functional categories like Manager or Server."
                        onClick={() => setSubSection('Roles')}
                    />
                    <SettingCard 
                        icon={ShieldCheck} 
                        title="Employee permissions" 
                        description="Granular control over what roles can see and do."
                        onClick={() => setSubSection('Permissions')}
                    />
                    <SettingCard 
                        icon={KeyRound} 
                        title="Device passcode" 
                        description="PIN requirements for logging into register devices."
                        onClick={() => setSubSection('Passcode')}
                    />
                </div>
            </div>
        );

      case 'BusinessInfo':
          return (
              <div className="max-w-4xl animate-fade-in pb-20">
                  {renderSectionHeader("About Your Business", "Legal business information, bank accounts, and locations.")}
                  <div className="space-y-6">
                      <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-2 gap-8">
