                              <div><label className="text-[10px] text-slate-400 uppercase font-bold">Merchant ID</label><p className="text-slate-900 font-mono text-sm">{biz.varConfig?.merchantId}</p></div>
                          </div>
                      </div>
                      <SettingCard icon={Zap} title="Rapid Deposit" description="Get your funds immediately for a 1.75% transaction fee." status="Active" />
                  </div>
              </div>
          );

      default:
        return <div className="p-12 text-center text-slate-400">Section under development</div>;
    }
  }

  const NavItem = ({ id, label, icon: Icon }: any) => (
    <button
      onClick={() => { setActiveSection(id); setSubSection(null); }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-all mb-1 group
        ${activeSection === id 
            ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' 
            : 'text-slate-600 hover:bg-slate-200/60'}`}
    >
        <div className={`${activeSection === id ? 'text-white' : 'text-slate-400 group-hover:text-slate-600'}`}>
            <Icon size={18}/>
        </div>
        <span className={`font-medium text-sm ${activeSection === id ? 'font-bold' : ''}`}>{label}</span>
        {activeSection === id && <ChevronRight size={14} className="ml-auto opacity-50" />}
    </button>
  );

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100vh-8rem)] bg-slate-50/50 rounded-2xl overflow-hidden border border-slate-200">
        <div className="w-full lg:w-72 bg-white border-r border-slate-200 p-4 flex flex-col shrink-0">
            <div className="p-4 mb-2">
                <h2 className="text-lg font-bold text-slate-900">Settings</h2>
                <p className="text-xs text-slate-500 font-medium">OmniCommand Enterprise</p>
            </div>
            <nav className="flex-1 space-y-6 overflow-y-auto px-2 pb-4">
                <div>
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 ml-4">Account</h3>
                    <NavItem id="Profile" label="User Profile" icon={User} />
                    <NavItem id="Employees" label="Employees" icon={Shield} />
                </div>
                <div>
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 ml-4">Business</h3>
                    <NavItem id="BusinessInfo" label="About your business" icon={Building} />
                    <NavItem id="Billing" label="Billing & Statements" icon={CreditCard} />
                </div>
                <div>
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 ml-4">Management</h3>
                    <NavItem id="Operations" label="Business operations" icon={SettingsIcon} />
                    <NavItem id="Transactions" label="Transactions" icon={ShoppingCart} />
                </div>
            </nav>
            <div className="mt-auto p-4 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-3">
                <div className="h-8 w-8 bg-indigo-100 rounded-lg flex items-center justify-center text-indigo-600"><Lock size={16} /></div>
                <div className="text-[10px] text-slate-500 font-medium leading-tight">
                    <p>Configuration changes are recorded in the <button className="text-indigo-600 font-bold hover:underline">Audit Log</button></p>
                </div>
            </div>
        </div>
        <div className="flex-1 overflow-y-auto bg-slate-50/30 p-8 lg:p-12 relative">
            {renderContent()}
        </div>
    </div>
  );
};

