                        <div className="overflow-auto flex-1">
                            <table className="w-full text-left border-collapse table-fixed">
                                <thead className="sticky top-0 z-30">
                                    <tr className="bg-slate-900 text-white text-[11px] font-bold uppercase tracking-wider">
                                        <th className="px-6 py-5 w-[300px] bg-slate-900">Feature Access</th>
                                        {MOCK_ROLES.map(role => (
                                            <th key={role.id} className="px-4 py-5 text-center w-[120px] border-l border-slate-800 bg-slate-900">{role.name}</th>
                                        ))}
                                    </tr>
                                </thead>
                                <tbody className="text-sm">
                                    {Object.entries(permissionsByCategory).map(([category, perms]) => (
                                        <React.Fragment key={category}>
                                            <tr className="bg-indigo-50/50 sticky top-[54px] z-20">
