                    <NavItem id="Employees" label="Employees" icon={Shield} />
                </div>
                <div>
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 ml-4">Business</h3>
                    <NavItem id="BusinessInfo" label="About your business" icon={Building} />
                    <NavItem id="Billing" label="Billing & Statements" icon={CreditCard} />
                </div>
                <div>
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 ml-4">Management</h3>
                    <NavItem id="Operations" label="Business operations" icon={SettingsIcon} />
                    <NavItem id="Transactions" label="Transactions" icon={ShoppingCart} />
                </div>
            </nav>
            <div className="mt-auto p-4 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-3">
                <div className="h-8 w-8 bg-indigo-100 rounded-lg flex items-center justify-center text-indigo-600"><Lock size={16} /></div>
                <div className="text-[10px] text-slate-500 font-medium leading-tight">
                    <p>Configuration changes are recorded in the <button className="text-indigo-600 font-bold hover:underline">Audit Log</button></p>
                </div>
            </div>
        </div>
        <div className="flex-1 overflow-y-auto bg-slate-50/30 p-8 lg:p-12 relative">
            {renderContent()}
        </div>
    </div>
  );
};

