    const [selectedPermission, setSelectedPermission] = useState<PermissionItem | null>(null);

    const renderHeader = (title: string, subtitle: string, breadcrumb?: string, onBcClick?: () => void) => (
        <div className="mb-8">
            {breadcrumb && (
                <button onClick={onBcClick || (() => setSubSection(null))} className="flex items-center gap-2 text-xs font-medium text-slate-400 mb-2 uppercase tracking-wider hover:text-indigo-600 transition-colors">
                    <span>{breadcrumb}</span> <ChevronRight size={12} /> <span className="text-indigo-600">{title}</span>
                </button>
            )}
            <h3 className="text-2xl font-bold text-slate-800">{title}</h3>
            <p className="text-slate-500 text-sm mt-1">{subtitle}</p>
        </div>
    );

    const NavItem = ({ id, label, icon: Icon }: any) => (
        <button onClick={() => { setActiveSection(id); setSubSection(null); setSelectedPermission(null); }} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left transition-all mb-1 group ${activeSection === id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:bg-slate-200/60'}`}>
            <Icon size={18} className={activeSection === id ? 'text-white' : 'text-slate-400 group-hover:text-slate-600'} />
            <span className={`font-medium text-sm ${activeSection === id ? 'font-bold' : ''}`}>{label}</span>
        </button>
    );

    const renderContent = () => {
        if (activeSection === 'Employees') {
            if (selectedPermission) {
                return (
                    <>
                        {renderHeader(selectedPermission.name, "Manage functional area access.", "Employee permission", () => setSelectedPermission(null))}
                        <Settings_Permissions selectedPermission={selectedPermission} onSelectPermission={setSelectedPermission} />
                    </>
                );
            }
            if (subSection === 'Roles') {
                return (
                    <>
                        {renderHeader("Employee roles", "Default roles cannot be removed.", "Employees")}
                        <Settings_EmployeeRoles onSelectRole={() => {}} />
                    </>
                );
            }
            if (subSection === 'Permissions') {
                return (
                    <>
                        {renderHeader("Employee permissions", "Functional access control.", "Employees")}
                        <Settings_Permissions selectedPermission={null} onSelectPermission={setSelectedPermission} />
                    </>
                );
            }
            if (subSection === 'Passcode') {
                return (
                    <>
                        {renderHeader("Device passcode", "Security policy for device access.", "Employees")}
                        <Settings_Passcode />
                    </>
                );
            }
            return (
                <div className="max-w-4xl animate-fade-in pb-20">
                    {renderHeader("Employee Settings", "Configure staff roles and security.")}
                    <div className="grid grid-cols-1 gap-4">
                        {[
                            { id: 'Roles', title: 'Employee roles', desc: 'Define categories like Manager or Server.', icon: Users },
                            { id: 'Permissions', title: 'Employee permissions', desc: 'Granular control over role actions.', icon: ShieldCheck },
                            { id: 'Passcode', title: 'Device passcode', desc: 'PIN requirements for register login.', icon: KeyRound }
                        ].map(card => (
                            <div key={card.id} onClick={() => setSubSection(card.id)} className="bg-white p-5 rounded-xl border border-slate-200 flex items-center gap-4 cursor-pointer hover:border-indigo-300 transition-all">
                                <div className="p-2.5 bg-slate-50 rounded-lg text-indigo-600"><card.icon size={22} /></div>
                                <div className="flex-1"><h4 className="font-bold text-slate-900">{card.title}</h4><p className="text-sm text-slate-500">{card.desc}</p></div>
                                <ChevronRight className="text-slate-300" size={20} />
                            </div>
                        ))}
                    </div>
                </div>
            );
        }

        if (activeSection === 'Profile') return <Settings_Profile />;
        return <div className="p-12 text-center text-slate-400 italic">Module under construction</div>;
    };

    return (
        <div className="flex flex-col lg:flex-row h-[calc(100vh-8rem)] bg-slate-50/50 rounded-2xl overflow-hidden border border-slate-200">
            <div className="w-full lg:w-72 bg-white border-r border-slate-200 p-4 flex flex-col shrink-0">
                <div className="p-4 mb-2"><h2 className="text-lg font-bold text-slate-900">Settings</h2><p className="text-xs text-slate-500 font-medium">Enterprise Suite</p></div>
                <nav className="flex-1 space-y-6 overflow-y-auto px-2 pb-4">
                    <div><h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 ml-4">Account</h3><NavItem id="Profile" label="User Profile" icon={User} /><NavItem id="Employees" label="Employees" icon={Shield} /></div>
                    <div><h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3 ml-4">Business</h3><NavItem id="BusinessInfo" label="About Business" icon={Building} /><NavItem id="Billing" label="Billing" icon={CreditCard} /></div>
                </nav>
                <div className="mt-auto p-4 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-3">
                    <div className="h-8 w-8 bg-indigo-100 rounded-lg flex items-center justify-center text-indigo-600"><Lock size={16} /></div>
                    <div className="text-[10px] text-slate-500 font-medium">Configuration changes are audited.</div>
                </div>
            </div>
            <div className="flex-1 overflow-y-auto bg-slate-50/30 p-8 lg:p-12 relative">{renderContent()}</div>
        </div>
    );
};

