                            value={settings.closeTime} 
                            onChange={(e) => setSettings({...settings, closeTime: e.target.value})}
                            className="bg-white border border-slate-300 rounded px-2 py-1 text-sm font-bold text-slate-700 outline-none focus:border-indigo-500"
                        />
                    </div>
