                    <ToggleRow 
                        label="Auto-Close Batch" 
                        description="Automatically settle transactions daily at the specified time." 
                        icon={Clock} 
                        value={settings.autoClose} 
                        onChange={() => setSettings({...settings, autoClose: !settings.autoClose})}
                    />
                    <ToggleRow 
                        label="System Notifications" 
                        description="Notify authorized staff when batch closing is complete." 
                        icon={Bell} 
                        value={settings.notifyOnClose} 
                        onChange={() => setSettings({...settings, notifyOnClose: !settings.notifyOnClose})}
