  const [subSection, setSubSection] = useState<string | null>(null);
  const [activeBusinessTab, setActiveBusinessTab] = useState<'customer' | 'billing'>('billing');
  const [selectedPermission, setSelectedPermission] = useState<PermissionItem | null>(null);

  // State for Roles to Permissions mapping
  const [permissionRoleMap, setPermissionRoleMap] = useState<Record<string, string[]>>({
      'ACCESS_REGISTER': ['Admin', 'Manager', 'Employee'],
      'ACCESS_PLANS': ['Admin'],
      'ACCESS_DINING': ['Admin', 'Manager', 'Server Lead', 'Server'],
      'ACCESS_APP_MARKET': ['Admin', 'Manager'],
      'ACCESS_INVENTORY': ['Admin', 'Manager'],
      'ACCESS_REPORTING': ['Admin', 'Manager'],
  });

  // Search States
  const [roleSearchTerm, setRoleSearchTerm] = useState('');
  const [permSearchTerm, setPermSearchTerm] = useState('');

  // View Filter for Permission Detail
  const [viewFilter, setViewFilter] = useState<'all' | 'selected'>('all');

  // Business States
  const biz = MOCK_BUSINESSES[0];

  const renderSectionHeader = (title: string, subtitle: string, breadcrumb?: string, onBreadcrumbClick?: () => void) => (
    <div className="mb-8">
        {breadcrumb && (
            <button 
                onClick={onBreadcrumbClick || (() => { setSubSection(null); setSelectedPermission(null); })}
                className="flex items-center gap-2 text-xs font-medium text-slate-400 mb-2 uppercase tracking-wider hover:text-indigo-600 transition-colors"
            >
                <span>{breadcrumb}</span>
                <ChevronRight size={12} />
                <span className="text-indigo-600">{title}</span>
            </button>
        )}
        <h3 className="text-2xl font-bold text-slate-800 uppercase tracking-tight">{title}</h3>
        {subtitle && <p className="text-slate-500 text-sm mt-1">{subtitle}</p>}
    </div>
  );

  const SettingCard = ({ icon: Icon, title, description, children, status, onClick }: any) => (
    <div 
        onClick={onClick}
        className={`bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-6 transition-all ${onClick ? 'cursor-pointer hover:border-indigo-300 hover:shadow-md active:scale-[0.99]' : ''}`}
    >
        <div className="p-5 flex items-start gap-4">
            <div className="p-2.5 bg-slate-50 rounded-lg text-indigo-600">
                <Icon size={22} />
            </div>
            <div className="flex-1">
                <div className="flex justify-between items-center mb-1">
                    <h4 className="font-bold text-slate-900">{title}</h4>
                    {status && <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-emerald-50 text-emerald-600 border border-emerald-100">{status}</span>}
                </div>
                <p className="text-sm text-slate-500 mb-2">{description}</p>
                {children}
            </div>
            {onClick && <ChevronRight className="text-slate-300 self-center" size={20} />}
        </div>
    </div>
  );

  const toggleRoleForPermission = (roleName: string) => {
      if (!selectedPermission) return;
      const key = selectedPermission.key;
      setPermissionRoleMap(prev => {
          const currentRoles = prev[key] || [];
          if (currentRoles.includes(roleName)) {
              if (roleName === 'Admin') return prev; // Cannot turn off Admin
              return { ...prev, [key]: currentRoles.filter(r => r !== roleName) };
          } else {
              return { ...prev, [key]: [...currentRoles, roleName] };
          }
      });
  };

  const isRoleSelected = (roleName: string) => {
      if (!selectedPermission) return false;
      if (roleName === 'Admin') return true; // Admin always has everything
      return (permissionRoleMap[selectedPermission.key] || []).includes(roleName);
  };

  const getAssignedRolesForPermission = (permKey: string) => {
      return permissionRoleMap[permKey] || ['Admin'];
  };

  const BillingItem = ({ label, value, description, actionLabel = "Edit", actionColor = "text-indigo-600", isCallToEdit = false, isDestructive = false }: any) => (
