    <div 
        onClick={onClick}
        className={`bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden mb-6 transition-all ${onClick ? 'cursor-pointer hover:border-indigo-300 hover:shadow-md active:scale-[0.99]' : ''}`}
