      setPermissionRoleMap(prev => {
          const currentRoles = prev[key] || [];
          if (currentRoles.includes(roleName)) {
              if (roleName === 'Admin') return prev; // Cannot turn off Admin
              return { ...prev, [key]: currentRoles.filter(r => r !== roleName) };
          } else {
              return { ...prev, [key]: [...currentRoles, roleName] };
          }
      });
  };

  const isRoleSelected = (roleName: string) => {
      if (!selectedPermission) return false;
      if (roleName === 'Admin') return true; // Admin always has everything
      return (permissionRoleMap[selectedPermission.key] || []).includes(roleName);
