import React, { useState, useRef, useEffect } from 'react';
import { DiningTable, FloorItemType } from '../types';
import { MOCK_FLOOR_TABLES, MOCK_OPTIMIZATIONS } from '../constants';
import { 
  Layout, Save, Plus, MousePointer2, Trash2, ZoomIn, ZoomOut, Maximize,
  ChevronDown, ChevronRight, Armchair, Flower2, Grid, Box, Sun, Wind,
  RefreshCw, PlayCircle, Smartphone, ExternalLink
} from 'lucide-react';
import InteractiveTable from './InteractiveTable';

interface DiningDashboardProps {
    initialTables?: DiningTable[];
    onSaveFloorPlan?: (tables: DiningTable[]) => void;
}

const DiningDashboard: React.FC<DiningDashboardProps> = ({ initialTables, onSaveFloorPlan }) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [tables, setTables] = useState<DiningTable[]>(initialTables || MOCK_FLOOR_TABLES);

  useEffect(() => {
      if (initialTables) {
          setTables(initialTables);
      }
  }, [initialTables]);

  const [selectedTableId, setSelectedTableId] = useState<string | null>(null);
  const [activeSection, setActiveSection] = useState('Dining Room');
  const [sections, setSections] = useState(['Dining Room', 'Patio', 'Bar']);

  // Canvas Viewport State
  const [scale, setScale] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  // Palette State
  const [expandedCategory, setExpandedCategory] = useState<string | null>('Tables');

  // Drag & Resize State
  const [interactionMode, setInteractionMode] = useState<'DRAG' | 'RESIZE' | null>(null);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [initialDims, setInitialDims] = useState({ x: 0, y: 0, w: 0, h: 0 });

  const canvasRef = useRef<HTMLDivElement>(null);

  // --- Actions ---
  const handleAddItem = (type: FloorItemType) => {
      const isSeatable = type.includes('TABLE') || type.includes('BOOTH') || type.includes('COUCH');

      const viewportWidth = canvasRef.current?.clientWidth || 800;
      const viewportHeight = canvasRef.current?.clientHeight || 600;
      const centerX = (viewportWidth / 2 - pan.x) / scale;
      const centerY = (viewportHeight / 2 - pan.y) / scale;

      const newItem: DiningTable = {
          id: `ITEM-${Date.now()}`,
          name: isSeatable ? `${tables.filter(t => t.isSeatable).length + 1}` : '',
          type,
          section: activeSection,
          x: centerX - 40,
          y: centerY - 40,
          width: type.includes('RECT') || type.includes('BOOTH') || type.includes('COUCH') || type.includes('POOL') || type.includes('WALL') ? 120 : 80,
          height: 80,
          seats: isSeatable ? 4 : 0,
          status: 'Available',
          isSeatable,
          rotation: 0
      };
      setTables([...tables, newItem]);
      setSelectedTableId(newItem.id);
  };

  const handleAddSection = () => {
      const name = prompt("Enter new section name:");
      if (name && !sections.includes(name)) {
          setSections([...sections, name]);
          setActiveSection(name);
      }
  };

  const handleSave = () => {
      if (onSaveFloorPlan) {
          onSaveFloorPlan(tables);
          const toast = document.createElement('div');
          toast.className = "fixed bottom-10 right-10 bg-emerald-600 text-white px-6 py-3 rounded-lg shadow-xl animate-fade-in-up z-50 font-bold";
          toast.innerText = "Floor Plan Saved Successfully!";
          document.body.appendChild(toast);
          setTimeout(() => document.body.removeChild(toast), 3000);
      }
  };

  const handleSync = () => {
      alert("Syncing table status from devices...");
  };

  // --- Canvas Interaction ---
  const handleWheel = (e: React.WheelEvent) => {
      if (e.ctrlKey || e.metaKey || isEditMode) {
          e.preventDefault();
          const zoomSensitivity = 0.001;
          const delta = -e.deltaY * zoomSensitivity;
          const newScale = Math.min(Math.max(0.5, scale + delta), 3);
          setScale(newScale);
      }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (interactionMode === null) {
          if (isEditMode && e.button === 0) {
             setSelectedTableId(null);
          }
          setIsPanning(true);
          setPanStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
      }
  };

  const handleItemMouseDown = (e: React.MouseEvent, table: DiningTable, isResizeHandle: boolean = false) => {
      e.stopPropagation();
      e.preventDefault();
      setSelectedTableId(table.id);
      if (isEditMode) {
          setInteractionMode(isResizeHandle ? 'RESIZE' : 'DRAG');
          setDragStart({ x: e.clientX, y: e.clientY });
          setInitialDims({ x: table.x, y: table.y, w: table.width, h: table.height });
      }
  };

  const handleGlobalMouseMove = (e: React.MouseEvent) => {
      if (isPanning) {
          setPan({ x: e.clientX - panStart.x, y: e.clientY - panStart.y });
          return;
      }
      if (!isEditMode || !selectedTableId || !interactionMode) return;
      const dx = (e.clientX - dragStart.x) / scale; 
      const dy = (e.clientY - dragStart.y) / scale;
      setTables(prev => prev.map(t => {
          if (t.id === selectedTableId) {
              if (interactionMode === 'DRAG') return { ...t, x: initialDims.x + dx, y: initialDims.y + dy };
              if (interactionMode === 'RESIZE') return { ...t, width: Math.max(40, initialDims.w + dx), height: Math.max(40, initialDims.h + dy) };
          }
          return t;
      }));
  };

  const handleGlobalMouseUp = () => {
      setInteractionMode(null);
      setIsPanning(false);
  };

  const toggleCategory = (cat: string) => {
      setExpandedCategory(expandedCategory === cat ? null : cat);
  }

  return (
    <div 
        className="space-y-6 animate-fade-in h-[calc(100vh-8rem)] flex flex-col" 
        onMouseMove={handleGlobalMouseMove}
        onMouseUp={handleGlobalMouseUp}
        onMouseLeave={handleGlobalMouseUp}
    >
      <div className="flex flex-col gap-1 shrink-0">
          <h1 className="text-2xl font-bold text-slate-800">Byte Dinning</h1>
          <p className="text-slate-500 font-medium">Byte Dinning</p>
      </div>

      <div className="flex flex-col gap-6 shrink-0 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <div className="flex flex-wrap gap-4 border-b border-slate-100 pb-4">
               <button onClick={handleSync} className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors border border-slate-200">
                   <RefreshCw size={14} className="text-indigo-600" /> SYNC
               </button>
               <button className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors border border-slate-200">
                   <PlayCircle size={14} className="text-indigo-600" /> TOUR
               </button>
               <button onClick={() => setIsEditMode(true)} className={`flex items-center gap-2 px-4 py-2 text-xs font-bold rounded-lg transition-colors border border-slate-200 ${isEditMode ? 'bg-indigo-600 text-white border-indigo-700' : 'text-slate-700 hover:bg-slate-50'}`}>
                   <Layout size={14} className={isEditMode ? 'text-white' : 'text-indigo-600'} /> EDIT FLOOR PLAN
               </button>
               <button className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors border border-slate-200">
                   <Smartphone size={14} className="text-indigo-600" /> CONTACTLESS DINING
               </button>
          </div>
          <div className="space-y-3">
              <p className="text-sm text-slate-600 leading-relaxed font-medium">
                  Set up and view your floor plan from your Web Dashboard.
              </p>
              <p className="text-sm text-slate-600 leading-relaxed">
                  To see the current status of your tables, click <span className="font-bold text-indigo-600 cursor-pointer hover:underline" onClick={handleSync}>Sync</span> above. This will pull the table information currently on your device.
              </p>
              <div className="flex items-center gap-2 text-xs text-slate-400 font-medium italic">
                  <div className="h-1 w-4 bg-slate-200 rounded"></div>
                  Press tab to focus first table, then use arrow keys to navigate tables
              </div>
          </div>
      </div>

      <div className="flex-1 flex gap-6 overflow-hidden">
          {/* Left Sidebar: Palette */}
          <div className="w-80 bg-white border border-slate-200 rounded-xl shadow-sm p-4 flex flex-col gap-4 overflow-y-auto shrink-0 z-10">
              {isEditMode ? (
                  <div className="space-y-4 animate-fade-in">
                      <div className="flex items-center justify-between">
                          <h3 className="font-bold text-slate-800 text-sm uppercase tracking-wide">Floor Objects</h3>
                          <button onClick={() => setIsEditMode(false)} className="text-xs text-slate-400 hover:text-slate-600">Close Editor</button>
                      </div>
                      <div className="border border-slate-200 rounded-lg overflow-hidden">
                          <button onClick={() => toggleCategory('Tables')} className="w-full flex justify-between items-center p-3 bg-slate-50 hover:bg-slate-100 font-semibold text-sm text-slate-700">
                              <span>Tables</span>
                              {expandedCategory === 'Tables' ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                          </button>
                          {expandedCategory === 'Tables' && (
                              <div className="p-3 grid grid-cols-2 gap-2 bg-white">
                                  <button onClick={() => handleAddItem('TABLE_SQUARE')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <div className="w-6 h-6 border-2 border-slate-400 bg-white rounded-sm mb-1"></div>
                                      <span className="text-[10px]">Square</span>
                                  </button>
                                  <button onClick={() => handleAddItem('TABLE_ROUND')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <div className="w-6 h-6 border-2 border-slate-400 bg-white rounded-full mb-1"></div>
                                      <span className="text-[10px]">Round</span>
                                  </button>
                                  <button onClick={() => handleAddItem('TABLE_RECT')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center col-span-2 transition-colors">
                                      <div className="w-12 h-6 border-2 border-slate-400 bg-white rounded-sm mb-1"></div>
                                      <span className="text-[10px]">Rectangle</span>
                                  </button>
                              </div>
                          )}
                      </div>
                      {/* Other categories omitted for brevity but they exist */}
                      {selectedTableId && (
                          <div className="border-t border-slate-100 pt-4 bg-slate-50 p-3 rounded-lg animate-fade-in-up">
                              <h3 className="font-bold text-slate-800 mb-2 text-xs uppercase tracking-wide">Properties</h3>
                              <div className="space-y-3">
                                  <div>
                                      <label className="text-[10px] text-slate-500 block mb-1">Label</label>
                                      <input type="text" value={tables.find(t => t.id === selectedTableId)?.name} onChange={(e) => setTables(prev => prev.map(t => t.id === selectedTableId ? { ...t, name: e.target.value } : t))} className="w-full border border-slate-300 rounded px-2 py-1 text-sm outline-none" />
                                  </div>
                                  <button onClick={() => { setTables(prev => prev.filter(t => t.id !== selectedTableId)); setSelectedTableId(null); }} className="w-full py-2 bg-red-50 text-red-600 border border-red-200 rounded hover:bg-red-100 text-xs flex items-center justify-center gap-2"><Trash2 size={14} /> Delete</button>
                              </div>
                          </div>
                      )}
                  </div>
              ) : (
                  <div className="animate-fade-in flex flex-col h-full">
                      <div className="p-4 bg-indigo-50 rounded-lg border border-indigo-100 mb-4 flex items-center gap-3">
                          <Layout size={20} className="text-indigo-600" />
                          <div>
                              <h3 className="font-bold text-indigo-900 text-sm">Visual Layout</h3>
                              <p className="text-xs text-indigo-700">Real-time status tracking.</p>
                          </div>
                      </div>
                      <h3 className="font-bold text-slate-800 text-sm mb-3">Live Insights</h3>
                      {MOCK_OPTIMIZATIONS.map(opt => (
                          <div key={opt.id} className="p-3 bg-white border border-slate-200 rounded-lg shadow-sm mb-2 hover:shadow-md transition-shadow">
                              <p className="text-sm font-medium text-slate-900">{opt.suggestion}</p>
                              <p className="text-xs text-slate-500 mt-1">Impact: {opt.impact}</p>
                          </div>
                      ))}
                  </div>
              )}
          </div>

          {/* Main Canvas Area */}
          <div className="flex-1 flex flex-col bg-slate-200/50 rounded-xl border border-slate-300 shadow-inner overflow-hidden relative group">
              <div className="absolute top-4 left-4 z-20 flex gap-2">
                  {sections.map(sec => (
                      <button key={sec} onClick={() => setActiveSection(sec)} className={`px-4 py-1.5 rounded-full text-xs font-bold shadow-sm transition-all ${activeSection === sec ? 'bg-slate-800 text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`}>{sec}</button>
                  ))}
                  {isEditMode && <button onClick={handleAddSection} className="p-1.5 bg-indigo-100 text-indigo-600 rounded-full hover:bg-indigo-200 shadow-sm"><Plus size={16} /></button>}
              </div>
              <div className="absolute bottom-4 right-4 z-20 flex flex-col bg-white border border-slate-200 rounded-lg shadow-sm">
                  <button onClick={() => setScale(s => Math.min(s + 0.1, 3))} className="p-2 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><ZoomIn size={18} /></button>
                  <button onClick={() => { setScale(1); setPan({x:0, y:0}); }} className="p-2 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><Maximize size={18} /></button>
                  <button onClick={() => setScale(s => Math.max(s - 0.1, 0.5))} className="p-2 text-slate-600 hover:bg-slate-50"><ZoomOut size={18} /></button>
              </div>
              <div ref={canvasRef} className="flex-1 relative overflow-hidden" onWheel={handleWheel} onMouseDown={handleMouseDown} style={{ cursor: isPanning ? 'grabbing' : 'grab' }}>
                  <div style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${scale})`, transformOrigin: '0 0', width: '100%', height: '100%' }}>
                      {tables.filter(t => t.section === activeSection).map(table => (
                          <InteractiveTable 
                              key={table.id}
                              table={table}
                              onClick={(e, t, handle) => handleItemMouseDown(e, t, handle)}
                              isEditing={isEditMode}
                              isSelected={selectedTableId === table.id}
                          />
                      ))}
                  </div>
              </div>
          </div>
      </div>
    </div>
  );
};

