import React, { useState, useEffect } from 'react';
import { DiningTable, InventoryItem, Category, Employee, DiningOrderItem, UserRole } from '../types';
import { X, MoreVertical, LogOut, Plus, Minus, User, Search, Grid, List, Lock, Unlock, AlertTriangle } from 'lucide-react';

interface TableServiceAppProps {
    tables: DiningTable[];
    inventory: InventoryItem[];
    categories: Category[];
    currentUser: Employee;
    onExit: () => void;
}

interface TableGuest {
    id: number;
    status: 'Active' | 'Paid';
}

const TableServiceApp: React.FC<TableServiceAppProps> = ({ tables, inventory, categories, currentUser, onExit }) => {
    const [localTables, setLocalTables] = useState<DiningTable[]>(tables);
    const [activeTableId, setActiveTableId] = useState<string | null>(null);
    const [activeSeat, setActiveSeat] = useState<number>(0); // 0 is shared
    const [guests, setGuests] = useState<TableGuest[]>([{ id: 1, status: 'Active' }]);
    const [orderItems, setOrderItems] = useState<DiningOrderItem[]>([]);
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');

    // Sync props to local state initially
    useEffect(() => {
        setLocalTables(tables);
    }, [tables]);

    const activeTable = localTables.find(t => t.id === activeTableId);

    // --- ACCESS CONTROL LOGIC ---
    const isManager = currentUser.role === UserRole.BUSINESS_ADMIN || currentUser.role === UserRole.SUPER_ADMIN || currentUser.role === 'Manager';

    const visibleTables = localTables.filter(t => {
        if (isManager) return true; // Managers see all
        return t.status === 'Available' || t.employeeId === currentUser.id; // Servers see Open OR Owned
    });

    // --- TABLE INTERACTION LOGIC ---
    const handleTableClick = (table: DiningTable) => {
        // Case 1: Table is Available -> Claim it
        if (table.status === 'Available') {
            const updatedTable = { ...table, status: 'Occupied' as const, employeeId: currentUser.id, assignedToName: currentUser.name };
            updateTableState(updatedTable);
            setActiveTableId(table.id);
            setGuests([{ id: 1, status: 'Active' }]); // Reset guests for new session
            setOrderItems([]); // Reset order
            return;
        }

        // Case 2: Table is Occupied by ME -> Open it
        if (table.employeeId === currentUser.id) {
            setActiveTableId(table.id);
            return;
        }

        // Case 3: Table is Occupied by SOMEONE ELSE
        if (table.employeeId !== currentUser.id) {
            if (isManager) {
                if (window.confirm(`Override table assigned to ${table.assignedToName}?`)) {
                    setActiveTableId(table.id);
                }
            } else {
                alert("This table is assigned to another server.");
            }
        }
    };

    const updateTableState = (updatedTable: DiningTable) => {
        setLocalTables(prev => prev.map(t => t.id === updatedTable.id ? updatedTable : t));
    };

    const handlePayGuest = (seatId: number) => {
        setGuests(prev => prev.map(g => g.id === seatId ? { ...g, status: 'Paid' } : g));
    };

    const handlePayAll = () => {
        setGuests(prev => prev.map(g => ({ ...g, status: 'Paid' })));
        if (activeTable) {
            const resetTable = { 
                ...activeTable, 
                status: 'Available' as const, 
                employeeId: undefined, 
                assignedToName: undefined,
                timeSeated: undefined 
            };
            updateTableState(resetTable);
            setActiveTableId(null);
            setOrderItems([]);
        }
    };

    const getItemsForSeat = (seatId: number) => {
        return orderItems.filter(item => item.seatNumber === seatId);
    };

    const removeFromOrder = (index: number) => {
        const newItems = [...orderItems];
        newItems.splice(index, 1);
        setOrderItems(newItems);
    };

    const addToOrder = (item: InventoryItem) => {
        const newItem: DiningOrderItem = {
            ...item,
            quantity: 1,
            seatNumber: activeSeat,
            fired: false,
            modifiers: [],
            color: 'bg-white'
        };
        setOrderItems([...orderItems, newItem]);
    };

    const filteredItems = inventory.filter(item => {
        const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
        const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
        return matchesCategory && matchesSearch && item.showOnPos;
    });

    if (!activeTableId) {
        return (
            <div className="h-full flex flex-col bg-slate-100">
                <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center">
                    <h2 className="text-xl font-bold text-slate-800">Byte Dinning - Floor Plan</h2>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2 text-sm text-slate-600">
                            <span className="w-3 h-3 rounded-full bg-white border border-slate-300"></span> Available
                            <span className="w-3 h-3 rounded-full bg-blue-100 border border-blue-300"></span> My Tables
                            <span className="w-3 h-3 rounded-full bg-slate-200 border border-slate-400"></span> Other
                        </div>
                        <button onClick={onExit} className="p-2 hover:bg-slate-100 rounded text-slate-500">
                            <X size={24} />
                        </button>
                    </div>
                </div>
                <div className="p-6 grid grid-cols-4 gap-4 overflow-y-auto">
                    {localTables.filter(t => t.isSeatable).map(table => {
                        const isMine = table.employeeId === currentUser.id;
                        const isLocked = table.status !== 'Available' && !isMine && !isManager;
                        return (
                            <button 
                                key={table.id} 
                                onClick={() => handleTableClick(table)}
                                disabled={isLocked}
                                className={`p-6 rounded-xl border-2 flex flex-col items-center justify-center gap-2 aspect-square transition-all relative
                                    ${table.status === 'Available' ? 'bg-white border-slate-200 hover:border-indigo-500 shadow-sm' : 
                                      isMine ? 'bg-blue-50 border-blue-400 shadow-md ring-1 ring-blue-200' : 
                                      'bg-slate-100 border-slate-200 opacity-60 cursor-not-allowed'}`}
                            >
                                <span className="font-bold text-2xl text-slate-700">{table.name}</span>
                                {table.status === 'Occupied' && (
                                    <div className="text-xs flex flex-col items-center">
                                        <span className="font-medium text-slate-600">{table.assignedToName}</span>
                                        {isMine ? <span className="text-blue-600 font-bold">ACTIVE</span> : <Lock size={12} />}
                                    </div>
                                )}
                                {table.status === 'Available' && <span className="text-xs text-green-600 font-medium">Open</span>}
                            </button>
                        );
                    })}
                </div>
            </div>
        );
    }

    return (
        <div className="flex h-full bg-slate-100">
            {/* Left: Order Management */}
            <div className="w-1/3 bg-white border-r border-slate-200 flex flex-col">
                <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                    <div>
                        <h2 className="font-bold text-lg text-slate-800">Table {activeTable?.name}</h2>
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                            <User size={12} /> {activeTable?.assignedToName}
                        </div>
                    </div>
                    <button onClick={() => setActiveTableId(null)} className="text-slate-400 hover:text-slate-600 flex items-center gap-1">
                        <LogOut size={16} /> Close
                    </button>
                </div>
                <div className="p-2 border-b border-slate-200 flex gap-2 overflow-x-auto bg-white">
                    <button onClick={() => setActiveSeat(0)} className={`px-3 py-1.5 rounded-lg text-sm font-medium whitespace-nowrap ${activeSeat === 0 ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-600'}`}>Whole Table</button>
                    {guests.map(g => (
                        <button key={g.id} onClick={() => setActiveSeat(g.id)} className={`px-3 py-1.5 rounded-lg text-sm font-medium whitespace-nowrap flex items-center gap-1 ${activeSeat === g.id ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-600'}`}>Guest {g.id}</button>
                    ))}
                    <button onClick={() => setGuests([...guests, { id: guests.length + 1, status: 'Active' }])} className="p-1.5 bg-slate-100 rounded-lg text-slate-500 hover:bg-slate-200"><Plus size={16} /></button>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-4">
                    {[{id: 0, label: 'Whole Table', status: undefined as any}, ...guests.map(g => ({id: g.id, label: `Guest ${g.id}`, status: g.status}))].map(seat => {
                        const seatItems = getItemsForSeat(seat.id);
                        if (seatItems.length === 0 && activeSeat !== seat.id) return null;
                        return (
                            <div key={seat.id} className={`rounded-xl overflow-hidden border-2 transition-colors ${activeSeat === seat.id ? 'border-indigo-500 bg-white shadow-sm' : 'border-transparent bg-slate-100/50'}`}>
                                <div className={`px-4 py-2 text-xs font-bold uppercase tracking-wider flex justify-between items-center cursor-pointer ${activeSeat === seat.id ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500'}`} onClick={() => setActiveSeat(seat.id)}>
                                    <span>{seat.label} {seat.status === 'Paid' && '(PAID)'}</span>
                                    <span>${seatItems.reduce((a, b) => a + b.price, 0).toFixed(2)}</span>
                                </div>
                                <div className="divide-y divide-slate-100">
                                    {seatItems.length === 0 ? <div className="p-4 text-center text-xs text-slate-400 italic">No items yet</div> : seatItems.map((item, idx) => (
                                        <div key={idx} className="p-3 flex justify-between items-start group hover:bg-slate-50">
                                            <span className="font-medium text-sm">{item.name}</span>
                                            <div className="flex items-center gap-3">
                                                <span className="font-mono text-sm">${item.price.toFixed(2)}</span>
                                                <button onClick={() => { const mainIndex = orderItems.indexOf(item); if (mainIndex > -1) removeFromOrder(mainIndex); }} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><X size={16} /></button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        );
                    })}
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50">
                    <div className="flex justify-between items-center mb-4"><span className="text-slate-500 font-medium">Total Due</span><span className="text-xl font-bold text-slate-900">${orderItems.reduce((a,b) => a + b.price, 0).toFixed(2)}</span></div>
                    <div className="grid grid-cols-2 gap-3">
                        <button className="py-3 bg-orange-500 text-white rounded-xl font-bold shadow-sm hover:bg-orange-600">Fire to Kitchen</button>
                        <button onClick={handlePayAll} className="py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-sm hover:bg-indigo-700">Pay All & Close</button>
                    </div>
                </div>
            </div>
            {/* Right: Menu */}
            <div className="flex-1 flex flex-col">
                <div className="p-4 border-b border-slate-200 bg-white flex gap-4">
                    <div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Search menu..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg outline-none" /></div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 bg-slate-100">
                    <div className="grid grid-cols-3 lg:grid-cols-4 gap-4">
                        {filteredItems.map(item => (
                            <button key={item.id} onClick={() => addToOrder(item)} className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 hover:border-indigo-500 flex flex-col items-center justify-center text-center aspect-square transition-all">
                                <div className="h-12 w-12 rounded-full bg-slate-100 flex items-center justify-center mb-2 font-bold text-slate-600">{item.name.charAt(0)}</div>
                                <span className="font-medium text-slate-900 line-clamp-2">{item.name}</span>
                                <span className="text-sm text-slate-500 mt-1">${item.price.toFixed(2)}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

