import React, { useState } from 'react';
import { 
    MenuItem, CartItem, InventoryItem, Category, PaymentSplit, 
    Receipt, DiscountCode 
} from '../../types';
import { 
    Search, Plus, Minus, Trash2, X, CreditCard, DollarSign, Tag 
} from 'lucide-react';

interface PosRegisterProps {
    inventory: InventoryItem[];
    categories: Category[];
    discounts: DiscountCode[];
    onFinish: (cart: CartItem[], total: number, payments: PaymentSplit[]) => void;
}

const PosRegister: React.FC<PosRegisterProps> = ({ inventory, categories, discounts, onFinish }) => {
    const [cart, setCart] = useState<CartItem[]>([]);
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');
    const [showTipScreen, setShowTipScreen] = useState(false);
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [payments, setPayments] = useState<PaymentSplit[]>([]);
    const [selectedTip, setSelectedTip] = useState<number>(0);
    const [selectedDiscount, setSelectedDiscount] = useState<DiscountCode | null>(null);

    const posCategories = ['All', ...categories.filter(c => c.showOnPos).map(c => c.name)];
    const filteredItems = inventory.filter(i => 
        i.showOnPos && 
        (activeCategory === 'All' || i.category === activeCategory) &&
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const addToCart = (item: InventoryItem) => {
        setCart(prev => {
            const existing = prev.find(i => i.id === item.id);
            if (existing) {
                return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { ...item, quantity: 1, modifiers: [], color: 'bg-white' }];
        });
    };

    const updateQty = (id: string, delta: number) => {
        setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + delta) } : i));
    };

    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    let discountAmt = 0;
    if (selectedDiscount) {
        discountAmt = selectedDiscount.type === 'Percentage' ? subtotal * (selectedDiscount.value / 100) : selectedDiscount.value;
    }
    const taxable = Math.max(0, subtotal - discountAmt);
    const tax = taxable * 0.0825;
    const total = taxable + tax + selectedTip;

    const handleAddPayment = (method: string, amount: number) => {
        const newPayments = [...payments, { method, amount, status: 'Paid' }];
        setPayments(newPayments);
        if (newPayments.reduce((a, b) => a + b.amount, 0) >= total - 0.01) {
            onFinish(cart, total, newPayments);
        }
    };

    return (
        <div className="flex flex-1 overflow-hidden h-full relative animate-fade-in bg-white">
            {/* Modal Overlays */}
            {showTipScreen && (
                <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-900/80 backdrop-blur-sm">
                    <div className="bg-white p-8 rounded-2xl shadow-xl text-center max-w-md w-full animate-scale-in">
                        <h2 className="text-2xl font-bold mb-6">Add Gratitude?</h2>
                        <div className="grid grid-cols-3 gap-3 mb-8">
                            {[15, 20, 25].map(p => (
                                <button key={p} onClick={() => { setSelectedTip(taxable * p/100); setShowTipScreen(false); setShowPaymentModal(true); }} 
                                    className="py-6 border-2 border-slate-100 rounded-2xl hover:border-indigo-500 hover:bg-indigo-50 transition-all">
                                    <span className="block text-xl font-bold">{p}%</span>
                                    <span className="text-xs text-slate-500">${(taxable * p/100).toFixed(2)}</span>
                                </button>
                            ))}
                        </div>
                        <div className="flex flex-col gap-4">
                            <button onClick={() => { setSelectedTip(0); setShowTipScreen(false); setShowPaymentModal(true); }} className="text-slate-500 font-bold py-2">NO TIP</button>
                            <button onClick={() => setShowTipScreen(false)} className="text-rose-500 font-bold py-2">CANCEL</button>
                        </div>
                    </div>
                </div>
            )}

            {showPaymentModal && (
                <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-900/80 backdrop-blur-sm">
                    <div className="bg-white p-10 rounded-3xl shadow-2xl max-w-lg w-full space-y-6 animate-scale-in">
                        <div className="text-center">
                            <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Total Due</p>
                            <h2 className="text-5xl font-black text-slate-900">${total.toFixed(2)}</h2>
                        </div>
                        <div className="grid grid-cols-1 gap-4">
                            <button onClick={() => handleAddPayment('Card', total)} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-bold text-xl shadow-lg hover:bg-indigo-700 flex items-center justify-center gap-3">
                                <CreditCard /> CARD PAYMENT
                            </button>
                            <button onClick={() => handleAddPayment('Cash', total)} className="w-full py-5 bg-emerald-600 text-white rounded-2xl font-bold text-xl shadow-lg hover:bg-emerald-700 flex items-center justify-center gap-3">
                                <DollarSign /> CASH PAYMENT
                            </button>
                        </div>
                        <button onClick={() => setShowPaymentModal(false)} className="w-full py-2 text-slate-400 font-bold">CANCEL</button>
                    </div>
                </div>
            )}

            {/* Main Register UI */}
            <div className="flex-1 flex flex-col overflow-hidden">
                <div className="p-4 border-b border-slate-100 flex gap-4 bg-white">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="Find items..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-transparent rounded-xl focus:bg-white focus:border-indigo-500 outline-none transition-all"
                        />
                    </div>
                </div>

                <div className="p-4 flex gap-2 overflow-x-auto bg-white shrink-0 scrollbar-hide">
                    {posCategories.map(cat => (
                        <button 
                            key={cat} 
                            onClick={() => setActiveCategory(cat)} 
                            className={`px-5 py-2 rounded-full whitespace-nowrap text-sm font-bold transition-all ${activeCategory === cat ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>

                <div className="flex-1 overflow-y-auto p-4 bg-slate-50/50">
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                        {filteredItems.map(item => (
                            <button 
                                key={item.id} 
                                onClick={() => addToCart(item)} 
                                className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 hover:border-indigo-500 hover:shadow-md transition-all flex flex-col items-center justify-center text-center aspect-square"
                            >
                                <div className="h-12 w-12 rounded-full bg-slate-50 flex items-center justify-center mb-3 text-indigo-600">
                                    <Tag size={20} />
                                </div>
                                <span className="font-bold text-slate-800 line-clamp-2 leading-tight">{item.name}</span>
                                <span className="text-sm font-bold text-slate-400 mt-2">${item.price.toFixed(2)}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Sidebar Cart */}
            <div className="w-96 border-l border-slate-200 bg-white flex flex-col shadow-2xl">
                <div className="p-6 border-b border-slate-100 bg-white">
                    <h3 className="font-black text-slate-900 text-xl tracking-tight">CART</h3>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50/30">
                    {cart.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                            <Trash2 size={48} className="mb-4" />
                            <p className="font-bold">EMPTY CART</p>
                        </div>
                    ) : cart.map(item => (
                        <div key={item.id} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center group">
                            <div className="flex-1">
                                <p className="font-bold text-slate-800 leading-tight">{item.name}</p>
                                <p className="text-xs font-bold text-slate-400 mt-1">${item.price.toFixed(2)} / ea</p>
                            </div>
                            <div className="flex items-center gap-3 bg-slate-100 rounded-xl p-1">
                                <button onClick={() => updateQty(item.id, -1)} className="p-1 hover:bg-white rounded-lg transition-colors"><Minus size={14}/></button>
                                <span className="font-black text-indigo-600 w-6 text-center">{item.quantity}</span>
                                <button onClick={() => updateQty(item.id, 1)} className="p-1 hover:bg-white rounded-lg transition-colors"><Plus size={14}/></button>
                            </div>
                        </div>
                    ))}
                </div>

                <div className="p-6 bg-white border-t border-slate-200 space-y-4 shadow-[0_-10px_20px_-10px_rgba(0,0,0,0.05)]">
                    <div className="space-y-2">
                        <div className="flex justify-between text-sm font-bold text-slate-400"><span>SUBTOTAL</span><span>${subtotal.toFixed(2)}</span></div>
                        <div className="flex justify-between text-sm font-bold text-slate-400"><span>TAX (8.25%)</span><span>${tax.toFixed(2)}</span></div>
                        {selectedTip > 0 && <div className="flex justify-between text-sm font-bold text-emerald-500"><span>TIP</span><span>${selectedTip.toFixed(2)}</span></div>}
                        <div className="flex justify-between text-2xl font-black text-slate-900 pt-2"><span>TOTAL</span><span>${total.toFixed(2)}</span></div>
                    </div>
                    <button 
                        onClick={() => setShowTipScreen(true)} 
                        disabled={cart.length === 0} 
                        className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black text-lg shadow-xl shadow-indigo-100 active:scale-[0.98] transition-all disabled:opacity-30 disabled:grayscale"
                    >
                        CHECKOUT
                    </button>
                </div>
            </div>
        </div>
    );
};

export default PosRegister;

import React, { useState } from 'react';
import { 
    DetailedOrder, Transaction, Customer, Employee, InventoryItem, 
    Table, Reservation, Schedule, Category, PaymentSplit, Receipt, 
    DiscountCode, DiningTable, KDSSettings, UserRole, CartItem 
} from '../types';
import { LayoutGrid, Lock, ShieldAlert } from 'lucide-react';
import PosLauncher, { PosAppType } from './POS/PosLauncher';
import PosRegister from './POS/PosRegister';
import ReservationsApp from './ReservationsApp';
import SchedulingApp from './SchedulingApp';
import TableServiceApp from './TableServiceApp';
import KitchenDisplay from './KitchenDisplay';
import PasscodeLock from './PasscodeLock';

interface CashierPOSProps {
  onLogout: () => void;
  onProcessSale: (cart: CartItem[], total: number) => void;
  currentUser: Employee;
  sharedOrders: DetailedOrder[];
  sharedTransactions: Transaction[];
  sharedCustomers: Customer[];
  sharedEmployees: Employee[];
  sharedInventory: InventoryItem[];
  sharedCategories: Category[];
  sharedDiscounts?: DiscountCode[];
  sharedTables: Table[];
  sharedReservations: Reservation[];
  sharedSchedules: Schedule[];
  onSeatReservation: (resId: string, tableId: string) => void;
  integrationConfig: { reservation_pos: boolean; scheduling_pos: boolean; kdsEnabled: boolean };
  floorPlanTables?: DiningTable[];
  kdsSettings?: KDSSettings;
  receiptSettings?: any;
  onFireToKitchen?: (kitchenPayload: any) => void;
}

const CashierPOS: React.FC<CashierPOSProps> = ({ 
    onLogout, onProcessSale, sharedInventory, sharedCategories, sharedDiscounts = [], 
    sharedReservations, sharedSchedules, onSeatReservation, integrationConfig, 
    floorPlanTables = [], kdsSettings, sharedEmployees
}) => {
  const [currentApp, setCurrentApp] = useState<PosAppType>('LAUNCHER');
  const [authenticatedPosUser, setAuthenticatedPosUser] = useState<Employee | null>(null);
  const [clockedIn, setClockedIn] = useState(true);

  const handleFinishRegister = (cart: CartItem[], total: number, payments: PaymentSplit[]) => {
      onProcessSale(cart, total);
      // In a real app, generate receipt here
      setCurrentApp('LAUNCHER');
  };

  if (!authenticatedPosUser) {
      return (
        <PasscodeLock 
            employees={sharedEmployees} 
            onAuthenticated={(user) => setAuthenticatedPosUser(user)}
            onCancel={onLogout}
        />
      );
  }

  return (
    <div className="h-screen flex flex-col overflow-hidden bg-slate-100 font-sans">
        <header className="h-16 bg-slate-900 text-white flex items-center justify-between px-6 shrink-0 shadow-md z-30">
            <div className="flex items-center gap-4">
                <button onClick={() => setCurrentApp('LAUNCHER')} className="p-2 hover:bg-slate-800 rounded-lg flex items-center gap-2 transition-colors">
                    <LayoutGrid size={20} className="text-indigo-400" />
                    <span className="font-bold text-lg">OmniOS</span>
                </button>
                {currentApp !== 'LAUNCHER' && (
                    <>
                        <span className="text-slate-600">/</span>
                        <h1 className="font-bold text-lg capitalize">{currentApp.toLowerCase().replace('_', ' ')}</h1>
                    </>
                )}
            </div>
            <div className="flex items-center gap-4">
                <div className="text-right hidden sm:block">
                    <p className="text-[10px] text-slate-400 uppercase font-black">Operator</p>
                    <p className="text-sm font-bold">{authenticatedPosUser.name}</p>
                </div>
                <div className="h-8 w-px bg-slate-700"></div>
                <button 
                    onClick={() => setClockedIn(!clockedIn)}
                    className={`px-3 py-1.5 rounded-full text-[10px] font-black transition-all border ${clockedIn ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30' : 'bg-red-500/10 text-red-400 border-red-500/30'}`}
                >
                    {clockedIn ? 'CLOCKED IN' : 'OFF CLOCK'}
                </button>
                <button onClick={() => setAuthenticatedPosUser(null)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white" title="Lock Terminal">
                    <Lock size={20} />
                </button>
            </div>
        </header>

        <main className="flex-1 overflow-hidden flex flex-col relative">
            {currentApp === 'LAUNCHER' && (
                <PosLauncher user={authenticatedPosUser} onAppSelect={setCurrentApp} />
            )}
            {currentApp === 'REGISTER' && (
                <PosRegister 
                    inventory={sharedInventory} 
                    categories={sharedCategories} 
                    discounts={sharedDiscounts} 
                    onFinish={handleFinishRegister} 
                />
            )}
            {currentApp === 'TABLE_SERVICE' && (
                <TableServiceApp 
                    tables={floorPlanTables}
                    inventory={sharedInventory}
                    categories={sharedCategories}
                    currentUser={authenticatedPosUser}
                    onExit={() => setCurrentApp('LAUNCHER')}
                />
            )}
            {currentApp === 'KITCHEN' && <KitchenDisplay settings={kdsSettings} />}
            {currentApp === 'RESERVATIONS' && (
                <ReservationsApp 
                    reservations={sharedReservations} 
                    tables={[]} // Compatibility
                    floorPlanTables={floorPlanTables}
                    onSeatReservation={onSeatReservation} 
                    isConnectedToPos={integrationConfig.reservation_pos} 
                />
            )}
            {currentApp === 'SCHEDULING' && <SchedulingApp schedules={sharedSchedules} />}
        </main>
    </div>
  );
};

export default CashierPOS;

