interface OrderOptionSettings {
  autoGroupItems: boolean;
  allowNotes: boolean;
  stayInCategory: boolean;
  trackRemovalReasons: boolean;
}

interface OrderReceiptSettings {
  requirePasscodeReprint: boolean;
  printVoidReceipt: boolean;
  fontSize: 'Small' | 'Medium' | 'Large';
  orderNumbers: 'None' | 'Manual' | 'Automatic';
  addBlankLines: boolean;
  blankLinesCount: number;
  showOrderNote: boolean;
  useAltNames: boolean;
  groupLineItems: boolean;
  showModNames: boolean;
  condenseMods: boolean;
  groupMods: boolean;
  showCustomerInfo: boolean;
  showBarcode: boolean;
}

interface PaymentSettings {
    cashBack: boolean;
    cashDiscount: boolean;
    dcc: boolean;
    invoiceNumber: boolean;
    offlinePayments: {
        id: string;
        name: string;
        enabled: boolean;
        limit: number;
        cumulative: number;
        prompt: number;
    }[];
    paymentPrefs: {
        logOutAfter: boolean;
        fastPayCash: boolean;
        scanToPay: boolean;
        tapToPay: boolean;
    };
    threshold: {
        amount: number;
        managerOverrides: boolean;
    };
    signature: {
        requirement: 'none' | 'always' | 'amount';
        location: 'receipt' | 'screen';
    };
    tenders: string[];
    customTenders: string[];
    trackVoidRefundReasons: boolean;
}

interface PaymentReceiptSettings {
  autoPrintCustomerReceipt: boolean;
  markItemsPrinted: boolean;
  displayLogo: boolean;
  customHeader: boolean;
  customHeaderTxt: string;
  customFooter: boolean;
  customFooterTxt: string;
  marketingOptIn: boolean;
  hideStreetAddress: boolean;
  groupItemsByGuest: boolean;
  showOrderNote: boolean;
  showPaymentNote: boolean;
  showCashierName: boolean;
  showLineItems: boolean;
  showModGroupNames: boolean;
  modifierDisplay: string;
  showCustomerInfo: boolean;
  showBusinessWebsite: boolean;
  showBarcode: boolean;
  spaceAtBottom: boolean;
}

interface EcommercePaymentSettings {
  convenienceFeesEnabled: boolean;
  convenienceFeeAmount: number;
  purchasingCardData: 'none' | 'l2' | 'l2l3';
}

interface APIToken {
  id: string;
  name: string;
  type: string;
  createdAt: string;
  token: string;
}

interface HostedCheckoutSettings {
    businessName: string;
    logoSize: 'Small' | 'Medium' | 'Large';
    headerColor: string;
    backgroundColor: string;
    footerColor: string;
    customFooterContent: string;
    captureFirstName: boolean;
    captureLastName: boolean;
    captureEmail: boolean;
    customFields: { id: string, name: string, enabled: boolean, required: boolean }[];
    useRecaptcha: boolean;
    failureUrl: string;
    successUrl: string;
    cancelUrl: string;
    webhookUrl: string;
    signingSecret: string;
}

interface PaymentLink {
  id: string;
  name: string;
  type: 'URL' | 'Button' | 'QR code';
  createdOn: string;
  amount: number;
  notifications: boolean;
  url: string;
}

interface FraudPreventionSettings {
  avs: {
    zipNoMatch: boolean;
    zipNotVerified: boolean;
    zipNotProvided: boolean;
    addrNoMatch: boolean;
    addrNotVerified: boolean;
    addrNotProvided: boolean;
