    }
  };

  // --- ROUTING LOGIC ---
  if (currentPath === '/feedback') {
    return <ReceiptFeedback />;
  }

  if (currentPath === '/kitchen') {
    return <KitchenDisplay settings={kdsSettings} />; // KDS is a standalone view when accessed directly
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  if (currentUser.role === UserRole.SUPER_ADMIN) {
    return (
        <div className="bg-slate-100 min-h-screen p-4">
            <div className="max-w-7xl mx-auto space-y-4">
                <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <h1 className="font-bold text-slate-800 text-lg">OmniCommand Super Admin</h1>
                    <button onClick={handleLogout} className="text-slate-500 hover:text-red-600 font-medium text-sm">Sign Out</button>
                </div>
                <SuperAdmin 
                    integrationConfig={integrationConfig} 
                    onToggleIntegration={(key) => {
                        setIntegrationConfig(prev => ({...prev, [key]: !prev[key]}));
                        if (key === 'kdsEnabled') {
                            setKdsSettings(prev => ({...prev, isEnabled: !prev.isEnabled}));
                        }
                    }} 
                />
            </div>
        </div>
    );
  }

  // --- ACCESS POLICY: LOCK-IN FOR STAFF ROLES ---
  const posOnlyRoles = ['Server Lead', 'Server', 'Host', 'Employee', UserRole.CASHIER, UserRole.STAFF];
  if (posOnlyRoles.includes(currentUser.role)) {
    return (
        <CashierPOS 
          onLogout={handleLogout} 
          onProcessSale={handleProcessSale}
          currentUser={currentUser}
          sharedOrders={orders}
          sharedTransactions={transactions}
          sharedCustomers={customers}
          sharedEmployees={employeesState}
          sharedInventory={inventory}
          sharedCategories={categories}
          sharedDiscounts={discounts}
          sharedTables={MOCK_TABLES}
          sharedReservations={MOCK_RESERVATIONS}
          sharedSchedules={MOCK_SCHEDULES}
          onSeatReservation={(resId, tableId) => console.log('Seat', resId, tableId)}
          integrationConfig={integrationConfig}
          floorPlanTables={floorPlanTables}
          kdsSettings={kdsSettings}
          receiptSettings={receiptSettings}
          onFireToKitchen={handleFireToKitchen} 
        />
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">
      {renderSidebar()}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shrink-0 z-20 shadow-sm relative">
            <h2 className="font-bold text-lg text-slate-800">{activeTab}</h2>

            <div className="flex items-center gap-6">
                {/* Utility Actions Icons */}
                <div className="flex items-center gap-3 border-r border-slate-200 pr-6 mr-2">
                    <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-lg transition-all relative" title="Notifications">
                        <Bell size={20} />
                        <span className="absolute top-2 right-2 h-2 w-2 bg-red-500 rounded-full border-2 border-white"></span>
                    </button>
                    <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-lg transition-all" title="Help & Documentation">
                        <HelpCircle size={20} />
                    </button>
                    <button 
                        onClick={() => setActiveTab('Settings')}
                        className={`p-2 rounded-lg transition-all ${activeTab === 'Settings' ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:text-indigo-600 hover:bg-slate-100'}`} 
                        title="Settings"
                    >
                        <SettingsIcon size={20} />
                    </button>
                </div>

                {/* Profile Section */}
                <div className="flex items-center gap-3 relative">
                    <div className="flex flex-col items-end hidden sm:flex">
                        <span className="text-sm font-bold text-slate-900 leading-none">{currentUser.name}</span>
                        <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider mt-1">{currentUser.role.replace('_', ' ')}</span>
                    </div>
                    <button 
                        onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)}
                        className={`h-10 w-10 rounded-xl flex items-center justify-center font-bold border transition-all shadow-sm
                            ${isProfileMenuOpen 
                                ? 'bg-indigo-600 text-white border-indigo-700' 
                                : 'bg-indigo-100 text-indigo-700 border-indigo-200 hover:ring-2 hover:ring-indigo-200'}`}
                        title="Account Profile"
                    >
                        {currentUser.name.charAt(0)}
                    </button>

                    {/* Profile Dropdown Menu */}
                    {isProfileMenuOpen && (
                        <>
                            {/* Overlay for closing menu when clicking outside */}
                            <div 
                                className="fixed inset-0 z-30" 
                                onClick={() => setIsProfileMenuOpen(false)}
                            />
                            <div className="absolute top-full right-0 mt-2 w-64 bg-white rounded-2xl shadow-2xl border border-slate-200 z-40 overflow-hidden animate-scale-in">
                                <div className="p-4 bg-slate-50 border-b border-slate-200">
                                    <p className="text-sm font-bold text-slate-900">{currentUser.name}</p>
                                    <p className="text-xs text-slate-500 font-medium">{currentUser.email}</p>
                                    <div className="mt-2 flex items-center gap-1.5">
                                        <span className="px-2 py-0.5 bg-indigo-100 text-indigo-700 text-[10px] font-bold uppercase rounded-md">
                                            {currentUser.role.replace('_', ' ')}
                                        </span>
                                    </div>
                                </div>
                                <div className="p-2">
                                    <button 
                                        onClick={() => { setActiveTab('Settings'); setIsProfileMenuOpen(false); }}
                                        className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
                                    >
                                        <User size={18} className="text-slate-400" />
                                        <span>My Profile</span>
                                    </button>
                                    <button 
                                        onClick={() => { setActiveTab('Settings'); setIsProfileMenuOpen(false); }}
                                        className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
                                    >
                                        <SettingsIcon size={18} className="text-slate-400" />
                                        <span>System Settings</span>
                                    </button>
                                    <div className="my-1 border-t border-slate-100" />
                                    <button 
                                        onClick={handleLogout}
                                        className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-rose-600 hover:bg-rose-50 rounded-lg transition-colors font-medium"
                                    >
                                        <LogOut size={18} className="text-rose-500" />
                                        <span>Sign Out</span>
                                    </button>
                                </div>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </header>
        <div className="flex-1 overflow-auto p-6 relative">
            {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Category, InventoryItem } from '../types';
import { 
  Plus, Search, Filter, Edit2, Trash2, Eye, EyeOff, Layers, Grid, List, 
  ChevronLeft, ArrowRight, Package, Check, X 
} from 'lucide-react';

interface CategoriesProps {
    categories?: Category[];
    setCategories?: React.Dispatch<React.SetStateAction<Category[]>>;
    inventory?: InventoryItem[];
    setInventory?: React.Dispatch<React.SetStateAction<InventoryItem[]>>;
}

const Categories: React.FC<CategoriesProps> = ({ 
    categories = [], 
    setCategories,
    inventory = [],
    setInventory
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'List' | 'Grid'>('List');
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);

  // Create Category State
  const [newCat, setNewCat] = useState({ name: '', pos: true, online: true });

  // Add Item State
  const [showItemPicker, setShowItemPicker] = useState(false);
  const [itemSearch, setItemSearch] = useState('');

  const filteredCategories = categories.filter(cat => 
      cat.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAddCategory = () => {
    if (!newCat.name.trim() || !setCategories) return;

    const category: Category = {
        id: `CAT-${Date.now()}`,
        name: newCat.name,
        itemsCount: 0,
        modifierGroups: [],
        showOnPos: newCat.pos,
        showOnline: newCat.online
    };

    setCategories(prev => [...prev, category]);
    setShowAddModal(false);
    setNewCat({ name: '', pos: true, online: true });
  };

  const handleAddItemToCategory = (itemId: string) => {
    if (!selectedCategory || !setInventory) return;

    setInventory(prev => prev.map(item => 
        item.id === itemId ? { ...item, category: selectedCategory.name } : item
    ));

    if (setCategories) {
        setCategories(prev => prev.map(cat => 
            cat.id === selectedCategory.id ? { ...cat, itemsCount: cat.itemsCount + 1 } : cat
        ));
    }
  };

  const removeItemFromCategory = (itemId: string) => {
    if (!selectedCategory || !setInventory) return;

    setInventory(prev => prev.map(item => 
        item.id === itemId ? { ...item, category: 'Uncategorized' } : item
    ));

    if (setCategories) {
        setCategories(prev => prev.map(cat => 
            cat.id === selectedCategory.id ? { ...cat, itemsCount: Math.max(0, cat.itemsCount - 1) } : cat
        ));
    }
  };

  // Drilled-down View
  if (selectedCategory) {
      const categoryItems = inventory.filter(i => i.category === selectedCategory.name);
      const availableItems = inventory.filter(i => i.category !== selectedCategory.name && 
          i.name.toLowerCase().includes(itemSearch.toLowerCase()));

      return (
          <div className="space-y-6 animate-fade-in h-full flex flex-col">
              <div className="flex items-center justify-between">
                  <button 
                      onClick={() => setSelectedCategory(null)}
                      className="flex items-center gap-2 text-slate-500 hover:text-indigo-600 font-bold transition-colors"
                  >
                      <ChevronLeft size={20} /> BACK TO CATEGORIES
                  </button>
                  <div className="flex gap-3">
                      <button 
                          onClick={() => setShowItemPicker(true)}
                          className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm font-bold text-sm"
                      >
                          <Plus size={18} /> ADD ITEMS
                      </button>
                  </div>
              </div>

              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6">
                  <div className="flex justify-between items-start mb-6">
                      <div>
                          <h1 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCategory.name}</h1>
                          <p className="text-slate-500 font-medium">{categoryItems.length} Items in this category</p>
                      </div>
                      <div className="flex gap-2">
                          <span className={`px-3 py-1 rounded-full text-xs font-bold border ${selectedCategory.showOnPos ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                              {selectedCategory.showOnPos ? 'VISIBLE ON POS' : 'HIDDEN ON POS'}
                          </span>
                      </div>
                  </div>

                  <div className="space-y-3">
                      <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Current Items</h3>
                      {categoryItems.length === 0 ? (
                          <div className="p-12 text-center border-2 border-dashed border-slate-100 rounded-2xl text-slate-400 font-medium">
                              No items currently assigned to this category.
                          </div>
                      ) : (
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                              {categoryItems.map(item => (
                                  <div key={item.id} className="p-4 bg-slate-50 rounded-xl border border-slate-200 flex justify-between items-center group">
                                      <div>
                                          <p className="font-bold text-slate-900">{item.name}</p>
                                          <p className="text-xs text-slate-500">${item.price.toFixed(2)}</p>
                                      </div>
                                      <button 
                                        onClick={() => removeItemFromCategory(item.id)}
                                        className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                                      >
                                          <X size={18} />
                                      </button>
                                  </div>
                              ))}
                          </div>
                      )}
                  </div>
              </div>

              {/* Item Picker Modal */}
              {showItemPicker && (
                  <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[80vh] animate-scale-in">
                          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                              <h3 className="text-xl font-black text-slate-800 tracking-tight">ADD ITEMS TO {selectedCategory.name}</h3>
                              <button onClick={() => setShowItemPicker(false)} className="text-slate-400 hover:text-slate-600 transition-colors">
                                  <X size={24} />
                              </button>
                          </div>
                          <div className="p-4 bg-white border-b border-slate-100">
                              <div className="relative">
                                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                                  <input 
                                      type="text" 
                                      placeholder="Search inventory..."
                                      value={itemSearch}
                                      onChange={e => setItemSearch(e.target.value)}
                                      className="w-full pl-10 pr-4 py-2 bg-slate-100 border-transparent rounded-xl outline-none focus:bg-white focus:ring-2 focus:ring-indigo-500"
                                  />
                              </div>
                          </div>
                          <div className="flex-1 overflow-y-auto p-4 space-y-2 bg-slate-50">
                              {availableItems.map(item => (
                                  <div key={item.id} className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center hover:border-indigo-500 transition-colors">
                                      <div className="flex items-center gap-4">
                                          <div className="h-10 w-10 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600 font-black">
                                              {item.name.charAt(0)}
                                          </div>
                                          <div>
                                              <p className="font-bold text-slate-900">{item.name}</p>
                                              <p className="text-xs text-slate-400 font-bold uppercase">{item.category}</p>
                                          </div>
                                      </div>
                                      <button 
                                          onClick={() => handleAddItemToCategory(item.id)}
                                          className="px-4 py-2 bg-slate-100 text-indigo-600 font-black text-xs rounded-xl hover:bg-indigo-600 hover:text-white transition-all uppercase tracking-widest"
                                      >
                                          Select
                                      </button>
                                  </div>
                              ))}
                          </div>
                          <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end">
                              <button onClick={() => setShowItemPicker(false)} className="px-6 py-2 bg-slate-900 text-white font-black text-sm rounded-xl">DONE</button>
                          </div>
                      </div>
                  </div>
              )}
          </div>
      );
  }

  return (
    <div className="space-y-6 animate-fade-in relative">
      {/* Create Modal */}
      {showAddModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-scale-in">
                  <div className="p-6 border-b border-slate-100 bg-slate-50/50">
                      <h3 className="text-xl font-black text-slate-800 tracking-tight">NEW CATEGORY</h3>
                  </div>
                  <div className="p-8 space-y-6">
                      <div>
                          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Category Name</label>
                          <input 
                              type="text" 
                              value={newCat.name}
                              onChange={e => setNewCat({...newCat, name: e.target.value})}
                              placeholder="e.g., Seasonal Specials"
                              className="w-full border border-slate-300 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
                          />
                      </div>
                      <div className="space-y-4 pt-4 border-t border-slate-100">
                          <label className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-200 cursor-pointer">
                              <div>
                                  <p className="text-sm font-black text-slate-800 uppercase tracking-tight">Show on POS</p>
                                  <p className="text-xs text-slate-500 font-medium">Visible on register terminals</p>
                              </div>
                              <button 
                                onClick={() => setNewCat({...newCat, pos: !newCat.pos})}
                                className={`w-12 h-6 rounded-full relative transition-all ${newCat.pos ? 'bg-indigo-600' : 'bg-slate-300'}`}
                              >
                                  <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${newCat.pos ? 'translate-x-6' : ''}`} />
                              </button>
                          </label>
                          <label className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-200 cursor-pointer">
                              <div>
                                  <p className="text-sm font-black text-slate-800 uppercase tracking-tight">Show Online</p>
                                  <p className="text-xs text-slate-500 font-medium">Visible on web store</p>
                              </div>
                              <button 
                                onClick={() => setNewCat({...newCat, online: !newCat.online})}
                                className={`w-12 h-6 rounded-full relative transition-all ${newCat.online ? 'bg-indigo-600' : 'bg-slate-300'}`}
                              >
                                  <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform ${newCat.online ? 'translate-x-6' : ''}`} />
                              </button>
                          </label>
                      </div>
                  </div>
                  <div className="p-6 bg-slate-50 flex gap-3">
                      <button onClick={() => setShowAddModal(false)} className="flex-1 py-4 text-slate-400 font-black text-xs uppercase tracking-widest">Cancel</button>
                      <button 
                        onClick={handleAddCategory}
                        className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-100"
                      >
                          CREATE
                      </button>
                  </div>
              </div>
          </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Categories</h1>
          <p className="text-slate-500">Organize menu items and control visibility</p>
        </div>
        <div className="flex gap-2">
            <div className="bg-white border border-slate-300 rounded-lg p-1 flex shadow-sm">
                <button 
                    onClick={() => setViewMode('List')}
                    className={`p-1.5 rounded-md transition-all ${viewMode === 'List' ? 'bg-indigo-50 text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    <List size={18} />
                </button>
                <button 
                    onClick={() => setViewMode('Grid')}
                    className={`p-1.5 rounded-md transition-all ${viewMode === 'Grid' ? 'bg-indigo-50 text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    <Grid size={18} />
                </button>
            </div>
            <button 
                onClick={() => setShowAddModal(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all font-bold active:scale-95"
            >
                <Plus size={18} /> Add Category
            </button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder="Search categories..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
        </div>
        <button className="flex items-center gap-2 px-4 py-2 bg-slate-100 rounded-lg text-slate-600 hover:bg-slate-200 font-medium">
            <Filter size={18} /> Filter
        </button>
      </div>

      {viewMode === 'List' ? (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 border-b border-slate-200 text-slate-500 font-black uppercase text-[10px] tracking-widest">
                <tr>
                  <th className="px-6 py-4">Category Name</th>
                  <th className="px-6 py-4">ID</th>
                  <th className="px-6 py-4 text-right">Items</th>
                  <th className="px-6 py-4 text-center">POS</th>
                  <th className="px-6 py-4 text-center">Online</th>
                  <th className="px-6 py-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredCategories.map(cat => (
                  <tr 
                    key={cat.id} 
                    onClick={() => setSelectedCategory(cat)}
                    className="hover:bg-indigo-50/30 group cursor-pointer transition-colors"
                  >
                    <td className="px-6 py-4">
                        <span className="font-bold text-slate-900 text-base">{cat.name}</span>
                    </td>
                    <td className="px-6 py-4 text-slate-500 font-mono text-xs uppercase">
                      {cat.id}
                    </td>
                    <td className="px-6 py-4 text-right font-black text-indigo-600">
                      {cat.itemsCount}
                    </td>
                    <td className="px-6 py-4 text-center">
                        <div className={`mx-auto h-2 w-2 rounded-full ${cat.showOnPos ? 'bg-emerald-500' : 'bg-slate-300'}`} />
                    </td>
                    <td className="px-6 py-4 text-center">
                        <div className={`mx-auto h-2 w-2 rounded-full ${cat.showOnline ? 'bg-emerald-500' : 'bg-slate-300'}`} />
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-white border border-transparent hover:border-slate-100 rounded-lg transition-all shadow-sm">
                                <ArrowRight size={16} />
                            </button>
                        </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
      ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredCategories.map(cat => (
                  <div 
                    key={cat.id} 
                    onClick={() => setSelectedCategory(cat)}
                    className="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm hover:shadow-xl hover:border-indigo-300 transition-all group relative cursor-pointer active:scale-95"
                  >
                      <div className="flex justify-between items-start mb-4">
                          <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl group-hover:scale-110 transition-transform shadow-inner">
                              <Layers size={24} />
                          </div>
                          <div className="flex gap-1">
                              {cat.showOnPos && <span className="h-2 w-2 bg-emerald-500 rounded-full" title="POS" />}
                              {cat.showOnline && <span className="h-2 w-2 bg-blue-500 rounded-full" title="Web" />}
                          </div>
                      </div>
                      <h3 className="font-black text-slate-800 text-lg mb-1 uppercase tracking-tight">{cat.name}</h3>
                      <p className="text-xs text-slate-400 font-mono mb-4">{cat.id}</p>
                      <div className="border-t border-slate-100 pt-4 flex justify-between items-center">
                          <span className="text-xs font-black text-indigo-600 bg-indigo-50 px-2 py-1 rounded-lg">{cat.itemsCount} ITEMS</span>
                          <button className="text-slate-400 hover:text-indigo-600 transition-colors">
                              <ArrowRight size={18} />
                          </button>
                      </div>
                  </div>
              ))}
          </div>
      )}
    </div>
  );
};

export default Categories;

