} from './types';
import {
  MOCK_EMPLOYEES, MOCK_DETAILED_ORDERS, MOCK_TRANSACTIONS, MOCK_CUSTOMERS,
  MOCK_INVENTORY_ITEMS, MOCK_CATEGORIES, MOCK_TABLES, MOCK_RESERVATIONS,
  MOCK_SCHEDULES, MOCK_FLOOR_TABLES, MOCK_KDS_SETTINGS, MOCK_HOURLY_SALES,
  MOCK_SALES_SUMMARY, MOCK_DEPOSITS, MOCK_TAX_REPORTS, MOCK_DISCOUNTS,
  MOCK_CASH_LOGS, MOCK_STATEMENTS, MOCK_REPORT_REQUESTS, MOCK_REVENUE_ITEMS,
  MOCK_FLOOR_PLAN, MOCK_RECEIPT_SETTINGS
} from './constants';

// Component Imports
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import CashierPOS from './components/CashierPOS';
import Orders from './components/Orders';
import Transactions from './components/Transactions';
import CashLog from './components/CashLog';
import Invoices from './components/Invoices';
import RecurringPayments from './components/RecurringPayments';
import SalesReports from './components/SalesReports';
import EmployeeSalesReport from './components/EmployeeSalesReport';
import GiftCardReport from './components/GiftCardReport';
import RemovedItems from './components/RemovedItems';
import ItemSales from './components/ItemSales';
import PeerInsights from './components/PeerInsights';
import FinancesOverview from './components/FinancesOverview';
import Closeout from './components/Closeout';
import Deposits from './components/Deposits';
import Disputes from './components/Disputes';
import PayBills from './components/PayBills';
import Documents from './components/Documents';
import Items from './components/Items';
import Categories from './components/Categories';
import ModifierGroups from './components/ModifierGroups';
import PrinterLabels from './components/PrinterLabels';
import Discounts from './components/Discounts';
import Employees from './components/Employees';
import Customers from './components/Customers';
