interface OrderOptionSettings {
  autoGroupItems: boolean;
  allowNotes: boolean;
  stayInCategory: boolean;
  trackRemovalReasons: boolean;
}

interface OrderReceiptSettings {
  requirePasscodeReprint: boolean;
  printVoidReceipt: boolean;
  fontSize: 'Small' | 'Medium' | 'Large';
  orderNumbers: 'None' | 'Manual' | 'Automatic';
  addBlankLines: boolean;
  blankLinesCount: number;
  showOrderNote: boolean;
