import React, { useState } from 'react';
import { Category, InventoryItem } from '../types';
import { 
  Plus, Search, Filter, Edit2, Trash2, Eye, EyeOff, Layers, Grid, List, 
  ChevronLeft, ArrowRight, Package, Check, X 
} from 'lucide-react';

interface CategoriesProps {
    categories?: Category[];
    setCategories?: React.Dispatch<React.SetStateAction<Category[]>>;
    inventory?: InventoryItem[];
    setInventory?: React.Dispatch<React.SetStateAction<InventoryItem[]>>;
}

const Categories: React.FC<CategoriesProps> = ({ 
    categories = [], 
    setCategories,
    inventory = [],
    setInventory
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'List' | 'Grid'>('List');
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);

  // Create Category State
  const [newCat, setNewCat] = useState({ name: '', pos: true, online: true });

  // Add Item State
  const [showItemPicker, setShowItemPicker] = useState(false);
  const [itemSearch, setItemSearch] = useState('');

  const filteredCategories = categories.filter(cat => 
      cat.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAddCategory = () => {
    if (!newCat.name.trim() || !setCategories) return;

    const category: Category = {
        id: `CAT-${Date.now()}`,
        name: newCat.name,
        itemsCount: 0,
        modifierGroups: [],
        showOnPos: newCat.pos,
        showOnline: newCat.online
    };

    setCategories(prev => [...prev, category]);
    setShowAddModal(false);
    setNewCat({ name: '', pos: true, online: true });
  };

  const handleAddItemToCategory = (itemId: string) => {
    if (!selectedCategory || !setInventory) return;

    setInventory(prev => prev.map(item => 
        item.id === itemId ? { ...item, category: selectedCategory.name } : item
    ));

    if (setCategories) {
        setCategories(prev => prev.map(cat => 
            cat.id === selectedCategory.id ? { ...cat, itemsCount: cat.itemsCount + 1 } : cat
        ));
    }
  };

  const removeItemFromCategory = (itemId: string) => {
    if (!selectedCategory || !setInventory) return;

    setInventory(prev => prev.map(item => 
        item.id === itemId ? { ...item, category: 'Uncategorized' } : item
    ));

    if (setCategories) {
        setCategories(prev => prev.map(cat => 
            cat.id === selectedCategory.id ? { ...cat, itemsCount: Math.max(0, cat.itemsCount - 1) } : cat
