import { MOCK_INVENTORY_ITEMS, MOCK_CATEGORIES, MOCK_EMPLOYEES, MOCK_FLOOR_TABLES, MOCK_ROLES, MOCK_PASSCODE_SETTINGS } from '../constants';

/**
 * BytePos IndexedDB Service
 * Designed for high-traffic data handling and persistence.
 */
class DatabaseService {
  private dbName = 'BytePosDB';
  private version = 1;

  async getDB(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.version);

      request.onupgradeneeded = (event: any) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains('inventory')) db.createObjectStore('inventory', { keyPath: 'id' });
        if (!db.objectStoreNames.contains('categories')) db.createObjectStore('categories', { keyPath: 'id' });
        if (!db.objectStoreNames.contains('employees')) db.createObjectStore('employees', { keyPath: 'id' });
        if (!db.objectStoreNames.contains('orders')) db.createObjectStore('id');
        if (!db.objectStoreNames.contains('dining')) db.createObjectStore('id');
        if (!db.objectStoreNames.contains('settings')) db.createObjectStore('key');
      };

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async getAll<T>(storeName: string): Promise<T[]> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(storeName, 'readonly');
      const store = transaction.objectStore(storeName);
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async put(storeName: string, data: any): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(storeName, 'readwrite');
      const store = transaction.objectStore(storeName);
      const request = store.put(data);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async delete(storeName: string, id: string): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(storeName, 'readwrite');
      const store = transaction.objectStore(storeName);
      const request = store.delete(id);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  /**
   * Seed the database with initial data if empty
   */
  async seed() {
    const inv = await this.getAll('inventory');
    if (inv.length === 0) {
      console.log("Seeding Database...");
      for (const item of MOCK_INVENTORY_ITEMS) await this.put('inventory', item);
      for (const cat of MOCK_CATEGORIES) await this.put('categories', cat);
      for (const emp of MOCK_EMPLOYEES) await this.put('employees', emp);
      for (const table of MOCK_FLOOR_TABLES) await this.put('dining', table);
      await this.put('settings', { key: 'passcode', ...MOCK_PASSCODE_SETTINGS });
    }
  }
}

export const db = new DatabaseService();

import { db } from '../services/db';
import { InventoryItem, Category } from '../types';

export const InventoryAPI = {
  async getItems(): Promise<InventoryItem[]> {
    return db.getAll<InventoryItem>('inventory');
  },

  async saveItem(item: InventoryItem): Promise<void> {
    await db.put('inventory', item);
  },

  async getCategories(): Promise<Category[]> {
    return db.getAll<Category>('categories');
  },

  async saveCategory(category: Category): Promise<void> {
    await db.put('categories', category);
  },

  async addItemToCategory(itemId: string, categoryName: string): Promise<void> {
    const items = await this.getItems();
    const item = items.find(i => i.id === itemId);
    if (item) {
      item.category = categoryName;
      await this.saveItem(item);

      // Update item count in category
      const categories = await this.getCategories();
      const cat = categories.find(c => c.name === categoryName);
      if (cat) {
        cat.itemsCount += 1;
        await this.saveCategory(cat);
      }
    }
  }
};

import { db } from '../services/db';
import { DiningTable } from '../types';

export const DiningAPI = {
  async getFloorPlan(): Promise<DiningTable[]> {
    return db.getAll<DiningTable>('dining');
  },

  async updateTable(table: DiningTable): Promise<void> {
    await db.put('dining', table);
  },

  async saveFullFloorPlan(tables: DiningTable[]): Promise<void> {
    // High traffic optimization: use a single transaction if possible
    // For simplicity with our db wrapper, we loop
    for (const table of tables) {
      await db.put('dining', table);
    }
  },

  async seatTable(tableId: string, employeeId: string, employeeName: string): Promise<void> {
    const tables = await this.getFloorPlan();
    const table = tables.find(t => t.id === tableId);
    if (table && table.status === 'Available') {
      table.status = 'Occupied';
      table.employeeId = employeeId;
      table.assignedToName = employeeName;
      table.timeSeated = new Date().toISOString();
      await this.updateTable(table);
    }
  }
};

