const Refunds: React.FC = () => {
    const [searchTerm, setSearchTerm] = useState('');
    const [foundOrder, setFoundOrder] = useState<DetailedOrder | null>(null);
    const [refundAmount, setRefundAmount] = useState(0);
    const [reason, setReason] = useState('');
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');

    const handleSearch = async () => {
        const orders = await OrdersAPI.getOrders();
        const match = orders.find(o => o.id === searchTerm || o.cardLast4 === searchTerm);
        setFoundOrder(match || null);
        if (match) setRefundAmount(match.total);
    };

    const handleRefund = async () => {
        if (!foundOrder) return;
        setStatus('processing');
        const success = await RefundsAPI.processRefund(foundOrder.id, refundAmount, reason);
        if (success) {
            setStatus('success');
            setTimeout(() => {
                setStatus('idle');
                setFoundOrder(null);
                setSearchTerm('');
            }, 2000);
        }
    };

    return (
        <div className="max-w-2xl mx-auto space-y-6 animate-fade-in">
            <div className="text-center">
                <div className="h-16 w-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
