                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="Enter Order ID or Last 4 Digits..."
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-xl outline-none focus:ring-2 focus:ring-red-500"
                        />
                    </div>
                    <button onClick={handleSearch} className="px-6 py-3 bg-slate-800 text-white font-bold rounded-xl hover:bg-slate-700">FIND</button>
                </div>

                {foundOrder && (
                    <div className="pt-4 border-t border-slate-100 space-y-4 animate-scale-in">
                        <div className="flex justify-between items-center p-4 bg-slate-50 rounded-xl border border-slate-200">
