                        </div>

                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Refund Amount</label>
                            <input 
                                type="number" 
                                value={refundAmount}
                                onChange={e => setRefundAmount(parseFloat(e.target.value))}
                                className="w-full border border-slate-300 rounded-xl px-4 py-3 font-bold text-lg"
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Reason for Refund</label>
                            <select value={reason} onChange={e => setReason(e.target.value)} className="w-full border border-slate-300 rounded-xl px-4 py-3 bg-white">
                                <option value="">Select a reason...</option>
                                <option>Customer Dissatisfaction</option>
                                <option>Order Error</option>
                                <option>Out of Stock</option>
                                <option>Accidental Charge</option>
                            </select>
                        </div>

                        <button 
                            onClick={handleRefund}
                            disabled={status !== 'idle' || !reason}
                            className={`w-full py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all
                                ${status === 'success' ? 'bg-emerald-500 text-white' : 'bg-red-600 text-white hover:bg-red-700 disabled:opacity-50'}`}
                        >
                            {status === 'processing' ? 'PROCESSING...' : status === 'success' ? 'REFUND COMPLETE' : 'CONFIRM REFUND'}
                        </button>
                    </div>
                )}
            </div>
