import { db } from '../services/db';
// Fix: Added DetailedOrder to imports to correctly type objects from the 'orders' store
import { Transaction, DetailedOrder } from '../types';

export const TransactionsAPI = {
  async getTransactions(): Promise<Transaction[]> {
    // Fix: The 'orders' store contains DetailedOrder objects. Using DetailedOrder as the generic type
    // ensures properties like total, status, paymentMethod, and employeeName are available.
    const txns = await db.getAll<DetailedOrder>('orders'); // Logic maps orders to transactions for summary
    return txns.map(t => ({
      id: t.id,
      date: t.date,
      // Fix: Accessing 'total' property from DetailedOrder (Error line 11)
      amount: t.total,
      // Fix: Accessing 'status' property from DetailedOrder (Error line 12)
      type: t.status === 'Paid' ? 'Sale' : 'Refund',
      // Fix: Accessing 'paymentMethod' property from DetailedOrder (Error line 13)
      method: t.paymentMethod as any,
      // Fix: Accessing 'employeeName' property from DetailedOrder (Error line 14)
      employeeId: t.employeeName
    }));
  },

  async logTransaction(txn: Transaction): Promise<void> {
    // In high traffic, we would use a separate store, but for consistency:
    await db.put('orders', { ...txn, total: txn.amount, status: txn.type === 'Sale' ? 'Paid' : 'Refunded' });
  }
};

import { db } from '../services/db';
import { CashLogEntry } from '../types';

export const CashLogAPI = {
  async getLogs(): Promise<CashLogEntry[]> {
    return db.getAll<CashLogEntry>('cashlog');
  },

  async recordEntry(entry: CashLogEntry): Promise<void> {
    await db.put('cashlog', entry);
  },

  async reconcileDrawer(id: string, closingAmount: number): Promise<void> {
    const logs = await this.getLogs();
    const log = logs.find(l => l.id === id);
    if (log) {
      log.closingAmount = closingAmount;
      log.variance = closingAmount - (log.openingAmount + log.cashSales - log.cashDrops);
      await db.put('cashlog', log);
    }
  }
};

