export const DiscountsAPI = {
  async getDiscounts(): Promise<DiscountCode[]> {
    return db.getAll<DiscountCode>('discounts');
  },

  async trackUsage(id: string): Promise<void> {
    const all = await this.getDiscounts();
    const disc = all.find(d => d.id === id);
    if (disc) {
      disc.usageCount = (disc.usageCount || 0) + 1;
      await db.put('discounts', disc);
    }
  },

  async getGiftCardHistory(): Promise<GiftCardTransaction[]> {
    return db.getAll<GiftCardTransaction>('giftcard_txns');
  }
};

