import { db } from '../services/db';
import { PermissionItem, PermissionGroup } from '../types';
import { MOCK_PERMISSIONS, MOCK_PERMISSION_GROUPS } from '../constants';

export const PermissionsAPI = {
  async getPermissions(): Promise<PermissionItem[]> {
    const perms = await db.getAll<PermissionItem>('permissions');
    return perms.length > 0 ? perms : MOCK_PERMISSIONS;
  },

  async getGroups(): Promise<PermissionGroup[]> {
    const groups = await db.getAll<PermissionGroup>('permission_groups');
    return groups.length > 0 ? groups : MOCK_PERMISSION_GROUPS;
  },

  async savePermission(perm: PermissionItem): Promise<void> {
    await db.put('permissions', perm);
  },

  async updateEmployeePermissions(employeeId: string, permissions: string[]): Promise<void> {
    const employees = await db.getAll<any>('employees');
    const emp = employees.find(e => e.id === employeeId);
    if (emp) {
      emp.permissions = permissions;
      await db.put('employees', emp);
    }
  }
};

