      subItems: [
        { label: 'Item Library', permission: 'ACCESS_INVENTORY' },
        { label: 'Categories', permission: 'ACCESS_INVENTORY' },
        { label: 'Modifier Groups', permission: 'ACCESS_INVENTORY' }
      ] 
    },
    { 
      id: 'Employees', 
      label: 'Employees', 
      icon: <Users size={20} />, 
      permission: 'ACCESS_SHIFTS',
      subItems: [
        { label: 'Employee List', permission: 'ACCESS_SETUP' },
        { label: 'Schedule', permission: 'ACCESS_SHIFTS' },
        { label: 'Time Clock', permission: 'ACCESS_SHIFTS' }
      ] 
    },
    { id: 'Customers', label: 'Customers', icon: <User size={20} />, permission: 'ACCESS_CUSTOMERS' },
    { 
      id: 'More', 
      label: 'More', 
      icon: <MoreHorizontal size={20} />, 
      permission: 'ACCESS_APP_MARKET',
      subItems: [
        { label: 'Byte Dinning', permission: 'ACCESS_DINING' },
        { label: 'App Market', permission: 'ACCESS_APP_MARKET' }
      ] 
    },
  ];

  const filteredMenuItems = menuItems.filter(item => hasPermission(item.permission));

  const renderSidebar = () => (
    <aside className={`bg-slate-900 text-slate-300 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} shrink-0 h-screen overflow-hidden`}>
      <div className="p-4 border-b border-slate-800 flex items-center justify-between">
        {isSidebarOpen && <span className="font-bold text-white text-lg tracking-tight">OmniCommand</span>}
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white">
          <Menu size={20} />
        </button>
      </div>

      <nav className="flex-1 overflow-y-auto py-4 space-y-1">
        {filteredMenuItems.map((item) => (
          <div key={item.id}>
            {item.subItems ? (
              <>
                <button
                  onClick={() => isSidebarOpen ? (setExpandedMenu(expandedMenu === item.id ? null : item.id)) : setActiveTab(item.id)}
                  className={`w-full flex items-center justify-between px-4 py-3 hover:bg-slate-800 hover:text-white transition-colors
                    ${activeTab === item.id || (item.subItems.some(sub => activeTab === sub.label)) ? 'text-white bg-slate-800' : ''}`}
                >
                  <div className="flex items-center gap-3">
                    {item.icon}
                    {isSidebarOpen && <span className="font-medium text-sm">{item.label}</span>}
                  </div>
                  {isSidebarOpen && (expandedMenu === item.id ? <ChevronDown size={16} /> : <ChevronRight size={16} />)}
                </button>
                {isSidebarOpen && expandedMenu === item.id && (
                  <div className="bg-slate-950 py-1">
                    {item.subItems.filter(sub => hasPermission(sub.permission)).map((sub) => (
                      <button
                        key={sub.label}
                        onClick={() => setActiveTab(sub.label)}
                        className={`w-full text-left pl-12 pr-4 py-2 text-sm hover:text-white transition-colors
                          ${activeTab === sub.label ? 'text-indigo-400 font-medium' : 'text-slate-500'}`}
                      >
                        {sub.label}
                      </button>
                    ))}
                  </div>
                )}
              </>
            ) : (
              <button
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-800 hover:text-white transition-colors
                  ${activeTab === item.id ? 'text-white bg-slate-800 border-l-4 border-indigo-500' : ''}`}
              >
                {item.icon}
                {isSidebarOpen && <span className="font-medium text-sm">{item.label}</span>}
              </button>
            )}
          </div>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-800">
        <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
          <LogOut size={20} />
          {isSidebarOpen && <span className="font-medium text-sm">Sign Out</span>}
        </button>
      </div>
    </aside>
  );

  const renderContent = () => {
    if (!currentUser) return null;
    switch(activeTab) {
      case 'Launcher': return <AppLauncher user={currentUser} onSelectApp={setActiveTab} />;
      case 'Home': return <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />;
      case 'New Sale': return <Register />;
      case 'Sales Activity': return <SalesActivity />;
      case 'Orders': return <Orders orders={orders} />;
      case 'Transactions': return <Transactions transactions={transactions} />;
      case 'Cash Log': return <CashLog logs={MOCK_CASH_LOGS} />;
      case 'Invoices': return <Invoices />;
      case 'Recurring Payments': return <RecurringPayments />;
      case 'Refund': return <Refunds />;
      case 'Sales Report': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} />;
      case 'Employee Sales': return <EmployeeSalesReport />;
      case 'Peer Insights': return <PeerInsights totalSales={10000} transactionCount={150} customers={customers} />;
      case 'Item Sales': return <ItemSales />;
      case 'Removed Items': return <RemovedItems />;
      case 'Gift Cards Report': return <GiftCardReport />;
      case 'Overview': return <FinancesOverview />;
      case 'Closeout': return <Closeout />;
      case 'Deposits': return <Deposits />;
      case 'Disputes': return <Disputes />;
      case 'Pay Bills': return <PayBills />;
      case 'Statements': return <Documents statements={MOCK_STATEMENTS} reports={MOCK_REPORT_REQUESTS} />;
      case 'Item Library': return <Items items={inventory} />;
      case 'Categories': return <Categories categories={categories} inventory={inventory} setCategories={setCategories} setInventory={setInventory} />;
      case 'Modifier Groups': return <ModifierGroups />;
      case 'Printer Labels': return <PrinterLabels />;
      case 'Discounts': return <Discounts discounts={discounts} setDiscounts={setDiscounts} />;
      case 'Employee List': return <Employees employees={employeesState} />;
      case 'Schedule': return <SchedulingApp schedules={[]} />;
      case 'Time Clock': return <TimeClock />;
      case 'Customer List': return <Customers customers={customers} />;
      case 'Feedback': return <ReceiptFeedback />;
      case 'Byte Dinning': return <DiningDashboard initialTables={floorPlanTables} onSaveFloorPlan={handleSaveFloorPlan} />;
      case 'App Market': return <AppMarket />;
      case 'Settings': return <Settings floorPlanTables={floorPlanTables} onSaveFloorPlan={handleSaveFloorPlan} />;
      case 'SuperAdmin': return <SuperAdmin />;
      default: return <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />;
    }
  };

  if (isInitializing) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-white">
        <Loader2 size={48} className="animate-spin text-indigo-500 mb-4" />
        <h1 className="text-xl font-bold tracking-tighter">OMNICOMMAND OS</h1>
        <p className="text-slate-400 text-sm mt-2">Connecting to Secure Backend Services...</p>
      </div>
    );
  }

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">
      {renderSidebar()}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shrink-0 z-20 shadow-sm">
            <h2 className="font-bold text-lg text-slate-800 uppercase tracking-tight">{activeTab}</h2>
            <div className="flex items-center gap-6">
                <div className="flex items-center gap-3 border-r border-slate-200 pr-6 mr-2">
                    <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-lg relative">
                        <Bell size={20} />
                        <span className="absolute top-2 right-2 h-2 w-2 bg-red-500 rounded-full border-2 border-white"></span>
                    </button>
                    {hasPermission('ACCESS_SETUP') && (
                        <button onClick={() => setActiveTab('Settings')} className={`p-2 rounded-lg ${activeTab === 'Settings' ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:text-indigo-600'}`}>
                            <SettingsIcon size={20} />
                        </button>
                    )}
                </div>
                <div className="flex items-center gap-3 relative">
                    <button onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)} className="h-10 w-10 rounded-xl bg-indigo-100 text-indigo-700 flex items-center justify-center font-bold border border-indigo-200">
                        {currentUser.name.charAt(0)}
                    </button>
                    {isProfileMenuOpen && (
                        <div className="absolute top-full right-0 mt-2 w-64 bg-white rounded-2xl shadow-2xl border border-slate-200 z-40 overflow-hidden animate-scale-in">
                            <div className="p-4 bg-slate-50 border-b border-slate-200">
                                <p className="text-sm font-bold text-slate-900">{currentUser.name}</p>
                                <p className="text-xs text-slate-500 font-medium">{currentUser.email}</p>
                                <span className="mt-1 inline-block text-[10px] font-black uppercase tracking-widest bg-indigo-100 text-indigo-700 px-1.5 py-0.5 rounded">{currentUser.role}</span>
                            </div>
                            <div className="p-2">
                                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-rose-600 hover:bg-rose-50 rounded-lg font-medium">
                                    <LogOut size={18} />
                                    <span>Sign Out</span>
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </header>
        <div className="flex-1 overflow-auto p-6 relative">
            {renderContent()}
        </div>
      </main>
    </div>
  );
};

