import React, { useState } from 'react';
import { Employee, UserRole, Role, RolePermission, PermissionItem, PermissionGroup, RoleAssignmentRequest, PasscodeSettings } from '../types';
import { Plus, Search, Edit2, Trash2, X, User, Shield, DollarSign, Lock, CheckCircle, Settings, Users, Key, Grid, Briefcase, XCircle, Mail, BadgeAlert, Check, ShieldCheck } from 'lucide-react';
import { MOCK_ROLES, MOCK_PERMISSIONS, MOCK_ROLE_PERMISSIONS, MOCK_PERMISSION_GROUPS, MOCK_ROLE_ASSIGNMENT_REQUESTS, MOCK_PASSCODE_SETTINGS } from '../constants';
import { PermissionsAPI } from '../api/permissions';

interface EmployeesProps {
  employees: Employee[];
  onAddEmployee?: (employee: Employee) => void;
  onUpdateEmployee?: (employee: Employee) => void;
  onDeleteEmployee?: (id: string) => void;
}

const Employees: React.FC<EmployeesProps> = ({ employees, onAddEmployee, onUpdateEmployee, onDeleteEmployee }) => {
  const [viewMode, setViewMode] = useState<'Employees' | 'Roles' | 'Matrix' | 'Assignments' | 'Security'>('Employees');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [activeTab, setActiveTab] = useState<'Profile' | 'Role' | 'Permissions' | 'Security'>('Profile');

  const [roles, setRoles] = useState<Role[]>(MOCK_ROLES);
  const [rolePermissions, setRolePermissions] = useState<RolePermission[]>(MOCK_ROLE_PERMISSIONS);
  const [selectedRoleForEdit, setSelectedRoleForEdit] = useState<Role | null>(null);
  const [showRoleEditModal, setShowRoleEditModal] = useState(false);
  const [assignments, setAssignments] = useState<RoleAssignmentRequest[]>(MOCK_ROLE_ASSIGNMENT_REQUESTS);
  const [passcodeSettings, setPasscodeSettings] = useState<PasscodeSettings>(MOCK_PASSCODE_SETTINGS);

  const [currentEmployee, setCurrentEmployee] = useState<Partial<Employee>>({
      role: UserRole.STAFF,
      status: 'Active',
      payType: 'Hourly',
      hourlyRate: 0,
      hoursWorked: 0,
      permissions: [],
      deviceAccess: true
  });
  const [formError, setFormError] = useState<string | null>(null);

  const handleOpenAdd = () => {
    setIsEditing(false);
    setCurrentEmployee({
      role: UserRole.STAFF,
      status: 'Active',
      payType: 'Hourly',
      hourlyRate: 0,
      hoursWorked: 0,
      permissions: [],
      deviceAccess: true
    });
    setFormError(null);
    setActiveTab('Profile');
    setShowModal(true);
  };

  const handleOpenEdit = (emp: Employee) => {
    setIsEditing(true);
    setCurrentEmployee({ ...emp, permissions: emp.permissions || [] });
    setFormError(null);
    setActiveTab('Profile');
    setShowModal(true);
  };

  const handleSaveEmployee = async () => {
      setFormError(null);
      if (!currentEmployee.name || !currentEmployee.email || !currentEmployee.passcode) {
          setFormError("Name, Email, and Passcode are required.");
          return;
      }

      if (isEditing && onUpdateEmployee) {
          onUpdateEmployee(currentEmployee as Employee);
      } else if (!isEditing && onAddEmployee) {
          const employee: Employee = {
              id: `E-${Date.now()}`,
              ...currentEmployee
          } as Employee;
          onAddEmployee(employee);
      }
      setShowModal(false);
  };

  const isEmpPermissionEnabled = (key: string) => {
      return currentEmployee.permissions?.includes(key) || false;
  };

  const toggleEmpPermission = (key: string) => {
      const perms = currentEmployee.permissions || [];
      const newPerms = perms.includes(key) 
          ? perms.filter(p => p !== key) 
          : [...perms, key];
      setCurrentEmployee({ ...currentEmployee, permissions: newPerms });
  };

  const permissionsByCategory = MOCK_PERMISSIONS.reduce((acc, perm) => {
      if (!acc[perm.category]) acc[perm.category] = [];
      acc[perm.category].push(perm);
      return acc;
  }, {} as Record<string, PermissionItem[]>);

  const renderEmployeeModal = () => (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-scale-in">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
              <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
                  <h3 className="font-bold text-lg text-slate-800">{isEditing ? 'Manage Staff Member' : 'Add New Team Member'}</h3>
                  <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-600">
                      <X size={24} />
                  </button>
              </div>

              <div className="flex border-b border-slate-200 overflow-x-auto bg-white">
                  {['Profile', 'Role', 'Permissions', 'Security'].map((tab) => (
                      <button 
                          key={tab}
                          onClick={() => setActiveTab(tab as any)}
                          className={`flex-1 min-w-[100px] py-3 text-xs font-black uppercase tracking-widest border-b-2 transition-colors flex items-center justify-center gap-2
                              ${activeTab === tab ? 'border-indigo-500 text-indigo-600 bg-indigo-50/50' : 'border-transparent text-slate-400 hover:bg-slate-50'}`}
                      >
                          {tab}
                      </button>
                  ))}
              </div>

              <div className="p-6 overflow-y-auto flex-1">
                  {formError && <div className="mb-6 p-4 bg-rose-50 border border-rose-100 rounded-xl text-rose-800 text-sm animate-shake">{formError}</div>}

                  {activeTab === 'Profile' && (
                      <div className="space-y-4">
                          <div>
                              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Full Name</label>
                              <input type="text" value={currentEmployee.name || ''} onChange={e => setCurrentEmployee({...currentEmployee, name: e.target.value})} className="w-full border border-slate-300 rounded-xl px-4 py-2 outline-none focus:ring-2 focus:ring-indigo-500" />
                          </div>
                          <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Email</label>
                                <input type="email" value={currentEmployee.email || ''} onChange={e => setCurrentEmployee({...currentEmployee, email: e.target.value})} className="w-full border border-slate-300 rounded-xl px-4 py-2" />
                            </div>
                            <div>
                                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Role</label>
                                <select value={currentEmployee.role} onChange={e => setCurrentEmployee({...currentEmployee, role: e.target.value})} className="w-full border border-slate-300 rounded-xl px-4 py-2 bg-white">
                                    {roles.map(r => <option key={r.id} value={r.name}>{r.name}</option>)}
                                </select>
                            </div>
                          </div>
                      </div>
                  )}

                  {activeTab === 'Permissions' && (
                      <div className="space-y-8 animate-fade-in">
                          <div className="p-4 bg-indigo-50 border border-indigo-100 rounded-2xl flex items-start gap-3">
                              <ShieldCheck size={20} className="text-indigo-600 mt-0.5" />
                              <div>
                                  <p className="text-sm font-bold text-indigo-900">Custom Permission Overrides</p>
                                  <p className="text-xs text-indigo-700">Manually authorized features will override role defaults for this user. This controls which "apps" appear on their launcher.</p>
                              </div>
                          </div>

                          {Object.entries(permissionsByCategory).map(([category, items]) => (
                              <div key={category}>
                                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 border-b pb-2">{category}</h4>
                                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                      {items.map(perm => (
                                          <label key={perm.key} className="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 cursor-pointer">
                                              <span className="text-sm font-bold text-slate-700">{perm.name}</span>
                                              <button 
                                                onClick={() => toggleEmpPermission(perm.key)}
                                                className={`h-5 w-10 rounded-full relative transition-all ${isEmpPermissionEnabled(perm.key) ? 'bg-indigo-600' : 'bg-slate-200'}`}
                                              >
                                                  <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${isEmpPermissionEnabled(perm.key) ? 'translate-x-5' : ''}`} />
                                              </button>
                                          </label>
                                      ))}
                                  </div>
                              </div>
                          ))}
                      </div>
                  )}

                  {activeTab === 'Security' && (
                      <div className="space-y-6">
                          <div>
                              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Terminal Passcode</label>
                              <input type="text" value={currentEmployee.passcode || ''} onChange={e => setCurrentEmployee({...currentEmployee, passcode: e.target.value.replace(/\D/g, '')})} className="w-full border border-slate-300 rounded-xl px-4 py-2 font-mono text-xl tracking-widest text-center" maxLength={4} />
                          </div>
                      </div>
                  )}
              </div>

              <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                  <button onClick={() => setShowModal(false)} className="px-6 py-2.5 text-slate-400 font-black text-xs uppercase tracking-widest">Cancel</button>
                  <button onClick={handleSaveEmployee} className="px-8 py-2.5 bg-indigo-600 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-xl shadow-indigo-100">
                      {isEditing ? 'Save Changes' : 'Add Employee'}
                  </button>
              </div>
          </div>
      </div>
  );

  return (
    <div className="space-y-6 relative">
      {showModal && renderEmployeeModal()}

      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Team & Access</h1>
          <p className="text-slate-500">Manage staff identity and granular permissions</p>
        </div>
        <div className="flex gap-2">
            <div className="bg-white border border-slate-300 rounded-xl p-1 flex shadow-sm">
                {['Employees', 'Roles', 'Matrix', 'Security'].map(mode => (
                    <button 
                        key={mode}
                        onClick={() => setViewMode(mode as any)}
                        className={`px-3 py-1.5 rounded-lg text-xs font-black uppercase tracking-wider transition-all ${viewMode === mode ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:text-slate-800'}`}
                    >
                        {mode}
                    </button>
                ))}
            </div>
            <button onClick={handleOpenAdd} className="bg-indigo-600 text-white px-5 py-2 rounded-xl flex items-center gap-2 hover:bg-indigo-700 shadow-xl shadow-indigo-100 font-bold transition-all active:scale-95">
                <Plus size={18} /> ADD NEW
            </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden animate-fade-in">
        <table className="w-full text-left border-collapse">
            <thead>
                <tr className="bg-slate-50 border-b border-slate-200 text-[10px] uppercase text-slate-500 font-black tracking-widest">
                <th className="px-6 py-4">Identity</th>
                <th className="px-6 py-4">Role / Permissions</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
                {employees.map((emp) => (
                <tr key={emp.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4">
                    <div className="flex items-center">
                        <div className="h-10 w-10 rounded-xl bg-indigo-100 flex items-center justify-center text-indigo-700 font-black border border-indigo-200 mr-3">
                        {emp.name.charAt(0)}
                        </div>
                        <div>
                        <div className="font-bold text-slate-900">{emp.name}</div>
                        <div className="text-xs text-slate-400">{emp.email}</div>
                        </div>
                    </div>
                    </td>
                    <td className="px-6 py-4">
                    <div className="flex flex-col gap-1">
                        <span className="inline-flex text-[10px] font-black tracking-widest uppercase text-indigo-600">{emp.role}</span>
                        <span className="text-[10px] text-slate-400 font-bold uppercase">{emp.permissions?.length || 0} OVERRIDES ACTIVE</span>
                    </div>
                    </td>
                    <td className="px-6 py-4">
                        <span className={`inline-flex px-2 py-1 rounded-lg text-[10px] font-black uppercase ${emp.status === 'Active' ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>
                            {emp.status}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => handleOpenEdit(emp)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-white border border-transparent hover:border-slate-100 rounded-lg transition-all shadow-sm">
                                <Edit2 size={16} />
                            </button>
                            <button onClick={() => onDeleteEmployee?.(emp.id)} className="p-2 text-slate-400 hover:text-rose-600 hover:bg-white border border-transparent hover:border-slate-100 rounded-lg transition-all shadow-sm">
                                <Trash2 size={16} />
                            </button>
                        </div>
                    </td>
                </tr>
                ))}
            </tbody>
        </table>
      </div>
    </div>
  );
};

