import { db } from '../services/db';
import { Employee, UserRole } from '../types';

export const AuthAPI = {
  async authenticate(passcode: string): Promise<Employee | null> {
    const employees = await db.getAll<Employee>('employees');
    const user = employees.find(e => e.passcode === passcode);
    return user || null;
  },

  async checkPermission(user: Employee, permission: string): Promise<boolean> {
    const isAdmin = user.role === 'Admin' || user.role === UserRole.SUPER_ADMIN || user.role === UserRole.BUSINESS_ADMIN;
    if (isAdmin) return true;
    return user.permissions?.includes(permission) || false;
  }
};

import { db } from '../services/db';
import { DetailedOrder } from '../types';

export const OrdersAPI = {
  async getOrders(): Promise<DetailedOrder[]> {
    return db.getAll<DetailedOrder>('orders');
  },

  async createOrder(order: DetailedOrder): Promise<void> {
    await db.put('orders', order);
  },

  async updateOrderStatus(orderId: string, status: DetailedOrder['status']): Promise<void> {
    const orders = await this.getOrders();
    const order = orders.find(o => o.id === orderId);
    if (order) {
      order.status = status;
      await db.put('orders', order);
    }
  }
};

