  },

  async getTransactions(): Promise<Transaction[]> {
    return db.getAll<Transaction>('transactions');
  },

  async recordRefund(transactionId: string, amount: number): Promise<void> {
    const refundTxn: Transaction = {
      id: `REF-${Date.now()}`,
      date: new Date().toLocaleDateString(),
      amount: -amount,
      type: 'Refund',
      method: 'Card',
      employeeId: 'System'
