import React, { useState, useEffect } from 'react';
import { InventoryItem, Category, CartItem, DiscountCode } from '../types';
import { InventoryAPI } from '../api/inventory';
import { OrdersAPI } from '../api/orders';
import MenuGrid from './POS/Register/MenuGrid';
import OrderSidebar from './POS/Register/OrderSidebar';
import { Loader2 } from 'lucide-react';

const Register: React.FC = () => {
    const [isLoading, setIsLoading] = useState(true);
    const [inventory, setInventory] = useState<InventoryItem[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);

    const [cart, setCart] = useState<CartItem[]>([]);
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        const loadData = async () => {
            const [items, cats] = await Promise.all([
                InventoryAPI.getItems(),
                InventoryAPI.getCategories()
            ]);
            setInventory(items);
            setCategories(cats);
            setIsLoading(false);
        };
        loadData();
    }, []);

    const handleAddToCart = (item: InventoryItem) => {
        setCart(prev => {
            const existing = prev.find(i => i.id === item.id);
            if (existing) {
                return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { ...item, quantity: 1, modifiers: [], color: 'bg-white' }];
        });
    };

    const handleUpdateQty = (id: string, delta: number) => {
        setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + delta) } : i));
    };

    const handleCheckout = async () => {
        const subtotal = cart.reduce((acc, i) => acc + (i.price * i.quantity), 0);
        const tax = subtotal * 0.0825;
        const total = subtotal + tax;

        const newOrder: any = {
            id: `ORD-${Date.now()}`,
            items: cart,
            total,
            status: 'Paid',
            date: new Date().toLocaleDateString(),
            time: new Date().toLocaleTimeString()
        };

        await OrdersAPI.createOrder(newOrder);
        setCart([]);
        alert("Order Complete!");
    };

    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * 0.0825;
    const total = subtotal + tax;

    const filteredItems = inventory.filter(i => 
        i.showOnPos && 
        (activeCategory === 'All' || i.category === activeCategory) &&
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (isLoading) return <div className="h-full flex items-center justify-center"><Loader2 className="animate-spin text-indigo-500" size={40} /></div>;

    return (
        <div className="flex h-full bg-white rounded-3xl overflow-hidden shadow-2xl border border-slate-200">
            <MenuGrid 
                items={filteredItems}
                categories={categories}
                activeCategory={activeCategory}
                onCategoryChange={setActiveCategory}
                onItemSelect={handleAddToCart}
                searchTerm={searchTerm}
                onSearchChange={setSearchTerm}
            />
            <OrderSidebar 
                cart={cart}
                onUpdateQty={handleUpdateQty}
                onCheckout={handleCheckout}
                subtotal={subtotal}
                tax={tax}
                total={total}
            />
        </div>
    );
};

