export const PaymentsAPI = {
  // Handshake with payment providers (Mock)
  async processTender(amount: number, method: string, tip: number = 0): Promise<Transaction> {
    const txn: Transaction = {
      id: `TXN-${Date.now()}`,
      date: new Date().toISOString(),
      amount: amount + tip,
      type: 'Sale',
      method: method as any,
      employeeId: 'Current_User_UID'
    };

    await db.put('transactions', txn);
    return txn;
  },

  async logCashActivity(entry: Partial<CashLogEntry>): Promise<void> {
    const log: CashLogEntry = {
        id: `CASH-${Date.now()}`,
        date: new Date().toLocaleDateString(),
        openingAmount: entry.openingAmount || 0,
        cashSales: entry.cashSales || 0,
        cashDrops: entry.cashDrops || 0,
        closingAmount: entry.closingAmount || 0,
        variance: (entry.closingAmount || 0) - (entry.openingAmount || 0 + (entry.cashSales || 0) - (entry.cashDrops || 0)),
        employeeId: entry.employeeId || 'System'
    };
    await db.put('cashlog', log);
  },

  async initiateRefund(originalTxnId: string, amount: number, employeeId: string): Promise<void> {
    // Record negative ledger entry
    const refund: Transaction = {
        id: `REF-${Date.now()}`,
        date: new Date().toISOString(),
        amount: -amount,
        type: 'Refund',
        method: 'Card',
        employeeId
    };
    await db.put('transactions', refund);
  }
};

