export const ReportsAPI = {
  async getDailySalesSummary(date: string): Promise<SalesSummary> {
    const orders = await db.getAll<DetailedOrder>('orders');
    const dayOrders = orders.filter(o => o.date === date);

    return {
      date,
      grossSales: dayOrders.reduce((a, b) => a + b.total, 0),
      discounts: dayOrders.reduce((a, b) => a + (b.discount || 0), 0),
      netSales: dayOrders.reduce((a, b) => a + (b.total - (b.tax || 0)), 0),
      orderCount: dayOrders.length
    };
  },

  async generateZReport(): Promise<string> {
    // Daily close logic - locks previous transactions
    const logId = `Z-REP-${Date.now()}`;
    await db.put('batches', {
        id: logId,
        timestamp: new Date().toISOString(),
        status: 'Closed',
        type: 'DAILY_CLOSE'
    });
    return logId;
  },

  async getAuditLogs(): Promise<any[]> {
    return db.getAll('batches'); // Reusing batches for audit trails
  }
};

