import { db } from '../services/db';
import { DetailedOrder, OrderItem } from '../types';
import { InventoryAPI } from './inventory';

export const OrdersAPI = {
  // Pure backend logic: Calculate order before saving
  async createOrder(rawItems: OrderItem[], employeeId: string, orderType: string): Promise<DetailedOrder> {
    const subtotal = rawItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);

    // Backend handles tax rules (Regional config)
    const TAX_RATE = 0.0825; 
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax;

    const newOrder: DetailedOrder = {
      id: `ORD-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      date: new Date().toLocaleDateString(),
      time: new Date().toLocaleTimeString(),
      total,
      status: 'Paid',
      paymentMethod: 'Card',
      employeeName: employeeId,
      device: 'Terminal-01',
      type: orderType as any,
      items: rawItems,
      fees: 0,
      tip: 0,
      // Fix: Storing tax explicitly in the order object for reporting purposes
      tax
    };

    // Commit to DB
    await db.put('orders', newOrder);

    // Trigger Inventory side-effect (Auto-deduct stock)
    await InventoryAPI.processOrderDeductions(rawItems);

    return newOrder;
  },

  async voidOrder(orderId: string, reason: string, authorizedBy: string): Promise<void> {
    const order = await this.getOrderById(orderId);
    if (!order) throw new Error("Order not found");

    order.status = 'Void';
    await db.put('orders', order);

    // Log for Audit
    await db.put('batches', {
        id: `AUDIT-${Date.now()}`,
        type: 'VOID_LOG',
        details: `Order ${orderId} voided by ${authorizedBy}. Reason: ${reason}`
    });
  },

  async getOrderById(id: string): Promise<DetailedOrder | undefined> {
    const orders = await db.getAll<DetailedOrder>('orders');
    return orders.find(o => o.id === id);
  }
};

