  Users, Settings, Shield, Package, UserCircle, 
  Database, Zap, BrainCircuit, Globe, CreditCard, 
  Clock, Bell, Search, Terminal, Coffee, ChefHat, Calendar
} from 'lucide-react';
import { Employee, UserRole } from '../types';
import { AuthAPI } from '../api/auth';

/**
 * AppLauncher: The central nerve center of OmniCommand OS.
 * This component manages the "Desktop" experience, handling app categorization,
 * searching, and granular permission checks via the AuthAPI backend simulation.
 */

interface AppLauncherProps {
    user: Employee;
    onSelectApp: (id: string) => void;
}

interface AppTile {
    id: string;
    name: string;
    description: string;
    icon: React.ReactNode;
    color: string;
    category: 'Operations' | 'Finance' | 'Team' | 'System';
    permission?: string;
    isBeta?: boolean;
}

const AppLauncher: React.FC<AppLauncherProps> = ({ user, onSelectApp }) => {
    const [searchTerm, setSearchTerm] = useState('');
    const [activeCategory, setActiveCategory] = useState<'All' | 'Operations' | 'Finance' | 'Team' | 'System'>('All');
    const [currentTime, setCurrentTime] = useState(new Date());
    const [isSearching, setIsSearching] = useState(false);

    // Dynamic Clock & Telemetry Simulation
    useEffect(() => {
        const timer = setInterval(() => setCurrentTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    const apps: AppTile[] = [
        { 
            id: 'Home', 
            name: 'Insights', 
            description: 'Real-time sales & traffic', 
            icon: <LayoutDashboard size={28} />, 
            color: 'bg-indigo-500', 
            category: 'Operations',
            permission: 'ACCESS_REPORTING'
        },
        { 
            id: 'New Sale', 
            name: 'Register', 
            description: 'Terminal POS interface', 
            icon: <ShoppingCart size={28} />, 
            color: 'bg-emerald-500', 
            category: 'Operations',
            permission: 'ACCESS_REGISTER'
        },
        { 
            id: 'Dining', 
            name: 'Byte Dining', 
            description: 'Floor & table management', 
            icon: <Coffee size={28} />, 
            color: 'bg-orange-500', 
            category: 'Operations',
            permission: 'ACCESS_DINING'
        },
        { 
            id: 'Kitchen', 
            name: 'KDS', 
            description: 'Kitchen display system', 
            icon: <ChefHat size={28} />, 
            color: 'bg-slate-700', 
            category: 'Operations',
            permission: 'ACCESS_KITCHEN'
        },
        { 
            id: 'Reports', 
            name: 'Finances', 
            description: 'Ledger & tax reports', 
            icon: <FileBarChart size={28} />, 
            color: 'bg-blue-600', 
            category: 'Finance',
            permission: 'ACCESS_REPORTING'
        },
        { 
            id: 'Transactions', 
            name: 'Payments', 
            description: 'Audit tender logs', 
            icon: <CreditCard size={28} />, 
            color: 'bg-cyan-600', 
            category: 'Finance',
            permission: 'ACCESS_TRANSACTIONS'
        },
        { 
            id: 'Employees', 
            name: 'Team', 
            description: 'Staff & permissions', 
            icon: <Users size={28} />, 
            color: 'bg-rose-500', 
            category: 'Team',
            permission: 'ACCESS_SHIFTS'
        },
        { 
            id: 'Inventory', 
            name: 'Catalog', 
            description: 'Items & stock levels', 
            icon: <Package size={28} />, 
            color: 'bg-amber-600', 
            category: 'Operations',
            permission: 'ACCESS_INVENTORY'
        },
        { 
            id: 'ML Pipeline', 
            name: 'Forecasting', 
            description: 'AI demand prediction', 
            icon: <BrainCircuit size={28} />, 
            color: 'bg-purple-600', 
            category: 'System',
            permission: 'ACCESS_SETUP',
            isBeta: true
        },
        { 
            id: 'Super Admin', 
            name: 'Control', 
            description: 'Global system governance', 
            icon: <Shield size={28} />, 
            color: 'bg-slate-900', 
            category: 'System',
            permission: UserRole.SUPER_ADMIN
        },
        { 
            id: 'Settings', 
            name: 'Setup', 
            description: 'Regional & hardware config', 
            icon: <Settings size={28} />, 
            color: 'bg-slate-400', 
            category: 'System',
            permission: 'ACCESS_SETUP'
        }
    ];

    const filteredApps = apps.filter(app => {
        const matchesSearch = app.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                             app.description.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = activeCategory === 'All' || app.category === activeCategory;

        // Backend Permission Simulation Check
        let hasPermission = false;
        if (user.role === 'Admin' || user.role === UserRole.SUPER_ADMIN) {
            hasPermission = true;
        } else if (app.permission) {
            hasPermission = user.permissions?.includes(app.permission) || false;
            if (app.permission === UserRole.SUPER_ADMIN) hasPermission = user.role === UserRole.SUPER_ADMIN;
        } else {
            hasPermission = true; // Default access
        }

        return matchesSearch && matchesCategory && hasPermission;
    });

    const categories = ['All', 'Operations', 'Finance', 'Team', 'System'];

    return (
        <div className="h-full flex flex-col space-y-8 animate-fade-in pb-20">
            {/* 1. Header & System Status */}
            <div className="flex justify-between items-end bg-white p-8 rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden">
                <div className="z-10">
                    <h1 className="text-4xl font-black text-slate-900 tracking-tighter uppercase mb-2">Welcome Back, {user.name.split(' ')[0]}</h1>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2 bg-slate-100 px-3 py-1 rounded-full border border-slate-200">
                            <Clock size={14} className="text-indigo-600" />
                            <span className="text-xs font-bold text-slate-600 uppercase">
                                {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                            </span>
                        </div>
                        <div className="flex items-center gap-2 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100">
                            <Database size={14} className="text-emerald-600" />
                            <span className="text-[10px] font-black text-emerald-700 uppercase tracking-widest">Backend Synchronized</span>
                        </div>
                        <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1 rounded-full border border-indigo-100">
                            <Globe size={14} className="text-indigo-600" />
                            <span className="text-[10px] font-black text-indigo-700 uppercase tracking-widest">Region: US-EAST-1</span>
                        </div>
                    </div>
                </div>

                <div className="text-right z-10 hidden md:block">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-2">Platform Telemetry</p>
                    <div className="flex gap-2 justify-end">
                        <div className="w-12 h-1.5 bg-indigo-500 rounded-full"></div>
                        <div className="w-8 h-1.5 bg-emerald-400 rounded-full"></div>
                        <div className="w-16 h-1.5 bg-slate-200 rounded-full"></div>
                    </div>
                </div>

                {/* Background Decor */}
                <div className="absolute right-[-50px] top-[-50px] opacity-[0.03] rotate-12 pointer-events-none">
                    <Terminal size={300} />
                </div>
            </div>

            {/* 2. Filter Bar */}
            <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm w-full md:w-auto">
                    {categories.map((cat: any) => (
                        <button
                            key={cat}
                            onClick={() => setActiveCategory(cat)}
                            className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all
                                ${activeCategory === cat 
                                    ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' 
                                    : 'text-slate-400 hover:text-slate-700 hover:bg-slate-50'}`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>

                <div className="relative w-full md:w-96 group">
                    <Search className={`absolute left-4 top-1/2 -translate-y-1/2 transition-colors ${isSearching ? 'text-indigo-600' : 'text-slate-400'}`} size={18} />
                    <input 
                        type="text" 
                        placeholder="Search apps or tools..." 
                        value={searchTerm}
                        onFocus={() => setIsSearching(true)}
                        onBlur={() => setIsSearching(false)}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl shadow-sm outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all font-medium text-slate-800"
                    />
                </div>
            </div>

            {/* 3. Application Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {filteredApps.map((app) => (
                    <button
                        key={app.id}
                        onClick={() => onSelectApp(app.id)}
                        className="group bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm hover:shadow-2xl hover:border-indigo-500 hover:-translate-y-2 transition-all text-left relative flex flex-col items-start"
                    >
                        <div className={`p-4 rounded-3xl ${app.color} text-white mb-6 group-hover:scale-110 group-hover:rotate-3 transition-transform shadow-lg shadow-indigo-100`}>
                            {app.icon}
                        </div>

                        <div className="flex-1">
                            <div className="flex items-center gap-2 mb-2">
                                <h3 className="text-xl font-black text-slate-900 tracking-tighter uppercase">{app.name}</h3>
                                {app.isBeta && (
                                    <span className="bg-amber-100 text-amber-700 text-[8px] font-black uppercase px-1.5 py-0.5 rounded tracking-widest">Beta</span>
                                )}
                            </div>
                            <p className="text-sm text-slate-500 font-medium leading-relaxed">{app.description}</p>
                        </div>

                        <div className="mt-8 pt-6 border-t border-slate-50 w-full flex justify-between items-center opacity-0 group-hover:opacity-100 transition-opacity">
                            <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Open Application</span>
                            <div className="h-8 w-8 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600">
                                <Zap size={14} />
                            </div>
                        </div>

                        {/* Visual categorization dot */}
                        <div className="absolute top-8 right-8 h-2 w-2 rounded-full bg-slate-200 group-hover:bg-indigo-500 transition-colors" />
                    </button>
                ))}

                {/* Empty State */}
                {filteredApps.length === 0 && (
                    <div className="col-span-full py-20 flex flex-col items-center justify-center text-slate-300 opacity-50">
                        <div className="p-8 bg-slate-100 rounded-full mb-6">
                            <BrainCircuit size={64} />
                        </div>
                        <h3 className="text-2xl font-black uppercase tracking-tighter">No Applications Found</h3>
                        <p className="font-bold mt-2">Try adjusting your search or category filters.</p>
                    </div>
                )}
            </div>

            {/* 4. Footer System Bar */}
            <div className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-slate-200 h-12 flex items-center justify-between px-10 z-30 ml-[20rem] transition-all group-hover:ml-[5rem]">
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-2">
                        <div className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Core Engine Active</span>
                    </div>
                    <div className="h-4 w-px bg-slate-200" />
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ver: 4.2.1 Stable</span>
                </div>
                <div className="flex items-center gap-4">
                    <button className="p-1 text-slate-400 hover:text-indigo-600 transition-colors">
                        <Bell size={16} />
                    </button>
                    <button className="p-1 text-slate-400 hover:text-indigo-600 transition-colors">
                        <UserCircle size={16} />
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AppLauncher;

import React, { useState, useEffect } from 'react';
import { 
    UserRole, Employee, DetailedOrder, Transaction, Customer, 
    InventoryItem, Category, DiningTable, KDSSettings, DiscountCode 
} from './types';

// Standardized Relative Imports (Standard Browser ESM Requirement)
import { db } from './services/db';
import { InventoryAPI } from './api/inventory';
import { DiningAPI } from './api/dining';
import { EmployeesAPI } from './api/employees';
import { OrdersAPI } from './api/orders';

// Components
import Login from './components/Login';
import AppLauncher from './components/AppLauncher';
import Dashboard from './components/Dashboard';
import Register from './components/Register';
import SalesReports from './components/SalesReports';
import Employees from './components/Employees';
import Settings from './components/Settings';
import Transactions from './components/Transactions';
import Customers from './components/Customers';
import Items from './components/Items';
import Discounts from './components/Discounts';
import KitchenDisplay from './components/KitchenDisplay';
import MLPipeline from './components/MLPipeline';

import { 
    LayoutDashboard, ShoppingCart, Activity, FileBarChart, 
    DollarSign, Package, Users, LogOut, ChevronDown, 
    ChevronRight, Menu, Bell, Settings as SettingsIcon, 
    Loader2, Home, Grid, Tag, BrainCircuit 
} from 'lucide-react';

import { 
    MOCK_DETAILED_ORDERS, MOCK_TRANSACTIONS, MOCK_CUSTOMERS, 
    MOCK_KDS_SETTINGS, MOCK_HOURLY_SALES, MOCK_SALES_SUMMARY, 
    MOCK_DEPOSITS, MOCK_TAX_REPORTS, MOCK_DISCOUNTS, 
    MOCK_RESOURCES, MOCK_ML_JOBS 
} from './constants';

const App: React.FC = () => {
  const [isInitializing, setIsInitializing] = useState(true);
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);

  // Global Application State (Synchronized with api/ persistence)
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [floorPlan, setFloorPlan] = useState<DiningTable[]>([]);
  const [orders, setOrders] = useState<DetailedOrder[]>([]);

  const [activeTab, setActiveTab] = useState('Launcher');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  /**
   * System Handshake: Seed database and fetch initial state from API layer.
   */
  useEffect(() => {
    const init = async () => {
      try {
        await db.seed();
        const [items, cats, emps, tables, ords] = await Promise.all([
          InventoryAPI.getItems(),
          InventoryAPI.getCategories(),
          EmployeesAPI.getEmployees(),
          DiningAPI.getFloorPlan(),
          OrdersAPI.getOrders()
        ]);
        setInventory(items);
        setCategories(cats);
        setEmployees(emps);
        setFloorPlan(tables);
        setOrders(ords);
      } catch (err) {
        console.error("System Initialization Failed:", err);
      } finally {
        setIsInitializing(false);
      }
    };
    init();
  }, []);

  // --- Handlers for "Full-Stack" CRUD Simulation ---

  const handleAddEmployee = async (e: Employee) => {
      await EmployeesAPI.saveEmployee(e);
      const updated = await EmployeesAPI.getEmployees();
      setEmployees(updated);
  };

  const handleDeleteEmployee = async (id: string) => {
      await EmployeesAPI.deleteEmployee(id);
      const updated = await EmployeesAPI.getEmployees();
      setEmployees(updated);
  };

  const handleUpdateFloorPlan = async (tables: DiningTable[]) => {
      await DiningAPI.saveFullFloorPlan(tables);
      setFloorPlan(tables);
  };

  const handleLogin = (user: Employee) => {
    setCurrentUser(user);
    setActiveTab('Launcher');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('Login');
  };

  if (isInitializing) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-white">
        <Loader2 size={48} className="animate-spin text-indigo-500 mb-4" />
        <h1 className="text-xl font-black tracking-tighter uppercase">OmniCommand OS</h1>
        <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Starting full-stack environment...</p>
      </div>
    );
  }

  if (!currentUser) return <Login onLogin={handleLogin} />;

  // Dynamic Navigation based on Role Permissions
  const menuItems = [
    { id: 'Launcher', label: 'Hub', icon: <Home size={20} /> },
    { id: 'New Sale', label: 'POS Terminal', icon: <ShoppingCart size={20} /> },
    { id: 'Home', label: 'Insights', icon: <LayoutDashboard size={20} /> },
    { id: 'Reports', label: 'Financials', icon: <FileBarChart size={20} /> },
    { id: 'Employees', label: 'Team', icon: <Users size={20} /> },
    { id: 'Inventory', label: 'Item Library', icon: <Package size={20} /> },
    { id: 'Transactions', label: 'Payments', icon: <DollarSign size={20} /> },
    { id: 'Settings', label: 'Settings', icon: <SettingsIcon size={20} /> },
  ];

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900 overflow-hidden">
      {/* Sidebar Navigation */}
      <aside className={`bg-slate-900 text-slate-300 flex flex-col transition-all duration-500 ease-in-out ${isSidebarOpen ? 'w-64' : 'w-20'} shrink-0 h-screen overflow-hidden z-40 shadow-2xl`}>
        <div className="p-6 border-b border-slate-800 flex items-center justify-between">
          {isSidebarOpen && <span className="font-black text-white text-xl tracking-tighter uppercase">OmniCommand</span>}
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-xl text-slate-400 transition-colors">
            <Menu size={20} />
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto py-6 space-y-1">
          {menuItems.map(item => (
            <button 
                key={item.id} 
                onClick={() => setActiveTab(item.id)} 
                className={`w-full flex items-center gap-3 px-6 py-4 hover:bg-slate-800 hover:text-white transition-all
                    ${activeTab === item.id 
                        ? 'text-white bg-slate-800 border-l-4 border-indigo-500 shadow-inner shadow-black/20' 
                        : 'border-l-4 border-transparent opacity-60 hover:opacity-100'}`}
            >
              <div className={activeTab === item.id ? 'text-indigo-400' : ''}>{item.icon}</div>
              {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-widest">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-slate-800 space-y-4">
          <div className={`flex items-center gap-3 px-2 ${isSidebarOpen ? '' : 'justify-center'}`}>
              <div className="h-10 w-10 rounded-xl bg-indigo-600 flex items-center justify-center font-black text-white shadow-lg shadow-indigo-950/50">
                  {currentUser.name.charAt(0)}
              </div>
              {isSidebarOpen && (
                  <div className="overflow-hidden">
                      <p className="text-[10px] font-black text-white truncate uppercase">{currentUser.name}</p>
                      <p className="text-[8px] font-bold text-indigo-400 uppercase truncate tracking-widest">{currentUser.role}</p>
                  </div>
              )}
          </div>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-2 py-4 text-slate-500 hover:text-rose-500 transition-colors group">
            <LogOut size={20} className="group-hover:rotate-180 transition-transform duration-500" />
            {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-widest">Terminate Session</span>}
          </button>
        </div>
      </aside>

      {/* Main Application Container */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-20 shadow-sm">
            <div className="flex items-center gap-2">
                <span className="font-black text-[10px] uppercase tracking-[0.3em] text-slate-300">Workspace</span>
                <ChevronRight size={14} className="text-slate-200" />
                <h2 className="font-black text-xs uppercase tracking-[0.2em] text-indigo-600">{activeTab}</h2>
            </div>

            <div className="flex items-center gap-6">
                <div className="hidden lg:flex items-center gap-4 text-slate-400">
                    <Bell size={18} className="cursor-pointer hover:text-slate-600" />
                    <SettingsIcon size={18} className="cursor-pointer hover:text-slate-600" />
                </div>
                <div className="h-8 w-px bg-slate-100 hidden lg:block" />
                <div className="flex items-center gap-3 bg-slate-50 px-4 py-2 rounded-xl border border-slate-200">
                    <div className="h-2 w-2 rounded-full bg-emerald-500" />
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Production Cloud</span>
                </div>
            </div>
        </header>

        {/* View Router */}
        <div className="flex-1 overflow-auto p-10 bg-slate-50/50 relative">
            {activeTab === 'Launcher' && <AppLauncher user={currentUser} onSelectApp={setActiveTab} />}
            {activeTab === 'Home' && <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />}
            {activeTab === 'New Sale' && <Register currentUser={currentUser} />}
            {activeTab === 'Reports' && <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} />}
            {activeTab === 'Transactions' && <Transactions transactions={MOCK_TRANSACTIONS} />}
            {activeTab === 'Customers' && <Customers customers={MOCK_CUSTOMERS} />}
            {activeTab === 'Inventory' && <Items items={inventory} />}
            {activeTab === 'Employees' && <Employees employees={employees} onAddEmployee={handleAddEmployee} onDeleteEmployee={handleDeleteEmployee} />}
            {activeTab === 'Settings' && <Settings floorPlanTables={floorPlan} onSaveFloorPlan={handleUpdateFloorPlan} />}
            {activeTab === 'Dining' && <div className="h-full"><Settings floorPlanTables={floorPlan} onSaveFloorPlan={handleUpdateFloorPlan} /></div>}
            {activeTab === 'Kitchen' && <KitchenDisplay settings={MOCK_KDS_SETTINGS} />}
            {activeTab === 'ML Pipeline' && <MLPipeline jobs={MOCK_ML_JOBS} resources={MOCK_RESOURCES} />}
            {activeTab === 'Super Admin' && <div className="p-4 bg-slate-900 text-white rounded-3xl h-full flex flex-col items-center justify-center">
                <Shield size={64} className="text-indigo-500 mb-4 animate-pulse" />
                <h3 className="text-2xl font-black uppercase tracking-tighter">System Governance Mode</h3>
                <p className="text-slate-400 mt-2 font-bold uppercase tracking-widest text-xs underline">Secure Access Override Enabled</p>
            </div>}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Employee, UserRole, Role, PermissionItem } from '../types';
import { 
  Plus, Search, Edit2, Trash2, X, User, Shield, 
  Settings, Key, LayoutGrid, CheckCircle, RefreshCw, Loader2
} from 'lucide-react';
import { 
  MOCK_ROLES, MOCK_PERMISSIONS 
} from '../constants';

/**
 * Employees Module: Manages Team Identity & Permission Registry.
 * Interacts directly with EmployeesAPI to simulate persistent storage.
 */

interface EmployeesProps {
  employees: Employee[];
  onAddEmployee?: (employee: Employee) => Promise<void>;
  onUpdateEmployee?: (employee: Employee) => Promise<void>;
  onDeleteEmployee?: (id: string) => Promise<void>;
}

const Employees: React.FC<EmployeesProps> = ({ employees, onAddEmployee, onUpdateEmployee, onDeleteEmployee }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [activeTab, setActiveTab] = useState<'Profile' | 'Permissions' | 'Security'>('Profile');

  const [currentEmployee, setCurrentEmployee] = useState<Partial<Employee>>({
      role: UserRole.STAFF,
      status: 'Active',
      payType: 'Hourly',
      hourlyRate: 0,
      hoursWorked: 0,
      permissions: [],
      deviceAccess: true
  });
  const [formError, setFormError] = useState<string | null>(null);

  const handleOpenAdd = () => {
    setIsEditing(false);
    setCurrentEmployee({
      role: 'Staff',
      status: 'Active',
      payType: 'Hourly',
      hourlyRate: 15,
      hoursWorked: 0,
      permissions: ['ACCESS_REGISTER'],
      deviceAccess: true
    });
    setFormError(null);
    setActiveTab('Profile');
