/**
 * AuthAPI: The system's primary security gateway.
 * Manages identity verification and device authentication.
 */
export const AuthAPI = {
  // Verifies passcode and returns a session token + user context
  async authenticate(passcode: string, deviceId: string): Promise<{user: Employee, token: string} | null> {
    const employees = await db.getAll<Employee>('employees');
    const user = employees.find(e => e.passcode === passcode);

    if (!user || user.status !== 'Active') return null;

    // Backend-side device validation
    const deviceAuthorized = await this.validateDevice(deviceId);
    if (!deviceAuthorized) throw new Error("Device identity mismatch. terminal not authorized.");

    return {
      user,
      token: `omni_sess_${Math.random().toString(36).substring(7)}`
    };
  },

  // Simulates checking if a specific tablet/terminal is registered to the business
  async validateDevice(deviceId: string): Promise<boolean> {
    return true; // Simplified for demo; would check 'apps' store in production
  },

  // Authoritative permission check
  async verifyActionAccess(user: Employee, permissionKey: string): Promise<boolean> {
    if (user.role === 'Admin' || user.role === UserRole.SUPER_ADMIN) return true;
    return user.permissions?.includes(permissionKey) || false;
  },

  async clockIn(employeeId: string): Promise<void> {
    await db.put('schedules', {
      id: `SHIFT-${Date.now()}`,
      employeeId,
      action: 'CLOCK_IN',
      timestamp: new Date().toISOString()
    });
  }
};

import { db } from '../services/db';
import { DetailedOrder, OrderItem, CartItem } from '../types';
import { InventoryAPI } from './inventory';

/**
 * OrdersAPI: Authoritative service for transaction lifecycle.
 */
export const OrdersAPI = {
  async getOrders(): Promise<DetailedOrder[]> {
    return db.getAll<DetailedOrder>('orders');
  },

  // BACKEND LOGIC: Frontend sends raw items, backend calculates money
  async processOrder(items: CartItem[], employeeId: string, locationId: string): Promise<DetailedOrder> {
    const subtotal = items.reduce((acc, i) => acc + (i.price * i.quantity), 0);

    // Backend-only Tax Rules (Simulation of Regional Settings)
    const TAX_RATE = 0.0825; 
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax;

    const newOrder: DetailedOrder = {
      id: `ORD-${Math.random().toString(36).substring(2, 11).toUpperCase()}`,
      date: new Date().toLocaleDateString(),
      time: new Date().toLocaleTimeString(),
      total,
      tax,
      status: 'Paid',
      paymentMethod: 'Card', // Default for simulation
      employeeName: employeeId,
      device: 'Terminal-01',
      type: 'Takeout',
      items: items.map(i => ({
        id: i.id,
        name: i.name,
        quantity: i.quantity,
        price: i.price,
        modifiers: i.modifiers
      })),
      discount: items.reduce((acc, i) => acc + (i.discount || 0), 0)
    };

    // 1. Record Transaction
    await db.put('orders', newOrder);

    // 2. Automated Inventory Deduction (Backend Side-effect)
    await InventoryAPI.autoDeductStock(items);

    // 3. Update Audit Batch
    await db.put('batches', {
      id: `AUDIT-${Date.now()}`,
      type: 'SALE_RECORD',
      details: `Order ${newOrder.id} processed by ${employeeId}`
    });

    return newOrder;
  },

  async voidOrder(orderId: string, managerPasscode: string): Promise<void> {
    // In a real system, verify managerPasscode with AuthAPI first
    const orders = await this.getOrders();
    const order = orders.find(o => o.id === orderId);
    if (order) {
      order.status = 'Void';
      await db.put('orders', order);
    }
  }
};

import { db } from '../services/db';
import { InventoryItem, Category, CartItem } from '../types';

/**
 * InventoryAPI: Central control for products and stock.
 */
export const InventoryAPI = {
  async getItems(): Promise<InventoryItem[]> {
    return db.getAll<InventoryItem>('inventory');
  },

  async getCategories(): Promise<Category[]> {
    return db.getAll<Category>('categories');
  },

  // Centralized availability update
  async setItemStatus(itemId: string, inStock: boolean): Promise<void> {
    const items = await this.getItems();
    const item = items.find(i => i.id === itemId);
    if (item) {
      item.inStock = inStock;
      await db.put('inventory', item);
    }
  },

  // Automated deduction logic triggered by Order service
  async autoDeductStock(items: CartItem[]): Promise<void> {
    const currentInventory = await this.getItems();

    for (const soldItem of items) {
      const product = currentInventory.find(i => i.id === soldItem.id);
      if (product) {
        // Simplified deduction logic for POC
        // If stock was tracked as a number: product.quantity -= soldItem.quantity;
        // If it reaches 0: 
        if (Math.random() > 0.9) { // Simulate random "Out of Stock" event
           product.inStock = false;
           await db.put('inventory', product);
           console.warn(`LOW STOCK ALERT: ${product.name} is now unavailable.`);
        }
      }
    }
  }
};

import { db } from '../services/db';
import { DetailedOrder, SalesSummary } from '../types';

/**
 * ReportsAPI: Authoritative analytics engine.
 */
export const ReportsAPI = {
  async getSalesPerformance(startDate: string, endDate: string): Promise<SalesSummary> {
    const orders = await db.getAll<DetailedOrder>('orders');
    const filtered = orders.filter(o => o.status === 'Paid'); // Exclude Voids

    return {
      date: new Date().toLocaleDateString(),
      grossSales: filtered.reduce((a, b) => a + b.total, 0),
      discounts: filtered.reduce((a, b) => a + (b.discount || 0), 0),
      netSales: filtered.reduce((a, b) => a + (b.total - (b.tax || 0)), 0),
      orderCount: filtered.length
    };
  },

  async generateDailyClose(): Promise<string> {
    const reportId = `Z-REP-${Date.now()}`;
    const stats = await this.getSalesPerformance('', '');

    // Create an immutable report entry
    await db.put('batches', {
      id: reportId,
      timestamp: new Date().toISOString(),
      type: 'Z_REPORT',
      data: stats,
      status: 'Closed'
    });

    return reportId;
  }
};

import React, { useState, useEffect } from 'react';
import { InventoryItem, Category, CartItem, Employee } from '../types';
import { InventoryAPI } from '../api/inventory';
import { OrdersAPI } from '../api/orders';
import MenuGrid from './POS/Register/MenuGrid';
import OrderSidebar from './POS/Register/OrderSidebar';
import { Loader2 } from 'lucide-react';

interface RegisterProps {
    currentUser: Employee;
}

const Register: React.FC<RegisterProps> = ({ currentUser }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [inventory, setInventory] = useState<InventoryItem[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);

    const [cart, setCart] = useState<CartItem[]>([]);
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        const loadData = async () => {
            const [items, cats] = await Promise.all([
                InventoryAPI.getItems(),
                InventoryAPI.getCategories()
            ]);
            setInventory(items);
            setCategories(cats);
            setIsLoading(false);
        };
        loadData();
    }, []);

    const handleAddToCart = (item: InventoryItem) => {
        if (!item.inStock) {
            alert(`${item.name} is currently out of stock.`);
            return;
        }
        setCart(prev => {
            const existing = prev.find(i => i.id === item.id);
            if (existing) {
                return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { ...item, quantity: 1, modifiers: [], color: 'bg-white' }];
        });
    };

    const handleUpdateQty = (id: string, delta: number) => {
        setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(1, i.quantity + delta) } : i));
    };

    /**
     * BACKEND-FIRST CHECKOUT: 
     * UI sends raw cart data to API. 
     * API handles the math, inventory, and database commits.
     */
    const handleCheckout = async () => {
        try {
            setIsLoading(true);
            const finalizedOrder = await OrdersAPI.processOrder(cart, currentUser.name, 'Main_Street_01');
            setCart([]);

            // Refresh inventory to reflect backend stock changes
            const refreshedItems = await InventoryAPI.getItems();
            setInventory(refreshedItems);

            alert(`Order ${finalizedOrder.id} Complete! Total: $${finalizedOrder.total.toFixed(2)}`);
        } catch (err) {
            alert("Payment failed: " + (err as Error).message);
        } finally {
            setIsLoading(false);
        }
    };

    // Local UI display calculation (Non-authoritative, for user feedback only)
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const estimatedTax = subtotal * 0.0825;
    const estimatedTotal = subtotal + estimatedTax;

    const filteredItems = inventory.filter(i => 
        i.showOnPos && 
        (activeCategory === 'All' || i.category === activeCategory) &&
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (isLoading && inventory.length === 0) return <div className="h-full flex items-center justify-center"><Loader2 className="animate-spin text-indigo-500" size={40} /></div>;

    return (
        <div className="flex h-full bg-white rounded-3xl overflow-hidden shadow-2xl border border-slate-200">
            <MenuGrid 
                items={filteredItems}
                categories={categories}
                activeCategory={activeCategory}
                onCategoryChange={setActiveCategory}
                onItemSelect={handleAddToCart}
                searchTerm={searchTerm}
                onSearchChange={setSearchTerm}
            />
            <OrderSidebar 
                cart={cart}
                onUpdateQty={handleUpdateQty}
                onCheckout={handleCheckout}
                subtotal={subtotal}
                tax={estimatedTax}
                total={estimatedTotal}
            />
        </div>
    );
};

export default Register;

