export const AuthAPI = {
  async authenticate(passcode: string, deviceId: string): Promise<{user: Employee, token: string} | null> {
    const employees = await db.getAll<Employee>('employees');
    const user = employees.find(e => e.passcode === passcode);

    if (!user || user.status !== 'Active') return null;

    // Backend-side device validation logic
    const isAuthorizedTerminal = await this.validateDevice(deviceId);
    if (!isAuthorizedTerminal) throw new Error("Unauthorized hardware. Device not registered.");

    return {
      user,
      token: `omni_session_${Math.random().toString(36).substring(7)}`
    };
  },

  async validateDevice(deviceId: string): Promise<boolean> {
    // In production, check against a hardware registry store
    return true;
  },

  async verifyAccess(user: Employee, permissionKey: string): Promise<boolean> {
    if (user.role === UserRole.SUPER_ADMIN || user.role === 'Admin') return true;
    return user.permissions?.includes(permissionKey) || false;
  }
};

