import { InventoryAPI } from './inventory';

export const OrdersAPI = {
  async getOrders(): Promise<DetailedOrder[]> {
    return db.getAll<DetailedOrder>('orders');
  },

  /**
   * BACKEND-AUTHORITATIVE PROCESSING:
   * 1. Calculate Totals (Frontend is only for display)
   * 2. Apply Regional Taxes
   * 3. Record to Ledger
   * 4. Trigger Inventory Side-effects
   */
  async processSale(items: CartItem[], employeeId: string, locationId: string = 'DEFAULT'): Promise<DetailedOrder> {
    const subtotal = items.reduce((acc, i) => acc + (i.price * i.quantity), 0);

    // Backend-defined tax rules
    const TAX_RATE = 0.0825; 
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax;

    const newOrder: DetailedOrder = {
      id: `ORD-${Math.random().toString(36).substring(2, 11).toUpperCase()}`,
      date: new Date().toLocaleDateString(),
      time: new Date().toLocaleTimeString(),
      total,
      tax,
      status: 'Paid',
      paymentMethod: 'Card',
      employeeName: employeeId,
      device: 'OmniNode-01',
      type: 'Takeout',
      items: items.map(i => ({
        id: i.id,
        name: i.name,
        quantity: i.quantity,
        price: i.price,
        modifiers: i.modifiers
      })),
      discount: items.reduce((acc, i) => acc + (i.discount || 0), 0)
    };

    // Commit to persistent storage (IndexedDB simulation)
    await db.put('orders', newOrder);

    // BACKEND SIDE EFFECT: Automated Stock Deduction
    await InventoryAPI.deductItems(items);

    // Audit Log Entry
    await db.put('batches', {
      id: `AUDIT-${Date.now()}`,
      type: 'TRANSACTION_LOG',
      details: `Processed order ${newOrder.id} for $${total.toFixed(2)}`
    });

    return newOrder;
  }
};

