export const InventoryAPI = {
  async getItems(): Promise<InventoryItem[]> {
    return db.getAll<InventoryItem>('inventory');
  },

  async getCategories(): Promise<Category[]> {
    return db.getAll<Category>('categories');
  },

  // Backend side-effect: Automated stock management
  async deductItems(cart: CartItem[]): Promise<void> {
    const items = await this.getItems();
    for (const cartItem of cart) {
        const product = items.find(i => i.id === cartItem.id);
        if (product) {
            // Simulated deduction logic
            // In a production system, product.quantity -= cartItem.quantity;
            if (Math.random() > 0.95) { // Simulate random "Out of Stock" event
                product.inStock = false;
                await db.put('inventory', product);
                console.warn(`[Backend] Alert: Item ${product.name} is now Out of Stock.`);
            }
        }
    }
  }
};

