  ];

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900 overflow-hidden">
      <aside className={`bg-slate-900 text-slate-300 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} shrink-0 h-screen overflow-hidden z-40 shadow-2xl`}>
        <div className="p-6 border-b border-slate-800 flex items-center justify-between">
          {isSidebarOpen && <span className="font-black text-white text-xl tracking-tighter uppercase">OmniCommand</span>}
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
            <Menu size={20} />
          </button>
        </div>
        <nav className="flex-1 overflow-y-auto py-6 space-y-1">
          {menuItems.map(item => (
            <button 
                key={item.id} 
                onClick={() => setActiveTab(item.id)} 
                className={`w-full flex items-center gap-3 px-6 py-4 hover:bg-slate-800 hover:text-white transition-all
                    ${activeTab === item.id ? 'text-white bg-slate-800 border-l-4 border-indigo-500' : 'opacity-60 hover:opacity-100'}`}
            >
              {item.icon}
              {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-widest">{item.label}</span>}
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-800">
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-2 py-4 text-slate-500 hover:text-rose-500 transition-colors">
            <LogOut size={20} />
            {isSidebarOpen && <span className="font-black text-[10px] uppercase tracking-widest">Sign Out</span>}
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-20 shadow-sm">
            <div className="flex items-center gap-2">
                <span className="font-black text-[10px] uppercase tracking-[0.3em] text-slate-300">Terminal Node-01</span>
                <ChevronRight size={14} className="text-slate-200" />
                <h2 className="font-black text-xs uppercase tracking-[0.2em] text-indigo-600">{activeTab}</h2>
            </div>
            <div className="flex items-center gap-6">
                <div className="flex items-center gap-3 bg-slate-50 px-4 py-2 rounded-xl border border-slate-200">
                    <div className="h-2 w-2 rounded-full bg-emerald-500" />
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">User: {currentUser.name}</span>
                </div>
            </div>
        </header>

        <div className="flex-1 overflow-auto p-10 bg-slate-50/50">
            {activeTab === 'Launcher' && <AppLauncher user={currentUser} onSelectApp={setActiveTab} />}
            {activeTab === 'Home' && <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />}
            {activeTab === 'New Sale' && <Register currentUser={currentUser} />}
            {activeTab === 'Reports' && <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} />}
            {activeTab === 'Employees' && <Employees employees={employees} onAddEmployee={e => EmployeesAPI.saveEmployee(e)} onDeleteEmployee={id => EmployeesAPI.deleteEmployee(id)} />}
            {activeTab === 'Inventory' && <Items items={inventory} />}
            {activeTab === 'Settings' && <Settings floorPlanTables={floorPlan} onSaveFloorPlan={DiningAPI.saveFullFloorPlan} />}
            {activeTab === 'Dining' && <div className="h-[600px]"><Settings floorPlanTables={floorPlan} onSaveFloorPlan={DiningAPI.saveFullFloorPlan} /></div>}
        </div>
      </main>
    </div>
  );
};

