import React from 'react';
import { 
  Grid, Coffee, ClipboardList, DollarSign, RotateCcw, Package, 
  LayoutGrid, User, Clock, Calendar, ChefHat, Barcode, Eye, CreditCard
} from 'lucide-react';
import { Employee, UserRole } from '../../types';

export type PosAppType = 'LAUNCHER' | 'REGISTER' | 'TABLE_SERVICE' | 'ORDERS' | 'TIPS' | 'REFUNDS' | 'CUSTOMERS' | 'INVENTORY_SCANNER' | 'RESERVATIONS' | 'SCHEDULING' | 'KITCHEN' | 'EXPEDITOR' | 'CLOSEOUT';

interface PosLauncherProps {
    user: Employee;
    onAppSelect: (app: PosAppType) => void;
}

const PosLauncher: React.FC<PosLauncherProps> = ({ user, onAppSelect }) => {
    const POSAppIcon = ({ title, id, icon, gradient, onClick, isNew }: { title: string, id: PosAppType, icon: React.ReactNode, gradient: string, onClick: () => void, isNew?: boolean }) => {
        const role = user.role;
        let allowed = false;

        if (role === UserRole.SUPER_ADMIN || role === UserRole.BUSINESS_ADMIN || role === 'Admin' || role === 'Manager') {
            allowed = true;
        } else if (role === UserRole.CASHIER) {
            allowed = ['REGISTER', 'ORDERS', 'CUSTOMERS', 'TIPS', 'REFUNDS', 'CLOSEOUT'].includes(id);
        } else if (role === UserRole.STAFF || role === 'Server' || role === 'Server Lead') {
            allowed = ['REGISTER', 'TABLE_SERVICE', 'SCHEDULING', 'KITCHEN', 'ORDERS'].includes(id);
        } else if (role === 'Host') {
            allowed = ['RESERVATIONS', 'TABLE_SERVICE'].includes(id);
        }

        if (!allowed) return null;

        return (
            <button 
                onClick={onClick}
                className="aspect-square flex flex-col items-center justify-center gap-4 transition-all group rounded-3xl bg-white hover:shadow-2xl hover:scale-[1.02] active:scale-95 shadow-md border border-slate-200 relative overflow-hidden"
            >
                {isNew && <div className="absolute top-2 right-2 bg-emerald-500 text-[8px] text-white px-1.5 py-0.5 rounded-full font-black">NEW</div>}
                <div className={`h-16 w-16 rounded-2xl bg-gradient-to-br ${gradient} text-white flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform`}>
                    {icon}
                </div>
                <span className="font-black text-slate-800 text-xs tracking-tighter uppercase">{title}</span>
            </button>
        );
    };

    return (
        <div className="p-12 h-full overflow-y-auto bg-slate-50 flex flex-col items-center justify-center">
            <div className="text-center mb-16">
                <p className="text-xs font-black text-indigo-600 uppercase tracking-[0.4em] mb-3">Enterprise Terminal</p>
                <h2 className="text-5xl font-black text-slate-900 tracking-tighter uppercase">OmniCommand Hub</h2>
                <div className="h-1 w-24 bg-indigo-600 mx-auto mt-6 rounded-full"></div>
            </div>
            <div className="max-w-6xl w-full grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-8 animate-fade-in pb-20">
                <POSAppIcon id="REGISTER" title="Register" icon={<CreditCard size={32} />} gradient="from-indigo-600 to-indigo-800" onClick={() => onAppSelect('REGISTER')} />
                <POSAppIcon id="TABLE_SERVICE" title="Dining" icon={<Coffee size={32} />} gradient="from-orange-500 to-orange-600" onClick={() => onAppSelect('TABLE_SERVICE')} />
                <POSAppIcon id="KITCHEN" title="KDS" icon={<ChefHat size={32} />} gradient="from-slate-700 to-slate-900" onClick={() => onAppSelect('KITCHEN')} />
                <POSAppIcon id="EXPEDITOR" title="Expo" icon={<Eye size={32} />} gradient="from-cyan-500 to-cyan-600" onClick={() => onAppSelect('EXPEDITOR')} isNew />
                <POSAppIcon id="RESERVATIONS" title="Host Stand" icon={<Calendar size={32} />} gradient="from-rose-500 to-rose-600" onClick={() => onAppSelect('RESERVATIONS')} />
                <POSAppIcon id="CLOSEOUT" title="Shift End" icon={<DollarSign size={32} />} gradient="from-emerald-600 to-emerald-800" onClick={() => onAppSelect('CLOSEOUT')} isNew />
                <POSAppIcon id="ORDERS" title="History" icon={<ClipboardList size={32} />} gradient="from-slate-400 to-slate-500" onClick={() => onAppSelect('ORDERS')} />
                <POSAppIcon id="INVENTORY_SCANNER" title="Scanner" icon={<Barcode size={32} />} gradient="from-amber-500 to-amber-600" onClick={() => onAppSelect('INVENTORY_SCANNER')} isNew />
                <POSAppIcon id="SCHEDULING" title="Staff" icon={<Clock size={32} />} gradient="from-blue-400 to-blue-500" onClick={() => onAppSelect('SCHEDULING')} />
                <POSAppIcon id="CUSTOMERS" title="Loyalty" icon={<User size={32} />} gradient="from-purple-600 to-purple-800" onClick={() => onAppSelect('CUSTOMERS')} />
            </div>
        </div>
    );
};

export default PosLauncher;

import React, { useState } from 'react';
import { 
    DetailedOrder, Transaction, Customer, Employee, InventoryItem, 
    Table, Reservation, Schedule, Category, PaymentSplit, Receipt, 
    DiscountCode, DiningTable, KDSSettings, UserRole, CartItem 
} from '../types';
import { LayoutGrid, Lock, ShieldAlert, Monitor, ChevronRight } from 'lucide-react';
import PosLauncher, { PosAppType } from './POS/PosLauncher';
import PosRegister from './POS/PosRegister';
import ReservationsApp from './ReservationsApp';
import SchedulingApp from './SchedulingApp';
import TableServiceApp from './TableServiceApp';
import KitchenDisplay from './KitchenDisplay';
import ExpeditorScreen from './POS/ExpeditorScreen';
import InventoryScanner from './POS/InventoryScanner';
import CashierCloseout from './POS/CashierCloseout';
import PasscodeLock from './PasscodeLock';

interface CashierPOSProps {
  onLogout: () => void;
  onProcessSale: (cart: CartItem[], total: number) => void;
  currentUser: Employee;
  sharedOrders: DetailedOrder[];
  sharedTransactions: Transaction[];
  sharedCustomers: Customer[];
  sharedEmployees: Employee[];
  sharedInventory: InventoryItem[];
  sharedCategories: Category[];
  sharedDiscounts?: DiscountCode[];
  sharedTables: Table[];
  sharedReservations: Reservation[];
  sharedSchedules: Schedule[];
  onSeatReservation: (resId: string, tableId: string) => void;
  integrationConfig: { reservation_pos: boolean; scheduling_pos: boolean; kdsEnabled: boolean };
  floorPlanTables?: DiningTable[];
  kdsSettings?: KDSSettings;
  receiptSettings?: any;
  onFireToKitchen?: (kitchenPayload: any) => void;
}

const CashierPOS: React.FC<CashierPOSProps> = (props) => {
  const [currentApp, setCurrentApp] = useState<PosAppType>('LAUNCHER');
  const [authenticatedPosUser, setAuthenticatedPosUser] = useState<Employee | null>(null);
  const [clockedIn, setClockedIn] = useState(true);

  if (!authenticatedPosUser) {
      return (
        <PasscodeLock 
            employees={props.sharedEmployees} 
            onAuthenticated={(user) => setAuthenticatedPosUser(user)}
            onCancel={props.onLogout}
        />
      );
  }

  return (
    <div className="h-screen flex flex-col overflow-hidden bg-slate-50 font-sans text-slate-900">
        <header className="h-20 bg-white text-slate-800 flex items-center justify-between px-8 shrink-0 shadow-sm z-30 border-b border-slate-200">
            <div className="flex items-center gap-6">
                <button onClick={() => setCurrentApp('LAUNCHER')} className="flex items-center gap-3 group">
                    <div className="h-10 w-10 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform">
                        <LayoutGrid size={20} className="text-white" />
                    </div>
                    <div className="text-left">
                        <p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.2em] leading-none mb-1">Terminal Mode</p>
                        <h1 className="font-black text-xl tracking-tighter uppercase leading-none">Omni COMMAND</h1>
                    </div>
                </button>
                {currentApp !== 'LAUNCHER' && (
                    <div className="flex items-center gap-4 animate-fade-in">
                        <ChevronRight size={18} className="text-slate-300" />
                        <h2 className="font-black text-sm uppercase tracking-widest text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-xl border border-indigo-100">
                            {currentApp.replace('_', ' ')}
                        </h2>
                    </div>
                )}
            </div>
            <div className="flex items-center gap-6">
                <div className="flex items-center gap-3 bg-slate-50 px-5 py-2.5 rounded-2xl border border-slate-100">
                    <div className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
                    <div className="text-left leading-none">
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Authenticated</p>
                        <p className="text-xs font-black uppercase text-slate-700">{authenticatedPosUser.name}</p>
                    </div>
                </div>
                <button onClick={() => setAuthenticatedPosUser(null)} className="p-3 hover:bg-slate-100 rounded-2xl text-slate-400 hover:text-indigo-600 transition-colors" title="Lock Terminal">
                    <Lock size={20} />
                </button>
            </div>
        </header>

        <main className="flex-1 overflow-hidden flex flex-col relative">
            {currentApp === 'LAUNCHER' && (
                <PosLauncher user={authenticatedPosUser} onAppSelect={setCurrentApp} />
            )}
            {currentApp === 'REGISTER' && (
                <PosRegister 
                    inventory={props.sharedInventory} 
                    categories={props.sharedCategories} 
                    discounts={props.sharedDiscounts || []} 
                    onFinish={(cart, total) => {
                        props.onProcessSale(cart, total);
                        setCurrentApp('LAUNCHER');
                    }} 
                />
            )}
            {currentApp === 'TABLE_SERVICE' && (
                <TableServiceApp 
                    tables={props.floorPlanTables || []}
                    inventory={props.sharedInventory}
                    categories={props.sharedCategories}
                    currentUser={authenticatedPosUser}
                    onExit={() => setCurrentApp('LAUNCHER')}
                />
            )}
            {currentApp === 'KITCHEN' && <KitchenDisplay settings={props.kdsSettings} />}
            {currentApp === 'EXPEDITOR' && <ExpeditorScreen />}
            {currentApp === 'INVENTORY_SCANNER' && <InventoryScanner items={props.sharedInventory} />}
            {currentApp === 'CLOSEOUT' && <CashierCloseout />}
            {currentApp === 'RESERVATIONS' && (
                <ReservationsApp 
                    reservations={props.sharedReservations} 
                    tables={[]} 
                    floorPlanTables={props.floorPlanTables || []}
                    onSeatReservation={props.onSeatReservation} 
                    isConnectedToPos={props.integrationConfig.reservation_pos} 
                />
            )}
            {currentApp === 'SCHEDULING' && <SchedulingApp schedules={props.sharedSchedules} />}
        </main>
    </div>
  );
};

export default CashierPOS;

