# BYTEPOS CART SYSTEM - COMPLETE SPECIFICATION
##  Cart Management & Order Workflows

---

## CART ARCHITECTURE OVERVIEW

```
┌─────────────────────────────────────────────────────────────────┐
│                        CART STATE MACHINE                        │
├─────────────────────────────────────────────────────────────────┤
│  EMPTY → BUILDING → REVIEWING → PAYMENT → COMPLETE              │
│                                                                   │
│  Parallel States:                                                │
│  - Items (add, modify, remove, discount, note)                  │
│  - Customer (assign, create, loyalty)                           │
│  - Table/Order Type (dine-in, takeout, delivery)               │
│  - Discounts (order-level, item-level, promo codes)            │
│  - Splits (by item, by seat, by amount, evenly)                │
│  - Payments (multiple tenders, tips, signatures)                │
└─────────────────────────────────────────────────────────────────┘
```

---

## CART DATA MODEL

```typescript
interface Cart {
  // Core Identity
  id: string;                           // Cart UUID
  orderId?: string;                     // Assigned when sent to kitchen
  businessId: string;                   // Tenant ID
  deviceId: string;                     // Device creating cart
  employeeId: string;                   // Cashier/Server ID

  // Order Metadata
  orderType: 'dine_in' | 'takeout' | 'delivery' | 'online';
  tableId?: string;                     // For dine-in
  tableName?: string;                   // "Table 12"
  seatCount?: number;                   // Number of guests
  customerId?: string;                  // Assigned customer
  customerName?: string;                // "John Doe"

  // Cart State
  state: 'building' | 'reviewing' | 'payment' | 'complete';
  createdAt: Date;
  updatedAt: Date;
  sentToKitchenAt?: Date;               // When fired

  // Items Collection
  items: CartItem[];                    // Line items

  // Financial Breakdown
  subtotal: number;                     // Sum of all items before discounts
  itemDiscounts: number;                // Item-level discounts
  orderDiscounts: Discount[];           // Order-level discounts
  totalDiscounts: number;               // Sum of all discounts
  taxableAmount: number;                // After discounts
  taxes: TaxBreakdown[];                // Multiple tax rates
  totalTax: number;                     // Sum of taxes
  fees: Fee[];                          // Delivery fee, service charge
  totalFees: number;                    // Sum of fees
  subtotalAfterDiscounts: number;       // Subtotal - discounts + fees
  total: number;                        // Final amount (subtotal - discounts + tax + fees)

  // Payment State
  payments: Payment[];                  // Multiple tender types
  totalPaid: number;                    // Sum of payments
  totalDue: number;                     // Remaining balance
  tipAmount?: number;                   // Tip (added to total)
  tipPercent?: number;                  // Tip % for reference

  // Split State
  splitMode?: 'none' | 'by_seat' | 'by_item' | 'by_amount' | 'evenly';
  splits?: CartSplit[];                 // Multiple carts if split

  // Metadata
  orderNote?: string;                   // "No peanuts"
  courseTiming?: CourseTiming[];        // Fire apps now, hold entrees
  printedReceipts: string[];            // Receipt IDs
  voidedAt?: Date;                      // If voided
  voidReason?: string;                  // Manager void reason
  refundedAt?: Date;                    // If refunded
  refundReason?: string;
}

interface CartItem {
  id: string;                           // Line item UUID
  itemId: string;                       // Menu item ID
  name: string;                         // "Cheeseburger"
  sku?: string;                         // "BURG-001"
  categoryId: string;
  categoryName: string;                 // "Entrees"

  // Quantity & Pricing
  quantity: number;                     // Default 1
  unitPrice: number;                    // Base price
  modifiersPrice: number;               // Sum of modifier adjustments
  linePrice: number;                    // (unitPrice + modifiersPrice) × quantity

  // Modifiers
  modifiers: CartModifier[];            // Applied modifiers

  // Seat Assignment (Table Service)
  seatNumber?: number;                  // Seat 1, 2, 3...
  guestName?: string;                   // "Alice"

  // Course Timing
  course?: 'appetizer' | 'entree' | 'dessert' | 'beverage';
  fireTiming?: 'now' | 'hold' | 'fire_at';
  fireAt?: Date;                        // When to send to kitchen

  // Discounts
  discounts: ItemDiscount[];            // Applied discounts
  totalDiscount: number;                // Sum of discounts
  finalPrice: number;                   // linePrice - totalDiscount

  // Tax
  taxable: boolean;                     // Is this item taxable?
  taxAmount: number;                    // Calculated tax

  // Kitchen State
  sentToKitchen: boolean;               // Fired to KDS
  sentAt?: Date;
  kitchenStation?: string;              // "Grill", "Fryer"
  prepTimeMinutes?: number;             // Estimated prep time

  // Special Requests
  specialRequest?: string;              // "Well done"
  allergies?: string[];                 // ["Gluten", "Dairy"]

  // Status Tracking
  status: 'draft' | 'sent' | 'preparing' | 'ready' | 'served' | 'voided';
  voidedAt?: Date;
  voidReason?: string;

  // Metadata
  isRefunded: boolean;
  refundedQuantity?: number;            // Partial refund support
  addedAt: Date;
  updatedAt: Date;
}

interface CartModifier {
  id: string;
  modifierGroupId: string;
  modifierGroupName: string;            // "Protein"
  modifierId: string;
  name: string;                         // "Add Bacon"
  priceAdjustment: number;              // +2.00, -1.00, 0.00
  quantity: number;                     // For "Extra Cheese" × 2
}

interface Discount {
  id: string;
  type: 'percentage' | 'fixed_amount' | 'bogo' | 'promo_code';
  name: string;                         // "Happy Hour 20%"
  code?: string;                        // "SUMMER25"
  value: number;                        // 20 (for %), 5.00 (for fixed)
  amount: number;                       // Calculated discount $
  appliedTo: 'order' | 'item';
  itemIds?: string[];                   // If item-level
  requiresManagerApproval: boolean;
  approvedBy?: string;                  // Employee ID
  appliedAt: Date;
}

interface ItemDiscount {
  discountId: string;
  name: string;
  amount: number;                       // Discount $ for this item
}

interface TaxBreakdown {
  taxId: string;
  name: string;                         // "State Sales Tax"
  rate: number;                         // 0.0725 (7.25%)
  taxableAmount: number;                // Amount this tax applies to
  amount: number;                       // Calculated tax $
}

interface Fee {
  id: string;
  type: 'delivery' | 'service_charge' | 'cc_surcharge';
  name: string;
  amount: number;
  percentage?: number;                  // If % based
}

interface Payment {
  id: string;
  method: 'card' | 'cash' | 'gift_card' | 'house_account' | 'comp' | 'custom';
  amount: number;
  tipAmount?: number;                   // Tip on this payment
  status: 'pending' | 'authorized' | 'captured' | 'declined' | 'voided';

  // Card Details (Tokenized)
  cardBrand?: string;                   // "Visa"
  cardLast4?: string;                   // "4242"
  cardToken?: string;                   // Processor token

  // Cash Details
  cashTendered?: number;                // Customer gave $50
  cashChange?: number;                  // Change $10.50

  // Metadata
  processedAt?: Date;
  processorTransactionId?: string;
  offline: boolean;                     // Queued for sync
  idempotencyKey: string;
}

interface CartSplit {
  splitId: string;
  name: string;                         // "Seat 1", "Alice", "Split 1/3"
  items: CartItem[];                    // Items in this split
  subtotal: number;
  discounts: number;
  tax: number;
  total: number;
  payments: Payment[];
  paid: boolean;
}

interface CourseTiming {
