## IMPLEMENTATION EXAMPLE

```typescript
// apps/mobile/pos-register/src/domain/cart/CartManager.ts

export class CartManager {
  private cart: Cart;
  private db: LocalDatabase;
  private api: APIClient;
  private eventBus: EventBus;

  constructor() {
    this.cart = this.createEmptyCart();
    this.setupAutoSave();
  }

  // ===== ITEM OPERATIONS =====

  async addItem(params: AddItemParams): Promise<CartItem> {
    const item: CartItem = {
      id: uuid(),
      itemId: params.itemId,
      name: await this.getItemName(params.itemId),
      quantity: params.quantity || 1,
      unitPrice: await this.getItemPrice(params.itemId),
      modifiers: await this.buildModifiers(params.modifiers),
      modifiersPrice: this.calculateModifiersPrice(params.modifiers),
      seatNumber: params.seatNumber,
      specialRequest: params.specialRequest,
      course: params.course,
      status: 'draft',
      addedAt: new Date(),
      updatedAt: new Date()
    };

    // Calculate prices
    item.linePrice = (item.unitPrice + item.modifiersPrice) * item.quantity;
    item.finalPrice = item.linePrice; // Before discounts

    // Add to cart
    this.cart.items.push(item);

    // Recalculate totals
    await this.recalculateTotals();

    // Save
    await this.save();

    // Emit event
    this.eventBus.emit('cart:item_added', item);

    return item;
  }

  async removeItem(itemId: string, reason?: string): Promise<void> {
    const item = this.cart.items.find(i => i.id === itemId);
    if (!item) throw new Error('Item not found');

    // Check if sent to kitchen
    if (item.sentToKitchen) {
      const approved = await this.requestManagerApproval('Remove item sent to kitchen');
      if (!approved) throw new Error('Manager approval required');
    }

    // Track reason
    if (reason) {
      await this.trackRemovalReason(itemId, reason);
    }

    // Remove from cart
    this.cart.items = this.cart.items.filter(i => i.id !== itemId);

    // Recalculate
    await this.recalculateTotals();
    await this.save();

    this.eventBus.emit('cart:item_removed', { itemId, reason });
  }

  async modifyItem(itemId: string, params: ModifyItemParams): Promise<CartItem> {
    const item = this.cart.items.find(i => i.id === itemId);
    if (!item) throw new Error('Item not found');

    // Update fields
    if (params.quantity) item.quantity = params.quantity;
    if (params.modifiers) item.modifiers = params.modifiers;
    if (params.specialRequest !== undefined) item.specialRequest = params.specialRequest;
    if (params.seatNumber) item.seatNumber = params.seatNumber;

    // Recalculate prices
    item.modifiersPrice = this.calculateModifiersPrice(item.modifiers);
    item.linePrice = (item.unitPrice + item.modifiersPrice) * item.quantity;
    item.finalPrice = item.linePrice - item.totalDiscount;
    item.updatedAt = new Date();

    // Recalculate totals
    await this.recalculateTotals();
    await this.save();

    this.eventBus.emit('cart:item_modified', item);

    return item;
  }

  // ===== DISCOUNT OPERATIONS =====

  async applyDiscount(params: ApplyDiscountParams): Promise<void> {
    const discount: Discount = {
      id: uuid(),
      type: params.type,
      name: params.name,
      value: params.value,
      amount: 0, // Calculated below
      appliedTo: params.appliedTo,
      itemIds: params.itemIds,
      requiresManagerApproval: params.value > 20, // >20% requires approval
      appliedAt: new Date()
    };

    // Manager approval
    if (discount.requiresManagerApproval) {
      const approved = await this.requestManagerApproval(
        `Apply ${discount.value}% discount`
      );
      if (!approved) throw new Error('Manager approval required');
      discount.approvedBy = this.currentEmployee.id;
    }

    // Calculate discount amount
    if (discount.appliedTo === 'order') {
      if (discount.type === 'percentage') {
        discount.amount = this.cart.subtotal * (discount.value / 100);
      } else {
        discount.amount = discount.value;
      }
      this.cart.orderDiscounts.push(discount);
    } else {
      // Item-level discount
      for (const itemId of discount.itemIds!) {
        const item = this.cart.items.find(i => i.id === itemId);
        if (!item) continue;

        const itemDiscount: ItemDiscount = {
          discountId: discount.id,
          name: discount.name,
          amount: discount.type === 'percentage'
            ? item.linePrice * (discount.value / 100)
            : discount.value
        };

        item.discounts.push(itemDiscount);
        item.totalDiscount += itemDiscount.amount;
        item.finalPrice = item.linePrice - item.totalDiscount;
      }
    }

    // Recalculate
    await this.recalculateTotals();
    await this.save();

    this.eventBus.emit('cart:discount_applied', discount);
  }

  // ===== SPLIT OPERATIONS =====

  async splitBySeat(): Promise<CartSplit[]> {
    const seats = [...new Set(this.cart.items.map(i => i.seatNumber))].filter(Boolean);
    const splits: CartSplit[] = [];

    for (const seat of seats) {
      const seatItems = this.cart.items.filter(i => i.seatNumber === seat);

      const split: CartSplit = {
        splitId: uuid(),
        name: `Seat ${seat}`,
        items: seatItems,
        subtotal: seatItems.reduce((sum, i) => sum + i.finalPrice, 0),
        discounts: 0, // TODO: Proportional
        tax: 0, // TODO: Calculate
        total: 0, // TODO: Calculate
        payments: [],
        paid: false
      };

      split.total = split.subtotal - split.discounts + split.tax;
      splits.push(split);
    }

    // Handle shared items
    const sharedItems = this.cart.items.filter(i => !i.seatNumber);
    if (sharedItems.length > 0) {
      const sharedSplit: CartSplit = {
        splitId: uuid(),
        name: 'Shared Items',
        items: sharedItems,
        subtotal: sharedItems.reduce((sum, i) => sum + i.finalPrice, 0),
        discounts: 0,
        tax: 0,
        total: 0,
        payments: [],
        paid: false
      };
      splits.push(sharedSplit);
    }

    this.cart.splitMode = 'by_seat';
    this.cart.splits = splits;

    await this.save();
    this.eventBus.emit('cart:split', splits);

    return splits;
  }

  // ===== PAYMENT OPERATIONS =====

  async processPayment(params: ProcessPaymentParams): Promise<Payment> {
    const payment: Payment = {
      id: uuid(),
      method: params.method,
      amount: params.amount,
      tipAmount: params.tipAmount,
      status: 'pending',
      offline: !navigator.onLine,
      idempotencyKey: `${this.deviceId}:${this.cart.id}:${Date.now()}`,
      processedAt: new Date()
    };

    // Process based on method
    if (params.method === 'card') {
      const result = await this.processCardPayment(payment, params.cardToken!);
      payment.status = result.status;
      payment.processorTransactionId = result.transactionId;
      payment.cardBrand = result.cardBrand;
      payment.cardLast4 = result.cardLast4;
    } else if (params.method === 'cash') {
      payment.cashTendered = params.cashTendered;
      payment.cashChange = params.cashTendered! - payment.amount;
      payment.status = 'captured';
    }

    // Add to cart
    this.cart.payments.push(payment);
    this.cart.totalPaid += payment.amount + (payment.tipAmount || 0);
    this.cart.totalDue = this.cart.total - this.cart.totalPaid;

    // Check if fully paid
    if (this.cart.totalDue <= 0) {
      this.cart.state = 'complete';
      await this.closeOrder();
    }

    await this.save();
    this.eventBus.emit('cart:payment_added', payment);

    return payment;
  }

  // ===== TOTALS CALCULATION =====

  private async recalculateTotals(): Promise<void> {
    // Subtotal
    this.cart.subtotal = this.cart.items.reduce((sum, i) => sum + i.linePrice, 0);

    // Item discounts
    this.cart.itemDiscounts = this.cart.items.reduce((sum, i) => sum + i.totalDiscount, 0);

    // Order discounts
    this.cart.totalDiscounts = this.cart.itemDiscounts + 
      this.cart.orderDiscounts.reduce((sum, d) => sum + d.amount, 0);

    // Taxable amount
    this.cart.taxableAmount = this.cart.subtotal - this.cart.totalDiscounts;

    // Calculate taxes
    this.cart.taxes = await this.calculateTaxes(this.cart.taxableAmount);
    this.cart.totalTax = this.cart.taxes.reduce((sum, t) => sum + t.amount, 0);

    // Fees
    this.cart.totalFees = this.cart.fees.reduce((sum, f) => sum + f.amount, 0);

    // Total
    this.cart.total = this.cart.taxableAmount + this.cart.totalTax + this.cart.totalFees;

    // Total due
    this.cart.totalDue = this.cart.total - this.cart.totalPaid;
  }

  // ===== SEND TO KITCHEN =====

  async sendToKitchen(): Promise<void> {
    // Validate
    if (this.cart.items.length === 0) {
      throw new Error('Cannot send empty cart');
    }

    // Create order
    const order = await this.api.orders.create({
      businessId: this.cart.businessId,
      items: this.cart.items,
      orderType: this.cart.orderType,
      tableId: this.cart.tableId,
      customerId: this.cart.customerId,
      employeeId: this.cart.employeeId
    });

    this.cart.orderId = order.id;
    this.cart.sentToKitchenAt = new Date();
    this.cart.state = 'reviewing';

    // Mark items as sent
    for (const item of this.cart.items) {
      item.sentToKitchen = true;
      item.sentAt = new Date();
      item.status = 'sent';
    }

    // Print kitchen tickets
    await this.printKitchenTickets(order);

    await this.save();
    this.eventBus.emit('cart:sent_to_kitchen', order);
  }

  // ===== PERSISTENCE =====

  private async save(): Promise<void> {
    this.cart.updatedAt = new Date();

    // Save locally
    await this.db.carts.put(this.cart);

    // Sync to server if online
    if (navigator.onLine) {
      await this.api.carts.update(this.cart.id, this.cart);
    }
  }

  private setupAutoSave(): void {
    setInterval(() => {
      this.save();
    }, 30000); // Every 30 seconds
  }
}
