const Register: React.FC<RegisterProps> = ({ inventory, categories, discounts, onFinish, currentUser }) => {
    const [isLoading, setIsLoading] = useState(false);

    // Cart State
    const [cart, setCart] = useState<CartItem[]>([]);
    const [activeCustomer, setActiveCustomer] = useState<string | null>(null);
    const [orderType, setOrderType] = useState('Dine-in');
    const [activeDiscount, setActiveDiscount] = useState<DiscountCode | null>(null);

    // UI State
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedItemForEdit, setSelectedItemForEdit] = useState<CartItem | null>(null);

    // Modal States
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showDiscountModal, setShowDiscountModal] = useState(false);

    // Filter Logic
    const filteredItems = inventory.filter(i => 
        i.showOnPos && 
        (activeCategory === 'All' || i.category === activeCategory) &&
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Cart Actions
    const handleAddToCart = (item: InventoryItem) => {
        if (!item.inStock) {
            alert(`${item.name} is currently out of stock.`);
            return;
        }
        setCart(prev => {
            // Check if exact item exists (no mods) to increment
            const existing = prev.find(i => i.id === item.id && (!i.modifiers || i.modifiers.length === 0));
            if (existing) {
                return prev.map(i => i.cartId === existing.cartId ? { ...i, quantity: i.quantity + 1 } : i);
            }
            // Add new line item
            return [...prev, { 
                ...item, 
                cartId: `cart-${Date.now()}-${Math.random()}`,
                quantity: 1, 
                modifiers: [], 
                color: 'bg-white' 
            }];
        });
    };

    const handleUpdateQty = (cartId: string, delta: number) => {
        setCart(prev => {
            const existing = prev.find(i => (i.cartId || i.id) === cartId);
            if (!existing) return prev;
            const newQty = existing.quantity + delta;
            if (newQty <= 0) return prev.filter(i => (i.cartId || i.id) !== cartId);
            return prev.map(i => (i.cartId || i.id) === cartId ? { ...i, quantity: newQty } : i);
        });
    };

    const handleRemoveItem = (cartId: string) => {
        setCart(prev => prev.filter(i => (i.cartId || i.id) !== cartId));
    };

    const handleUpdateItem = (updatedItem: CartItem) => {
        setCart(prev => prev.map(i => i.cartId === updatedItem.cartId ? updatedItem : i));
    };

    const handleCheckout = async () => {
        setIsLoading(true);
        // Simulate backend processing
        setTimeout(() => {
            const total = calculateTotals().total;
            // Mock payments for now
            const payments = [{ method: 'Card', amount: total, status: 'Paid' }];
            onFinish(cart, total, payments);
            setCart([]);
            setActiveCustomer(null);
            setIsLoading(false);
        }, 800);
    };

    const calculateTotals = () => {
        const subtotal = cart.reduce((acc, item) => item.isVoided ? acc : acc + (item.price * item.quantity), 0);

        let discountAmt = 0;
        if (activeDiscount) {
            discountAmt = activeDiscount.type === 'Percentage' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value;
        }

        const taxable = Math.max(0, subtotal - discountAmt);
        const tax = taxable * 0.0825;
        const total = taxable + tax;

        return { subtotal, tax, total };
    };

    const { subtotal, tax, total } = calculateTotals();

    return (
        <div className="flex h-full bg-white rounded-[2rem] overflow-hidden shadow-2xl border border-slate-200 relative">
            {/* Overlay Modals */}
            {selectedItemForEdit && (
                <ItemDetailModal 
                    item={selectedItemForEdit} 
                    onClose={() => setSelectedItemForEdit(null)} 
                    onSave={handleUpdateItem} 
                />
            )}
            {showCustomerModal && (
                <CustomerModal 
                    onClose={() => setShowCustomerModal(false)}
                    onSelect={(name) => setActiveCustomer(name)}
                />
            )}

            {/* Main Area */}
            <div className="flex-1 flex flex-col bg-slate-50/50 relative">
                {/* Top Action Bar */}
                <div className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-6 shrink-0">
                    <div className="flex items-center gap-4">
                        <button 
                            onClick={() => setShowCustomerModal(true)}
                            className="flex items-center gap-2 px-3 py-1.5 bg-slate-100 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-200 transition-colors"
                        >
                            {activeCustomer ? <><Check size={16} className="text-emerald-500" /> {activeCustomer}</> : <><UserPlus size={16} /> Add Customer</>}
                        </button>
                        <select 
                            value={orderType} 
                            onChange={(e) => setOrderType(e.target.value)}
                            className="bg-slate-100 border-none rounded-lg px-3 py-1.5 text-sm font-bold text-slate-600 focus:ring-0 cursor-pointer hover:bg-slate-200 transition-colors"
                        >
                            <option>Dine-in</option>
                            <option>Takeout</option>
                            <option>Delivery</option>
                        </select>
                    </div>
                    <div className="relative w-64">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input 
                            type="text" 
                            placeholder="Search..." 
                            value={searchTerm} 
                            onChange={e => setSearchTerm(e.target.value)}
                            className="w-full bg-slate-100 rounded-lg pl-9 pr-3 py-1.5 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500"
                        />
                    </div>
                </div>

                {/* Content */}
                <MenuGrid 
                    items={filteredItems}
                    categories={categories}
                    activeCategory={activeCategory}
                    onCategoryChange={setActiveCategory}
                    onItemSelect={handleAddToCart}
                    searchTerm={searchTerm}
                    onSearchChange={setSearchTerm}
                />
            </div>

            {/* Right Sidebar */}
            <OrderSidebar 
                cart={cart}
                onUpdateQty={handleUpdateQty}
                onRemoveItem={handleRemoveItem}
                onEditItem={setSelectedItemForEdit}
                onCheckout={handleCheckout}
                onSplit={() => alert("Split Check Modal Placeholder")}
                onDiscount={() => {
                    // Simple discount toggle for demo
                    setActiveDiscount(activeDiscount ? null : { id: 'd1', name: 'VIP 10%', type: 'Percentage', value: 10, status: 'Active' });
                }}
                onFire={() => {
                    setCart(prev => prev.map(i => ({...i, isFired: true})));
                    alert("Items fired to kitchen!");
                }}
                subtotal={subtotal}
                tax={tax}
                total={total}
                orderType={orderType}
                activeCustomer={activeCustomer}
                activeDiscount={activeDiscount}
            />

            {isLoading && (
                <div className="absolute inset-0 z-[100] bg-white/50 backdrop-blur-sm flex items-center justify-center">
                    <div className="bg-white p-6 rounded-2xl shadow-xl flex items-center gap-4">
                        <Loader2 className="animate-spin text-indigo-600" />
                        <span className="font-bold text-slate-800">Processing Transaction...</span>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Register;

import React, { useState, useEffect } from 'react';
import { DiningTable, InventoryItem, Category, Employee, DiningOrderItem, UserRole } from '../types';
import { X, LogOut, Plus, Minus, User, Search, Lock, Flame } from 'lucide-react';

interface TableServiceAppProps {
    tables: DiningTable[];
    inventory: InventoryItem[];
    categories: Category[];
    currentUser: Employee;
    onExit: () => void;
}

interface TableGuest {
    id: number;
    status: 'Active' | 'Paid';
}

const TableServiceApp: React.FC<TableServiceAppProps> = ({ tables, inventory, categories, currentUser, onExit }) => {
    const [localTables, setLocalTables] = useState<DiningTable[]>(tables);
    const [activeTableId, setActiveTableId] = useState<string | null>(null);
    const [activeSeat, setActiveSeat] = useState<number>(0); // 0 is shared
    const [guests, setGuests] = useState<TableGuest[]>([{ id: 1, status: 'Active' }]);
    const [orderItems, setOrderItems] = useState<DiningOrderItem[]>([]);
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        setLocalTables(tables);
    }, [tables]);

    const activeTable = localTables.find(t => t.id === activeTableId);
    const isManager = currentUser.role === UserRole.BUSINESS_ADMIN || currentUser.role === UserRole.SUPER_ADMIN || currentUser.role === 'Manager';

    const handleTableClick = (table: DiningTable) => {
        if (table.status === 'Available') {
            const updatedTable = { ...table, status: 'Occupied' as const, employeeId: currentUser.id, assignedToName: currentUser.name, timeSeated: new Date().toISOString() };
            setLocalTables(prev => prev.map(t => t.id === updatedTable.id ? updatedTable : t));
            setActiveTableId(table.id);
            setGuests([{ id: 1, status: 'Active' }]);
            setOrderItems([]);
            return;
        }
        if (table.employeeId === currentUser.id || isManager) {
            setActiveTableId(table.id);
        } else {
            alert("Table locked by another server.");
        }
    };

    const addToOrder = (item: InventoryItem) => {
        const newItem: DiningOrderItem = {
            ...item,
            cartId: `din-${Date.now()}-${Math.random()}`,
            quantity: 1,
            seatNumber: activeSeat,
            fired: false,
            modifiers: [],
            color: 'bg-white'
        };
        setOrderItems([...orderItems, newItem]);
    };

    const handleFire = () => {
        const unfired = orderItems.filter(i => !i.fired);
        if (unfired.length === 0) return;

        // Mark as fired
        setOrderItems(prev => prev.map(i => ({ ...i, fired: true })));

        // Simulating KDS push
        console.log("Fired items to kitchen:", unfired);
        // Visual feedback would go here
    };

    const filteredItems = inventory.filter(item => item.showOnPos && item.name.toLowerCase().includes(searchTerm.toLowerCase()));

    if (!activeTableId) {
        return (
            <div className="h-full flex flex-col bg-slate-100">
                <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center">
                    <h2 className="text-xl font-bold text-slate-800">Byte Dinning - Floor Plan</h2>
                    <button onClick={onExit}><X size={24} className="text-slate-500 hover:text-slate-800"/></button>
                </div>
                <div className="p-6 grid grid-cols-4 gap-4 overflow-y-auto">
                    {localTables.filter(t => t.isSeatable).map(table => {
                        const isMine = table.employeeId === currentUser.id;
                        return (
                            <button 
                                key={table.id} 
                                onClick={() => handleTableClick(table)}
                                className={`p-6 rounded-xl border-2 flex flex-col items-center justify-center gap-2 aspect-square transition-all relative
                                    ${table.status === 'Available' ? 'bg-white border-slate-200 hover:border-indigo-500 shadow-sm' : 
                                      isMine ? 'bg-blue-50 border-blue-400 shadow-md ring-1 ring-blue-200' : 
                                      'bg-slate-100 border-slate-200 opacity-60 cursor-not-allowed'}`}
                            >
                                <span className="font-bold text-2xl text-slate-700">{table.name}</span>
                                {table.status === 'Occupied' && (
                                    <div className="text-xs flex flex-col items-center">
