import React, { useState, useEffect } from 'react';
import { InventoryItem, Category, CartItem, Employee } from '../types';
// Note: In a real app you'd likely use an InventoryAPI too, but for now we reuse mocks via props or direct import
// For this structure, we assume props are passed from App.tsx or fetched here.
// To satisfy the "Backend-First" spec, we use the OrdersAPI.
import { OrdersAPI } from '../api/orders';
import { InventoryAPI } from '../api/inventory'; // Assuming this exists or we mock it
import MenuGrid from './POS/Register/MenuGrid';
import OrderSidebar from './POS/Register/OrderSidebar';
import { Loader2 } from 'lucide-react';

interface RegisterProps {
    currentUser: Employee;
}

const Register: React.FC<RegisterProps> = ({ currentUser }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [inventory, setInventory] = useState<InventoryItem[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);

    // Cart State
    const [cart, setCart] = useState<CartItem[]>([]);

    // UI State
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');

    // --- 1. Load Initial Data (Simulated Backend Fetch) ---
    useEffect(() => {
        // Simulating fetching inventory from an API
        const loadData = async () => {
            // In a real scenario: const items = await InventoryAPI.getItems();
            // For now, we import constants but simulate async
            // To make this compile with existing file structure if InventoryAPI isn't there, 
            // I'll assume MOCK_INVENTORY_ITEMS is available via the parent or global import, 
            // but for cleaner code I'll pretend InventoryAPI exists in api/inventory.ts
            // If it doesn't, I'll define a local mock.

            // Temporary Mock for demonstration if API file missing
            const { MOCK_INVENTORY_ITEMS, MOCK_CATEGORIES } = await import('../constants');

            setInventory(MOCK_INVENTORY_ITEMS);
            setCategories(MOCK_CATEGORIES);
            setIsLoading(false);
        };
        loadData();
    }, []);

    // --- 2. Cart Logic ---
    const handleAddToCart = (item: InventoryItem) => {
        if (!item.inStock) {
            alert(`${item.name} is currently out of stock.`);
            return;
        }

        setCart(prev => {
            const existing = prev.find(i => i.id === item.id);
            if (existing) {
                return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            // Transform InventoryItem to CartItem
            return [...prev, { 
                ...item, 
                quantity: 1, 
                modifiers: [], 
                color: 'bg-white' // default prop
            }];
        });
    };

    const handleUpdateQty = (id: string, delta: number) => {
        setCart(prev => {
            const existing = prev.find(i => i.id === id);
            if (!existing) return prev;

            const newQty = existing.quantity + delta;
            if (newQty <= 0) {
                return prev.filter(i => i.id !== id);
            }
            return prev.map(i => i.id === id ? { ...i, quantity: newQty } : i);
        });
    };

    const handleRemoveItem = (id: string) => {
        setCart(prev => prev.filter(i => (i.cartId || i.id) !== id));
    };

    // --- 3. Backend-First Checkout ---
    const handleCheckout = async () => {
        try {
            setIsLoading(true);
            // Delegate math and processing to the "Backend"
            const finalizedOrder = await OrdersAPI.processSale(cart, currentUser.name, 'Main_Street_01');

            // Success
            console.log("Order Finalized:", finalizedOrder);
            setCart([]);
            alert(`Order ${finalizedOrder.id} Complete! Total: $${finalizedOrder.total.toFixed(2)}`);
        } catch (err) {
            console.error("Checkout failed", err);
            alert("Payment failed. Please try again.");
        } finally {
            setIsLoading(false);
        }
    };

    // Local UI display calculation (Non-authoritative, just for user feedback)
    // The ACTUAL total is calculated by OrdersAPI.processSale
    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const estimatedTax = subtotal * 0.0825;
    const estimatedTotal = subtotal + estimatedTax;

    const filteredItems = inventory.filter(i => 
        i.showOnPos && 
        (activeCategory === 'All' || i.category === activeCategory) &&
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (isLoading && inventory.length === 0) return <div className="h-full flex items-center justify-center"><Loader2 className="animate-spin text-indigo-500" size={40} /></div>;

    return (
        <div className="flex h-full bg-white rounded-[3rem] overflow-hidden shadow-2xl border border-slate-200">
            {/* Left: Product Grid */}
            <MenuGrid 
                items={filteredItems}
                categories={categories}
                activeCategory={activeCategory}
                onCategoryChange={setActiveCategory}
                onItemSelect={handleAddToCart}
                searchTerm={searchTerm}
                onSearchChange={setSearchTerm}
            />

            {/* Right: Order Sidebar */}
            <OrderSidebar 
                cart={cart}
                onUpdateQty={handleUpdateQty}
                onRemoveItem={handleRemoveItem}
                onEditItem={(item) => console.log('Edit item not implemented in this view', item)}
                onCheckout={handleCheckout}
                onSplit={() => console.log('Split not implemented')}
                onDiscount={() => console.log('Discount not implemented')}
                onFire={() => console.log('Fire not implemented')}
                subtotal={subtotal}
                tax={estimatedTax}
                total={estimatedTotal}
                orderType="Dine-in"
            />

            {isLoading && cart.length > 0 && (
                <div className="absolute inset-0 z-50 bg-white/50 backdrop-blur-sm flex items-center justify-center">
                    <div className="bg-white p-6 rounded-2xl shadow-xl flex items-center gap-4">
                        <Loader2 className="animate-spin text-indigo-600" />
                        <span className="font-bold text-slate-800">Processing Transaction...</span>
                    </div>
                </div>
            )}
        </div>
    );
};

