const ItemDetailModal = ({ item, discounts, onClose, onSave }: { item: CartItem, discounts: DiscountCode[], onClose: () => void, onSave: (item: CartItem) => void }) => {
    const [localItem, setLocalItem] = useState({...item});
    const [activeTab, setActiveTab] = useState<'Modifiers' | 'Discounts'>('Modifiers');
    const modifiers = ['Extra Cheese', 'No Onions', 'Gluten Free', 'Spicy', 'Sauce on Side', 'Well Done', 'Medium Rare', 'Add Bacon', 'Sub Salad'];

    const toggleModifier = (mod: string) => {
        const mods = localItem.modifiers || [];
        setLocalItem({...localItem, modifiers: mods.includes(mod) ? mods.filter(m => m !== mod) : [...mods, mod]});
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
                <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50">
                    <div>
                        <h3 className="text-xl font-black text-slate-800 tracking-tight">{localItem.name}</h3>
                        <p className="text-sm text-slate-500 font-mono font-bold">${localItem.price.toFixed(2)}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={20} /></button>
                </div>

                <div className="flex border-b border-slate-200">
                    <button 
                        onClick={() => setActiveTab('Modifiers')}
                        className={`flex-1 py-3 text-sm font-bold text-center transition-colors ${activeTab === 'Modifiers' ? 'border-b-2 border-indigo-600 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
                    >
                        Modifiers
                    </button>
                    <button 
                        onClick={() => setActiveTab('Discounts')}
                        className={`flex-1 py-3 text-sm font-bold text-center transition-colors ${activeTab === 'Discounts' ? 'border-b-2 border-indigo-600 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
                    >
                        Discounts
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-8">
                    {/* Qty & Seat - Always Visible */}
                    <div className="flex gap-6">
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Quantity</label>
                            <div className="flex items-center gap-4 bg-slate-100 rounded-xl p-1.5 w-fit border border-slate-200">
                                <button onClick={() => setLocalItem({...localItem, quantity: Math.max(1, localItem.quantity - 1)})} className="w-10 h-10 bg-white rounded-lg shadow-sm flex items-center justify-center font-bold text-slate-700 hover:bg-slate-50">-</button>
                                <span className="font-black text-xl w-8 text-center text-slate-800">{localItem.quantity}</span>
                                <button onClick={() => setLocalItem({...localItem, quantity: localItem.quantity + 1})} className="w-10 h-10 bg-white rounded-lg shadow-sm flex items-center justify-center font-bold text-slate-700 hover:bg-slate-50">+</button>
                            </div>
                        </div>
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Seat Assignment</label>
                            <div className="flex gap-2 flex-wrap">
                                {[1, 2, 3, 4].map(s => (
                                    <button 
                                        key={s} 
                                        onClick={() => setLocalItem({...localItem, seatId: localItem.seatId === s ? undefined : s})}
                                        className={`h-12 w-12 rounded-xl font-bold border-2 transition-all flex items-center justify-center ${localItem.seatId === s ? 'border-indigo-600 bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'border-slate-200 text-slate-400 hover:border-indigo-300'}`}
                                    >
                                        {s}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {activeTab === 'Modifiers' && (
                        <div className="space-y-6 animate-fade-in">
                            <div>
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block">Modifiers</label>
                                <div className="flex flex-wrap gap-2">
                                    {modifiers.map(mod => (
                                        <button
                                            key={mod}
                                            onClick={() => toggleModifier(mod)}
                                            className={`px-4 py-2.5 rounded-lg text-xs font-bold border-2 transition-all ${localItem.modifiers?.includes(mod) ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white text-slate-600 border-slate-100 hover:border-slate-300'}`}
                                        >
                                            {mod}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Special Request</label>
                                <textarea 
                                    value={localItem.specialRequest || ''} 
                                    onChange={e => setLocalItem({...localItem, specialRequest: e.target.value})}
