                                    placeholder="Allergies, preparation notes..."
                                    rows={2}
                                />
                            </div>

                            <div>
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Course Timing</label>
                                <div className="flex gap-2 bg-slate-100 p-1 rounded-xl border border-slate-200">
                                    {['Appetizer', 'Entree', 'Dessert', 'Beverage'].map(c => (
                                        <button 
                                            key={c}
                                            onClick={() => setLocalItem({...localItem, course: c as any})}
                                            className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${localItem.course === c ? 'bg-white shadow text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}
                                        >
                                            {c}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}

                    {activeTab === 'Discounts' && (
                        <div className="space-y-4 animate-fade-in">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Apply Item Discount</label>
                            <div className="grid grid-cols-2 gap-3">
                                {discounts.filter(d => d.applicability === 'Item' || d.applicability === 'Category' || d.applicability === 'Order').map(d => (
                                    <button 
                                        key={d.id}
                                        onClick={() => setLocalItem({...localItem, discount: { type: d.type, value: d.value, name: d.name || d.code || 'Discount' }})}
                                        className={`p-4 rounded-xl border-2 text-left transition-all group ${localItem.discount?.name === d.name ? 'bg-emerald-50 border-emerald-500 ring-1 ring-emerald-500' : 'bg-white border-slate-200 hover:border-indigo-300'}`}
                                    >
                                        <div className="flex justify-between items-start mb-1">
                                            <div className={`p-1.5 rounded-md ${d.type === 'Percentage' ? 'bg-purple-100 text-purple-600' : 'bg-blue-100 text-blue-600'}`}>
                                                {d.type === 'Percentage' ? <Percent size={14} /> : <DollarSign size={14} />}
                                            </div>
                                            {localItem.discount?.name === d.name && <Check size={16} className="text-emerald-600" />}
                                        </div>
                                        <div className="font-bold text-slate-800 text-sm">{d.name}</div>
                                        <div className="text-xs text-slate-500 font-medium">{d.type === 'Percentage' ? `${d.value}% Off` : `$${d.value.toFixed(2)} Off`}</div>
                                    </button>
                                ))}
                            </div>
                            {localItem.discount && (
                                <button 
                                    onClick={() => setLocalItem({...localItem, discount: undefined})}
                                    className="w-full py-3 mt-4 border-2 border-red-100 bg-red-50 text-red-600 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-red-100 transition-colors"
                                >
                                    Remove Applied Discount
                                </button>
                            )}
                        </div>
                    )}
                </div>

                <div className="p-4 border-t border-slate-200 bg-slate-50 flex gap-3">
                    <button 
                        onClick={() => { onSave({...localItem, isVoided: !localItem.isVoided}); onClose(); }}
                        className={`flex-1 py-3.5 font-black text-xs uppercase tracking-widest rounded-xl border-2 transition-all ${localItem.isVoided ? 'bg-slate-200 text-slate-500 border-transparent' : 'border-red-100 text-red-600 bg-red-50 hover:bg-red-100'}`}
                    >
                        {localItem.isVoided ? 'UN-VOID' : 'VOID ITEM'}
                    </button>
                    <button 
                        onClick={() => { onSave(localItem); onClose(); }}
                        className="flex-[2] py-3.5 bg-indigo-600 text-white font-black text-xs uppercase tracking-widest rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all"
                    >
                        UPDATE ORDER
                    </button>
                </div>
            </div>
        </div>
    );
};

