    const handleCustomApply = () => {
        const val = parseFloat(customValue);
        if (!val || isNaN(val)) return;

        onApply({
            id: `temp-${Date.now()}`,
            name: 'Custom Discount',
            code: 'CUSTOM',
            type: customType,
            value: val,
            status: 'Active',
            applicability: 'Order'
        });
        onClose();
    };

