const Register: React.FC<RegisterProps> = ({ inventory, categories, discounts, onFinish, currentUser }) => {
    const [isLoading, setIsLoading] = useState(false);

    // Cart State
    const [cart, setCart] = useState<CartItem[]>([]);
    const [activeCustomer, setActiveCustomer] = useState<string | null>(null);
    const [orderType, setOrderType] = useState('Dine-in');
    const [activeDiscount, setActiveDiscount] = useState<DiscountCode | null>(null);

    // UI State
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedItemForEdit, setSelectedItemForEdit] = useState<CartItem | null>(null);

    // Modal States
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showDiscountModal, setShowDiscountModal] = useState(false);
    const [showPaymentModal, setShowPaymentModal] = useState(false);

    // Filter Logic
    const filteredItems = inventory.filter(i => 
        i.showOnPos && 
        (activeCategory === 'All' || i.category === activeCategory) &&
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Cart Actions
    const handleAddToCart = (item: InventoryItem) => {
        if (!item.inStock) {
            alert(`${item.name} is currently out of stock.`);
            return;
        }
        setCart(prev => {
            const existing = prev.find(i => i.id === item.id && (!i.modifiers || i.modifiers.length === 0));
            if (existing) {
                return prev.map(i => i.cartId === existing.cartId ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { 
                ...item, 
                cartId: `cart-${Date.now()}-${Math.random()}`,
                quantity: 1, 
                modifiers: [], 
                color: 'bg-white' 
            }];
        });
    };

    const handleUpdateQty = (cartId: string, delta: number) => {
        setCart(prev => {
            const existing = prev.find(i => (i.cartId || i.id) === cartId);
            if (!existing) return prev;
            const newQty = existing.quantity + delta;
            if (newQty <= 0) return prev.filter(i => (i.cartId || i.id) !== cartId);
            return prev.map(i => (i.cartId || i.id) === cartId ? { ...i, quantity: newQty } : i);
        });
    };

    const handleRemoveItem = (cartId: string) => {
        setCart(prev => prev.filter(i => (i.cartId || i.id) !== cartId));
    };

    const handleUpdateItem = (updatedItem: CartItem) => {
        setCart(prev => prev.map(i => i.cartId === updatedItem.cartId ? updatedItem : i));
    };

    const calculateTotals = () => {
        const subtotal = cart.reduce((acc, item) => {
            if (item.isVoided) return acc;
            let itemTotal = item.price * item.quantity;

            // Apply Item Discount
            if (item.discount) {
                if (item.discount.type === 'Percentage') {
                    itemTotal -= itemTotal * (item.discount.value / 100);
                } else {
                    // Fixed discount applies to the line total
                    itemTotal -= item.discount.value;
                }
            }
            return acc + Math.max(0, itemTotal);
        }, 0);

        let discountAmt = 0;
        // Apply Order Discount
        if (activeDiscount) {
            discountAmt = activeDiscount.type === 'Percentage' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value;
        }

        const taxable = Math.max(0, subtotal - discountAmt);
        const tax = taxable * 0.0825;
        const total = taxable + tax;
        return { subtotal, tax, total };
    };

    const { subtotal, tax, total } = calculateTotals();

    const handlePayment = (method: string) => {
        setShowPaymentModal(false);
        setIsLoading(true);
        setTimeout(() => {
            const payments = [{ method, amount: total, status: 'Paid' }];
            onFinish(cart, total, payments);
            setCart([]);
            setActiveCustomer(null);
            setIsLoading(false);
        }, 1000);
    };

    return (
        <div className="flex h-full bg-white rounded-[2rem] overflow-hidden shadow-2xl border border-slate-200 relative">
            {/* Modals */}
            {selectedItemForEdit && (
                <ItemDetailModal 
                    item={selectedItemForEdit} 
                    discounts={discounts}
                    onClose={() => setSelectedItemForEdit(null)} 
                    onSave={handleUpdateItem} 
                />
            )}
            {showCustomerModal && (
                <CustomerModal 
                    onClose={() => setShowCustomerModal(false)}
                    onSelect={(name) => setActiveCustomer(name)}
                />
            )}
            {showDiscountModal && (
                <DiscountModal 
                    discounts={discounts}
                    onClose={() => setShowDiscountModal(false)}
                    onApply={setActiveDiscount}
                />
            )}
            {showPaymentModal && (
                <PaymentModal 
                    total={total}
                    onClose={() => setShowPaymentModal(false)}
                    onPay={handlePayment}
                />
            )}

            {/* Main Content */}
            <div className="flex-1 flex flex-col bg-slate-50/50 relative">
                <div className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-6 shrink-0">
                    <div className="flex items-center gap-4">
                        <button 
                            onClick={() => setShowCustomerModal(true)}
                            className="flex items-center gap-2 px-3 py-1.5 bg-slate-100 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-200 transition-colors"
                        >
                            {activeCustomer ? <><Check size={16} className="text-emerald-500" /> {activeCustomer}</> : <><UserPlus size={16} /> Add Customer</>}
                        </button>
                        <select 
                            value={orderType} 
                            onChange={(e) => setOrderType(e.target.value)}
                            className="bg-slate-100 border-none rounded-lg px-3 py-1.5 text-sm font-bold text-slate-600 focus:ring-0 cursor-pointer hover:bg-slate-200 transition-colors"
                        >
                            <option>Dine-in</option>
                            <option>Takeout</option>
                            <option>Delivery</option>
                        </select>
                    </div>
                    <div className="relative w-64">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input 
                            type="text" 
                            placeholder="Search..." 
                            value={searchTerm} 
                            onChange={e => setSearchTerm(e.target.value)}
                            className="w-full bg-slate-100 rounded-lg pl-9 pr-3 py-1.5 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500"
                        />
                    </div>
                </div>

                <MenuGrid 
                    items={filteredItems}
                    categories={categories}
                    activeCategory={activeCategory}
                    onCategoryChange={setActiveCategory}
                    onItemSelect={handleAddToCart}
                    searchTerm={searchTerm}
                    onSearchChange={setSearchTerm}
                />
            </div>

            {/* Sidebar */}
            <OrderSidebar 
                cart={cart}
                onUpdateQty={handleUpdateQty}
                onRemoveItem={handleRemoveItem}
                onEditItem={setSelectedItemForEdit}
                onCheckout={() => setShowPaymentModal(true)}
                onSplit={() => alert("Split Check: Select Seats to separate.")}
                onDiscount={() => setShowDiscountModal(true)}
                onFire={() => {
                    setCart(prev => prev.map(i => ({...i, isFired: true})));
                    alert("Items fired to kitchen!");
                }}
                subtotal={subtotal}
                tax={tax}
                total={total}
                orderType={orderType}
                activeCustomer={activeCustomer}
                activeDiscount={activeDiscount}
            />

            {isLoading && (
                <div className="absolute inset-0 z-[100] bg-white/50 backdrop-blur-sm flex items-center justify-center">
                    <div className="bg-white p-6 rounded-2xl shadow-xl flex items-center gap-4">
                        <Loader2 className="animate-spin text-indigo-600" />
                        <span className="font-bold text-slate-800">Processing Transaction...</span>
                    </div>
                </div>
            )}
        </div>
    );
};

