                                                        <Fingerprint size={20} className="text-slate-300" />
                                                    </label>
                                                 </div>
                                             </div>
                                         </div>
                                         <div className="space-y-8">
                                             <div>
                                                 <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Passcode Expiration</label>
                                                 <div className="relative">
                                                     <select 
                                                        value={passcodeSettings.expirationDays}
                                                        onChange={e => setPasscodeSettings({...passcodeSettings, expirationDays: parseInt(e.target.value)})}
                                                        className="w-full border-2 border-slate-100 rounded-2xl px-5 py-4 text-sm font-black text-slate-800 bg-white outline-none focus:border-indigo-500 transition-all appearance-none"
                                                     >
                                                         <option value={30}>EVERY 30 DAYS</option>
                                                         <option value={90}>EVERY 90 DAYS</option>
                                                         <option value={180}>EVERY 6 MONTHS</option>
                                                         <option value={0}>NEVER EXPIRE</option>
                                                     </select>
                                                     <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={18} />
                                                 </div>
                                             </div>
                                             <div className="p-6 bg-indigo-900 rounded-2xl shadow-xl flex flex-col gap-4">
                                                 <div className="flex items-center gap-3">
                                                     <div className="p-2 bg-white/10 rounded-lg">
                                                        <Key size={20} className="text-indigo-300" />
                                                     </div>
                                                     <h5 className="font-black text-white text-xs uppercase tracking-widest">Auto-Lock</h5>
                                                 </div>
                                                 <p className="text-xs text-indigo-200 leading-relaxed font-medium">Terminal will automatically lock and require a passcode after <span className="text-white font-black">2 minutes</span> of inactivity.</p>
                                                 <button className="w-full py-3 bg-white text-indigo-900 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 transition-all">CHANGE TIMEOUT</button>
                                             </div>
                                         </div>
                                     </div>
                                </div>

                                <div className="py-8 flex justify-end gap-3">
                                    <button className="px-6 py-2.5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Discard</button>
                                    <button 
                                        onClick={() => setPasscodeSettings(tempPasscodeSettings)}
                                        className="px-10 py-2.5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 text-[10px] uppercase tracking-[0.2em]"
                                    >
                                        Update Security Profile
                                    </button>
                                </div>
                            </div>
                        </div>
                    );
                }

                return (
                    <div className="max-w-4xl animate-fade-in pb-20">
                        {renderSectionHeader("Employees", "Admin settings for staff management, access, and security.")}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <SettingCard icon={Users} title="Employee roles" description="Define access levels like Manager, Server, or Admin." onClick={() => setSubSection('Employee roles')} />
                            <SettingCard icon={Shield} title="Employee permissions" description="Granular control over specific app features per role." onClick={() => setSubSection('Employee permissions')} />
                            <SettingCard icon={Key} title="Device passcode" description="Set global security policies for hardware login." onClick={() => setSubSection('Device passcode')} />
                        </div>
                    </div>
                );

            default:
                return (
                    <div className="max-w-4xl animate-fade-in pb-20">
                        {renderSectionHeader("Global Configuration", "Standard and advanced settings to fine-tune your store operations.")}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <SettingCard icon={SettingsIcon} title="Business operations" description="Configure taxes, tips, and inventory tracking." onClick={() => setActiveSection('Business operations')} />
                            <SettingCard icon={ShoppingCart} title="Transactions" description="Configure orders, payments, and receipts." onClick={() => setActiveSection('Transactions')} />
                            <SettingCard icon={Globe} title="Ecommerce" description="Manage online payments and hosted checkout." onClick={() => setActiveSection('Ecommerce')} />
                            <SettingCard icon={Users} title="Employees" description="Admin settings for staff and security." onClick={() => setActiveSection('Employees')} />
                        </div>
                    </div>
                );
        }
    };

    return (
        <div className="flex h-[calc(100vh-8rem)] bg-slate-50">
            {/* Settings Sidebar */}
            <div className="w-64 border-r border-slate-200 bg-white flex flex-col shrink-0">
                <div className="p-6 border-b border-slate-100">
                    <h2 className="text-lg font-black text-slate-800 tracking-tight">Settings</h2>
                </div>
                <nav className="flex-1 overflow-y-auto py-4 space-y-1 px-3">
                    {['Overview', 'Business operations', 'Transactions', 'Ecommerce', 'Employees', 'Hardware'].map(section => (
                        <button
                            key={section}
                            onClick={() => { setActiveSection(section); setSubSection(null); }}
                            className={`w-full text-left px-4 py-3 rounded-xl font-bold text-sm transition-all
                                ${activeSection === section ? 'bg-slate-900 text-white shadow-lg shadow-slate-200' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
                        >
                            {section}
                        </button>
                    ))}
                </nav>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto p-12 relative">
                {renderContent()}
            </div>
        </div>
    );
};

