                                                        <input type="checkbox" disabled className="h-5 w-5 rounded border-slate-300" />
                                                        <div className="flex-1">
                                                            <p className="text-sm font-black text-slate-400 uppercase tracking-tight">Biometric Override</p>
                                                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter mt-0.5">Mobile Only</p>
                                                        </div>
                                                        <Fingerprint size={20} className="text-slate-300" />
                                                    </label>
                                                 </div>
                                             </div>
                                         </div>
                                         <div className="space-y-8">
                                             <div>
                                                 <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Passcode Expiration</label>
                                                 <div className="relative">
                                                     <select 
                                                        value={passcodeSettings.expirationDays}
                                                        onChange={e => setPasscodeSettings({...passcodeSettings, expirationDays: parseInt(e.target.value)})}
                                                        className="w-full border-2 border-slate-100 rounded-2xl px-5 py-4 text-sm font-black text-slate-800 bg-white outline-none focus:border-indigo-500 transition-all appearance-none"
                                                     >
                                                         <option value={30}>EVERY 30 DAYS</option>
                                                         <option value={90}>EVERY 90 DAYS</option>
                                                         <option value={180}>EVERY 6 MONTHS</option>
                                                         <option value={0}>NEVER EXPIRE</option>
                                                     </select>
                                                     <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={18} />
                                                 </div>
                                             </div>
                                             <div className="p-6 bg-indigo-900 rounded-2xl shadow-xl flex flex-col gap-4">
                                                 <div className="flex items-center gap-3">
                                                     <div className="p-2 bg-white/10 rounded-lg">
                                                        <Key size={20} className="text-indigo-300" />
                                                     </div>
                                                     <h5 className="font-black text-white text-xs uppercase tracking-widest">Auto-Lock</h5>
                                                 </div>
                                                 <p className="text-xs text-indigo-200 leading-relaxed font-medium">Terminal will automatically lock and require a passcode after <span className="text-white font-black">2 minutes</span> of inactivity.</p>
                                                 <button className="w-full py-3 bg-white text-indigo-900 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 transition-all">CHANGE TIMEOUT</button>
                                             </div>
                                         </div>
                                     </div>
                                </div>

                                <div className="py-8 flex justify-end gap-3">
                                    <button className="px-6 py-2.5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Discard</button>
                                    <button 
                                        onClick={() => setPasscodeSettings(tempPasscodeSettings)}
                                        className="px-10 py-2.5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 text-[10px] uppercase tracking-[0.2em]"
                                    >
                                        Update Security Profile
                                    </button>
                                </div>
                            </div>
                        </div>
                    );
                }

                return (
                    <div className="max-w-4xl animate-fade-in pb-20">
                        {renderSectionHeader("Employees", "Admin settings for staff management, access, and security.")}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <SettingCard icon={Users} title="Employee roles" description="Define access levels like Manager, Server, or Admin." onClick={() => setSubSection('Employee roles')} />
                            <SettingCard icon={Shield} title="Employee permissions" description="Granular control over specific app features per role." onClick={() => setSubSection('Employee permissions')} />
                            <SettingCard icon={Key} title="Device passcode" description="Set global security policies for hardware login." onClick={() => setSubSection('Device passcode')} />
                        </div>
                    </div>
                );

            default:
                return (
                    <div className="max-w-4xl animate-fade-in pb-20">
                        {renderSectionHeader("Global Configuration", "Standard and advanced settings to fine-tune your store operations.")}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <SettingCard icon={SettingsIcon} title="Business operations" description="Configure taxes, tips, and inventory tracking." onClick={() => setActiveSection('Business operations')} />
                            <SettingCard icon={ShoppingCart} title="Transactions" description="Configure orders, payments, and receipts." onClick={() => setActiveSection('Transactions')} />
                            <SettingCard icon={Globe} title="Ecommerce" description="Manage online payments and hosted checkout." onClick={() => setActiveSection('Ecommerce')} />
                            <SettingCard icon={Users} title="Employees" description="Admin settings for staff and security." onClick={() => setActiveSection('Employees')} />
                        </div>
                    </div>
                );
        }
    };

    return (
        <div className="flex h-[calc(100vh-8rem)] bg-slate-50">
            {/* Settings Sidebar */}
            <div className="w-64 border-r border-slate-200 bg-white flex flex-col shrink-0">
                <div className="p-6 border-b border-slate-100">
                    <h2 className="text-lg font-black text-slate-800 tracking-tight">Settings</h2>
                </div>
                <nav className="flex-1 overflow-y-auto py-4 space-y-1 px-3">
                    {['Overview', 'Business operations', 'Transactions', 'Ecommerce', 'Employees', 'Hardware'].map(section => (
                        <button
                            key={section}
                            onClick={() => { setActiveSection(section); setSubSection(null); }}
                            className={`w-full text-left px-4 py-3 rounded-xl font-bold text-sm transition-all
                                ${activeSection === section ? 'bg-slate-900 text-white shadow-lg shadow-slate-200' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
                        >
                            {section}
                        </button>
                    ))}
                </nav>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto p-12 relative">
                {renderContent()}
            </div>
        </div>
    );
};

export default Settings;

import React, { useState, useRef, useEffect } from 'react';
import { DiningTable, FloorItemType } from '../types';
import { MOCK_FLOOR_TABLES, MOCK_OPTIMIZATIONS } from '../constants';
import { 
  Layout, Save, Plus, MousePointer2, Trash2, ZoomIn, ZoomOut, Maximize,
  ChevronDown, ChevronRight, Armchair, Flower2, Grid, Box, Sun, Wind,
  RefreshCw, PlayCircle, Smartphone, ExternalLink, X
} from 'lucide-react';
import InteractiveTable from './InteractiveTable';

interface DiningDashboardProps {
    initialTables?: DiningTable[];
    onSaveFloorPlan?: (tables: DiningTable[]) => void;
}

const DiningDashboard: React.FC<DiningDashboardProps> = ({ initialTables, onSaveFloorPlan }) => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [tables, setTables] = useState<DiningTable[]>(initialTables || MOCK_FLOOR_TABLES);

  useEffect(() => {
      if (initialTables) {
          setTables(initialTables);
      }
  }, [initialTables]);

  const [selectedTableId, setSelectedTableId] = useState<string | null>(null);
  const [activeSection, setActiveSection] = useState('Dining Room');
  const [sections, setSections] = useState(['Dining Room', 'Patio', 'Bar']);

  // Canvas Viewport State
  const [scale, setScale] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  // Palette State
  const [expandedCategory, setExpandedCategory] = useState<string | null>('Tables');

  // Drag & Resize State
  const [interactionMode, setInteractionMode] = useState<'DRAG' | 'RESIZE' | null>(null);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [initialDims, setInitialDims] = useState({ x: 0, y: 0, w: 0, h: 0 });

  const canvasRef = useRef<HTMLDivElement>(null);

  // --- Actions ---
  const handleAddItem = (type: FloorItemType) => {
      const isSeatable = type.includes('TABLE') || type.includes('BOOTH') || type.includes('COUCH');

      const viewportWidth = canvasRef.current?.clientWidth || 800;
      const viewportHeight = canvasRef.current?.clientHeight || 600;
      const centerX = (viewportWidth / 2 - pan.x) / scale;
      const centerY = (viewportHeight / 2 - pan.y) / scale;

      const newItem: DiningTable = {
          id: `ITEM-${Date.now()}`,
          name: isSeatable ? `${tables.filter(t => t.isSeatable).length + 1}` : '',
          type,
          section: activeSection,
          x: centerX - 40,
          y: centerY - 40,
          width: type.includes('RECT') || type.includes('BOOTH') || type.includes('COUCH') || type.includes('POOL') || type.includes('WALL') ? 120 : 80,
          height: 80,
          seats: isSeatable ? 4 : 0,
          status: 'Available',
          isSeatable,
          rotation: 0
      };
      setTables([...tables, newItem]);
      setSelectedTableId(newItem.id);
  };

  const handleAddSection = () => {
      const name = prompt("Enter new section name:");
      if (name && !sections.includes(name)) {
          setSections([...sections, name]);
          setActiveSection(name);
      }
  };

  const handleSave = () => {
      if (onSaveFloorPlan) {
          onSaveFloorPlan(tables);
          const toast = document.createElement('div');
          toast.className = "fixed bottom-10 right-10 bg-emerald-600 text-white px-6 py-3 rounded-lg shadow-xl animate-fade-in-up z-50 font-bold flex items-center gap-3";
          toast.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg> Floor Plan Saved & Synced!`;
          document.body.appendChild(toast);
          setTimeout(() => document.body.removeChild(toast), 3000);
          setIsEditMode(false);
      }
  };

  const handleCancel = () => {
      if (initialTables) {
          setTables(initialTables);
      }
      setIsEditMode(false);
  };

  const handleSync = () => {
      alert("Syncing table status from devices...");
  };

  // --- Canvas Interaction ---
  const handleWheel = (e: React.WheelEvent) => {
      if (e.ctrlKey || e.metaKey || isEditMode) {
          e.preventDefault();
          const zoomSensitivity = 0.001;
          const delta = -e.deltaY * zoomSensitivity;
          const newScale = Math.min(Math.max(0.5, scale + delta), 3);
          setScale(newScale);
      }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (interactionMode === null) {
          if (isEditMode && e.button === 0) {
             setSelectedTableId(null);
          }
          setIsPanning(true);
          setPanStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
      }
  };

  const handleItemMouseDown = (e: React.MouseEvent, table: DiningTable, isResizeHandle: boolean = false) => {
      e.stopPropagation();
      e.preventDefault();
      setSelectedTableId(table.id);
      if (isEditMode) {
          setInteractionMode(isResizeHandle ? 'RESIZE' : 'DRAG');
          setDragStart({ x: e.clientX, y: e.clientY });
          setInitialDims({ x: table.x, y: table.y, w: table.width, h: table.height });
      }
  };

  const handleGlobalMouseMove = (e: React.MouseEvent) => {
      if (isPanning) {
          setPan({ x: e.clientX - panStart.x, y: e.clientY - panStart.y });
          return;
      }
      if (!isEditMode || !selectedTableId || !interactionMode) return;
      const dx = (e.clientX - dragStart.x) / scale; 
      const dy = (e.clientY - dragStart.y) / scale;
      setTables(prev => prev.map(t => {
          if (t.id === selectedTableId) {
              if (interactionMode === 'DRAG') return { ...t, x: initialDims.x + dx, y: initialDims.y + dy };
              if (interactionMode === 'RESIZE') return { ...t, width: Math.max(40, initialDims.w + dx), height: Math.max(40, initialDims.h + dy) };
          }
          return t;
      }));
  };

  const handleGlobalMouseUp = () => {
      setInteractionMode(null);
      setIsPanning(false);
  };

  const toggleCategory = (cat: string) => {
      setExpandedCategory(expandedCategory === cat ? null : cat);
  }

  return (
    <div 
        className="space-y-6 animate-fade-in h-[calc(100vh-8rem)] flex flex-col" 
        onMouseMove={handleGlobalMouseMove}
        onMouseUp={handleGlobalMouseUp}
        onMouseLeave={handleGlobalMouseUp}
    >
      <div className="flex flex-col gap-1 shrink-0">
          <h1 className="text-2xl font-bold text-slate-800">Byte Dinning</h1>
          <p className="text-slate-500 font-medium">Floor Plan Management & Live Status</p>
      </div>

      <div className="flex flex-col gap-6 shrink-0 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <div className="flex flex-wrap gap-4 border-b border-slate-100 pb-4 items-center">
               {isEditMode ? (
                   <>
                       <button onClick={handleSave} className="flex items-center gap-2 px-6 py-2.5 text-xs font-black bg-emerald-600 text-white hover:bg-emerald-700 rounded-xl transition-all shadow-lg shadow-emerald-200 active:scale-95 tracking-widest">
                           <Save size={16} /> SAVE & UPDATE SERVERS
                       </button>
                       <button onClick={handleCancel} className="flex items-center gap-2 px-4 py-2.5 text-xs font-bold text-slate-500 hover:bg-slate-100 hover:text-slate-800 rounded-xl transition-colors border-2 border-slate-100">
                           <X size={16} /> CANCEL
                       </button>
                       <div className="h-6 w-px bg-slate-200 mx-2"></div>
                       <span className="text-xs font-bold text-slate-400 uppercase tracking-wider animate-pulse">Editing Mode Active</span>
                   </>
               ) : (
                   <>
                       <button onClick={handleSync} className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors border border-slate-200">
                           <RefreshCw size={14} className="text-indigo-600" /> SYNC
                       </button>
                       <button className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors border border-slate-200">
                           <PlayCircle size={14} className="text-indigo-600" /> TOUR
                       </button>
                       <button onClick={() => setIsEditMode(true)} className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-700 hover:border-indigo-200 rounded-lg transition-all border border-slate-200 shadow-sm">
                           <Layout size={14} className="text-indigo-600" /> EDIT FLOOR PLAN
                       </button>
                       <button className="flex items-center gap-2 px-4 py-2 text-xs font-bold text-slate-700 hover:bg-slate-50 rounded-lg transition-colors border border-slate-200">
                           <Smartphone size={14} className="text-indigo-600" /> CONTACTLESS DINING
                       </button>
                   </>
               )}
          </div>
          <div className="space-y-3">
              <p className="text-sm text-slate-600 leading-relaxed font-medium">
                  {isEditMode 
                    ? "Drag tables to move, grab corners to resize. Add new items from the palette on the left. Changes update server apps immediately upon saving." 
                    : "Set up and view your floor plan from your Web Dashboard."}
              </p>
              {!isEditMode && (
                  <p className="text-sm text-slate-600 leading-relaxed">
                      To see the current status of your tables, click <span className="font-bold text-indigo-600 cursor-pointer hover:underline" onClick={handleSync}>Sync</span> above. This will pull the table information currently on your device.
                  </p>
              )}
          </div>
      </div>

      <div className="flex-1 flex gap-6 overflow-hidden">
          {/* Left Sidebar: Palette */}
          <div className="w-80 bg-white border border-slate-200 rounded-xl shadow-sm p-4 flex flex-col gap-4 overflow-y-auto shrink-0 z-10">
              {isEditMode ? (
                  <div className="space-y-4 animate-fade-in">
                      <div className="flex items-center justify-between">
                          <h3 className="font-bold text-slate-800 text-sm uppercase tracking-wide">Floor Objects</h3>
                          <button onClick={handleCancel} className="text-xs text-slate-400 hover:text-slate-600">Close Editor</button>
                      </div>
                      <div className="border border-slate-200 rounded-lg overflow-hidden">
                          <button onClick={() => toggleCategory('Tables')} className="w-full flex justify-between items-center p-3 bg-slate-50 hover:bg-slate-100 font-semibold text-sm text-slate-700">
                              <span>Tables</span>
                              {expandedCategory === 'Tables' ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                          </button>
                          {expandedCategory === 'Tables' && (
                              <div className="p-3 grid grid-cols-2 gap-2 bg-white">
                                  <button onClick={() => handleAddItem('TABLE_SQUARE')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <div className="w-6 h-6 border-2 border-slate-400 bg-white rounded-sm mb-1"></div>
                                      <span className="text-[10px]">Square</span>
                                  </button>
                                  <button onClick={() => handleAddItem('TABLE_ROUND')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <div className="w-6 h-6 border-2 border-slate-400 bg-white rounded-full mb-1"></div>
                                      <span className="text-[10px]">Round</span>
                                  </button>
                                  <button onClick={() => handleAddItem('TABLE_RECT')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center col-span-2 transition-colors">
                                      <div className="w-12 h-6 border-2 border-slate-400 bg-white rounded-sm mb-1"></div>
                                      <span className="text-[10px]">Rectangle</span>
                                  </button>
                              </div>
                          )}
                      </div>
                      <div className="border border-slate-200 rounded-lg overflow-hidden">
                          <button onClick={() => toggleCategory('Seating')} className="w-full flex justify-between items-center p-3 bg-slate-50 hover:bg-slate-100 font-semibold text-sm text-slate-700">
                              <span>Seating</span>
                              {expandedCategory === 'Seating' ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                          </button>
                          {expandedCategory === 'Seating' && (
                              <div className="p-3 grid grid-cols-2 gap-2 bg-white">
                                  <button onClick={() => handleAddItem('BOOTH_SINGLE')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <Armchair size={20} className="mb-1 text-slate-500" />
                                      <span className="text-[10px]">Booth</span>
                                  </button>
                                  <button onClick={() => handleAddItem('COUCH_STRAIGHT')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <Armchair size={20} className="mb-1 text-slate-500" />
                                      <span className="text-[10px]">Couch</span>
                                  </button>
                              </div>
                          )}
                      </div>
                      <div className="border border-slate-200 rounded-lg overflow-hidden">
                          <button onClick={() => toggleCategory('Decor')} className="w-full flex justify-between items-center p-3 bg-slate-50 hover:bg-slate-100 font-semibold text-sm text-slate-700">
                              <span>Decor</span>
                              {expandedCategory === 'Decor' ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                          </button>
                          {expandedCategory === 'Decor' && (
                              <div className="p-3 grid grid-cols-2 gap-2 bg-white">
                                  <button onClick={() => handleAddItem('PLANT_MONSTERA')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <Flower2 size={20} className="mb-1 text-green-600" />
                                      <span className="text-[10px]">Plant</span>
                                  </button>
                                  <button onClick={() => handleAddItem('DECOR_WALL')} className="p-2 border rounded hover:bg-indigo-50 flex flex-col items-center transition-colors">
                                      <Box size={20} className="mb-1 text-slate-600" />
                                      <span className="text-[10px]">Wall</span>
                                  </button>
                              </div>
                          )}
                      </div>

                      {selectedTableId && (
                          <div className="border-t border-slate-100 pt-4 bg-slate-50 p-3 rounded-lg animate-fade-in-up">
                              <h3 className="font-bold text-slate-800 mb-2 text-xs uppercase tracking-wide">Properties</h3>
                              <div className="space-y-3">
                                  <div>
                                      <label className="text-[10px] text-slate-500 block mb-1 font-bold">LABEL / NUMBER</label>
                                      <input 
                                        type="text" 
                                        value={tables.find(t => t.id === selectedTableId)?.name} 
                                        onChange={(e) => setTables(prev => prev.map(t => t.id === selectedTableId ? { ...t, name: e.target.value } : t))} 
                                        className="w-full border border-slate-300 rounded px-2 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500" 
                                      />
                                  </div>
                                  <div className="flex items-center gap-2">
                                      <input 
                                        type="checkbox" 
                                        checked={tables.find(t => t.id === selectedTableId)?.isSeatable}
                                        onChange={(e) => setTables(prev => prev.map(t => t.id === selectedTableId ? { ...t, isSeatable: e.target.checked } : t))}
                                        className="h-4 w-4 text-indigo-600 rounded border-gray-300"
                                      />
                                      <label className="text-xs text-slate-700 font-medium">Seatable</label>
                                  </div>
                                  {tables.find(t => t.id === selectedTableId)?.isSeatable && (
                                      <div>
                                          <label className="text-[10px] text-slate-500 block mb-1 font-bold">SEATS</label>
                                          <input 
                                            type="number" 
                                            value={tables.find(t => t.id === selectedTableId)?.seats} 
                                            onChange={(e) => setTables(prev => prev.map(t => t.id === selectedTableId ? { ...t, seats: parseInt(e.target.value) || 0 } : t))} 
                                            className="w-full border border-slate-300 rounded px-2 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500" 
                                          />
                                      </div>
                                  )}
                                  <div>
                                      <label className="text-[10px] text-slate-500 block mb-1 font-bold">ROTATION</label>
                                      <input 
                                        type="range" min="0" max="360" step="5"
                                        value={tables.find(t => t.id === selectedTableId)?.rotation || 0} 
                                        onChange={(e) => setTables(prev => prev.map(t => t.id === selectedTableId ? { ...t, rotation: parseInt(e.target.value) } : t))} 
                                        className="w-full accent-indigo-600" 
                                      />
                                  </div>
                                  <button onClick={() => { setTables(prev => prev.filter(t => t.id !== selectedTableId)); setSelectedTableId(null); }} className="w-full py-2.5 bg-red-50 text-red-600 border border-red-200 rounded-lg hover:bg-red-100 text-xs flex items-center justify-center gap-2 font-bold"><Trash2 size={14} /> DELETE ITEM</button>
                              </div>
                          </div>
                      )}
                  </div>
              ) : (
                  <div className="animate-fade-in flex flex-col h-full">
                      <div className="p-4 bg-indigo-50 rounded-lg border border-indigo-100 mb-4 flex items-center gap-3">
                          <Layout size={20} className="text-indigo-600" />
                          <div>
                              <h3 className="font-bold text-indigo-900 text-sm">Visual Layout</h3>
                              <p className="text-xs text-indigo-700">Real-time status tracking.</p>
                          </div>
                      </div>
                      <h3 className="font-bold text-slate-800 text-sm mb-3">Live Insights</h3>
                      {MOCK_OPTIMIZATIONS.map(opt => (
                          <div key={opt.id} className="p-3 bg-white border border-slate-200 rounded-lg shadow-sm mb-2 hover:shadow-md transition-shadow">
                              <p className="text-sm font-medium text-slate-900">{opt.suggestion}</p>
                              <p className="text-xs text-slate-500 mt-1">Impact: {opt.impact}</p>
                          </div>
                      ))}
                  </div>
              )}
          </div>

          {/* Main Canvas Area */}
          <div className="flex-1 flex flex-col bg-slate-200/50 rounded-xl border border-slate-300 shadow-inner overflow-hidden relative group">
              <div className="absolute top-4 left-4 z-20 flex gap-2">
                  {sections.map(sec => (
                      <button key={sec} onClick={() => setActiveSection(sec)} className={`px-4 py-1.5 rounded-full text-xs font-bold shadow-sm transition-all ${activeSection === sec ? 'bg-slate-800 text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`}>{sec}</button>
                  ))}
                  {isEditMode && <button onClick={handleAddSection} className="p-1.5 bg-indigo-100 text-indigo-600 rounded-full hover:bg-indigo-200 shadow-sm"><Plus size={16} /></button>}
              </div>
              <div className="absolute bottom-4 right-4 z-20 flex flex-col bg-white border border-slate-200 rounded-lg shadow-sm">
                  <button onClick={() => setScale(s => Math.min(s + 0.1, 3))} className="p-2 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><ZoomIn size={18} /></button>
                  <button onClick={() => { setScale(1); setPan({x:0, y:0}); }} className="p-2 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><Maximize size={18} /></button>
                  <button onClick={() => setScale(s => Math.max(s - 0.1, 0.5))} className="p-2 text-slate-600 hover:bg-slate-50"><ZoomOut size={18} /></button>
              </div>
              <div ref={canvasRef} className="flex-1 relative overflow-hidden" onWheel={handleWheel} onMouseDown={handleMouseDown} style={{ cursor: isPanning ? 'grabbing' : 'grab' }}>
                  <div style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${scale})`, transformOrigin: '0 0', width: '100%', height: '100%' }}>
                      {tables.filter(t => t.section === activeSection).map(table => (
                          <InteractiveTable 
                              key={table.id}
                              table={table}
                              onClick={(e, t, handle) => handleItemMouseDown(e, t, handle)}
                              isEditing={isEditMode}
                              isSelected={selectedTableId === table.id}
                          />
                      ))}
                  </div>
              </div>
          </div>
      </div>
    </div>
  );
};

export default DiningDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { DiningTable, InventoryItem, Category, Employee, DiningOrderItem, UserRole, DiscountCode, CartItem } from '../types';
import { X, LogOut, Plus, Minus, User, Search, Lock, Flame, SplitSquareHorizontal, DollarSign, Tag, CreditCard, CheckCircle, Percent, ZoomIn, ZoomOut, Maximize, Hand } from 'lucide-react';
import { MOCK_CUSTOMERS } from '../constants';
import InteractiveTable from './InteractiveTable';

interface TableServiceAppProps {
    tables: DiningTable[];
    inventory: InventoryItem[];
    categories: Category[];
    currentUser: Employee;
    onExit: () => void;
}

// Reuse similar modal logic for Table Service (inline for isolation as requested)
const TableItemModal = ({ item, onClose, onSave, seatId }: { item: DiningOrderItem, onClose: () => void, onSave: (item: DiningOrderItem) => void, seatId: number }) => {
    const [localItem, setLocalItem] = useState({...item});
    const modifiers = ['Extra Cheese', 'No Onions', 'Gluten Free', 'Spicy', 'Sauce on Side', 'Well Done', 'Medium Rare'];

    const toggleModifier = (mod: string) => {
        const mods = localItem.modifiers || [];
        setLocalItem({...localItem, modifiers: mods.includes(mod) ? mods.filter(m => m !== mod) : [...mods, mod]});
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50">
                    <div>
                        <h3 className="text-xl font-black text-slate-800">{localItem.name}</h3>
                        <p className="text-sm text-slate-500 font-bold">${localItem.price.toFixed(2)}</p>
                    </div>
                    <button onClick={onClose}><X size={24} className="text-slate-400" /></button>
                </div>
                <div className="flex-1 overflow-y-auto p-6 space-y-6">
                    <div className="flex gap-4">
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Quantity</label>
                            <div className="flex items-center gap-4 bg-slate-100 rounded-xl p-2 w-fit">
                                <button onClick={() => setLocalItem({...localItem, quantity: Math.max(1, localItem.quantity - 1)})} className="w-8 h-8 bg-white rounded shadow-sm font-bold">-</button>
                                <span className="font-bold text-xl">{localItem.quantity}</span>
                                <button onClick={() => setLocalItem({...localItem, quantity: localItem.quantity + 1})} className="w-8 h-8 bg-white rounded shadow-sm font-bold">+</button>
                            </div>
                        </div>
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Seat</label>
                            <div className="flex gap-2 flex-wrap">
                                {[0, 1, 2, 3, 4].map(s => (
                                    <button 
                                        key={s} 
                                        onClick={() => setLocalItem({...localItem, seatNumber: s})}
                                        className={`h-10 w-10 rounded-lg font-bold border-2 transition-all ${localItem.seatNumber === s ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-slate-200 text-slate-400'}`}
                                    >
                                        {s === 0 ? 'S' : s}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Modifiers</label>
                        <div className="flex flex-wrap gap-2">
                            {modifiers.map(mod => (
                                <button
                                    key={mod}
                                    onClick={() => toggleModifier(mod)}
                                    className={`px-3 py-2 rounded-lg text-xs font-bold border transition-all ${localItem.modifiers?.includes(mod) ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-600'}`}
                                >
                                    {mod}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Course</label>
                        <div className="flex gap-2">
                            {['Appetizer', 'Entree', 'Dessert'].map(c => (
                                <button 
                                    key={c}
                                    onClick={() => setLocalItem({...localItem, course: c as any})}
                                    className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${localItem.course === c ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-500'}`}
                                >
                                    {c}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex gap-3">
                    <button onClick={() => { onSave({...localItem, isVoided: !localItem.isVoided}); onClose(); }} className={`flex-1 py-3 font-bold rounded-xl border-2 ${localItem.isVoided ? 'bg-slate-200 text-slate-500' : 'border-red-100 text-red-600 bg-red-50'}`}>
                        {localItem.isVoided ? 'UN-VOID' : 'VOID'}
                    </button>
                    <button onClick={() => { onSave(localItem); onClose(); }} className="flex-[2] py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg">
                        SAVE
                    </button>
                </div>
            </div>
        </div>
    );
};

const TableServiceApp: React.FC<TableServiceAppProps> = ({ tables, inventory, categories, currentUser, onExit }) => {
    const [localTables, setLocalTables] = useState<DiningTable[]>(tables);
    const [activeTableId, setActiveTableId] = useState<string | null>(null);
    const [activeSeat, setActiveSeat] = useState<number>(0); 
    const [guests, setGuests] = useState<{id: number, name?: string}[]>([{ id: 1 }]);
    const [orderItems, setOrderItems] = useState<DiningOrderItem[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeCustomer, setActiveCustomer] = useState<string | null>(null);

    // Floor View State
    const [activeSection, setActiveSection] = useState('Dining Room');
    const [scale, setScale] = useState(1);
    const [pan, setPan] = useState({ x: 0, y: 0 });
    const [isPanning, setIsPanning] = useState(false);
    const [panStart, setPanStart] = useState({ x: 0, y: 0 });
    const canvasRef = useRef<HTMLDivElement>(null);

    // Modals
    const [editingItem, setEditingItem] = useState<DiningOrderItem | null>(null);
    const [showCustomerSearch, setShowCustomerSearch] = useState(false);
    const [showPayment, setShowPayment] = useState(false);

    useEffect(() => { setLocalTables(tables); }, [tables]);

    // Derive sections from tables
    const sections = Array.from(new Set(localTables.map(t => t.section))).sort();

    const activeTable = localTables.find(t => t.id === activeTableId);

    const handleTableClick = (e: React.MouseEvent, table: DiningTable) => {
        // Only allow clicking seatable tables
        if (!table.isSeatable) return;

        if (table.status === 'Available') {
            const updated = { ...table, status: 'Occupied' as const, employeeId: currentUser.id, assignedToName: currentUser.name, timeSeated: new Date().toISOString() };
            setLocalTables(prev => prev.map(t => t.id === updated.id ? updated : t));
            setActiveTableId(table.id);
            setGuests([{ id: 1 }]);
            setOrderItems([]);
        } else {
            setActiveTableId(table.id);
        }
    };

    // Canvas Interaction Handlers
    const handleMouseDown = (e: React.MouseEvent) => {
        setIsPanning(true);
        setPanStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (isPanning) {
            setPan({ x: e.clientX - panStart.x, y: e.clientY - panStart.y });
        }
    };

    const handleMouseUp = () => {
        setIsPanning(false);
    };

    const addToOrder = (item: InventoryItem) => {
        const newItem: DiningOrderItem = {
            ...item,
            cartId: `din-${Date.now()}-${Math.random()}`,
            quantity: 1,
            seatNumber: activeSeat,
            fired: false,
            modifiers: [],
            course: 'Entree', // Default
            color: 'bg-white'
        };
        setOrderItems([...orderItems, newItem]);
    };

    const handleUpdateItem = (updated: DiningOrderItem) => {
        setOrderItems(prev => prev.map(i => i.cartId === updated.cartId ? updated : i));
    };

    const handleFire = () => {
        setOrderItems(prev => prev.map(i => ({ ...i, fired: true })));
    };

    const handleCloseCheck = () => {
        // Mock closing
        const updated = { ...activeTable!, status: 'Available' as const, assignedToName: undefined, timeSeated: undefined };
        setLocalTables(prev => prev.map(t => t.id === updated.id ? updated : t));
        setActiveTableId(null);
        setOrderItems([]);
        setActiveCustomer(null);
        setShowPayment(false);
    };

    const subtotal = orderItems.reduce((acc, i) => i.isVoided ? acc : acc + (i.price * i.quantity), 0);
    const tax = subtotal * 0.0825;
    const total = subtotal + tax;

    const filteredMenu = inventory.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()));

    if (!activeTableId) {
        return (
            <div className="h-full flex flex-col bg-slate-100 animate-fade-in relative">
                {/* Header */}
                <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center shadow-sm z-20">
                    <div>
                        <h2 className="text-xl font-bold text-slate-800">Dining Floor</h2>
                        <p className="text-xs text-slate-500 font-medium">Logged in as {currentUser.name}</p>
                    </div>
                    <div className="flex gap-2">
                        {sections.map(sec => (
                            <button 
                                key={sec} 
                                onClick={() => setActiveSection(sec)} 
                                className={`px-4 py-2 rounded-full text-xs font-bold transition-all ${activeSection === sec ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                {sec}
                            </button>
                        ))}
                    </div>
                    <button onClick={onExit} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X size={24} className="text-slate-500 hover:text-slate-800"/></button>
                </div>

                {/* Canvas Area */}
                <div 
                    ref={canvasRef} 
                    className="flex-1 relative overflow-hidden bg-slate-200/50 cursor-grab active:cursor-grabbing"
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                >
                    <div style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${scale})`, transformOrigin: '0 0', width: '100%', height: '100%' }}>
                        {localTables.filter(t => t.section === activeSection).map(table => (
                            <InteractiveTable 
                                key={table.id}
                                table={table}
                                onClick={(e, t) => handleTableClick(e, t)}
                                isEditing={false}
                                isSelected={false}
                            />
                        ))}
                    </div>
                </div>

                {/* Zoom Controls */}
                <div className="absolute bottom-6 right-6 z-20 flex flex-col bg-white border border-slate-200 rounded-lg shadow-lg">
                    <button onClick={() => setScale(s => Math.min(s + 0.1, 3))} className="p-3 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><ZoomIn size={20} /></button>
                    <button onClick={() => { setScale(1); setPan({x:0, y:0}); }} className="p-3 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><Maximize size={20} /></button>
                    <button onClick={() => setScale(s => Math.max(s - 0.1, 0.5))} className="p-3 text-slate-600 hover:bg-slate-50"><ZoomOut size={20} /></button>
                </div>
            </div>
        );
    }

    return (
        <div className="flex h-full bg-slate-100 animate-fade-in">
            {editingItem && <TableItemModal item={editingItem} onClose={() => setEditingItem(null)} onSave={handleUpdateItem} seatId={editingItem.seatNumber} />}

            {showCustomerSearch && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm">
                    <div className="bg-white w-full max-w-md rounded-2xl shadow-xl p-6">
                        <div className="flex justify-between mb-4">
                            <h3 className="font-bold text-lg">Assign Customer</h3>
                            <button onClick={() => setShowCustomerSearch(false)}><X size={20} /></button>
                        </div>
                        <div className="space-y-2 max-h-80 overflow-y-auto">
                            {MOCK_CUSTOMERS.map(c => (
                                <button key={c.id} onClick={() => { setActiveCustomer(c.name); setShowCustomerSearch(false); }} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg font-medium text-slate-700">
                                    {c.name}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* Left: Table Order */}
            <div className="w-[450px] bg-white border-r border-slate-200 flex flex-col shadow-xl z-20">
                {/* Header */}
                <div className="p-4 border-b border-slate-200 bg-slate-50">
                    <div className="flex justify-between items-start mb-2">
                        <div>
                            <h2 className="text-2xl font-black text-slate-800">Table {activeTable?.name}</h2>
                            <button onClick={() => setShowCustomerSearch(true)} className="flex items-center gap-1 text-indigo-600 text-sm font-bold hover:underline mt-1">
                                {activeCustomer ? <><User size={14}/> {activeCustomer}</> : <><Plus size={14}/> Add Customer</>}
                            </button>
                        </div>
                        <div className="text-right">
                            <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest">Server</span>
                            <span className="font-bold text-slate-700">{activeTable?.assignedToName}</span>
                        </div>
                    </div>
                    {/* Seat Tabs */}
                    <div className="flex gap-2 overflow-x-auto pb-1 mt-2 no-scrollbar">
                        <button onClick={() => setActiveSeat(0)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase whitespace-nowrap transition-colors ${activeSeat === 0 ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>Shared</button>
                        {guests.map(g => (
                            <button key={g.id} onClick={() => setActiveSeat(g.id)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase whitespace-nowrap transition-colors ${activeSeat === g.id ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>Guest {g.id}</button>
                        ))}
                        <button onClick={() => setGuests([...guests, { id: guests.length + 1 }])} className="p-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300"><Plus size={14} /></button>
                    </div>
                </div>

                {/* Order List */}
                <div className="flex-1 overflow-y-auto p-4 space-y-6">
                    {/* Render Shared Items */}
                    {orderItems.filter(i => i.seatNumber === 0).length > 0 && (
                        <div>
                            <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 pl-1">Shared Items</div>
                            <div className="space-y-2">
                                {orderItems.filter(i => i.seatNumber === 0).map(item => (
                                    <OrderItemRow key={item.cartId} item={item} onClick={() => setEditingItem(item)} />
                                ))}
                            </div>
                        </div>
                    )}
                    {/* Render Guests */}
                    {guests.map(g => {
                        const items = orderItems.filter(i => i.seatNumber === g.id);
                        if (items.length === 0 && activeSeat !== g.id) return null;
                        return (
                            <div key={g.id} className={`rounded-xl p-3 border-2 transition-all ${activeSeat === g.id ? 'border-indigo-100 bg-indigo-50/30' : 'border-transparent'}`}>
                                <div className="flex justify-between items-center mb-2">
                                    <span className="text-xs font-black text-indigo-900 uppercase tracking-widest">Guest {g.id}</span>
                                    <span className="text-xs font-bold text-slate-500">${items.reduce((a,b) => a + (b.isVoided ? 0 : b.price * b.quantity), 0).toFixed(2)}</span>
                                </div>
                                <div className="space-y-2">
                                    {items.map(item => (
                                        <OrderItemRow key={item.cartId} item={item} onClick={() => setEditingItem(item)} />
                                    ))}
                                    {items.length === 0 && <div className="text-xs text-slate-400 italic text-center py-2">No items</div>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Footer Actions */}
                <div className="bg-white border-t border-slate-200 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                    <div className="flex justify-between items-end mb-4">
                        <div className="text-xs font-medium text-slate-500 space-y-1">
                            <div className="flex justify-between w-32"><span>Subtotal</span><span>${subtotal.toFixed(2)}</span></div>
                            <div className="flex justify-between w-32"><span>Tax</span><span>${tax.toFixed(2)}</span></div>
                        </div>
                        <div className="text-right">
                            <span className="block text-xs font-black text-slate-400 uppercase tracking-widest">Total Due</span>
                            <span className="text-3xl font-black text-slate-900">${total.toFixed(2)}</span>
                        </div>
                    </div>
                    <div className="grid grid-cols-4 gap-2">
                        <button onClick={() => alert("Split Check")} className="flex flex-col items-center justify-center p-2 rounded-lg bg-slate-50 hover:bg-slate-100 text-slate-600 border border-slate-200">
                            <SplitSquareHorizontal size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Split</span>
                        </button>
                        <button onClick={() => alert("Discount")} className="flex flex-col items-center justify-center p-2 rounded-lg bg-slate-50 hover:bg-slate-100 text-slate-600 border border-slate-200">
                            <Tag size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Disc</span>
                        </button>
                        <button onClick={handleFire} className="flex flex-col items-center justify-center p-2 rounded-lg bg-orange-50 hover:bg-orange-100 text-orange-600 border border-orange-200">
                            <Flame size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Fire</span>
                        </button>
                        <button onClick={() => setShowPayment(true)} className="flex flex-col items-center justify-center p-2 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white shadow-md">
                            <CreditCard size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Pay</span>
                        </button>
                    </div>
                </div>
            </div>

            {/* Right: Menu */}
            <div className="flex-1 flex flex-col bg-slate-100">
                <div className="p-4 bg-white border-b border-slate-200">
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input type="text" placeholder="Search menu items..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto p-6">
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                        {filteredMenu.map(item => (
                            <button key={item.id} onClick={() => addToOrder(item)} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 hover:border-indigo-500 hover:shadow-lg transition-all flex flex-col items-center text-center group active:scale-95">
                                <div className="h-12 w-12 rounded-full bg-slate-100 flex items-center justify-center mb-3 text-slate-500 font-bold group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-colors">
                                    {item.name.charAt(0)}
                                </div>
                                <span className="font-bold text-slate-800 text-sm leading-tight line-clamp-2">{item.name}</span>
                                <span className="text-xs font-mono text-slate-500 mt-2 font-medium">${item.price.toFixed(2)}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Simple Payment Modal */}
            {showPayment && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white w-full max-w-lg rounded-3xl p-8 shadow-2xl animate-scale-in">
                        <div className="text-center mb-8">
                            <h2 className="text-3xl font-black text-slate-900">${total.toFixed(2)}</h2>
                            <p className="text-slate-500 font-medium">Total Due for Table {activeTable?.name}</p>
                        </div>
                        <div className="grid grid-cols-2 gap-4 mb-8">
                            {['Card', 'Cash', 'Gift Card', 'Split'].map(m => (
                                <button key={m} onClick={handleCloseCheck} className="p-6 border-2 border-slate-100 rounded-2xl font-bold text-slate-700 hover:border-indigo-500 hover:bg-indigo-50 hover:text-indigo-700 transition-all">
                                    {m}
                                </button>
                            ))}
                        </div>
                        <button onClick={() => setShowPayment(false)} className="w-full py-4 font-bold text-slate-400 hover:text-slate-600">Cancel Payment</button>
                    </div>
                </div>
            )}
        </div>
    );
};

const OrderItemRow = ({ item, onClick }: { item: DiningOrderItem, onClick: () => void }) => (
    <div 
        onClick={onClick}
        className={`relative p-3 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-indigo-400 cursor-pointer group transition-all ${item.isVoided ? 'opacity-50 grayscale' : ''}`}
    >
        <div className="flex justify-between items-start">
            <div className="flex items-start gap-3">
                <span className="font-black text-indigo-600 pt-0.5">{item.quantity}</span>
                <div>
                    <p className={`font-bold text-sm ${item.isVoided ? 'line-through' : 'text-slate-800'}`}>{item.name}</p>
                    <div className="flex flex-wrap gap-1 mt-1">
                        {item.modifiers?.map((m, i) => <span key={i} className="text-[10px] bg-slate-100 px-1.5 py-0.5 rounded text-slate-600 border border-slate-200">{m}</span>)}
                        {item.course && <span className="text-[10px] bg-indigo-50 text-indigo-700 px-1.5 py-0.5 rounded font-bold uppercase tracking-wider">{item.course}</span>}
                    </div>
                    {item.specialRequest && <p className="text-[10px] text-orange-600 font-medium mt-1 italic">"{item.specialRequest}"</p>}
                </div>
            </div>
            <div className="text-right">
                <p className="font-mono font-bold text-sm">${(item.price * item.quantity).toFixed(2)}</p>
                {item.fired && <Flame size={12} className="text-orange-500 ml-auto mt-1" />}
            </div>
        </div>
    </div>
);

