import { Clock, CheckCircle, AlertTriangle, TrendingUp, TrendingDown, Minus, Filter, Bell, ChefHat, Package, Printer } from 'lucide-react';

interface KitchenDisplayProps {
    settings?: KDSSettings;
}

const KitchenDisplay: React.FC<KitchenDisplayProps> = ({ settings }) => {
    const [tickets, setTickets] = useState<KitchenTicket[]>(MOCK_KITCHEN_TICKETS);
    const [activeTab, setActiveTab] = useState<'All' | 'Dine-in' | 'Takeout'>('All');
    const [activeStation, setActiveStation] = useState<string>('All Stations');

    // Simulate Receiving "Fired" items from POS
    // In a real app, this would use a websocket or polling
    // For now, we assume MOCK_KITCHEN_TICKETS is the source of truth

    const handleStatusChange = (id: string, status: KitchenTicket['status']) => {
        setTickets(prev => prev.map(t => t.id === id ? { ...t, status } : t));
    };

    // Filter Logic
    const filteredTickets = tickets.filter(t => {
        // 1. Filter by Order Type
        const typeMatch = activeTab === 'All' || t.type === activeTab;

        // 2. Filter by Station (Label)
        // If "All Stations", show all tickets.
        // If specific station, show ticket ONLY if it contains items for that station.
        const stationMatch = activeStation === 'All Stations' || t.items.some(item => 
            // In real scenario, we check if item.printerLabels contains the activeStation ID
            // For mocks, we'll check against IDs in MOCK_PRINTER_LABELS
            item.printerLabels?.includes(activeStation)
        );

        return typeMatch && stationMatch;
    });

    // Group by status
    const pendingTickets = filteredTickets.filter(t => t.status === 'Pending');
    const prepTickets = filteredTickets.filter(t => t.status === 'Prep');
    const readyTickets = filteredTickets.filter(t => t.status === 'Ready');

    return (
        <div className="h-[calc(100vh-8rem)] flex flex-col bg-slate-900 text-white animate-fade-in">
            {/* KDS Header */}
            <div className="h-16 bg-slate-950 flex items-center justify-between px-6 shrink-0 border-b border-slate-800">
                <div className="flex items-center gap-4">
                    <h1 className="text-xl font-bold flex items-center gap-2">
                        <ChefHat className="text-orange-500" /> Kitchen Display
                    </h1>

                    <div className="h-8 w-px bg-slate-800 mx-2"></div>

                    {/* Station Selector (Simulating Screens/Printers) */}
                    <div className="relative group">
                        <button className="flex items-center gap-2 px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 rounded-lg text-sm font-bold transition-colors">
                            <Printer size={16} /> 
                            {activeStation === 'All Stations' ? 'Master View' : MOCK_PRINTER_LABELS.find(l => l.id === activeStation)?.name}
                        </button>
                        <div className="absolute top-full left-0 mt-2 w-48 bg-slate-800 border border-slate-700 rounded-xl shadow-xl overflow-hidden hidden group-hover:block z-50">
                            <button 
                                onClick={() => setActiveStation('All Stations')}
                                className="w-full text-left px-4 py-3 hover:bg-slate-700 text-sm font-medium border-b border-slate-700"
                            >
                                All Stations
                            </button>
                            {MOCK_PRINTER_LABELS.filter(l => l.isActive).map(label => (
                                <button
                                    key={label.id}
                                    onClick={() => setActiveStation(label.id)}
                                    className="w-full text-left px-4 py-3 hover:bg-slate-700 text-sm text-slate-300 hover:text-white"
                                >
                                    {label.name}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="flex bg-slate-800 rounded-lg p-1">
                        {['All', 'Dine-in', 'Takeout'].map(tab => (
                            <button
                                key={tab}
                                onClick={() => setActiveTab(tab as any)}
                                className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${activeTab === tab ? 'bg-slate-700 text-white' : 'text-slate-400 hover:text-white'}`}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>
                </div>
                <div className="flex items-center gap-6">
                    {MOCK_KITCHEN_METRICS.map((m, idx) => (
                        <div key={idx} className="flex flex-col items-end">
                            <span className="text-[10px] text-slate-400 uppercase font-bold">{m.metric}</span>
                            <div className="flex items-center gap-1 font-mono font-bold">
                                {m.trend === 'up' && <TrendingUp size={14} className="text-red-500" />}
                                {m.trend === 'down' && <TrendingDown size={14} className="text-emerald-500" />}
                                {m.trend === 'neutral' && <Minus size={14} className="text-slate-500" />}
                                {m.value}
                            </div>
                        </div>
                    ))}
                    <div className="h-8 w-px bg-slate-800"></div>
                    <button className="p-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white relative">
                        <Bell size={20} />
                        {settings?.soundAlerts && <span className="absolute top-2 right-2 h-2 w-2 bg-red-500 rounded-full"></span>}
                    </button>
                </div>
            </div>

            {/* Ticket Columns */}
            <div className="flex-1 overflow-x-auto p-4 flex gap-4">

                {/* Pending Column */}
                <div className="w-80 shrink-0 flex flex-col">
                    <div className="bg-slate-800/50 p-2 rounded-t-lg border-b border-slate-700 flex justify-between items-center">
                        <span className="font-bold text-slate-300">NEW ORDERS</span>
                        <span className="bg-red-500 text-white text-xs px-2 py-0.5 rounded-full font-bold">{pendingTickets.length}</span>
                    </div>
                    <div className="flex-1 bg-slate-900/50 rounded-b-lg border border-slate-800 p-2 space-y-3 overflow-y-auto">
                        {pendingTickets.map(ticket => (
                            <TicketCard 
                                key={ticket.id} 
                                ticket={ticket} 
                                onAction={() => handleStatusChange(ticket.id, 'Prep')} 
                                actionLabel="START" 
                                settings={settings}
                                activeStation={activeStation}
                            />
                        ))}
                    </div>
                </div>

                {/* Prep Column (Grid for density) */}
                <div className="flex-1 flex flex-col">
                    <div className="bg-slate-800/50 p-2 rounded-t-lg border-b border-slate-700 flex justify-between items-center">
                        <span className="font-bold text-slate-300">IN PREP</span>
                        <span className="bg-orange-500 text-white text-xs px-2 py-0.5 rounded-full font-bold">{prepTickets.length}</span>
                    </div>
                    <div className="flex-1 bg-slate-900/50 rounded-b-lg border border-slate-800 p-3 overflow-y-auto">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                            {prepTickets.map(ticket => (
                                <TicketCard 
                                    key={ticket.id} 
                                    ticket={ticket} 
                                    onAction={() => handleStatusChange(ticket.id, 'Ready')} 
                                    actionLabel="DONE" 
                                    settings={settings}
                                    activeStation={activeStation}
                                />
                            ))}
                        </div>
                    </div>
                </div>

                {/* Ready Column */}
                <div className="w-80 shrink-0 flex flex-col">
                    <div className="bg-slate-800/50 p-2 rounded-t-lg border-b border-slate-700 flex justify-between items-center">
                        <span className="font-bold text-slate-300">READY TO SERVE</span>
                        <span className="bg-emerald-500 text-white text-xs px-2 py-0.5 rounded-full font-bold">{readyTickets.length}</span>
                    </div>
                    <div className="flex-1 bg-slate-900/50 rounded-b-lg border border-slate-800 p-2 space-y-3 overflow-y-auto">
                        {readyTickets.map(ticket => (
                            <TicketCard 
                                key={ticket.id} 
                                ticket={ticket} 
                                onAction={() => handleStatusChange(ticket.id, 'Delivered')} 
                                actionLabel="CLEAR" 
                                variant="ready" 
                                settings={settings}
                                activeStation={activeStation}
                            />
                        ))}
                    </div>
                </div>

            </div>
        </div>
    );
};

const TicketCard: React.FC<{ 
    ticket: KitchenTicket, 
    onAction: () => void, 
    actionLabel: string, 
    variant?: 'normal' | 'ready', 
    settings?: KDSSettings,
    activeStation: string 
}> = ({ ticket, onAction, actionLabel, variant = 'normal', settings, activeStation }) => {

    // Timer simulation
    const elapsed = '12:30'; 
    const isLate = false; 

    return (
        <div className={`rounded-xl border-l-4 overflow-hidden shadow-sm flex flex-col transition-all hover:translate-y-[-2px]
            ${variant === 'ready' ? 'bg-emerald-900/20 border-l-emerald-500 border-white/10' : 
              ticket.type === 'Takeout' ? 'bg-blue-900/20 border-l-blue-500 border-white/10' : 
              'bg-slate-800 border-l-orange-500 border-white/5'} border`}>

            {/* Header */}
            <div className={`p-3 flex justify-between items-start border-b ${variant === 'ready' ? 'border-emerald-800/50' : 'border-white/5'}`}>
                <div>
                    <div className="flex items-center gap-2">
                        <span className="font-mono font-bold text-lg">#{ticket.orderId.split('-')[1]}</span>
                        {ticket.type === 'Takeout' && (
                            <span className="bg-blue-600 text-white text-[10px] px-1.5 py-0.5 rounded font-bold uppercase flex items-center gap-1">
                                <Package size={10} /> To-Go
                            </span>
                        )}
                    </div>
                    <div className="text-xs text-slate-400 mt-1">
                        {/* Respect Show Server Setting */}
                        {(settings?.showServer ?? true) && (ticket.server ? `Svr: ${ticket.server}` : 'Online Order')} 
                        {(settings?.showServer ?? true) && (settings?.showTable ?? true) && ' • '}
                        {/* Respect Show Table Setting */}
                        {(settings?.showTable ?? true) && (ticket.table || 'No Table')}
                    </div>
                </div>
                <div className={`font-mono text-sm font-bold ${isLate ? 'text-red-500 animate-pulse' : 'text-slate-300'}`}>
                    {elapsed}
                </div>
            </div>

            {/* Items */}
            <div className="p-3 space-y-3 flex-1">
                {ticket.items.map((item, idx) => {
                    // Logic: Does this item belong to the currently viewed station?
                    const isRelevantToStation = activeStation === 'All Stations' || item.printerLabels?.includes(activeStation);

                    return (
                        <div key={idx} className={isRelevantToStation ? 'opacity-100' : 'opacity-20 grayscale'}>
                            <div className="flex justify-between items-start">
                                <span className="font-bold text-lg">{item.qty}</span>
                                <span className="flex-1 ml-3 font-medium text-slate-200">{item.name}</span>
                            </div>
                            {item.modifiers.length > 0 && (
                                <div className="ml-6 text-sm text-slate-400 mt-1 space-y-0.5">
                                    {item.modifiers.map((mod, i) => (
                                        <div key={i} className="text-orange-400/80">• {mod}</div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            {/* Footer Action */}
            <div className="p-3">
                <button 
                    onClick={onAction}
                    className={`w-full py-3 rounded-lg font-bold text-sm tracking-wider flex items-center justify-center gap-2 transition-colors
                        ${variant === 'ready' 
                            ? 'bg-emerald-600 hover:bg-emerald-500 text-white' 
                            : 'bg-slate-700 hover:bg-slate-600 text-slate-200'}`}
                >
                    {variant === 'ready' ? <CheckCircle size={16} /> : <Clock size={16} />}
                    {actionLabel}
                </button>
            </div>
        </div>
    );
}

export default KitchenDisplay;

import React, { useState } from 'react';
import { InventoryItem } from '../types';
import { Search, Plus, Filter, Edit2, Trash2, Tag, Monitor, Smartphone, Layers, Box, X, Check, Printer } from 'lucide-react';
import { MOCK_PRINTER_LABELS } from '../constants';

interface ItemsProps {
    items: InventoryItem[];
}

const Items: React.FC<ItemsProps> = ({ items }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<InventoryItem>>({
      name: '', price: 0, cost: 0, category: 'Uncategorized', printerLabels: [], inStock: true, showOnPos: true, showOnline: true
  });

  const filteredItems = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleOpenAdd = () => {
      setEditingItem(null);
      setFormData({ name: '', price: 0, cost: 0, category: 'Uncategorized', printerLabels: [], inStock: true, showOnPos: true, showOnline: true });
      setShowModal(true);
  };

  const handleOpenEdit = (item: InventoryItem) => {
      setEditingItem(item);
      setFormData({...item});
      setShowModal(true);
  };

  const toggleLabel = (labelId: string) => {
      const labels = formData.printerLabels || [];
      if (labels.includes(labelId)) {
          setFormData({ ...formData, printerLabels: labels.filter(l => l !== labelId) });
      } else {
          setFormData({ ...formData, printerLabels: [...labels, labelId] });
      }
  };

  const handleSave = () => {
      // In real app, dispatch update to parent/backend
      console.log("Saved Item:", formData);
      setShowModal(false);
  };

  return (
    <div className="space-y-6 animate-fade-in relative">
      {/* Add/Edit Modal */}
      {showModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                      <h3 className="text-xl font-black text-slate-800 tracking-tight">
                          {editingItem ? 'Edit Item' : 'New Item'}
                      </h3>
                      <button onClick={() => setShowModal(false)}><X size={24} className="text-slate-400" /></button>
                  </div>

                  <div className="p-6 overflow-y-auto space-y-6">
                      <div>
                          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Item Name</label>
                          <input 
                              type="text" 
                              value={formData.name} 
                              onChange={e => setFormData({...formData, name: e.target.value})}
                              className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                              placeholder="e.g. Cheeseburger"
                          />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Price ($)</label>
                              <input 
                                  type="number" 
                                  value={formData.price} 
                                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                                  className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                              />
                          </div>
                          <div>
                              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Cost ($)</label>
                              <input 
                                  type="number" 
                                  value={formData.cost} 
                                  onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})}
                                  className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                              />
                          </div>
                      </div>

                      <div>
                          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Printer Routing / Labels</label>
                          <div className="grid grid-cols-2 gap-3">
                              {MOCK_PRINTER_LABELS.map(label => {
                                  const isSelected = formData.printerLabels?.includes(label.id);
                                  return (
                                      <button 
                                          key={label.id}
                                          onClick={() => toggleLabel(label.id)}
                                          className={`flex items-center gap-3 p-3 rounded-xl border-2 transition-all text-left ${isSelected ? 'border-indigo-600 bg-indigo-50' : 'border-slate-100 bg-white hover:border-slate-300'}`}
                                      >
                                          <div className={`w-5 h-5 rounded flex items-center justify-center border transition-colors ${isSelected ? 'bg-indigo-600 border-indigo-600' : 'bg-white border-slate-300'}`}>
                                              {isSelected && <Check size={14} className="text-white" />}
                                          </div>
                                          <div>
                                              <p className={`text-sm font-bold ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{label.name}</p>
                                              <p className="text-[10px] text-slate-400">{label.assignedPrinter}</p>
                                          </div>
                                      </button>
                                  );
                              })}
                          </div>
                      </div>

                      <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <label className="flex items-center gap-3 cursor-pointer">
                              <input type="checkbox" checked={formData.inStock} onChange={e => setFormData({...formData, inStock: e.target.checked})} className="w-5 h-5 text-indigo-600 rounded" />
                              <span className="text-sm font-bold text-slate-700">In Stock</span>
                          </label>
                          <label className="flex items-center gap-3 cursor-pointer">
                              <input type="checkbox" checked={formData.showOnPos} onChange={e => setFormData({...formData, showOnPos: e.target.checked})} className="w-5 h-5 text-indigo-600 rounded" />
                              <span className="text-sm font-bold text-slate-700">Show on POS</span>
                          </label>
                      </div>
                  </div>

                  <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowModal(false)} className="px-6 py-3 font-bold text-slate-500 hover:text-slate-700 text-sm uppercase tracking-widest">Cancel</button>
                      <button onClick={handleSave} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg hover:bg-indigo-700 active:scale-95 transition-all text-sm uppercase tracking-widest">Save Item</button>
                  </div>
              </div>
          </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Item Library</h1>
          <p className="text-slate-500">Manage products, pricing, modifiers, and inventory</p>
        </div>
        <button onClick={handleOpenAdd} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-colors font-medium">
            <Plus size={18} /> Add Item
        </button>
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder="Search by name, category, or SKU..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
        </div>
        <div className="flex gap-2">
            <button className="flex items-center gap-2 px-4 py-2 bg-slate-100 rounded-lg text-slate-600 hover:bg-slate-200 font-medium">
                <Filter size={18} /> Filter
            </button>
        </div>
      </div>

      {/* Items Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 border-b border-slate-200 text-slate-500">
            <tr>
              <th className="px-6 py-3 font-semibold">Item Name</th>
              <th className="px-6 py-3 font-semibold">Category</th>
              <th className="px-6 py-3 font-semibold text-right">Price</th>
              <th className="px-6 py-3 font-semibold text-center">Routing</th>
              <th className="px-6 py-3 font-semibold text-center">In Stock</th>
              <th className="px-6 py-3 font-semibold text-center">POS</th>
              <th className="px-6 py-3 font-semibold text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredItems.map(item => (
              <tr key={item.id} className="hover:bg-slate-50 group">
                <td className="px-6 py-4">
                    <div className="flex flex-col">
                        <span className="font-medium text-slate-900 text-base">{item.name}</span>
                        {item.modifierGroups.length > 0 && (
                            <div className="flex items-center gap-1 text-xs text-slate-500 mt-1">
                                <Layers size={12} /> {item.modifierGroups.length} Modifier Groups
                            </div>
                        )}
                    </div>
                </td>
                <td className="px-6 py-4">
                    <span className="inline-flex items-center gap-1 px-2.5 py-0.5 bg-slate-100 rounded-full text-xs text-slate-600 font-medium border border-slate-200">
                        <Tag size={10} /> {item.category}
                    </span>
                </td>
                <td className="px-6 py-4 text-right font-mono text-slate-900 font-medium text-base">
                  ${item.price.toFixed(2)}
                </td>
                <td className="px-6 py-4 text-center">
                    <div className="flex gap-1 justify-center">
                        {item.printerLabels && item.printerLabels.length > 0 ? (
                            item.printerLabels.map(l => (
                                <span key={l} className="text-[10px] bg-slate-100 border border-slate-200 text-slate-500 px-1.5 py-0.5 rounded font-bold uppercase" title={MOCK_PRINTER_LABELS.find(pl => pl.id === l)?.name}>
                                    {MOCK_PRINTER_LABELS.find(pl => pl.id === l)?.name.substring(0, 3) || l}
                                </span>
                            ))
                        ) : (
                            <span className="text-slate-300 text-xs">-</span>
                        )}
                    </div>
                </td>
                <td className="px-6 py-4 text-center">
                    {item.inStock ? (
                        <span className="text-emerald-600 bg-emerald-50 px-2 py-1 rounded text-xs font-bold">In Stock</span>
                    ) : (
                        <span className="text-red-600 bg-red-50 px-2 py-1 rounded text-xs font-bold flex items-center justify-center gap-1">
                            <Box size={12} /> Out
                        </span>
                    )}
                </td>
                <td className="px-6 py-4 text-center">
                    <div className={`mx-auto h-2 w-2 rounded-full ${item.showOnPos ? 'bg-emerald-500' : 'bg-slate-300'}`} />
                </td>
                <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleOpenEdit(item)} className="p-1.5 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded transition-colors">
                            <Edit2 size={16} />
                        </button>
                        <button className="p-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors">
                            <Trash2 size={16} />
                        </button>
                    </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Items;

import React, { useState, useEffect, useRef } from 'react';
