}

// Reuse similar modal logic for Table Service (inline for isolation as requested)
const TableItemModal = ({ item, onClose, onSave, seatId }: { item: DiningOrderItem, onClose: () => void, onSave: (item: DiningOrderItem) => void, seatId: number }) => {
    const [localItem, setLocalItem] = useState({...item});
    const modifiers = ['Extra Cheese', 'No Onions', 'Gluten Free', 'Spicy', 'Sauce on Side', 'Well Done', 'Medium Rare'];

    const toggleModifier = (mod: string) => {
        const mods = localItem.modifiers || [];
        setLocalItem({...localItem, modifiers: mods.includes(mod) ? mods.filter(m => m !== mod) : [...mods, mod]});
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50">
                    <div>
                        <h3 className="text-xl font-black text-slate-800">{localItem.name}</h3>
                        <p className="text-sm text-slate-500 font-bold">${localItem.price.toFixed(2)}</p>
                    </div>
                    <button onClick={onClose}><X size={24} className="text-slate-400" /></button>
                </div>
                <div className="flex-1 overflow-y-auto p-6 space-y-6">
                    <div className="flex gap-4">
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Quantity</label>
                            <div className="flex items-center gap-4 bg-slate-100 rounded-xl p-2 w-fit">
                                <button onClick={() => setLocalItem({...localItem, quantity: Math.max(1, localItem.quantity - 1)})} className="w-8 h-8 bg-white rounded shadow-sm font-bold">-</button>
                                <span className="font-bold text-xl">{localItem.quantity}</span>
                                <button onClick={() => setLocalItem({...localItem, quantity: localItem.quantity + 1})} className="w-8 h-8 bg-white rounded shadow-sm font-bold">+</button>
                            </div>
                        </div>
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Seat</label>
                            <div className="flex gap-2 flex-wrap">
                                {[0, 1, 2, 3, 4].map(s => (
                                    <button 
                                        key={s} 
                                        onClick={() => setLocalItem({...localItem, seatNumber: s})}
                                        className={`h-10 w-10 rounded-lg font-bold border-2 transition-all ${localItem.seatNumber === s ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-slate-200 text-slate-400'}`}
                                    >
                                        {s === 0 ? 'S' : s}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Modifiers</label>
                        <div className="flex flex-wrap gap-2">
                            {modifiers.map(mod => (
                                <button
                                    key={mod}
                                    onClick={() => toggleModifier(mod)}
                                    className={`px-3 py-2 rounded-lg text-xs font-bold border transition-all ${localItem.modifiers?.includes(mod) ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-600'}`}
                                >
                                    {mod}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Course</label>
                        <div className="flex gap-2">
                            {['Appetizer', 'Entree', 'Dessert'].map(c => (
                                <button 
                                    key={c}
                                    onClick={() => setLocalItem({...localItem, course: c as any})}
                                    className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${localItem.course === c ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-500'}`}
                                >
                                    {c}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex gap-3">
                    <button onClick={() => { onSave({...localItem, isVoided: !localItem.isVoided}); onClose(); }} className={`flex-1 py-3 font-bold rounded-xl border-2 ${localItem.isVoided ? 'bg-slate-200 text-slate-500' : 'border-red-100 text-red-600 bg-red-50'}`}>
                        {localItem.isVoided ? 'UN-VOID' : 'VOID'}
                    </button>
                    <button onClick={() => { onSave(localItem); onClose(); }} className="flex-[2] py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg">
                        SAVE
                    </button>
                </div>
            </div>
        </div>
    );
};

const TableServiceApp: React.FC<TableServiceAppProps> = ({ tables, inventory, categories, currentUser, onExit }) => {
    const [localTables, setLocalTables] = useState<DiningTable[]>(tables);
    const [activeTableId, setActiveTableId] = useState<string | null>(null);
    const [activeSeat, setActiveSeat] = useState<number>(0); 
    const [guests, setGuests] = useState<{id: number, name?: string}[]>([{ id: 1 }]);
    const [orderItems, setOrderItems] = useState<DiningOrderItem[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeCustomer, setActiveCustomer] = useState<string | null>(null);

    // Per-table State Storage
    const [ordersByTable, setOrdersByTable] = useState<Record<string, { items: DiningOrderItem[], guests: {id: number, name?: string}[] }>>({});

    // Floor View State
    const [activeSection, setActiveSection] = useState('Dining Room');
    const [scale, setScale] = useState(1);
    const [pan, setPan] = useState({ x: 0, y: 0 });
    const [isPanning, setIsPanning] = useState(false);
    const [panStart, setPanStart] = useState({ x: 0, y: 0 });
    const canvasRef = useRef<HTMLDivElement>(null);

    // Modals
    const [editingItem, setEditingItem] = useState<DiningOrderItem | null>(null);
    const [showCustomerSearch, setShowCustomerSearch] = useState(false);
    const [showPayment, setShowPayment] = useState(false);

    useEffect(() => { setLocalTables(tables); }, [tables]);

    const activeTable = localTables.find(t => t.id === activeTableId);

    // Helpers to update current state AND persistence
    const updateOrderItems = (newItems: DiningOrderItem[]) => {
        setOrderItems(newItems);
        if (activeTableId) {
            setOrdersByTable(prev => ({
                ...prev,
                [activeTableId]: { items: newItems, guests: guests }
            }));
        }
    };

    const updateGuests = (newGuests: {id: number, name?: string}[]) => {
        setGuests(newGuests);
        if (activeTableId) {
            setOrdersByTable(prev => ({
                ...prev,
                [activeTableId]: { items: orderItems, guests: newGuests }
            }));
        }
    };

    const handleTableClick = (e: React.MouseEvent, table: DiningTable) => {
        if (!table.isSeatable) return;

        // Load persisted data if exists
        const storedData = ordersByTable[table.id];

        if (table.status === 'Available' && !storedData) {
            const updated = { ...table, status: 'Occupied' as const, employeeId: currentUser.id, assignedToName: currentUser.name, timeSeated: new Date().toISOString() };
            setLocalTables(prev => prev.map(t => t.id === updated.id ? updated : t));

            // Init empty state
            setOrderItems([]);
            setGuests([{ id: 1 }]);
            setOrdersByTable(prev => ({
                ...prev,
                [table.id]: { items: [], guests: [{ id: 1 }] }
            }));
        } else {
            // Restore state
            setOrderItems(storedData?.items || []);
            setGuests(storedData?.guests || [{ id: 1 }]);
        }

        setActiveTableId(table.id);
    };

    // Canvas Interaction Handlers
    const handleMouseDown = (e: React.MouseEvent) => {
        setIsPanning(true);
        setPanStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (isPanning) {
            setPan({ x: e.clientX - panStart.x, y: e.clientY - panStart.y });
        }
    };

    const handleMouseUp = () => {
        setIsPanning(false);
    };

    const addToOrder = (item: InventoryItem) => {
        const newItem: DiningOrderItem = {
            ...item,
            cartId: `din-${Date.now()}-${Math.random()}`,
            quantity: 1,
            seatNumber: activeSeat,
            fired: false,
            modifiers: [],
            course: 'Entree', 
            color: 'bg-white'
        };
        const updatedItems = [...orderItems, newItem];
        updateOrderItems(updatedItems);
    };

    const handleUpdateItem = (updated: DiningOrderItem) => {
        const updatedItems = orderItems.map(i => i.cartId === updated.cartId ? updated : i);
        updateOrderItems(updatedItems);
    };

    const handleFire = () => {
        const updatedItems = orderItems.map(i => ({ ...i, fired: true }));
        updateOrderItems(updatedItems);
    };

    const handleCloseCheck = () => {
        const updated = { ...activeTable!, status: 'Available' as const, assignedToName: undefined, timeSeated: undefined };
        setLocalTables(prev => prev.map(t => t.id === updated.id ? updated : t));

        // Clear Persistence
        setOrdersByTable(prev => {
            const next = { ...prev };
            delete next[activeTableId!];
            return next;
        });

        setActiveTableId(null);
        setOrderItems([]);
        setActiveCustomer(null);
        setShowPayment(false);
    };

    const subtotal = orderItems.reduce((acc, i) => i.isVoided ? acc : acc + (i.price * i.quantity), 0);
    const tax = subtotal * 0.0825;
    const total = subtotal + tax;

    const filteredMenu = inventory.filter(i => i.name.toLowerCase().includes(searchTerm.toLowerCase()));

    // Sections derived from current tables
    const sections = Array.from(new Set(localTables.map(t => t.section))).sort();

    if (!activeTableId) {
        return (
            <div className="h-full flex flex-col bg-slate-100 animate-fade-in relative">
                {/* Header */}
                <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center shadow-sm z-20">
                    <div>
                        <h2 className="text-xl font-bold text-slate-800">Dining Floor</h2>
                        <p className="text-xs text-slate-500 font-medium">Logged in as {currentUser.name}</p>
                    </div>
                    <div className="flex gap-2">
                        {sections.map(sec => (
                            <button 
                                key={sec} 
                                onClick={() => setActiveSection(sec)} 
                                className={`px-4 py-2 rounded-full text-xs font-bold transition-all ${activeSection === sec ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                {sec}
                            </button>
                        ))}
                    </div>
                    <button onClick={onExit} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X size={24} className="text-slate-500 hover:text-slate-800"/></button>
                </div>

                {/* Canvas Area */}
                <div 
                    ref={canvasRef} 
                    className="flex-1 relative overflow-hidden bg-slate-200/50 cursor-grab active:cursor-grabbing"
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                >
                    <div style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${scale})`, transformOrigin: '0 0', width: '100%', height: '100%' }}>
                        {localTables.filter(t => t.section === activeSection).map(table => (
                            <InteractiveTable 
                                key={table.id}
                                table={table}
                                onClick={(e, t) => handleTableClick(e, t)}
                                isEditing={false}
                                isSelected={false}
                            />
                        ))}
                    </div>
                </div>

                {/* Zoom Controls */}
                <div className="absolute bottom-6 right-6 z-20 flex flex-col bg-white border border-slate-200 rounded-lg shadow-lg">
                    <button onClick={() => setScale(s => Math.min(s + 0.1, 3))} className="p-3 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><ZoomIn size={20} /></button>
                    <button onClick={() => { setScale(1); setPan({x:0, y:0}); }} className="p-3 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><Maximize size={20} /></button>
                    <button onClick={() => setScale(s => Math.max(s - 0.1, 0.5))} className="p-3 text-slate-600 hover:bg-slate-50"><ZoomOut size={20} /></button>
                </div>
            </div>
        );
    }

    return (
        <div className="flex h-full bg-slate-100 animate-fade-in">
            {editingItem && <TableItemModal item={editingItem} onClose={() => setEditingItem(null)} onSave={handleUpdateItem} seatId={editingItem.seatNumber} />}

            {showCustomerSearch && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm">
                    <div className="bg-white w-full max-w-md rounded-2xl shadow-xl p-6">
                        <div className="flex justify-between mb-4">
                            <h3 className="font-bold text-lg">Assign Customer</h3>
                            <button onClick={() => setShowCustomerSearch(false)}><X size={20} /></button>
                        </div>
                        <div className="space-y-2 max-h-80 overflow-y-auto">
                            {MOCK_CUSTOMERS.map(c => (
                                <button key={c.id} onClick={() => { setActiveCustomer(c.name); setShowCustomerSearch(false); }} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg font-medium text-slate-700">
                                    {c.name}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* Left: Table Order */}
            <div className="w-[450px] bg-white border-r border-slate-200 flex flex-col shadow-xl z-20">
                {/* Header */}
                <div className="p-4 border-b border-slate-200 bg-slate-50">
                    <div className="flex items-center gap-2 mb-2">
                        <button onClick={() => setActiveTableId(null)} className="p-2 hover:bg-slate-200 rounded-full text-slate-500 transition-colors">
                            <ArrowLeft size={20} />
                        </button>
                        <div>
                            <h2 className="text-2xl font-black text-slate-800">Table {activeTable?.name}</h2>
                            <button onClick={() => setShowCustomerSearch(true)} className="flex items-center gap-1 text-indigo-600 text-sm font-bold hover:underline mt-1">
                                {activeCustomer ? <><User size={14}/> {activeCustomer}</> : <><Plus size={14}/> Add Customer</>}
                            </button>
                        </div>
                    </div>
                    <div className="flex justify-end">
                        <div className="text-right">
                            <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest">Server</span>
                            <span className="font-bold text-slate-700">{activeTable?.assignedToName}</span>
                        </div>
                    </div>
                    {/* Seat Tabs */}
                    <div className="flex gap-2 overflow-x-auto pb-1 mt-2 no-scrollbar">
                        <button onClick={() => setActiveSeat(0)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase whitespace-nowrap transition-colors ${activeSeat === 0 ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>Shared</button>
                        {guests.map(g => (
                            <button key={g.id} onClick={() => setActiveSeat(g.id)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase whitespace-nowrap transition-colors ${activeSeat === g.id ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>Guest {g.id}</button>
                        ))}
                        <button onClick={() => updateGuests([...guests, { id: guests.length + 1 }])} className="p-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300"><Plus size={14} /></button>
                    </div>
                </div>

                {/* Order List */}
                <div className="flex-1 overflow-y-auto p-4 space-y-6">
                    {/* Render Shared Items */}
                    {orderItems.filter(i => i.seatNumber === 0).length > 0 && (
                        <div>
                            <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 pl-1">Shared Items</div>
                            <div className="space-y-2">
                                {orderItems.filter(i => i.seatNumber === 0).map(item => (
                                    <OrderItemRow key={item.cartId} item={item} onClick={() => setEditingItem(item)} />
                                ))}
                            </div>
                        </div>
                    )}
                    {/* Render Guests */}
                    {guests.map(g => {
                        const items = orderItems.filter(i => i.seatNumber === g.id);
                        if (items.length === 0 && activeSeat !== g.id) return null;
                        return (
                            <div key={g.id} className={`rounded-xl p-3 border-2 transition-all ${activeSeat === g.id ? 'border-indigo-100 bg-indigo-50/30' : 'border-transparent'}`}>
                                <div className="flex justify-between items-center mb-2">
                                    <span className="text-xs font-black text-indigo-900 uppercase tracking-widest">Guest {g.id}</span>
                                    <span className="text-xs font-bold text-slate-500">${items.reduce((a,b) => a + (b.isVoided ? 0 : b.price * b.quantity), 0).toFixed(2)}</span>
                                </div>
                                <div className="space-y-2">
                                    {items.map(item => (
                                        <OrderItemRow key={item.cartId} item={item} onClick={() => setEditingItem(item)} />
                                    ))}
                                    {items.length === 0 && <div className="text-xs text-slate-400 italic text-center py-2">No items</div>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Footer Actions */}
                <div className="bg-white border-t border-slate-200 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                    <div className="flex justify-between items-end mb-4">
                        <div className="text-xs font-medium text-slate-500 space-y-1">
                            <div className="flex justify-between w-32"><span>Subtotal</span><span>${subtotal.toFixed(2)}</span></div>
                            <div className="flex justify-between w-32"><span>Tax</span><span>${tax.toFixed(2)}</span></div>
                        </div>
                        <div className="text-right">
                            <span className="block text-xs font-black text-slate-400 uppercase tracking-widest">Total Due</span>
                            <span className="text-3xl font-black text-slate-900">${total.toFixed(2)}</span>
                        </div>
                    </div>
                    <div className="grid grid-cols-4 gap-2">
                        <button onClick={() => alert("Split Check")} className="flex flex-col items-center justify-center p-2 rounded-lg bg-slate-50 hover:bg-slate-100 text-slate-600 border border-slate-200">
                            <SplitSquareHorizontal size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Split</span>
                        </button>
                        <button onClick={() => alert("Discount")} className="flex flex-col items-center justify-center p-2 rounded-lg bg-slate-50 hover:bg-slate-100 text-slate-600 border border-slate-200">
                            <Tag size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Disc</span>
                        </button>
                        <button onClick={handleFire} className="flex flex-col items-center justify-center p-2 rounded-lg bg-orange-50 hover:bg-orange-100 text-orange-600 border border-orange-200">
                            <Flame size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Fire</span>
                        </button>
                        <button onClick={() => setShowPayment(true)} className="flex flex-col items-center justify-center p-2 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white shadow-md">
                            <CreditCard size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Pay</span>
                        </button>
                    </div>
                </div>
            </div>

            {/* Right: Menu */}
            <div className="flex-1 flex flex-col bg-slate-100">
                <div className="p-4 bg-white border-b border-slate-200">
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input type="text" placeholder="Search menu items..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto p-6">
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                        {filteredMenu.map(item => (
                            <button key={item.id} onClick={() => addToOrder(item)} className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 hover:border-indigo-500 hover:shadow-lg transition-all flex flex-col items-center text-center group active:scale-95">
                                <div className="h-12 w-12 rounded-full bg-slate-100 flex items-center justify-center mb-3 text-slate-500 font-bold group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-colors">
                                    {item.name.charAt(0)}
                                </div>
                                <span className="font-bold text-slate-800 text-sm leading-tight line-clamp-2">{item.name}</span>
                                <span className="text-xs font-mono text-slate-500 mt-2 font-medium">${item.price.toFixed(2)}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Simple Payment Modal */}
            {showPayment && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-white w-full max-w-lg rounded-3xl p-8 shadow-2xl animate-scale-in">
                        <div className="text-center mb-8">
                            <h2 className="text-3xl font-black text-slate-900">${total.toFixed(2)}</h2>
                            <p className="text-slate-500 font-medium">Total Due for Table {activeTable?.name}</p>
                        </div>
                        <div className="grid grid-cols-2 gap-4 mb-8">
                            {['Card', 'Cash', 'Gift Card', 'Split'].map(m => (
                                <button key={m} onClick={handleCloseCheck} className="p-6 border-2 border-slate-100 rounded-2xl font-bold text-slate-700 hover:border-indigo-500 hover:bg-indigo-50 hover:text-indigo-700 transition-all">
                                    {m}
                                </button>
                            ))}
                        </div>
                        <button onClick={() => setShowPayment(false)} className="w-full py-4 font-bold text-slate-400 hover:text-slate-600">Cancel Payment</button>
                    </div>
                </div>
            )}
        </div>
    );
};

const OrderItemRow = ({ item, onClick }: { item: DiningOrderItem, onClick: () => void }) => (
    <div 
        onClick={onClick}
        className={`relative p-3 bg-white border border-slate-200 rounded-xl shadow-sm hover:border-indigo-400 cursor-pointer group transition-all ${item.isVoided ? 'opacity-50 grayscale' : ''}`}
    >
        <div className="flex justify-between items-start">
            <div className="flex items-start gap-3">
                <span className="font-black text-indigo-600 pt-0.5">{item.quantity}</span>
                <div>
                    <p className={`font-bold text-sm ${item.isVoided ? 'line-through' : 'text-slate-800'}`}>{item.name}</p>
                    <div className="flex flex-wrap gap-1 mt-1">
                        {item.modifiers?.map((m, i) => <span key={i} className="text-[10px] bg-slate-100 px-1.5 py-0.5 rounded text-slate-600 border border-slate-200">{m}</span>)}
                        {item.course && <span className="text-[10px] bg-indigo-50 text-indigo-700 px-1.5 py-0.5 rounded font-bold uppercase tracking-wider">{item.course}</span>}
                    </div>
                    {item.specialRequest && <p className="text-[10px] text-orange-600 font-medium mt-1 italic">"{item.specialRequest}"</p>}
                </div>
            </div>
            <div className="text-right">
                <p className="font-mono font-bold text-sm">${(item.price * item.quantity).toFixed(2)}</p>
                {item.fired && <Flame size={12} className="text-orange-500 ml-auto mt-1" />}
            </div>
        </div>
    </div>
);

export default TableServiceApp;

export enum UserRole {
  SUPER_ADMIN = 'SUPER_ADMIN',
  BUSINESS_ADMIN = 'BUSINESS_ADMIN',
  CASHIER = 'CASHIER',
  STAFF = 'STAFF',
  VENDOR = 'VENDOR',
  CUSTOMER = 'CUSTOMER'
}

export interface GlobalTaxConfig {
    rate: number;
