import React, { useState, useEffect } from 'react';
import { MOCK_KITCHEN_METRICS, MOCK_PRINTER_LABELS } from '../constants';
import { KitchenTicket, KitchenMetric, KDSSettings } from '../types';
import { Clock, CheckCircle, AlertTriangle, TrendingUp, TrendingDown, Minus, Filter, Bell, ChefHat, Package, Printer } from 'lucide-react';

interface KitchenDisplayProps {
    settings?: KDSSettings;
    liveTickets?: KitchenTicket[];
    onUpdateStatus?: (id: string, status: KitchenTicket['status']) => void;
}

const KitchenDisplay: React.FC<KitchenDisplayProps> = ({ settings, liveTickets, onUpdateStatus }) => {
    // If no live tickets passed (e.g. direct component test), fallback to empty.
    // Ideally we assume App.tsx provides the state.
    const tickets = liveTickets || [];

    const [activeTab, setActiveTab] = useState<'All' | 'Dine-in' | 'Takeout'>('All');
    const [activeStation, setActiveStation] = useState<string>('All Stations');

    const handleStatusChange = (id: string, status: KitchenTicket['status']) => {
        if (onUpdateStatus) {
            onUpdateStatus(id, status);
        }
    };

    // Filter Logic
    const filteredTickets = tickets.filter(t => {
        // 1. Filter by Order Type
        const typeMatch = activeTab === 'All' || t.type === activeTab;

        // 2. Filter by Station (Label)
        const stationMatch = activeStation === 'All Stations' || t.items.some(item => 
            item.printerLabels?.includes(activeStation)
        );

        return typeMatch && stationMatch;
    });

    // Group by status
    const pendingTickets = filteredTickets.filter(t => t.status === 'Pending');
    const prepTickets = filteredTickets.filter(t => t.status === 'Prep');
    const readyTickets = filteredTickets.filter(t => t.status === 'Ready');

    return (
        <div className="h-[calc(100vh-8rem)] flex flex-col bg-slate-900 text-white animate-fade-in">
            {/* KDS Header */}
            <div className="h-16 bg-slate-950 flex items-center justify-between px-6 shrink-0 border-b border-slate-800">
                <div className="flex items-center gap-4">
                    <h1 className="text-xl font-bold flex items-center gap-2">
                        <ChefHat className="text-orange-500" /> Kitchen Display
                    </h1>

                    <div className="h-8 w-px bg-slate-800 mx-2"></div>

                    {/* Station Selector (Simulating Screens/Printers) */}
                    <div className="relative group">
                        <button className="flex items-center gap-2 px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 rounded-lg text-sm font-bold transition-colors">
                            <Printer size={16} /> 
                            {activeStation === 'All Stations' ? 'Master View' : MOCK_PRINTER_LABELS.find(l => l.id === activeStation)?.name}
                        </button>
                        <div className="absolute top-full left-0 mt-2 w-48 bg-slate-800 border border-slate-700 rounded-xl shadow-xl overflow-hidden hidden group-hover:block z-50">
                            <button 
                                onClick={() => setActiveStation('All Stations')}
                                className="w-full text-left px-4 py-3 hover:bg-slate-700 text-sm font-medium border-b border-slate-700"
                            >
                                All Stations
                            </button>
                            {MOCK_PRINTER_LABELS.filter(l => l.isActive).map(label => (
                                <button
                                    key={label.id}
                                    onClick={() => setActiveStation(label.id)}
                                    className="w-full text-left px-4 py-3 hover:bg-slate-700 text-sm text-slate-300 hover:text-white"
                                >
                                    {label.name}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="flex bg-slate-800 rounded-lg p-1">
                        {['All', 'Dine-in', 'Takeout'].map(tab => (
                            <button
                                key={tab}
                                onClick={() => setActiveTab(tab as any)}
                                className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${activeTab === tab ? 'bg-slate-700 text-white' : 'text-slate-400 hover:text-white'}`}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>
                </div>
                <div className="flex items-center gap-6">
                    {MOCK_KITCHEN_METRICS.map((m, idx) => (
                        <div key={idx} className="flex flex-col items-end">
                            <span className="text-[10px] text-slate-400 uppercase font-bold">{m.metric}</span>
                            <div className="flex items-center gap-1 font-mono font-bold">
                                {m.trend === 'up' && <TrendingUp size={14} className="text-red-500" />}
                                {m.trend === 'down' && <TrendingDown size={14} className="text-emerald-500" />}
                                {m.trend === 'neutral' && <Minus size={14} className="text-slate-500" />}
                                {m.value}
                            </div>
                        </div>
                    ))}
                    <div className="h-8 w-px bg-slate-800"></div>
                    <button className="p-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white relative">
                        <Bell size={20} />
                        {settings?.soundAlerts && <span className="absolute top-2 right-2 h-2 w-2 bg-red-500 rounded-full"></span>}
                    </button>
                </div>
            </div>

            {/* Ticket Columns */}
            <div className="flex-1 overflow-x-auto p-4 flex gap-4">

                {/* Pending Column */}
                <div className="w-80 shrink-0 flex flex-col">
                    <div className="bg-slate-800/50 p-2 rounded-t-lg border-b border-slate-700 flex justify-between items-center">
                        <span className="font-bold text-slate-300">NEW ORDERS</span>
                        <span className="bg-red-500 text-white text-xs px-2 py-0.5 rounded-full font-bold">{pendingTickets.length}</span>
                    </div>
                    <div className="flex-1 bg-slate-900/50 rounded-b-lg border border-slate-800 p-2 space-y-3 overflow-y-auto">
                        {pendingTickets.map(ticket => (
                            <TicketCard 
                                key={ticket.id} 
                                ticket={ticket} 
                                onAction={() => handleStatusChange(ticket.id, 'Prep')} 
                                actionLabel="START" 
                                settings={settings}
                                activeStation={activeStation}
                            />
                        ))}
                    </div>
                </div>

                {/* Prep Column (Grid for density) */}
                <div className="flex-1 flex flex-col">
                    <div className="bg-slate-800/50 p-2 rounded-t-lg border-b border-slate-700 flex justify-between items-center">
                        <span className="font-bold text-slate-300">IN PREP</span>
                        <span className="bg-orange-500 text-white text-xs px-2 py-0.5 rounded-full font-bold">{prepTickets.length}</span>
                    </div>
                    <div className="flex-1 bg-slate-900/50 rounded-b-lg border border-slate-800 p-3 overflow-y-auto">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                            {prepTickets.map(ticket => (
                                <TicketCard 
                                    key={ticket.id} 
                                    ticket={ticket} 
                                    onAction={() => handleStatusChange(ticket.id, 'Ready')} 
                                    actionLabel="DONE" 
                                    settings={settings}
                                    activeStation={activeStation}
                                />
                            ))}
                        </div>
                    </div>
                </div>

                {/* Ready Column */}
                <div className="w-80 shrink-0 flex flex-col">
                    <div className="bg-slate-800/50 p-2 rounded-t-lg border-b border-slate-700 flex justify-between items-center">
                        <span className="font-bold text-slate-300">READY TO SERVE</span>
                        <span className="bg-emerald-500 text-white text-xs px-2 py-0.5 rounded-full font-bold">{readyTickets.length}</span>
                    </div>
                    <div className="flex-1 bg-slate-900/50 rounded-b-lg border border-slate-800 p-2 space-y-3 overflow-y-auto">
                        {readyTickets.map(ticket => (
                            <TicketCard 
                                key={ticket.id} 
                                ticket={ticket} 
                                onAction={() => handleStatusChange(ticket.id, 'Delivered')} 
                                actionLabel="CLEAR" 
                                variant="ready" 
                                settings={settings}
                                activeStation={activeStation}
                            />
                        ))}
                    </div>
                </div>

            </div>
        </div>
    );
};

const TicketCard: React.FC<{ 
    ticket: KitchenTicket, 
    onAction: () => void, 
    actionLabel: string, 
    variant?: 'normal' | 'ready', 
    settings?: KDSSettings,
    activeStation: string 
}> = ({ ticket, onAction, actionLabel, variant = 'normal', settings, activeStation }) => {

    // Timer simulation
    const elapsed = '12:30'; 
    const isLate = false; 

    return (
        <div className={`rounded-xl border-l-4 overflow-hidden shadow-sm flex flex-col transition-all hover:translate-y-[-2px]
            ${variant === 'ready' ? 'bg-emerald-900/20 border-l-emerald-500 border-white/10' : 
              ticket.type === 'Takeout' ? 'bg-blue-900/20 border-l-blue-500 border-white/10' : 
              'bg-slate-800 border-l-orange-500 border-white/5'} border`}>

            {/* Header */}
            <div className={`p-3 flex justify-between items-start border-b ${variant === 'ready' ? 'border-emerald-800/50' : 'border-white/5'}`}>
                <div>
                    <div className="flex items-center gap-2">
                        <span className="font-mono font-bold text-lg">#{ticket.orderId.split('-')[1]}</span>
                        {ticket.type === 'Takeout' && (
                            <span className="bg-blue-600 text-white text-[10px] px-1.5 py-0.5 rounded font-bold uppercase flex items-center gap-1">
                                <Package size={10} /> To-Go
                            </span>
                        )}
                    </div>
                    <div className="text-xs text-slate-400 mt-1">
                        {/* Respect Show Server Setting */}
                        {(settings?.showServer ?? true) && (ticket.server ? `Svr: ${ticket.server}` : 'Online Order')} 
                        {(settings?.showServer ?? true) && (settings?.showTable ?? true) && ' • '}
                        {/* Respect Show Table Setting */}
                        {(settings?.showTable ?? true) && (ticket.table || 'No Table')}
                    </div>
                </div>
                <div className={`font-mono text-sm font-bold ${isLate ? 'text-red-500 animate-pulse' : 'text-slate-300'}`}>
                    {elapsed}
                </div>
            </div>

            {/* Items */}
            <div className="p-3 space-y-3 flex-1">
                {ticket.items.map((item, idx) => {
                    // Logic: Does this item belong to the currently viewed station?
                    const isRelevantToStation = activeStation === 'All Stations' || item.printerLabels?.includes(activeStation);

                    return (
                        <div key={idx} className={isRelevantToStation ? 'opacity-100' : 'opacity-20 grayscale'}>
                            <div className="flex justify-between items-start">
                                <span className="font-bold text-lg">{item.qty}</span>
                                <span className="flex-1 ml-3 font-medium text-slate-200">{item.name}</span>
                            </div>
                            {item.modifiers.length > 0 && (
                                <div className="ml-6 text-sm text-slate-400 mt-1 space-y-0.5">
                                    {item.modifiers.map((mod, i) => (
                                        <div key={i} className="text-orange-400/80">• {mod}</div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>

            {/* Footer Action */}
            <div className="p-3">
                <button 
                    onClick={onAction}
                    className={`w-full py-3 rounded-lg font-bold text-sm tracking-wider flex items-center justify-center gap-2 transition-colors
                        ${variant === 'ready' 
                            ? 'bg-emerald-600 hover:bg-emerald-500 text-white' 
                            : 'bg-slate-700 hover:bg-slate-600 text-slate-200'}`}
                >
                    {variant === 'ready' ? <CheckCircle size={16} /> : <Clock size={16} />}
                    {actionLabel}
                </button>
            </div>
        </div>
    );
}

