// --- HELPER COMPONENTS ---

const Numpad = ({ value, onChange, onClear }: { value: string, onChange: (val: string) => void, onClear: () => void }) => {
    const handleNum = (num: string) => {
        if (value.includes('.') && num === '.') return;
        // Limit to 2 decimals
        if (value.includes('.') && value.split('.')[1]?.length >= 2) return;
        onChange(value + num);
    };

    const handleBackspace = () => {
        onChange(value.slice(0, -1));
    };

    return (
        <div className="grid grid-cols-3 gap-2 h-full">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(n => (
                <button key={n} onClick={() => handleNum(n.toString())} className="h-12 rounded-xl bg-slate-100 text-xl font-bold text-slate-700 hover:bg-slate-200 active:scale-95 transition-all">
                    {n}
                </button>
            ))}
            <button onClick={() => handleNum('.')} className="h-12 rounded-xl bg-slate-100 text-xl font-bold text-slate-700 hover:bg-slate-200 active:scale-95 transition-all">.</button>
            <button onClick={() => handleNum('0')} className="h-12 rounded-xl bg-slate-100 text-xl font-bold text-slate-700 hover:bg-slate-200 active:scale-95 transition-all">0</button>
            <button onClick={handleBackspace} className="h-12 rounded-xl bg-slate-100 text-xl font-bold text-slate-700 hover:bg-red-100 hover:text-red-600 active:scale-95 transition-all flex items-center justify-center">
                <Delete size={24} />
            </button>
        </div>
    );
};

// --- SUB-COMPONENTS (MODALS) ---

const ItemDetailModal = ({ item, discounts, onClose, onSave }: { item: CartItem, discounts: DiscountCode[], onClose: () => void, onSave: (item: CartItem) => void }) => {
    const [localItem, setLocalItem] = useState({...item});
    const [view, setView] = useState<'DETAILS' | 'DISCOUNT'>('DETAILS');

    // Custom Discount State
    const [customValue, setCustomValue] = useState('');
    const [customType, setCustomType] = useState<'Percentage' | 'Fixed'>('Percentage');

    const modifiers = ['Extra Cheese', 'No Onions', 'Gluten Free', 'Spicy', 'Sauce on Side', 'Well Done', 'Medium Rare', 'Add Bacon', 'Sub Salad'];

    const toggleModifier = (mod: string) => {
        const mods = localItem.modifiers || [];
        setLocalItem({...localItem, modifiers: mods.includes(mod) ? mods.filter(m => m !== mod) : [...mods, mod]});
    };

    const applyCustomDiscount = () => {
        const val = parseFloat(customValue);
        if (!val || isNaN(val)) return;

        setLocalItem({
            ...localItem,
            discount: {
                name: 'Custom Disc.',
                type: customType,
                value: val
            }
        });
        setCustomValue('');
        setView('DETAILS');
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">

                {/* Header */}
                <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/80 backdrop-blur">
                    {view === 'DISCOUNT' ? (
                        <div className="flex items-center gap-2">
                            <button onClick={() => setView('DETAILS')} className="p-2 -ml-2 hover:bg-slate-200 rounded-full transition-colors">
                                <ChevronLeft size={24} className="text-slate-600" />
                            </button>
                            <h3 className="text-xl font-black text-slate-800 tracking-tight">Apply Discount</h3>
                        </div>
