// URL Routing Helper
const getUrlPath = () => window.location.pathname;

// Helper: Generate Unique 10-char Order ID (Alphanumeric)
const generateOrderId = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let result = '';
    for (let i = 0; i < 10; i++) {
        result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
};

const App: React.FC = () => {
  const [currentPath, setCurrentPath] = useState(getUrlPath());

  // --- GLOBAL STATE ---
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);

  // Architecture: Multi-Tenant Support
  const [businesses, setBusinesses] = useState<Business[]>(MOCK_BUSINESSES);

  // Data State
  const [orders, setOrders] = useState<DetailedOrder[]>(MOCK_DETAILED_ORDERS);
  const [transactions, setTransactions] = useState<Transaction[]>(MOCK_TRANSACTIONS);
  const [customers, setCustomers] = useState<Customer[]>(MOCK_CUSTOMERS);
  const [employeesState, setEmployeesState] = useState<Employee[]>(MOCK_EMPLOYEES);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY_ITEMS);
  const [categories, setCategories] = useState<Category[]>(MOCK_CATEGORIES);
  const [discounts, setDiscounts] = useState<DiscountCode[]>(MOCK_DISCOUNTS);

  // Kitchen & Notification State
  const [activeTickets, setActiveTickets] = useState<KitchenTicket[]>(MOCK_KITCHEN_TICKETS);
  const [serverNotifications, setServerNotifications] = useState<Notification[]>([]);

  // Advanced Module State (Persistent POS State)
  const [floorPlanTables, setFloorPlanTables] = useState<DiningTable[]>(MOCK_FLOOR_TABLES);
  const [activeTableOrders, setActiveTableOrders] = useState<Record<string, { items: DiningOrderItem[], guests: {id: number, name?: string}[] }>>({});
  const [registerCart, setRegisterCart] = useState<CartItem[]>([]);

  const [kdsSettings, setKdsSettings] = useState<KDSSettings>(MOCK_KDS_SETTINGS);
  const [integrationConfig, setIntegrationConfig] = useState<AppIntegrationConfig>({
      reservation_pos: true,
      scheduling_pos: false,
      scheduling_reservation: false,
      kdsEnabled: MOCK_KDS_SETTINGS.isEnabled, 
  });
  const [receiptSettings, setReceiptSettings] = useState(MOCK_RECEIPT_SETTINGS);

  // Business Operations State
  const [taxConfig, setTaxConfig] = useState<GlobalTaxConfig>({ rate: 8.25, name: 'Sales Tax', enabled: true, includeInPrice: false });
  const [tipConfig, setTipConfig] = useState<TipConfig>(MOCK_TIP_CONFIG);

  // Navigation State
  const [activeTab, setActiveTab] = useState('Home');
  const [expandedMenu, setExpandedMenu] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);

  // Role Switcher State
  const [showRoleSwitcher, setShowRoleSwitcher] = useState(false);

  // --- EFFECTS ---
  useEffect(() => {
    const handlePopState = () => setCurrentPath(window.location.pathname);
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  // Update KDS enabled state in integrationConfig when kdsSettings changes
  useEffect(() => {
    setIntegrationConfig(prev => ({...prev, kdsEnabled: kdsSettings.isEnabled}));
  }, [kdsSettings.isEnabled]);

  // --- ACTIONS ---
  const handleLogin = (user: Employee) => {
    setCurrentUser(user);
    const posOnlyRoles = ['Server Lead', 'Server', 'Host', 'Employee', UserRole.CASHIER, UserRole.STAFF];

    if (posOnlyRoles.includes(user.role)) {
      setActiveTab('New Sale'); // Direct POS-only roles to POS App Launcher
    } else if (user.role === UserRole.SUPER_ADMIN) {
      setActiveTab('SuperAdmin');
    } else {
      setActiveTab('Home');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('Login');
    setIsProfileMenuOpen(false);
  };

  const handleSwitchRole = (roleName: string) => {
      // Find valid user for role
      const user = employeesState.find(u => u.role === roleName) || MOCK_EMPLOYEES.find(u => u.role === roleName);

      if (user) {
          handleLogin(user);
          setShowRoleSwitcher(false);
          setIsProfileMenuOpen(false);
      } else {
          if (roleName === UserRole.SUPER_ADMIN) {
             const sa = MOCK_EMPLOYEES.find(u => u.role === UserRole.SUPER_ADMIN);
             if (sa) {
                 handleLogin(sa);
                 setShowRoleSwitcher(false);
                 setIsProfileMenuOpen(false);
                 return;
             }
          }
          alert(`No user found with role: ${roleName}`);
      }
  };

  const handleProcessSale = (cart: any[], total: number, paymentMethod: string = 'Card', existingOrderId?: string) => {
    const newOrder: DetailedOrder = {
      id: existingOrderId || generateOrderId(),
      date: new Date().toLocaleDateString(),
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      total: total,
      status: 'Paid',
      paymentMethod: paymentMethod as any, 
      employeeName: currentUser?.name || 'Staff',
      device: 'Main Register',
      type: 'Dine-in', 
      items: cart
    };

    setOrders([newOrder, ...orders]);
    setTransactions([{
      id: `TRX-${Date.now()}`,
      date: new Date().toLocaleDateString(),
      amount: total,
      type: 'Sale',
      method: paymentMethod as any, 
      employeeId: currentUser?.id || 'E001'
    }, ...transactions]);
  };

  const handleUpdateTableOrder = (tableId: string, data: { items: DiningOrderItem[], guests: {id: number, name?: string}[] } | undefined) => {
      setActiveTableOrders(prev => {
          if (data === undefined) {
              const next = { ...prev };
              delete next[tableId];
              return next;
          }
          return { ...prev, [tableId]: data };
      });
  };

  const handleUpdateTableStatus = (updatedTable: DiningTable) => {
      setFloorPlanTables(prev => prev.map(t => t.id === updatedTable.id ? updatedTable : t));
  };

  // --- DATA MANAGEMENT HANDLERS ---
  const handleSaveItem = (item: InventoryItem) => {
      setInventory(prev => {
          const index = prev.findIndex(i => i.id === item.id);
          if (index >= 0) {
              const newItems = [...prev];
              newItems[index] = item;
              return newItems;
          }
          return [...prev, item];
      });
  };

  const handleDeleteItem = (id: string) => {
      setInventory(prev => prev.filter(i => i.id !== id));
  };

  const handleAddCustomer = (customer: Customer) => {
      setCustomers(prev => [customer, ...prev]);
  };

  // --- ARCHITECTURE: EMPLOYEE MANAGEMENT ---
  const handleAddEmployee = (emp: Employee) => {
    const linkedEmployee = {
        ...emp,
        businessId: currentUser?.businessId
    };
    setEmployeesState([...employeesState, linkedEmployee]);
  };

  const handleUpdateEmployee = (updatedEmp: Employee) => {
    setEmployeesState(prev => prev.map(emp => emp.id === updatedEmp.id ? updatedEmp : emp));
  };

  const handleDeleteEmployee = (id: string) => {
    if (window.confirm("Are you sure you want to delete this employee?")) {
        setEmployeesState(prev => prev.filter(emp => emp.id !== id));
    }
  };

  // --- ARCHITECTURE: SUPER ADMIN FUNCTIONS ---
  const handleAddBusiness = (biz: Business, owner: Partial<Employee>) => {
      const newBusiness = { ...biz, id: `B-${Date.now()}` };
      setBusinesses(prev => [...prev, newBusiness]);

      const newOwner: Employee = {
          id: `E-${Date.now()}`,
          name: owner.name || 'Admin',
          email: owner.email || '',
          passcode: owner.passcode || '1234',
          role: UserRole.BUSINESS_ADMIN,
          businessId: newBusiness.id,
          status: 'Active',
          hourlyRate: 0,
          hoursWorked: 0,
          deviceAccess: true
      };
      setEmployeesState(prev => [...prev, newOwner]);
  };

  const handleSaveFloorPlan = (tables: DiningTable[]) => {
    setFloorPlanTables(tables);
  };

  // KDS & Notification Logic
  const handleFireToKitchen = (ticket: KitchenTicket) => {
    setActiveTickets(prev => [...prev, ticket]);
  };

  const handleTicketStatusChange = (ticketId: string, status: KitchenTicket['status']) => {
    setActiveTickets(prev => prev.map(t => t.id === ticketId ? { ...t, status } : t));

    if (status === 'Ready' || status === 'Delivered') {
        const ticket = activeTickets.find(t => t.id === ticketId);
        if (ticket && ticket.serverEmployeeId) {
            const notification: Notification = {
                id: `NOTIF-${Date.now()}`,
                type: 'OrderReady',
                message: `Order #${ticket.orderId.split('-')[1] || ticket.orderId} for ${ticket.table || 'Takeout'} is ${status}!`,
                targetEmployeeId: ticket.serverEmployeeId,
                timestamp: new Date().toISOString(),
                read: false
            };
            setServerNotifications(prev => [notification, ...prev]);
        }
    }
  };

  const handleDismissNotification = (id: string) => {
      setServerNotifications(prev => prev.filter(n => n.id !== id));
  };

  // --- HELPER: Merge Open Table Orders for View ---
  const getMergedOrders = () => {
      const openOrders: DetailedOrder[] = floorPlanTables
          .filter(t => t.status === 'Occupied' && activeTableOrders[t.id])
          .map(t => {
              const orderData = activeTableOrders[t.id];
              const total = orderData.items.reduce((sum, i) => sum + (i.price * i.quantity), 0) * (1 + taxConfig.rate/100);

              return {
                  id: t.orderId || `TEMP-${t.id}`,
                  date: new Date().toLocaleDateString(),
                  time: t.timeSeated ? new Date(t.timeSeated).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '',
                  total: total,
                  status: 'Partially Refunded', // Visual placeholder for OPEN
                  paymentMethod: 'Card', 
                  employeeName: t.assignedToName || 'Server',
                  device: 'Table Service',
                  type: 'Dine-in',
                  items: orderData.items
              } as DetailedOrder;
          });
      const openOrdersFixed = openOrders.map(o => ({ ...o, status: 'Open' as any }));
      return [...openOrdersFixed, ...orders];
  };


  // --- NAVIGATION CONFIG ---
  const menuItems = [
    { id: 'New Sale', label: 'New Sale', icon: <ShoppingCart size={20} />, action: () => setActiveTab('New Sale') },
    { id: 'Home', label: 'Home', icon: <LayoutDashboard size={20} />, action: () => setActiveTab('Home') },
    { 
      id: 'Sales Activity', label: 'Sales Activity', icon: <Activity size={20} />, 
      subItems: ['Orders', 'Transactions', 'Cash Log', 'Invoices', 'Recurring Payments'] 
    },
    { 
      id: 'Reports', label: 'Reports', icon: <FileBarChart size={20} />, 
      subItems: ['Sales Report', 'Employee Sales', 'Peer Insights', 'Item Sales', 'Removed Items', 'Tender Types', 'Discounts Report', 'Gift Cards Report', 'Requested Reports'] 
    },
    { 
      id: 'Finances', label: 'Finances', icon: <DollarSign size={20} />, 
      subItems: ['Overview', 'Closeout', 'Deposits', 'Statements', 'Taxes', 'Disputes', 'Pay Bills'] 
    },
    { 
      id: 'Items', label: 'Items', icon: <Package size={20} />, 
      subItems: ['Item Library', 'Categories', 'Modifier Groups', 'Printer Labels', 'Discounts'] 
    },
    { 
      id: 'Employees', label: 'Employees', icon: <Users size={20} />, 
      subItems: ['Employee List', 'Schedule', 'Time Clock'] 
    },
    { 
      id: 'Customers', label: 'Customers', icon: <User size={20} />, 
      subItems: ['Customer List', 'Feedback'] 
    },
    { 
      id: 'More', label: 'More', icon: <MoreHorizontal size={20} />, 
      subItems: ['Byte Dinning', 'App Market'] 
    },
  ];

  // --- RENDER HELPERS ---
  const toggleSubMenu = (id: string) => {
    setExpandedMenu(expandedMenu === id ? null : id);
  };

  const renderSidebar = () => (
    <aside className={`bg-slate-900 text-slate-300 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} shrink-0 h-screen overflow-hidden`}>
      <div className="p-4 border-b border-slate-800 flex items-center justify-between">
        {isSidebarOpen && <span className="font-bold text-white text-lg tracking-tight">OmniCommand</span>}
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white">
          <Menu size={20} />
        </button>
      </div>

      <nav className="flex-1 overflow-y-auto py-4 space-y-1">
        {menuItems.map((item) => (
          <div key={item.id}>
            {item.subItems ? (
              <>
                <button
                  onClick={() => isSidebarOpen ? toggleSubMenu(item.id) : setActiveTab(item.subItems[0])}
                  className={`w-full flex items-center justify-between px-4 py-3 hover:bg-slate-800 hover:text-white transition-colors
                    ${activeTab === item.id || (item.subItems && item.subItems.includes(activeTab)) ? 'text-white bg-slate-800' : ''}`}
                >
                  <div className="flex items-center gap-3">
                    {item.icon}
                    {isSidebarOpen && <span className="font-medium text-sm">{item.label}</span>}
                  </div>
                  {isSidebarOpen && (
                    expandedMenu === item.id ? <ChevronDown size={16} /> : <ChevronRight size={16} />
                  )}
                </button>

                {isSidebarOpen && expandedMenu === item.id && (
                  <div className="bg-slate-950 py-1">
                    {item.subItems.map((sub) => (
                      <button
                        key={sub}
                        onClick={() => setActiveTab(sub)}
                        className={`w-full text-left pl-12 pr-4 py-2 text-sm hover:text-white transition-colors
                          ${activeTab === sub ? 'text-indigo-400 font-medium' : 'text-slate-500'}`}
                      >
                        {sub}
                      </button>
                    ))}
                  </div>
                )}
              </>
            ) : (
              <button
                onClick={item.action}
                className={`w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-800 hover:text-white transition-colors
                  ${activeTab === item.id ? 'text-white bg-slate-800 border-l-4 border-indigo-500' : ''}`}
              >
                {item.icon}
                {isSidebarOpen && <span className="font-medium text-sm">{item.label}</span>}
              </button>
            )}
          </div>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-800">
        <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
          <LogOut size={20} />
          {isSidebarOpen && <span className="font-medium text-sm">Sign Out</span>}
        </button>
      </div>
    </aside>
  );

  const renderRoleSwitcher = () => (
      <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fade-in">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-scale-in">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                  <h3 className="font-black text-xl text-slate-800 tracking-tight">Switch Role</h3>
                  <button onClick={() => setShowRoleSwitcher(false)} className="hover:bg-slate-200 rounded-full p-2 transition-colors">
                      <X size={24} className="text-slate-400" />
                  </button>
              </div>
              <div className="p-6 grid grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto">
                  {[
                      { role: 'Admin', icon: <Shield size={20} />, color: 'text-indigo-600', bg: 'bg-indigo-50' },
                      { role: 'Manager', icon: <Briefcase size={20} />, color: 'text-purple-600', bg: 'bg-purple-50' },
                      { role: 'Server Lead', icon: <Users size={20} />, color: 'text-orange-600', bg: 'bg-orange-50' },
                      { role: 'Server', icon: <Coffee size={20} />, color: 'text-blue-600', bg: 'bg-blue-50' },
                      { role: 'Host', icon: <Calendar size={20} />, color: 'text-rose-600', bg: 'bg-rose-50' },
                      { role: 'Employee', icon: <User size={20} />, color: 'text-slate-600', bg: 'bg-slate-100' },
                      { role: UserRole.SUPER_ADMIN, label: 'Platform Owner', icon: <Shield size={20} />, color: 'text-amber-600', bg: 'bg-amber-50' },
                  ].map((roleItem, idx) => (
                      <button 
                          key={idx}
                          onClick={() => handleSwitchRole(roleItem.role)}
                          className="flex flex-col items-center gap-3 p-4 rounded-2xl border-2 border-slate-100 hover:border-indigo-500 hover:bg-slate-50 transition-all group"
                      >
                          <div className={`p-4 rounded-xl ${roleItem.bg} ${roleItem.color} group-hover:scale-110 transition-transform`}>
                              {roleItem.icon}
                          </div>
                          <span className="font-bold text-slate-700 text-sm group-hover:text-slate-900">{roleItem.label || roleItem.role}</span>
                      </button>
                  ))}
              </div>
          </div>
      </div>
  );

  const renderContent = () => {
    // --- SECURITY FILTERING ---
    const filteredEmployees = currentUser?.role === UserRole.SUPER_ADMIN 
        ? employeesState 
        : employeesState.filter(e => e.businessId === currentUser?.businessId);

    switch(activeTab) {
      // Core
      case 'Home': return <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />;
      case 'New Sale': return (
        <CashierPOS 
          onLogout={() => setActiveTab('Home')} 
          onProcessSale={handleProcessSale}
          currentUser={currentUser!}
          sharedOrders={orders}
          sharedTransactions={transactions}
          sharedCustomers={customers}
          sharedEmployees={filteredEmployees}
          sharedInventory={inventory}
          sharedCategories={categories}
          sharedDiscounts={discounts}
          sharedTables={MOCK_TABLES}
          sharedReservations={MOCK_RESERVATIONS}
          sharedSchedules={MOCK_SCHEDULES}
          onSeatReservation={(resId, tableId) => console.log('Seat', resId, tableId)}
          integrationConfig={integrationConfig}
          floorPlanTables={floorPlanTables}
          // PASS PERSISTENT STATE PROPS
          activeTableOrders={activeTableOrders}
          onUpdateTableOrder={handleUpdateTableOrder}
          onUpdateTableStatus={handleUpdateTableStatus}
          activeRegisterCart={registerCart}
          onUpdateRegisterCart={setRegisterCart}
          onAddCustomer={handleAddCustomer}
          // END PERSISTENT STATE PROPS
          kdsSettings={kdsSettings}
          receiptSettings={receiptSettings}
          onFireToKitchen={handleFireToKitchen}
          taxConfig={taxConfig}
          tipConfig={tipConfig}
          onNavigate={(tab) => setActiveTab(tab)}
          notifications={serverNotifications}
          onDismissNotification={handleDismissNotification}
          kitchenTickets={activeTickets}
          onKitchenStatusChange={handleTicketStatusChange}
        />
      );

      // Sales Activity
      case 'Orders': return <Orders orders={getMergedOrders()} />;
      case 'Transactions': return <Transactions transactions={transactions} />;
      case 'Cash Log': return <CashLog logs={MOCK_CASH_LOGS} />;
      case 'Invoices': return <Invoices />;
      case 'Recurring Payments': return <RecurringPayments />;

      // Reports
      case 'Sales Report': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Daily Sales" />;
      case 'Employee Sales': return <EmployeeSalesReport />;
      case 'Peer Insights': return <PeerInsights totalSales={145000} transactionCount={1200} customers={customers} />;
      case 'Item Sales': return <ItemSales />;
      case 'Removed Items': return <RemovedItems />;
      case 'Tender Types': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Tender Types" />;
      case 'Discounts Report': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Overview" />;
      case 'Gift Cards Report': return <GiftCardReport />;
      case 'Requested Reports': return <Documents statements={MOCK_STATEMENTS} reports={MOCK_REPORT_REQUESTS} />;

      // Finances
      case 'Overview': return <FinancesOverview />;
      case 'Closeout': return <Closeout />;
      case 'Deposits': return <Deposits />;
      case 'Statements': return <Documents statements={MOCK_STATEMENTS} reports={MOCK_REPORT_REQUESTS} />;
      case 'Taxes': return <SalesReports salesData={MOCK_SALES_SUMMARY} deposits={MOCK_DEPOSITS} taxReports={MOCK_TAX_REPORTS} initialTab="Tax" />;
      case 'Disputes': return <Disputes />;
      case 'Pay Bills': return <PayBills />;

      // Items
      case 'Item Library': return <Items items={inventory} onSaveItem={handleSaveItem} onDeleteItem={handleDeleteItem} />;
      case 'Categories': return (
          <Categories 
            categories={categories} 
            setCategories={setCategories} 
            inventory={inventory} 
            setInventory={setInventory}
          />
      );
      case 'Modifier Groups': return <ModifierGroups />;
      case 'Printer Labels': return <PrinterLabels />;
      case 'Discounts': return <Discounts discounts={discounts} setDiscounts={setDiscounts} />;

      // Employees
      case 'Employee List': return (
        <Employees 
            employees={filteredEmployees}
            onAddEmployee={handleAddEmployee} 
            onUpdateEmployee={handleUpdateEmployee}
            onDeleteEmployee={handleDeleteEmployee}
        />
      );
      case 'Schedule': return <SchedulingApp schedules={MOCK_SCHEDULES} />;
      case 'Time Clock': return <SchedulingApp schedules={MOCK_SCHEDULES} />;

      // Customers
      case 'Customer List': return <Customers customers={customers} onAddCustomer={handleAddCustomer} />;
      case 'Feedback': return <div className="p-8 text-center text-slate-500">Feedback Dashboard Coming Soon</div>;

      // More / Apps
      case 'Byte Dinning': return (
        <DiningDashboard 
          initialTables={floorPlanTables} 
          onSaveFloorPlan={handleSaveFloorPlan} 
        />
      );
      case 'App Market': return <div className="p-8 text-center text-slate-500">App Market Coming Soon</div>;
      case 'Settings': return (
        <Settings 
            taxConfig={taxConfig}
            setTaxConfig={setTaxConfig}
            tipConfig={tipConfig}
            setTipConfig={setTipConfig}
            onNavigate={(tab) => setActiveTab(tab)}
        />
      );

      default: return <Dashboard hourlySales={MOCK_HOURLY_SALES} salesSummary={MOCK_SALES_SUMMARY} />;
    }
  };

  // --- ROUTING LOGIC ---
  if (currentPath === '/feedback') {
    return <ReceiptFeedback />;
  }

  if (currentPath === '/kitchen') {
    return (
        <KitchenDisplay 
            settings={kdsSettings} 
            liveTickets={activeTickets}
            onUpdateStatus={handleTicketStatusChange}
        />
    );
  }

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  // --- SUPER ADMIN VIEW ---
  if (currentUser.role === UserRole.SUPER_ADMIN) {
    return (
        <div className="bg-slate-100 min-h-screen p-4">
            {showRoleSwitcher && renderRoleSwitcher()}
            <div className="max-w-7xl mx-auto space-y-4">
                <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <h1 className="font-bold text-slate-800 text-lg">OmniCommand Super Admin</h1>
                    <div className="flex items-center gap-4">
                        <button onClick={() => setShowRoleSwitcher(true)} className="flex items-center gap-2 text-indigo-600 hover:text-indigo-800 font-bold text-sm">
                            <RefreshCw size={16} /> Switch Role
                        </button>
                        <div className="h-4 w-px bg-slate-200"></div>
                        <button onClick={handleLogout} className="text-slate-500 hover:text-red-600 font-medium text-sm">Sign Out</button>
                    </div>
                </div>
                <SuperAdmin 
                    integrationConfig={integrationConfig} 
                    onToggleIntegration={(key) => {
                        setIntegrationConfig(prev => ({...prev, [key]: !prev[key]}));
                        if (key === 'kdsEnabled') {
                            setKdsSettings(prev => ({...prev, isEnabled: !prev.isEnabled}));
                        }
                    }}
                    businesses={businesses}
                    onAddBusiness={handleAddBusiness}
                />
            </div>
        </div>
    );
  }

  // --- ACCESS POLICY: LOCK-IN FOR STAFF ROLES ---
  const posOnlyRoles = ['Server Lead', 'Server', 'Host', 'Employee', UserRole.CASHIER, UserRole.STAFF];
  if (posOnlyRoles.includes(currentUser.role)) {
    return (
        <>
            {showRoleSwitcher && renderRoleSwitcher()}
            <CashierPOS 
              onLogout={handleLogout} 
              onProcessSale={handleProcessSale}
              currentUser={currentUser}
              sharedOrders={orders}
              sharedTransactions={transactions}
              sharedCustomers={customers}
              sharedEmployees={employeesState.filter(e => e.businessId === currentUser.businessId)}
              sharedInventory={inventory}
              sharedCategories={categories}
              sharedDiscounts={discounts}
              sharedTables={MOCK_TABLES}
              sharedReservations={MOCK_RESERVATIONS}
              sharedSchedules={MOCK_SCHEDULES}
              onSeatReservation={(resId, tableId) => console.log('Seat', resId, tableId)}
              integrationConfig={integrationConfig}
              floorPlanTables={floorPlanTables}
              // PASS PERSISTENT STATE PROPS
              activeTableOrders={activeTableOrders}
              onUpdateTableOrder={handleUpdateTableOrder}
              onUpdateTableStatus={handleUpdateTableStatus}
              activeRegisterCart={registerCart}
              onUpdateRegisterCart={setRegisterCart}
              onAddCustomer={handleAddCustomer}
              // END PERSISTENT STATE PROPS
              kdsSettings={kdsSettings}
              receiptSettings={receiptSettings}
              onFireToKitchen={handleFireToKitchen}
              taxConfig={taxConfig}
              tipConfig={tipConfig}
              onNavigate={(tab) => {
                  if (tab === 'SwitchRole') setShowRoleSwitcher(true);
                  else setActiveTab(tab);
              }}
              notifications={serverNotifications}
              onDismissNotification={handleDismissNotification}
              kitchenTickets={activeTickets}
              onKitchenStatusChange={handleTicketStatusChange}
            />
        </>
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">
      {showRoleSwitcher && renderRoleSwitcher()}
      {renderSidebar()}
      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shrink-0 z-20 shadow-sm relative">
            <h2 className="font-bold text-lg text-slate-800">{activeTab}</h2>

            <div className="flex items-center gap-6">
                {/* Utility Actions Icons */}
                <div className="flex items-center gap-3 border-r border-slate-200 pr-6 mr-2">
                    <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-lg transition-all relative" title="Notifications">
                        <Bell size={20} />
                        {serverNotifications.length > 0 && <span className="absolute top-2 right-2 h-2 w-2 bg-red-500 rounded-full border-2 border-white"></span>}
                    </button>
                    <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded-lg transition-all" title="Help & Documentation">
                        <HelpCircle size={20} />
                    </button>
                    <button 
                        onClick={() => setActiveTab('Settings')}
                        className={`p-2 rounded-lg transition-all ${activeTab === 'Settings' ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:text-indigo-600 hover:bg-slate-100'}`} 
                        title="Settings"
                    >
                        <SettingsIcon size={20} />
                    </button>
                </div>

                {/* Profile Section */}
                <div className="flex items-center gap-3 relative">
                    <div className="flex flex-col items-end hidden sm:flex">
                        <span className="text-sm font-bold text-slate-900 leading-none">{currentUser.name}</span>
                        <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider mt-1">{currentUser.role.replace('_', ' ')}</span>
                    </div>
                    <button 
                        onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)}
                        className={`h-10 w-10 rounded-xl flex items-center justify-center font-bold border transition-all shadow-sm
                            ${isProfileMenuOpen 
                                ? 'bg-indigo-600 text-white border-indigo-700' 
                                : 'bg-indigo-100 text-indigo-700 border-indigo-200 hover:ring-2 hover:ring-indigo-200'}`}
                        title="Account Profile"
                    >
                        {currentUser.name.charAt(0)}
                    </button>

                    {/* Profile Dropdown Menu */}
                    {isProfileMenuOpen && (
                        <>
                            <div 
                                className="fixed inset-0 z-30" 
                                onClick={() => setIsProfileMenuOpen(false)}
                            />
                            <div className="absolute top-full right-0 mt-2 w-64 bg-white rounded-2xl shadow-2xl border border-slate-200 z-40 overflow-hidden animate-scale-in">
                                <div className="p-4 bg-slate-50 border-b border-slate-200">
                                    <p className="text-sm font-bold text-slate-900">{currentUser.name}</p>
                                    <p className="text-xs text-slate-500 font-medium">{currentUser.email}</p>
                                    <div className="mt-2 flex items-center gap-1.5">
                                        <span className="px-2 py-0.5 bg-indigo-100 text-indigo-700 text-[10px] font-bold uppercase rounded-md">
                                            {currentUser.role.replace('_', ' ')}
                                        </span>
                                    </div>
                                </div>
                                <div className="p-2">
                                    <button 
                                        onClick={() => { setActiveTab('Settings'); setIsProfileMenuOpen(false); }}
                                        className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
                                    >
                                        <User size={18} className="text-slate-400" />
                                        <span>My Profile</span>
                                    </button>
                                    <button 
                                        onClick={() => { setShowRoleSwitcher(true); setIsProfileMenuOpen(false); }}
                                        className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
                                    >
                                        <RefreshCw size={18} className="text-slate-400" />
                                        <span>Switch Role</span>
                                    </button>
                                    <button 
                                        onClick={() => { setActiveTab('Settings'); setIsProfileMenuOpen(false); }}
                                        className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
                                    >
                                        <SettingsIcon size={18} className="text-slate-400" />
                                        <span>System Settings</span>
                                    </button>
                                    <div className="my-1 border-t border-slate-100" />
                                    <button 
                                        onClick={handleLogout}
                                        className="w-full flex items-center gap-3 px-3 py-2.5 text-sm text-rose-600 hover:bg-rose-50 rounded-lg transition-colors font-medium"
                                    >
                                        <LogOut size={18} className="text-rose-500" />
                                        <span>Sign Out</span>
                                    </button>
                                </div>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </header>
        <div className="flex-1 overflow-auto p-6 relative">
            {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { InventoryItem } from '../types';
import { Search, Plus, Filter, Edit2, Trash2, Tag, Monitor, Smartphone, Layers, Box, X, Check, Printer } from 'lucide-react';
import { MOCK_PRINTER_LABELS } from '../constants';

interface ItemsProps {
    items: InventoryItem[];
    onSaveItem?: (item: InventoryItem) => void;
    onDeleteItem?: (id: string) => void;
}

const Items: React.FC<ItemsProps> = ({ items, onSaveItem, onDeleteItem }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<InventoryItem>>({
      name: '', price: 0, cost: 0, category: 'Uncategorized', printerLabels: [], inStock: true, showOnPos: true, showOnline: true
  });

  const filteredItems = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleOpenAdd = () => {
      setEditingItem(null);
      setFormData({ name: '', price: 0, cost: 0, category: 'Uncategorized', printerLabels: [], inStock: true, showOnPos: true, showOnline: true });
      setShowModal(true);
  };

  const handleOpenEdit = (item: InventoryItem) => {
      setEditingItem(item);
      setFormData({...item});
      setShowModal(true);
  };

  const toggleLabel = (labelId: string) => {
      const labels = formData.printerLabels || [];
      if (labels.includes(labelId)) {
          setFormData({ ...formData, printerLabels: labels.filter(l => l !== labelId) });
      } else {
          setFormData({ ...formData, printerLabels: [...labels, labelId] });
      }
  };

  const handleSave = () => {
      if (onSaveItem && formData.name) {
          const itemToSave: InventoryItem = {
              id: editingItem ? editingItem.id : `ITEM-${Date.now()}`,
              name: formData.name,
              price: formData.price || 0,
              cost: formData.cost || 0,
              category: formData.category || 'Uncategorized',
              printerLabels: formData.printerLabels || [],
              inStock: formData.inStock ?? true,
              showOnPos: formData.showOnPos ?? true,
              showOnline: formData.showOnline ?? true,
              modifierGroups: formData.modifierGroups || []
          };
          onSaveItem(itemToSave);
      }
      setShowModal(false);
  };

  const handleDelete = (id: string) => {
      if (confirm("Are you sure you want to delete this item?") && onDeleteItem) {
          onDeleteItem(id);
      }
  };

  return (
    <div className="space-y-6 animate-fade-in relative">
      {/* Add/Edit Modal */}
      {showModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh] animate-scale-in">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                      <h3 className="text-xl font-black text-slate-800 tracking-tight">
                          {editingItem ? 'Edit Item' : 'New Item'}
                      </h3>
                      <button onClick={() => setShowModal(false)}><X size={24} className="text-slate-400" /></button>
                  </div>

                  <div className="p-6 overflow-y-auto space-y-6">
                      <div>
                          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Item Name</label>
                          <input 
                              type="text" 
                              value={formData.name} 
                              onChange={e => setFormData({...formData, name: e.target.value})}
                              className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                              placeholder="e.g. Cheeseburger"
                          />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Price ($)</label>
                              <input 
                                  type="number" 
                                  value={formData.price} 
                                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                                  className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                              />
                          </div>
                          <div>
                              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Cost ($)</label>
                              <input 
                                  type="number" 
                                  value={formData.cost} 
                                  onChange={e => setFormData({...formData, cost: parseFloat(e.target.value)})}
                                  className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                              />
                          </div>
                      </div>

                      <div>
                          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Printer Routing / Labels</label>
                          <div className="grid grid-cols-2 gap-3">
                              {MOCK_PRINTER_LABELS.map(label => {
                                  const isSelected = formData.printerLabels?.includes(label.id);
                                  return (
                                      <button 
                                          key={label.id}
                                          onClick={() => toggleLabel(label.id)}
                                          className={`flex items-center gap-3 p-3 rounded-xl border-2 transition-all text-left ${isSelected ? 'border-indigo-600 bg-indigo-50' : 'border-slate-100 bg-white hover:border-slate-300'}`}
                                      >
                                          <div className={`w-5 h-5 rounded flex items-center justify-center border transition-colors ${isSelected ? 'bg-indigo-600 border-indigo-600' : 'bg-white border-slate-300'}`}>
                                              {isSelected && <Check size={14} className="text-white" />}
                                          </div>
                                          <div>
                                              <p className={`text-sm font-bold ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{label.name}</p>
                                              <p className="text-[10px] text-slate-400">{label.assignedPrinter}</p>
                                          </div>
                                      </button>
                                  );
                              })}
                          </div>
                      </div>

                      <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <label className="flex items-center gap-3 cursor-pointer">
                              <input type="checkbox" checked={formData.inStock} onChange={e => setFormData({...formData, inStock: e.target.checked})} className="w-5 h-5 text-indigo-600 rounded" />
                              <span className="text-sm font-bold text-slate-700">In Stock</span>
                          </label>
                          <label className="flex items-center gap-3 cursor-pointer">
                              <input type="checkbox" checked={formData.showOnPos} onChange={e => setFormData({...formData, showOnPos: e.target.checked})} className="w-5 h-5 text-indigo-600 rounded" />
                              <span className="text-sm font-bold text-slate-700">Show on POS</span>
                          </label>
                      </div>
                  </div>

                  <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
                      <button onClick={() => setShowModal(false)} className="px-6 py-3 font-bold text-slate-500 hover:text-slate-700 text-sm uppercase tracking-widest">Cancel</button>
                      <button onClick={handleSave} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg hover:bg-indigo-700 active:scale-95 transition-all text-sm uppercase tracking-widest">Save Item</button>
                  </div>
              </div>
          </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Item Library</h1>
          <p className="text-slate-500">Manage products, pricing, modifiers, and inventory</p>
        </div>
        <button onClick={handleOpenAdd} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 shadow-sm transition-colors font-medium">
            <Plus size={18} /> Add Item
        </button>
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder="Search by name, category, or SKU..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
        </div>
        <div className="flex gap-2">
            <button className="flex items-center gap-2 px-4 py-2 bg-slate-100 rounded-lg text-slate-600 hover:bg-slate-200 font-medium">
                <Filter size={18} /> Filter
            </button>
        </div>
      </div>

      {/* Items Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 border-b border-slate-200 text-slate-500">
            <tr>
              <th className="px-6 py-3 font-semibold">Item Name</th>
              <th className="px-6 py-3 font-semibold">Category</th>
              <th className="px-6 py-3 font-semibold text-right">Price</th>
              <th className="px-6 py-3 font-semibold text-center">Routing</th>
              <th className="px-6 py-3 font-semibold text-center">In Stock</th>
              <th className="px-6 py-3 font-semibold text-center">POS</th>
              <th className="px-6 py-3 font-semibold text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredItems.map(item => (
              <tr key={item.id} className="hover:bg-slate-50 group">
                <td className="px-6 py-4">
                    <div className="flex flex-col">
                        <span className="font-medium text-slate-900 text-base">{item.name}</span>
                        {item.modifierGroups.length > 0 && (
                            <div className="flex items-center gap-1 text-xs text-slate-500 mt-1">
                                <Layers size={12} /> {item.modifierGroups.length} Modifier Groups
                            </div>
                        )}
                    </div>
                </td>
                <td className="px-6 py-4">
                    <span className="inline-flex items-center gap-1 px-2.5 py-0.5 bg-slate-100 rounded-full text-xs text-slate-600 font-medium border border-slate-200">
                        <Tag size={10} /> {item.category}
                    </span>
                </td>
                <td className="px-6 py-4 text-right font-mono text-slate-900 font-medium text-base">
                  ${item.price.toFixed(2)}
                </td>
                <td className="px-6 py-4 text-center">
                    <div className="flex gap-1 justify-center">
                        {item.printerLabels && item.printerLabels.length > 0 ? (
                            item.printerLabels.map(l => (
                                <span key={l} className="text-[10px] bg-slate-100 border border-slate-200 text-slate-500 px-1.5 py-0.5 rounded font-bold uppercase" title={MOCK_PRINTER_LABELS.find(pl => pl.id === l)?.name}>
                                    {MOCK_PRINTER_LABELS.find(pl => pl.id === l)?.name.substring(0, 3) || l}
                                </span>
                            ))
                        ) : (
                            <span className="text-slate-300 text-xs">-</span>
                        )}
                    </div>
                </td>
                <td className="px-6 py-4 text-center">
                    {item.inStock ? (
                        <span className="text-emerald-600 bg-emerald-50 px-2 py-1 rounded text-xs font-bold">In Stock</span>
                    ) : (
                        <span className="text-red-600 bg-red-50 px-2 py-1 rounded text-xs font-bold flex items-center justify-center gap-1">
                            <Box size={12} /> Out
                        </span>
                    )}
                </td>
                <td className="px-6 py-4 text-center">
                    <div className={`mx-auto h-2 w-2 rounded-full ${item.showOnPos ? 'bg-emerald-500' : 'bg-slate-300'}`} />
                </td>
                <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleOpenEdit(item)} className="p-1.5 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded transition-colors">
                            <Edit2 size={16} />
                        </button>
                        <button onClick={() => handleDelete(item.id)} className="p-1.5 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors">
                            <Trash2 size={16} />
                        </button>
                    </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Items;

import React, { useState } from 'react';
import { 
    DetailedOrder, Transaction, Customer, Employee, InventoryItem, 
    Table, Reservation, Schedule, Category, PaymentSplit, Receipt, 
    DiscountCode, DiningTable, KDSSettings, UserRole, CartItem, GlobalTaxConfig, TipConfig, KitchenTicket, Notification, DiningOrderItem
} from '../types';
import { LayoutGrid, Lock, ShieldAlert, Monitor, ChevronRight, Search, Settings, CreditCard, ShoppingBag, Box, ArrowRight, Bell, CheckCircle, X } from 'lucide-react';
import PosLauncher, { PosAppType } from './POS/PosLauncher';
import PosRegister from './POS/PosRegister';
import ReservationsApp from './ReservationsApp';
import SchedulingApp from './SchedulingApp';
import TableServiceApp from './TableServiceApp';
import KitchenDisplay from './KitchenDisplay';
import ExpeditorScreen from './POS/ExpeditorScreen';
