export default TableServiceApp;

import React, { useState, useEffect } from 'react';
import { DiningTable } from '../types';
import { User, Clock, AlertCircle, MoveDiagonal, Check } from 'lucide-react';

interface InteractiveTableProps {
    table: DiningTable;
    onClick: (e: React.MouseEvent, table: DiningTable, isResizeHandle: boolean) => void;
    isEditing?: boolean;
    isSelected?: boolean;
    isOrderReady?: boolean;
}

const InteractiveTable: React.FC<InteractiveTableProps> = ({ table, onClick, isEditing, isSelected, isOrderReady }) => {
    const [elapsedMinutes, setElapsedMinutes] = useState(0);
    const [isHovered, setIsHovered] = useState(false);

    useEffect(() => {
        if (table.status !== 'Available' && table.timeSeated) {
            const calculateTime = () => {
                const seatedTime = new Date(table.timeSeated!).getTime();
                const now = new Date().getTime();
                const diffMins = Math.floor((now - seatedTime) / 60000);
                setElapsedMinutes(Math.max(0, diffMins));
            };

            calculateTime();
            const interval = setInterval(calculateTime, 60000);
            return () => clearInterval(interval);
        } else {
            setElapsedMinutes(0);
        }
    }, [table.status, table.timeSeated]);

    const expected = table.expectedDuration || 60;
    const progress = Math.min(100, (elapsedMinutes / expected) * 100);
    const radius = 24; 
    const circumference = 2 * Math.PI * radius;
    const strokeDashoffset = circumference - (progress / 100) * circumference;

    // --- VISUAL LOGIC ---
    let tableFill = 'fill-white';
    let tableStroke = 'stroke-slate-400';
    let chairStroke = '#94a3b8';
    let ringColor = '#cbd5e1'; 
    let labelColor = 'text-slate-500';

    if (table.isSeatable) {
        if (table.highlight) {
            tableFill = 'fill-yellow-50';
            tableStroke = 'stroke-yellow-400';
            chairStroke = '#facc15';
        } else if (table.status === 'Available') {
            tableFill = 'fill-white';
            tableStroke = 'stroke-emerald-500';
            chairStroke = '#10b981';
            labelColor = 'text-emerald-700';
        } else if (table.status === 'Occupied') {
            tableFill = 'fill-blue-50';
            tableStroke = 'stroke-blue-500';
            chairStroke = '#3b82f6';
            ringColor = '#3b82f6';
            labelColor = 'text-blue-700';
        } else if (table.status === 'Overdue' || (elapsedMinutes > expected)) {
            tableFill = 'fill-red-50';
            tableStroke = 'stroke-red-500';
            chairStroke = '#ef4444';
            ringColor = '#ef4444';
            labelColor = 'text-red-700';
        }
    }

    const renderChairs = () => {
        if (!table.isSeatable || table.seats === 0) return null;

        const chairs = [];
        const chairLength = 8;
        const strokeWidth = 4;

        if (table.type === 'TABLE_ROUND') {
            for (let i = 0; i < table.seats; i++) {
                const angle = (i / table.seats) * 2 * Math.PI;
                const x1 = 50 + 45 * Math.cos(angle); 
                const y1 = 50 + 45 * Math.sin(angle);
                const x2 = 50 + (50 + chairLength) * Math.cos(angle);
                const y2 = 50 + (50 + chairLength) * Math.sin(angle);

                chairs.push(
                    <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={chairStroke} strokeWidth={strokeWidth} strokeLinecap="round" />
                );
            }
        } else {
            const seatsPerSide = Math.ceil(table.seats / 4);
            const perimeter = 400;
            const step = perimeter / table.seats;

            const getCoords = (dist: number) => {
                let x=0, y=0, dx=0, dy=0;
                if (dist <= 100) { 
                    x = dist; y = 2; dx = 0; dy = -1; 
                } else if (dist <= 200) { 
                    x = 98; y = dist - 100; dx = 1; dy = 0; 
                } else if (dist <= 300) { 
                    x = 300 - dist; y = 98; dx = 0; dy = 1; 
                } else { 
                    x = 2; y = 400 - dist; dx = -1; dy = 0; 
                }
                return { x, y, dx, dy };
            };

            for(let i=0; i<table.seats; i++) {
                const dist = (step * i) + (step/2);
                const pos = getCoords(dist % 400);

                chairs.push(
                    <line 
                        key={i} 
                        x1={pos.x} 
                        y1={pos.y} 
                        x2={pos.x + (pos.dx * chairLength)} 
                        y2={pos.y + (pos.dy * chairLength)} 
                        stroke={chairStroke} 
                        strokeWidth={strokeWidth} 
                        strokeLinecap="round" 
                    />
                );
            }
        }
        return chairs;
    };

    const renderVectorContent = () => {
        switch(table.type) {
            case 'TABLE_ROUND':
                return (
                    <svg viewBox="-20 -20 140 140" className="w-full h-full overflow-visible pointer-events-none">
                        {renderChairs()}
                        <circle cx="50" cy="50" r="48" className={`${tableFill} ${tableStroke}`} strokeWidth="3" />
                    </svg>
                );
            case 'TABLE_SQUARE':
            case 'TABLE_RECT':
                return (
                    <svg viewBox="-20 -20 140 140" className="w-full h-full overflow-visible pointer-events-none">
                        {renderChairs()}
                        <rect x="2" y="2" width="96" height="96" rx="4" className={`${tableFill} ${tableStroke}`} strokeWidth="3" />
                    </svg>
                );
            case 'BOOTH_SINGLE':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none">
                        <path d="M5 20 Q5 5 20 5 L80 5 Q95 5 95 20 L95 90 Q95 95 90 95 L10 95 Q5 95 5 90 Z" fill="#f1f5f9" stroke="#94a3b8" strokeWidth="2" />
                        <path d="M10 25 L90 25 L90 40 L10 40 Z" fill="#cbd5e1" />
                        <path d="M15 45 L85 45 L85 85 L15 85 Z" fill="#e2e8f0" stroke="#cbd5e1" />
                    </svg>
                );
            case 'BOOTH_DOUBLE':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none">
                        <rect x="5" y="5" width="90" height="90" rx="5" fill="#f1f5f9" stroke="#94a3b8" strokeWidth="2" />
                        <rect x="10" y="10" width="80" height="20" fill="#cbd5e1" />
                        <rect x="10" y="70" width="80" height="20" fill="#cbd5e1" />
                        <rect x="15" y="35" width="70" height="30" fill="#e2e8f0" stroke="#cbd5e1" />
                    </svg>
                );
            case 'COUCH_STRAIGHT':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none">
                        <rect x="5" y="20" width="90" height="60" rx="10" fill="#e2e8f0" stroke="#94a3b8" strokeWidth="2" />
                        <rect x="10" y="15" width="80" height="15" rx="5" fill="#cbd5e1" />
                        <path d="M10 35 L90 35" stroke="#94a3b8" strokeWidth="1" />
                        <rect x="10" y="45" width="35" height="30" rx="5" fill="#f8fafc" stroke="#cbd5e1" />
                        <rect x="55" y="45" width="35" height="30" rx="5" fill="#f8fafc" stroke="#cbd5e1" />
                    </svg>
                );
            case 'COUCH_L':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none">
                        <path d="M10 10 L90 10 L90 40 L40 40 L40 90 L10 90 Z" fill="#e2e8f0" stroke="#94a3b8" strokeWidth="2" />
