                        {Array.from({length: 12}).map((_, i) => (
                            <g key={i} transform={`rotate(${i * 30} 50 50)`}>
                                <path d="M50 50 Q45 25 50 0 Q55 25 50 50" fill="#15803d" stroke="#14532d" strokeWidth="1" />
                            </g>
