            case 'PLANT_SHRUB':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-sm pointer-events-none">
                        <circle cx="50" cy="50" r="40" fill="#22c55e" opacity="0.9" />
                        <circle cx="30" cy="30" r="25" fill="#16a34a" opacity="0.8" />
                        <circle cx="70" cy="70" r="25" fill="#15803d" opacity="0.8" />
                        <circle cx="70" cy="30" r="20" fill="#166534" opacity="0.8" />
                        <circle cx="30" cy="70" r="20" fill="#14532d" opacity="0.8" />
                    </svg>
                );
            case 'DECOR_POOL':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none">
                        <rect x="0" y="0" width="100" height="100" rx="5" fill="#0ea5e9" stroke="#0284c7" strokeWidth="4" />
                        <path d="M10 20 Q25 10 40 20 T70 20 T100 20" stroke="white" strokeWidth="2" opacity="0.3" fill="none" />
                        <path d="M10 50 Q25 40 40 50 T70 50 T100 50" stroke="white" strokeWidth="2" opacity="0.3" fill="none" />
                        <path d="M10 80 Q25 70 40 80 T70 80 T100 80" stroke="white" strokeWidth="2" opacity="0.3" fill="none" />
                        <rect x="0" y="30" width="20" height="40" fill="white" opacity="0.2" />
                    </svg>
                );
            case 'DECOR_BEACH_BENCH':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none">
                        <rect x="5" y="20" width="90" height="60" rx="2" fill="#fde68a" stroke="#d97706" strokeWidth="2" />
                        <line x1="15" y1="20" x2="15" y2="80" stroke="#d97706" strokeWidth="2" />
                        <line x1="35" y1="20" x2="35" y2="80" stroke="#d97706" strokeWidth="2" />
                        <line x1="55" y1="20" x2="55" y2="80" stroke="#d97706" strokeWidth="2" />
                        <line x1="75" y1="20" x2="75" y2="80" stroke="#d97706" strokeWidth="2" />
                    </svg>
                );
            case 'DECOR_WALL':
                return <div className="w-full h-full bg-slate-800 border-2 border-slate-600 shadow-sm"></div>;
            case 'DECOR_WINDOW':
                return (
                    <div className="w-full h-full bg-blue-100/50 border-4 border-slate-700 flex">
                        <div className="flex-1 border-r-2 border-slate-700"></div>
                        <div className="flex-1"></div>
                    </div>
                );
            default:
                return <div className="w-full h-full bg-slate-200 border border-slate-400 flex items-center justify-center text-[10px]">?</div>;
        }
    };

    return (
        <div
            onMouseDown={(e) => onClick(e, table, false)}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            style={{
                position: 'absolute',
                left: table.x,
                top: table.y,
                width: table.width,
                height: table.height,
                cursor: isEditing ? 'grab' : (table.isSeatable ? 'pointer' : 'default'),
                zIndex: isSelected ? 100 : (isHovered || table.highlight ? 50 : 10),
                transform: `rotate(${table.rotation || 0}deg)`,
                transition: isEditing ? 'none' : 'box-shadow 0.2s, transform 0.2s',
            }}
            className={`
                flex flex-col items-center justify-center select-none relative
                ${isSelected && isEditing ? 'ring-4 ring-indigo-500 ring-offset-4 shadow-2xl' : ''}
            `}
        >
            {!isEditing && table.assignedToName && (
                <div 
                    className="absolute -top-10 bg-white/95 backdrop-blur-sm px-3 py-1.5 rounded-full shadow-md text-xs font-bold text-slate-800 border border-slate-200 whitespace-nowrap z-50 flex items-center gap-1 animate-fade-in-up"
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    <User size={10} className="text-indigo-500" />
                    {table.assignedToName}
                </div>
            )}

            {/* Ready Notification Badge */}
            {!isEditing && isOrderReady && (
                <div 
                    className="absolute -top-3 -right-3 bg-emerald-500 text-white p-1.5 rounded-full shadow-lg z-[60] animate-bounce border-2 border-white"
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    <Check size={16} strokeWidth={4} />
                </div>
            )}

            {renderVectorContent()}

            {table.status !== 'Available' && table.isSeatable && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <svg className="w-1/2 h-1/2 transform -rotate-90" viewBox="0 0 100 100">
                        <circle cx="50" cy="50" r={radius} stroke="#e2e8f0" strokeWidth="8" fill="transparent" />
                        <circle cx="50" cy="50" r={radius} stroke={ringColor} strokeWidth="8" fill="transparent"
                            strokeDasharray={circumference} strokeDashoffset={strokeDashoffset} strokeLinecap="round"
                            className="transition-all duration-1000 ease-linear"
                        />
                    </svg>
                </div>
            )}

            {table.isSeatable && (
                <div className="absolute inset-0 flex flex-col items-center justify-center z-10 pointer-events-none">
                    <span className={`font-bold text-lg leading-none ${labelColor} drop-shadow-md`}>{table.name}</span>
                    {!isEditing && (
                        <span className="text-[9px] text-slate-600 font-medium bg-white/80 px-1 rounded flex items-center gap-0.5 mt-0.5 shadow-sm backdrop-blur-sm">
                            {table.status === 'Available' ? <><User size={8} />{table.seats}</> : <><Clock size={8} /> {elapsedMinutes}m</>}
                        </span>
                    )}
                </div>
            )}

            {isEditing && isSelected && (
                <div 
                    onMouseDown={(e) => { e.stopPropagation(); onClick(e, table, true); }}
                    className="absolute -bottom-3 -right-3 w-6 h-6 bg-white border-2 border-indigo-600 rounded-full cursor-nwse-resize z-50 flex items-center justify-center shadow-lg hover:scale-110 transition-transform"
                >
                    <MoveDiagonal size={12} className="text-indigo-600" />
                </div>
            )}

            {isHovered && !isEditing && table.isSeatable && table.status !== 'Available' && (
                <div 
                    className="absolute top-full mt-3 bg-slate-900/90 backdrop-blur text-white text-xs p-3 rounded-lg shadow-xl w-36 z-50 pointer-events-none animate-fade-in"
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    <p className="font-bold text-sm mb-1">{table.assignedToName || 'Guest'}</p>
                    <div className="space-y-1 opacity-90">
                        <p className="flex justify-between"><span>Size:</span> <span>{table.seats} ppl</span></p>
                        <p className="flex justify-between"><span>Seated:</span> <span>{table.timeSeated ? new Date(table.timeSeated).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--'}</span></p>
                    </div>
                    {elapsedMinutes > expected && (
                        <div className="bg-red-500/20 text-red-200 px-2 py-1 rounded mt-2 font-bold flex items-center gap-1 border border-red-500/30">
                            <AlertCircle size={10} /> Overdue
                        </div>
                    )}
                    {isOrderReady && (
                        <div className="bg-emerald-500/20 text-emerald-200 px-2 py-1 rounded mt-2 font-bold flex items-center gap-1 border border-emerald-500/30 animate-pulse">
                            <Check size={10} /> Order Ready
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

