export interface KitchenTicket {
    id: string;
    orderId: string;
    type: 'Dine-in' | 'Takeout' | 'Delivery';
    items: {
        name: string;
        qty: number;
        modifiers: string[];
        seatNumber?: number;
        guestName?: string; // Added for KDS display
        status?: 'Pending' | 'Prep' | 'Ready' | 'Served'; // Item-level status tracking
        printerLabels?: string[];
    }[];
    status: 'Pending' | 'Prep' | 'Ready' | 'Delivered'; // Overall ticket status
    timeIn: string; // ISO string for accurate time elapsed calculation
    table?: string;
    server?: string;
    serverEmployeeId?: string; // ID for notifications
    priority?: boolean; // For priority highlighting
}

const handleFire = () => {
    // 1. Identify unfired items
    const unfiredItems = orderItems.filter(i => !i.fired && !i.isVoided);

    if (unfiredItems.length > 0 && onFireToKitchen && activeTable) {
        // 2. Construct Kitchen Ticket
        const ticket: KitchenTicket = {
            id: `TKT-${Date.now()}`,
            orderId: activeTable.orderId || `ORD-${Date.now()}`, // Use generated 10-char ID
            type: 'Dine-in',
            status: 'Pending',
            timeIn: new Date().toISOString(),
            table: `Table ${activeTable.name}`,
            server: currentUser.name,
            serverEmployeeId: currentUser.id,
            items: unfiredItems.map(i => {
                const guest = guests.find(g => g.id === i.seatNumber);
                const guestName = i.seatNumber === 0 ? 'Shared' : (guest?.name || `Guest ${i.seatNumber}`);

                return {
                    name: i.name,
                    qty: i.quantity,
                    modifiers: i.modifiers || [],
                    seatNumber: i.seatNumber,
                    guestName: guestName,
                    printerLabels: i.printerLabels
                };
            })
        };

        // 3. Send to App state
        onFireToKitchen(ticket);
    }

    // 4. Mark local items as fired
    const updatedItems = orderItems.map(i => ({ ...i, fired: true }));
    updateOrderItems(updatedItems);
};

{/* Items */}
<div className="p-3 space-y-3 flex-1">
    {ticket.items.map((item, idx) => {
        // Logic: Does this item belong to the currently viewed station?
        const isRelevantToStation = activeStation === 'All Stations' || item.printerLabels?.includes(activeStation);

        return (
            <div key={idx} className={isRelevantToStation ? 'opacity-100' : 'opacity-20 grayscale'}>
                <div className="flex justify-between items-start">
                    <div className="flex gap-3">
                        <span className="font-bold text-lg">{item.qty}</span>
                        <div className="flex-1">
                            <p className="font-medium text-slate-200 leading-tight">{item.name}</p>
                            {item.guestName && (
                                <p className="text-[10px] text-indigo-300 font-bold uppercase tracking-wider mt-0.5">
                                    {item.guestName}
                                </p>
                            )}
                        </div>
                    </div>
                </div>
                {item.modifiers.length > 0 && (
                    <div className="ml-6 text-sm text-slate-400 mt-1 space-y-0.5">
                        {item.modifiers.map((mod, i) => (
                            <div key={i} className="text-orange-400/80">• {mod}</div>
                        ))}
                    </div>
                )}
            </div>
        );
    })}
</div>

