import React, { useState } from 'react';
import { DiningTable, InventoryItem, Category, DiningOrderItem, Employee, KitchenTicket, CartItem } from '../types';
import { ArrowLeft, Plus, Trash2, ChefHat, CheckCircle, SplitSquareHorizontal, CreditCard, Users, Search } from 'lucide-react';

interface TableServiceAppProps {
    tables: DiningTable[];
    inventory: InventoryItem[];
    categories: Category[];
    currentUser: Employee;
    activeTableOrders: Record<string, { items: DiningOrderItem[], guests: {id: number, name?: string}[] }>;
    onUpdateTableOrder: (tableId: string, data: { items: DiningOrderItem[], guests: {id: number, name?: string}[] } | undefined) => void;
    onUpdateTableStatus: (table: DiningTable) => void;
    onExit: () => void;
    onFireToKitchen?: (ticket: KitchenTicket) => void;
    onProcessSale: (cart: CartItem[], total: number, paymentMethod: string, existingOrderId?: string) => void;
    kitchenTickets?: KitchenTicket[];
}

const TableServiceApp: React.FC<TableServiceAppProps> = ({ 
    tables, inventory, categories, currentUser, activeTableOrders, 
    onUpdateTableOrder, onUpdateTableStatus, onExit, onFireToKitchen, onProcessSale 
}) => {
    const [selectedTableId, setSelectedTableId] = useState<string | null>(null);
    const [view, setView] = useState<'FLOOR' | 'ORDER'>('FLOOR');
    const [activeCategory, setActiveCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');

    const activeTable = tables.find(t => t.id === selectedTableId);
    const currentOrder = selectedTableId ? activeTableOrders[selectedTableId] : null;
    const orderItems = currentOrder?.items || [];
    const guests = currentOrder?.guests || [];

    const handleTableClick = (table: DiningTable) => {
        if (!table.isSeatable) return;
        setSelectedTableId(table.id);

        // If table is empty/available, initialize it
        if (table.status === 'Available') {
            onUpdateTableStatus({ 
                ...table, 
                status: 'Occupied', 
                assignedToName: currentUser.name, 
                employeeId: currentUser.id,
                timeSeated: new Date().toISOString()
            });
            onUpdateTableOrder(table.id, { items: [], guests: [{id: 1, name: 'Guest 1'}, {id: 2, name: 'Guest 2'}] });
        }
        setView('ORDER');
    };

    const handleAddItem = (item: InventoryItem) => {
        if (!selectedTableId) return;
        const newItem: DiningOrderItem = {
            id: `item-${Date.now()}`,
            name: item.name,
            quantity: 1,
            price: item.price,
            modifiers: [],
            seatNumber: 1, // Default to seat 1
            printerLabels: item.printerLabels,
            fired: false
        };
        const updatedItems = [...orderItems, newItem];
        onUpdateTableOrder(selectedTableId, { ...currentOrder!, items: updatedItems });
    };

    const handleFire = () => {
        const unfiredItems = orderItems.filter(i => !i.fired && !i.isVoided);

        if (unfiredItems.length > 0 && onFireToKitchen && activeTable) {
            const ticket: KitchenTicket = {
                id: `TKT-${Date.now()}`,
                orderId: activeTable.orderId || `ORD-${Date.now()}`,
                type: 'Dine-in',
                status: 'Pending',
                timeIn: new Date().toISOString(),
                table: `${activeTable.name}`,
                server: currentUser.name,
                serverEmployeeId: currentUser.id,
                items: unfiredItems.map(i => ({
                    name: i.name,
                    qty: i.quantity,
                    modifiers: i.modifiers || [],
                    seatNumber: i.seatNumber,
                    guestName: `Guest ${i.seatNumber}`,
                    printerLabels: i.printerLabels
                }))
            };
            onFireToKitchen(ticket);
        }

        const updatedItems = orderItems.map(i => ({ ...i, fired: true }));
        onUpdateTableOrder(selectedTableId!, { ...currentOrder!, items: updatedItems });
    };

    const handlePay = () => {
        if (!selectedTableId || !activeTable) return;
        // Convert DiningOrderItem to CartItem for payment processing
        const cartItems: CartItem[] = orderItems.map(i => ({
            id: i.id || '',
            name: i.name,
            price: i.price,
            cost: 0,
            category: 'Dining',
            modifierGroups: [],
            inStock: true,
            showOnPos: true,
            showOnline: false,
            quantity: i.quantity,
            modifiers: i.modifiers || [],
            color: 'bg-white',
            seatId: i.seatNumber,
            isFired: i.fired,
            isVoided: i.isVoided
        }));

        const total = cartItems.reduce((acc, i) => acc + (i.price * i.quantity), 0);
        onProcessSale(cartItems, total, 'Card', activeTable.orderId);

        // Clear table
        onUpdateTableStatus({ ...activeTable, status: 'Available', assignedToName: undefined, timeSeated: undefined });
        onUpdateTableOrder(selectedTableId, undefined);
        setView('FLOOR');
        setSelectedTableId(null);
    };

    if (view === 'FLOOR') {
        return (
            <div className="h-full bg-slate-100 p-6 overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-2xl font-bold text-slate-800">Dining Room</h2>
                    <button onClick={onExit} className="px-4 py-2 bg-slate-200 rounded-lg font-bold text-slate-700">Exit Dining</button>
                </div>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                    {tables.filter(t => t.isSeatable).map(table => (
                        <button 
                            key={table.id}
                            onClick={() => handleTableClick(table)}
                            className={`p-6 rounded-xl border-2 flex flex-col items-center justify-center gap-2 aspect-square transition-all
                                ${table.status === 'Available' ? 'bg-white border-slate-200 hover:border-indigo-500' : 
                                  table.status === 'Occupied' ? 'bg-indigo-50 border-indigo-500 shadow-md' : 'bg-slate-100 border-slate-300'}`}
                        >
                            <span className="text-2xl font-black text-slate-800">{table.name}</span>
                            <span className={`text-xs font-bold uppercase px-2 py-1 rounded ${table.status === 'Occupied' ? 'bg-indigo-200 text-indigo-800' : 'bg-slate-200 text-slate-600'}`}>
                                {table.status}
                            </span>
                            {table.assignedToName && <span className="text-xs text-slate-500">{table.assignedToName}</span>}
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col bg-white">
            {/* Header */}
            <div className="h-16 border-b border-slate-200 flex items-center justify-between px-4 bg-slate-50">
                <div className="flex items-center gap-4">
                    <button onClick={() => setView('FLOOR')} className="p-2 hover:bg-slate-200 rounded-full"><ArrowLeft /></button>
                    <h2 className="text-xl font-bold">Table {activeTable?.name}</h2>
                    <div className="flex items-center gap-2 text-sm text-slate-500">
                        <Users size={16} /> {guests.length} Guests
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={handleFire} className="px-4 py-2 bg-orange-100 text-orange-700 rounded-lg font-bold flex items-center gap-2 hover:bg-orange-200">
                        <ChefHat size={18} /> Fire Order
                    </button>
                    <button onClick={handlePay} className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-bold flex items-center gap-2 hover:bg-emerald-700">
                        <CreditCard size={18} /> Pay
                    </button>
                </div>
            </div>

            <div className="flex-1 flex overflow-hidden">
                {/* Menu */}
                <div className="flex-1 bg-slate-50 p-4 flex flex-col">
                    <div className="flex gap-2 overflow-x-auto pb-4">
                        {['All', ...categories.map(c => c.name)].map(cat => (
                            <button 
                                key={cat} 
                                onClick={() => setActiveCategory(cat)}
                                className={`px-4 py-2 rounded-full text-sm font-bold whitespace-nowrap ${activeCategory === cat ? 'bg-indigo-600 text-white' : 'bg-white text-slate-600 border border-slate-200'}`}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>
                    <div className="flex-1 overflow-y-auto grid grid-cols-3 gap-4 content-start">
                        {inventory.filter(i => activeCategory === 'All' || i.category === activeCategory).map(item => (
                            <button 
                                key={item.id} 
                                onClick={() => handleAddItem(item)}
                                className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all text-left flex flex-col justify-between h-32"
                            >
                                <span className="font-bold text-slate-800">{item.name}</span>
                                <span className="text-sm text-slate-500">${item.price.toFixed(2)}</span>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Ticket */}
                <div className="w-96 bg-white border-l border-slate-200 flex flex-col">
                    <div className="flex-1 overflow-y-auto p-4 space-y-4">
                        {guests.map(guest => (
                            <div key={guest.id} className="space-y-2">
                                <div className="text-sm font-bold text-slate-400 uppercase border-b border-slate-100 pb-1">
                                    Seat {guest.id}
                                </div>
                                {orderItems.filter(i => i.seatNumber === guest.id).map((item, idx) => (
                                    <div key={idx} className="flex justify-between items-start group">
                                        <div>
                                            <p className={`font-medium ${item.fired ? 'text-slate-800' : 'text-indigo-600'}`}>{item.name}</p>
                                            {item.fired && <span className="text-[10px] text-emerald-600 font-bold bg-emerald-50 px-1 rounded">SENT</span>}
                                        </div>
                                        <p className="font-mono text-sm">${item.price.toFixed(2)}</p>
                                    </div>
                                ))}
                            </div>
                        ))}
                    </div>
                    <div className="p-4 border-t border-slate-200 bg-slate-50">
                        <div className="flex justify-between text-lg font-bold">
                            <span>Total</span>
                            <span>${orderItems.reduce((acc, i) => acc + i.price, 0).toFixed(2)}</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TableServiceApp;

