interface InteractiveTableProps {
    table: DiningTable;
    onClick: (e: React.MouseEvent, table: DiningTable, isResizeHandle: boolean) => void;
    isEditing?: boolean;
    isSelected?: boolean;
    kitchenStatus?: KitchenStatus | null;
}

const InteractiveTable: React.FC<InteractiveTableProps> = ({ table, onClick, isEditing, isSelected, kitchenStatus }) => {
    const [elapsedMinutes, setElapsedMinutes] = useState(0);
    const [isHovered, setIsHovered] = useState(false);

    useEffect(() => {
        if (table.status !== 'Available' && table.timeSeated) {
            const calculateTime = () => {
                const seatedTime = new Date(table.timeSeated!).getTime();
                const now = new Date().getTime();
                const diffMins = Math.floor((now - seatedTime) / 60000);
                setElapsedMinutes(Math.max(0, diffMins));
            };

            calculateTime();
            const interval = setInterval(calculateTime, 60000);
            return () => clearInterval(interval);
        } else {
            setElapsedMinutes(0);
        }
    }, [table.status, table.timeSeated]);

    const expected = table.expectedDuration || 60;
    const progress = Math.min(100, (elapsedMinutes / expected) * 100);
    const radius = 24; 
    const circumference = 2 * Math.PI * radius;
    const strokeDashoffset = circumference - (progress / 100) * circumference;

    // --- VISUAL LOGIC ---
    let tableFill = 'fill-amber-100'; // Wood-like base
    let tableStroke = 'stroke-amber-800';
    let tableShadow = 'drop-shadow-md';
    let chairFill = 'fill-slate-700';
    let chairStroke = 'stroke-slate-900';
    let ringColor = '#cbd5e1'; 
    let labelColor = 'text-slate-700';

    // Status Overrides
    if (table.isSeatable) {
        if (table.highlight) {
            tableFill = 'fill-yellow-100';
            tableStroke = 'stroke-yellow-600';
        } else if (table.status === 'Available') {
            tableFill = 'fill-white';
            tableStroke = 'stroke-slate-300';
            chairFill = 'fill-slate-600';
            chairStroke = 'stroke-slate-700';
            labelColor = 'text-slate-500';
        } else if (table.status === 'Occupied') {
            tableFill = 'fill-blue-50';
            tableStroke = 'stroke-blue-400';
            chairFill = 'fill-blue-600';
            chairStroke = 'stroke-blue-800';
            labelColor = 'text-blue-800';
            ringColor = '#3b82f6';
        } else if (table.status === 'Overdue' || (elapsedMinutes > expected)) {
            tableFill = 'fill-red-50';
            tableStroke = 'stroke-red-400';
            chairFill = 'fill-red-600';
            chairStroke = 'stroke-red-800';
            labelColor = 'text-red-800';
            ringColor = '#ef4444';
        } else if (table.status === 'Dirty') {
            tableFill = 'fill-orange-50';
            tableStroke = 'stroke-orange-400';
            labelColor = 'text-orange-800';
        } else if (table.status === 'Payment') {
            tableFill = 'fill-emerald-50';
            tableStroke = 'stroke-emerald-400';
            labelColor = 'text-emerald-800';
        }
    }

    const renderChairs = () => {
        if (!table.isSeatable || table.seats === 0) return null;

        const chairs = [];
        const seatW = 28; 
        const seatH = 24; 
        const backD = 6;  

        if (table.type === 'TABLE_ROUND') {
            const r = 48; 
            const offset = 18; 

            for (let i = 0; i < table.seats; i++) {
                const angle = (i / table.seats) * 2 * Math.PI;
                const degrees = (angle * 180) / Math.PI;
                const cx = 50 + (r + offset) * Math.cos(angle); 
                const cy = 50 + (r + offset) * Math.sin(angle);

                chairs.push(
                    <g key={i} transform={`translate(${cx}, ${cy}) rotate(${degrees + 90})`}>
                        <rect x={-seatW/2 + 3} y={-seatH/2 + 3} width={seatW} height={seatH} rx="6" fill="black" opacity="0.15" />
                        <rect x={-seatW/2} y={-seatH/2} width={seatW} height={seatH} rx="6" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                        <path d={`M ${-seatW/2} ${seatH/2} Q 0 ${seatH/2 + 8} ${seatW/2} ${seatH/2}`} fill="none" stroke={chairStroke.replace('stroke-', '#')} strokeWidth="2.5" />
                        <rect x={-seatW/2} y={seatH/2 + 2} width={seatW} height={backD} rx="3" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                    </g>
                );
            }
        } else {
            const perSide = Math.ceil(table.seats / 2);
            for(let i=0; i<table.seats; i++) {
                const side = i % 2; 
                const idxInSide = Math.floor(i / 2);
                const availableSpace = 100;
                const step = availableSpace / perSide;
                const x = (step * idxInSide) + (step / 2);
                const y = side === 0 ? -20 : 120; 
                const rot = side === 0 ? 180 : 0;

                chairs.push(
                    <g key={i} transform={`translate(${x}, ${y}) rotate(${rot})`}>
                        <rect x={-seatW/2 + 3} y={-seatH + 3} width={seatW} height={seatH} rx="6" fill="black" opacity="0.15" />
                        <rect x={-seatW/2} y={-seatH} width={seatW} height={seatH} rx="6" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                        <rect x={-seatW/2} y={2} width={seatW} height={backD} rx="3" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                        <path d={`M ${-seatW/2} ${-seatH/2} L ${-seatW/2 - 4} ${-seatH/2} L ${-seatW/2 - 4} 4`} fill="none" stroke={chairStroke.replace('stroke-', '#')} strokeWidth="2" opacity="0.4"/>
                        <path d={`M ${seatW/2} ${-seatH/2} L ${seatW/2 + 4} ${-seatH/2} L ${seatW/2 + 4} 4`} fill="none" stroke={chairStroke.replace('stroke-', '#')} strokeWidth="2" opacity="0.4"/>
                    </g>
                );
            }
        }
        return chairs;
    };

    const renderVectorContent = () => {
        switch(table.type) {
            case 'TABLE_ROUND':
                return (
                    <svg viewBox="-50 -50 200 200" className="w-full h-full overflow-visible pointer-events-none">
                        {renderChairs()}
                        <circle cx="53" cy="53" r="48" fill="black" opacity="0.15" />
                        <circle cx="50" cy="50" r="48" className={`${tableFill} ${tableStroke} ${tableShadow}`} strokeWidth="2" />
                        <path d="M 20 30 Q 50 60 80 30" stroke="black" strokeWidth="0.5" opacity="0.05" fill="none"/>
                        <path d="M 15 50 Q 50 80 85 50" stroke="black" strokeWidth="0.5" opacity="0.05" fill="none"/>
                        <path d="M 25 70 Q 50 40 75 70" stroke="black" strokeWidth="0.5" opacity="0.05" fill="none"/>
                        <circle cx="50" cy="50" r="8" fill="black" opacity="0.05" />
                    </svg>
                );
            case 'TABLE_SQUARE':
            case 'TABLE_RECT':
                return (
                    <svg viewBox="-40 -40 180 180" className="w-full h-full overflow-visible pointer-events-none">
                        {renderChairs()}
                        <rect x="5" y="5" width="96" height="96" rx="6" fill="black" opacity="0.15" />
                        <rect x="2" y="2" width="96" height="96" rx="6" className={`${tableFill} ${tableStroke} ${tableShadow}`} strokeWidth="2" />
                        <line x1="10" y1="20" x2="90" y2="20" stroke="black" strokeWidth="0.5" opacity="0.05" />
                        <line x1="5" y1="50" x2="95" y2="50" stroke="black" strokeWidth="0.5" opacity="0.05" />
                        <line x1="10" y1="80" x2="90" y2="80" stroke="black" strokeWidth="0.5" opacity="0.05" />
                        <rect x="40" y="2" width="20" height="96" fill="black" opacity="0.03" />
                    </svg>
                );
            case 'BOOTH_SINGLE':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none drop-shadow-md">
                        <path d="M5 20 Q5 5 20 5 L80 5 Q95 5 95 20 L95 90 Q95 95 90 95 L10 95 Q5 95 5 90 Z" fill="#64748b" stroke="#334155" strokeWidth="2" />
                        <path d="M15 15 L15 90" stroke="#475569" strokeWidth="1" />
                        <path d="M30 10 L30 90" stroke="#475569" strokeWidth="1" />
                        <path d="M50 10 L50 90" stroke="#475569" strokeWidth="1" />
                        <path d="M70 10 L70 90" stroke="#475569" strokeWidth="1" />
                        <path d="M85 15 L85 90" stroke="#475569" strokeWidth="1" />
                        <path d="M10 25 L90 25 L90 45 L10 45 Z" fill="#94a3b8" stroke="#475569" strokeWidth="1" />
                        <rect x="15" y="45" width="70" height="40" rx="4" className={`${tableFill} ${tableStroke}`} strokeWidth="2" />
                    </svg>
                );
            case 'BOOTH_DOUBLE':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none drop-shadow-md">
                        <rect x="15" y="35" width="70" height="30" rx="4" className={`${tableFill} ${tableStroke}`} strokeWidth="2" />
                        <rect x="5" y="5" width="90" height="25" rx="6" fill="#64748b" stroke="#334155" strokeWidth="2" />
                        <rect x="10" y="22" width="80" height="8" rx="4" fill="#94a3b8" />
                        <line x1="25" y1="5" x2="25" y2="22" stroke="#475569" strokeWidth="1" />
                        <line x1="50" y1="5" x2="50" y2="22" stroke="#475569" strokeWidth="1" />
                        <line x1="75" y1="5" x2="75" y2="22" stroke="#475569" strokeWidth="1" />
                        <rect x="5" y="70" width="90" height="25" rx="6" fill="#64748b" stroke="#334155" strokeWidth="2" />
                        <rect x="10" y="70" width="80" height="8" rx="4" fill="#94a3b8" />
                        <line x1="25" y1="78" x2="25" y2="95" stroke="#475569" strokeWidth="1" />
                        <line x1="50" y1="78" x2="50" y2="95" stroke="#475569" strokeWidth="1" />
                        <line x1="75" y1="78" x2="75" y2="95" stroke="#475569" strokeWidth="1" />
                    </svg>
                );
            case 'COUCH_STRAIGHT':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none drop-shadow-md">
                        <rect x="5" y="20" width="90" height="60" rx="12" fill="#e2e8f0" stroke="#94a3b8" strokeWidth="2" />
                        <rect x="10" y="15" width="80" height="15" rx="6" fill="#cbd5e1" stroke="#94a3b8" strokeWidth="1" />
                        <line x1="50" y1="35" x2="50" y2="80" stroke="#cbd5e1" strokeWidth="1" />
                        <rect x="5" y="35" width="12" height="45" rx="6" fill="#cbd5e1" />
                        <rect x="83" y="35" width="12" height="45" rx="6" fill="#cbd5e1" />
                        {table.seats > 0 && <rect x="30" y="90" width="40" height="15" rx="4" className={`${tableFill} ${tableStroke}`} />}
                    </svg>
                );
            case 'PLANT_MONSTERA':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-lg pointer-events-none">
                        <circle cx="50" cy="50" r="15" fill="#3f2e18" /> 
                        <circle cx="50" cy="50" r="18" stroke="#78350f" strokeWidth="4" fill="none" /> 
                        {[0, 60, 120, 180, 240, 300].map(deg => (
                            <g key={deg} transform={`rotate(${deg} 50 50)`}>
                                <path d="M50 50 Q30 20 50 2 Q70 20 50 50" fill="#15803d" stroke="#14532d" strokeWidth="1" />
                                <path d="M50 50 Q35 25 50 10" fill="none" stroke="#22c55e" strokeWidth="1" opacity="0.4" />
                            </g>
                        ))}
                    </svg>
                );
            case 'PLANT_BANANA':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-lg pointer-events-none">
                        <circle cx="50" cy="50" r="12" fill="#3f2e18" />
                        <circle cx="50" cy="50" r="14" stroke="#a8a29e" strokeWidth="3" fill="none" />
                        {[0, 120, 240].map(deg => (
                            <g key={deg} transform={`rotate(${deg} 50 50)`}>
                                <path d="M50 50 C20 50 10 10 50 0 C90 10 80 50 50 50" fill="#4d7c0f" stroke="#365314" strokeWidth="1" />
                                <line x1="50" y1="50" x2="50" y2="5" stroke="#65a30d" strokeWidth="1" />
                            </g>
                        ))}
                    </svg>
                );
            case 'DECOR_BILLIARDS':
                return (
                    <svg viewBox="0 0 200 100" className="w-full h-full drop-shadow-xl pointer-events-none">
                        <defs>
                            <linearGradient id="feltGrad" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="0%" stopColor="#166534" />
                                <stop offset="100%" stopColor="#14532d" />
                            </linearGradient>
                        </defs>
                        <rect x="5" y="5" width="190" height="90" rx="8" fill="#78350f" stroke="#451a03" strokeWidth="4" />
                        <rect x="15" y="15" width="170" height="70" rx="2" fill="url(#feltGrad)" />
                        {[ [15,15], [100,15], [185,15], [15,85], [100,85], [185,85] ].map((pos, i) => (
                            <circle key={i} cx={pos[0]} cy={pos[1]} r="5" fill="#0f172a" />
                        ))}
                        <line x1="120" y1="30" x2="170" y2="80" stroke="#fcd34d" strokeWidth="2" strokeLinecap="round" />
                        <line x1="165" y1="75" x2="170" y2="80" stroke="#1e293b" strokeWidth="2" strokeLinecap="round" />
                        <circle cx="60" cy="50" r="3" fill="white" />
                        <g transform="translate(130, 50)">
                            <circle cx="0" cy="0" r="3" fill="#ef4444" />
                            <circle cx="5" cy="-3" r="3" fill="#eab308" />
                            <circle cx="5" cy="3" r="3" fill="#3b82f6" />
                        </g>
                    </svg>
                );
            case 'DECOR_PIANO':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-2xl pointer-events-none">
                        <path d="M10 10 L60 10 Q95 10 95 40 L95 90 L10 90 Z" fill="#020617" stroke="#334155" strokeWidth="2" />
                        <path d="M10 10 L60 10 Q90 10 90 40 L90 85 L15 85 Z" fill="none" stroke="white" strokeWidth="0.5" opacity="0.2" />
                        <rect x="8" y="8" width="25" height="84" fill="#1e293b" />
                        <rect x="10" y="10" width="20" height="80" fill="#fff" stroke="#94a3b8" />
                        {[15, 20, 27, 32, 37, 44, 49, 56, 61, 66, 73, 78].map(y => <rect key={y} x="10" y={y+5} width="12" height="3" fill="#0f172a" />)}
                        <rect x="-15" y="30" width="15" height="40" rx="2" fill="#3f2e18" stroke="#271c0e" strokeWidth="2" />
                    </svg>
                );
            case 'FURNITURE_BAR':
                return (
                    <svg viewBox="0 0 200 60" className="w-full h-full pointer-events-none drop-shadow-md">
                        <rect x="0" y="0" width="200" height="60" rx="4" fill="#78350f" stroke="#451a03" strokeWidth="2" />
                        <line x1="10" y1="10" x2="190" y2="10" stroke="#92400e" strokeWidth="1" opacity="0.3" />
                        <line x1="20" y1="30" x2="180" y2="30" stroke="#92400e" strokeWidth="1" opacity="0.3" />
                        <line x1="10" y1="50" x2="190" y2="50" stroke="#92400e" strokeWidth="1" opacity="0.3" />
                        <rect x="0" y="50" width="200" height="10" rx="2" fill="#451a03" />
                        <circle cx="30" cy="75" r="8" fill="#1e293b" stroke="#475569" strokeWidth="2" />
                        <circle cx="70" cy="75" r="8" fill="#1e293b" stroke="#475569" strokeWidth="2" />
                        <circle cx="110" cy="75" r="8" fill="#1e293b" stroke="#475569" strokeWidth="2" />
                        <circle cx="150" cy="75" r="8" fill="#1e293b" stroke="#475569" strokeWidth="2" />
                    </svg>
                );
            case 'DECOR_RUG_RECT':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full opacity-90 pointer-events-none">
                        <rect x="2" y="2" width="96" height="96" rx="2" fill="#78350f" stroke="#92400e" strokeWidth="1" />
                        <rect x="10" y="10" width="80" height="80" fill="#92400e" />
                        <pattern id="pattern-rug" x="0" y="0" width="20" height="20" patternUnits="userSpaceOnUse">
                            <rect x="0" y="0" width="10" height="10" fill="#b45309" />
                            <rect x="10" y="10" width="10" height="10" fill="#b45309" />
                        </pattern>
                        <rect x="15" y="15" width="70" height="70" fill="url(#pattern-rug)" opacity="0.5" />
                    </svg>
                );
            case 'DECOR_RUG_ROUND':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full opacity-90 pointer-events-none">
                        <circle cx="50" cy="50" r="48" fill="#1e40af" stroke="#1e3a8a" strokeWidth="2" />
                        <circle cx="50" cy="50" r="40" fill="none" stroke="#60a5fa" strokeWidth="2" strokeDasharray="4 2" />
                        <circle cx="50" cy="50" r="30" fill="#2563eb" opacity="0.5" />
                        <circle cx="50" cy="50" r="10" fill="#93c5fd" />
                    </svg>
                );
            case 'DECOR_WALL':
                return <div className="w-full h-full bg-slate-800 border-b-4 border-slate-900 shadow-md"></div>;
            default:
                return <div className="w-full h-full bg-slate-200 border border-slate-400 flex items-center justify-center text-[10px]">?</div>;
        }
    };

    return (
        <div
            onMouseDown={(e) => onClick(e, table, false)}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            style={{
                position: 'absolute',
                left: table.x,
                top: table.y,
                width: table.width,
                height: table.height,
                cursor: isEditing ? 'grab' : (table.isSeatable ? 'pointer' : 'default'),
                zIndex: isSelected ? 100 : (isHovered || table.highlight ? 50 : 10),
                transform: `rotate(${table.rotation || 0}deg)`,
                transition: isEditing ? 'none' : 'box-shadow 0.2s, transform 0.2s',
            }}
            className={`
                flex flex-col items-center justify-center select-none relative group
                ${isSelected && isEditing ? 'ring-2 ring-indigo-500 ring-offset-2 shadow-2xl' : ''}
            `}
        >
            {!isEditing && table.assignedToName && (
                <div 
                    className="absolute -top-10 bg-white/95 backdrop-blur-sm px-3 py-1.5 rounded-full shadow-lg text-xs font-bold text-slate-800 border border-slate-200 whitespace-nowrap z-50 flex items-center gap-1 animate-fade-in-up"
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    <User size={10} className="text-indigo-500" />
                    {table.assignedToName}
                </div>
            )}

            {/* Kitchen Status Badges */}
            {!isEditing && kitchenStatus && (
                <div 
                    className={`absolute -top-4 right-0 z-[60] px-2 py-1 rounded-full shadow-lg border-2 border-white flex items-center gap-1 font-bold text-[9px] uppercase tracking-wide whitespace-nowrap animate-bounce-short
                    ${kitchenStatus.status === 'Pending' ? 'bg-amber-100 text-amber-700' :
                      kitchenStatus.status === 'Prep' ? 'bg-indigo-100 text-indigo-700' :
                      kitchenStatus.status === 'Ready' ? 'bg-emerald-500 text-white' : 'hidden'}`}
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    {kitchenStatus.status === 'Pending' && (
                        <>
                            <Hourglass size={10} /> 
                            Queue #{kitchenStatus.queuePosition}
                        </>
                    )}
                    {kitchenStatus.status === 'Prep' && (
                        <>
                            <ChefHat size={10} /> 
                            Cooking
                        </>
                    )}
                    {kitchenStatus.status === 'Ready' && (
                        <>
                            <Check size={12} strokeWidth={4} /> 
                            Ready
                        </>
                    )}
                </div>
            )}

            {renderVectorContent()}

            {/* Timer Ring */}
            {table.status !== 'Available' && table.isSeatable && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <svg className="w-2/3 h-2/3 transform -rotate-90" viewBox="0 0 100 100">
                        <circle cx="50" cy="50" r={radius} stroke="#e2e8f0" strokeWidth="6" fill="transparent" opacity="0.8" />
                        <circle cx="50" cy="50" r={radius} stroke={ringColor} strokeWidth="6" fill="transparent"
                            strokeDasharray={circumference} strokeDashoffset={strokeDashoffset} strokeLinecap="round"
                            className="transition-all duration-1000 ease-linear drop-shadow-sm"
                        />
                    </svg>
                </div>
            )}

            {/* Labels */}
            {table.isSeatable && (
                <div className="absolute inset-0 flex flex-col items-center justify-center z-10 pointer-events-none">
                    <span className={`font-black text-lg leading-none ${labelColor} drop-shadow-sm`} style={{ transform: `rotate(-${table.rotation || 0}deg)` }}>
                        {table.name}
                    </span>
                    {!isEditing && (
                        <div style={{ transform: `rotate(-${table.rotation || 0}deg)` }} className="mt-1">
                            <span className="text-[9px] text-slate-600 font-bold bg-white/90 px-1.5 py-0.5 rounded-full flex items-center gap-0.5 shadow-sm backdrop-blur-sm border border-slate-100">
                                {table.status === 'Available' ? <><User size={8} />{table.seats}</> : <><Clock size={8} /> {elapsedMinutes}m</>}
                            </span>
                        </div>
                    )}
                </div>
            )}

            {/* Editing Handles */}
            {isEditing && isSelected && (
                <>
                    <div 
                        onMouseDown={(e) => { e.stopPropagation(); onClick(e, table, true); }}
                        className="absolute -bottom-3 -right-3 w-6 h-6 bg-white border-2 border-indigo-600 rounded-full cursor-nwse-resize z-50 flex items-center justify-center shadow-lg hover:scale-110 transition-transform"
                    >
                        <MoveDiagonal size={12} className="text-indigo-600" />
                    </div>
                </>
            )}

            {/* Hover Tooltip */}
            {isHovered && !isEditing && table.isSeatable && table.status !== 'Available' && (
                <div 
                    className="absolute top-full mt-4 bg-slate-900/95 backdrop-blur text-white text-xs p-3 rounded-xl shadow-xl w-40 z-50 pointer-events-none animate-fade-in border border-white/10"
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    <p className="font-bold text-sm mb-1 text-white">{table.assignedToName || 'Guest'}</p>
                    <div className="space-y-1.5 opacity-90">
                        <p className="flex justify-between border-b border-white/10 pb-1"><span>Size:</span> <span className="font-mono">{table.seats} ppl</span></p>
                        <p className="flex justify-between"><span>Seated:</span> <span className="font-mono">{table.timeSeated ? new Date(table.timeSeated).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--'}</span></p>
                    </div>
                    {elapsedMinutes > expected && (
                        <div className="bg-red-500/20 text-red-200 px-2 py-1 rounded-lg mt-2 font-bold flex items-center gap-2 border border-red-500/30 text-[10px] uppercase tracking-wide">
                            <AlertCircle size={12} /> Overdue
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default InteractiveTable;

import React, { useState, useEffect, useRef } from 'react';
import { DiningTable, InventoryItem, Category, Employee, DiningOrderItem, UserRole, DiscountCode, CartItem, KitchenTicket } from '../types';
import { X, LogOut, Plus, Minus, User, Search, Lock, Flame, SplitSquareHorizontal, DollarSign, Tag, CreditCard, CheckCircle, Percent, ZoomIn, ZoomOut, Maximize, Hand, ArrowLeft, PanelLeft, PanelTop } from 'lucide-react';
import { MOCK_CUSTOMERS } from '../constants';
import InteractiveTable from './InteractiveTable';

interface TableServiceAppProps {
    tables: DiningTable[];
    inventory: InventoryItem[];
    categories: Category[];
    currentUser: Employee;
    onExit: () => void;
    onFireToKitchen?: (ticket: KitchenTicket) => void;
    activeTableOrders: Record<string, { items: DiningOrderItem[], guests: {id: number, name?: string}[] }>;
    onUpdateTableOrder: (tableId: string, data: { items: DiningOrderItem[], guests: {id: number, name?: string}[] } | undefined) => void;
    onUpdateTableStatus: (table: DiningTable) => void;
    onProcessSale?: (cart: CartItem[], total: number, paymentMethod: string, existingOrderId?: string) => void;
    kitchenTickets?: KitchenTicket[];
}

// Reuse similar modal logic for Table Service (inline for isolation as requested)
const TableItemModal = ({ item, onClose, onSave, seatId }: { item: DiningOrderItem, onClose: () => void, onSave: (item: DiningOrderItem) => void, seatId: number }) => {
    const [localItem, setLocalItem] = useState({...item});
    const modifiers = ['Extra Cheese', 'No Onions', 'Gluten Free', 'Spicy', 'Sauce on Side', 'Well Done', 'Medium Rare'];

    const toggleModifier = (mod: string) => {
        const mods = localItem.modifiers || [];
        setLocalItem({...localItem, modifiers: mods.includes(mod) ? mods.filter(m => m !== mod) : [...mods, mod]});
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50">
                    <div>
                        <h3 className="text-xl font-black text-slate-800">{localItem.name}</h3>
                        <p className="text-sm text-slate-500 font-bold">${localItem.price.toFixed(2)}</p>
                    </div>
                    <button onClick={onClose}><X size={24} className="text-slate-400" /></button>
                </div>
                <div className="flex-1 overflow-y-auto p-6 space-y-6">
                    <div className="flex gap-4">
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Quantity</label>
                            <div className="flex items-center gap-4 bg-slate-100 rounded-xl p-2 w-fit">
                                <button onClick={() => setLocalItem({...localItem, quantity: Math.max(1, localItem.quantity - 1)})} className="w-8 h-8 bg-white rounded shadow-sm font-bold">-</button>
                                <span className="font-bold text-xl">{localItem.quantity}</span>
                                <button onClick={() => setLocalItem({...localItem, quantity: localItem.quantity + 1})} className="w-8 h-8 bg-white rounded shadow-sm font-bold">+</button>
                            </div>
                        </div>
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Seat</label>
                            <div className="flex gap-2 flex-wrap">
                                {[0, 1, 2, 3, 4].map(s => (
                                    <button 
                                        key={s} 
                                        onClick={() => setLocalItem({...localItem, seatNumber: s})}
                                        className={`h-10 w-10 rounded-lg font-bold border-2 transition-all ${localItem.seatNumber === s ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-slate-200 text-slate-400'}`}
                                    >
                                        {s === 0 ? 'S' : s}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Modifiers</label>
                        <div className="flex flex-wrap gap-2">
                            {modifiers.map(mod => (
                                <button
                                    key={mod}
                                    onClick={() => toggleModifier(mod)}
                                    className={`px-3 py-2 rounded-lg text-xs font-bold border transition-all ${localItem.modifiers?.includes(mod) ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-600'}`}
                                >
                                    {mod}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Course</label>
                        <div className="flex gap-2">
                            {['Appetizer', 'Entree', 'Dessert'].map(c => (
                                <button 
                                    key={c}
                                    onClick={() => setLocalItem({...localItem, course: c as any})}
                                    className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${localItem.course === c ? 'bg-indigo-50 border-indigo-600 text-indigo-700' : 'bg-white border-slate-200 text-slate-500'}`}
                                >
                                    {c}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
                <div className="p-4 border-t border-slate-200 bg-slate-50 flex gap-3">
                    <button onClick={() => { onSave({...localItem, isVoided: !localItem.isVoided}); onClose(); }} className={`flex-1 py-3 font-bold rounded-xl border-2 ${localItem.isVoided ? 'bg-slate-200 text-slate-500' : 'border-red-100 text-red-600 bg-red-50'}`}>
                        {localItem.isVoided ? 'UN-VOID' : 'VOID'}
                    </button>
                    <button onClick={() => { onSave(localItem); onClose(); }} className="flex-[2] py-3 bg-indigo-600 text-white font-bold rounded-xl shadow-lg">
                        SAVE
                    </button>
                </div>
            </div>
        </div>
    );
};

const TableServiceApp: React.FC<TableServiceAppProps> = ({ tables, inventory, categories, currentUser, onExit, onFireToKitchen, activeTableOrders, onUpdateTableOrder, onUpdateTableStatus, onProcessSale, kitchenTickets }) => {
    // Removed localTables state to rely on props for source of truth
    const [activeTableId, setActiveTableId] = useState<string | null>(null);
    const [activeSeat, setActiveSeat] = useState<number>(0); 
    const [searchTerm, setSearchTerm] = useState('');
    const [activeCustomer, setActiveCustomer] = useState<string | null>(null);

    // Category State
    const [activeCategory, setActiveCategory] = useState('All');
    const [categoryLayout, setCategoryLayout] = useState<'TOP' | 'SIDE'>('SIDE');

    // Derived state for current table
    const currentOrderData = activeTableId ? activeTableOrders[activeTableId] : undefined;
    const orderItems = currentOrderData?.items || [];
    const guests = currentOrderData?.guests || [{ id: 1 }];

    // Floor View State
    const [activeSection, setActiveSection] = useState('Dining Room');
    const [scale, setScale] = useState(1);
    const [pan, setPan] = useState({ x: 0, y: 0 });
    const [isPanning, setIsPanning] = useState(false);
    const [panStart, setPanStart] = useState({ x: 0, y: 0 });
    const canvasRef = useRef<HTMLDivElement>(null);

    // Modals
    const [editingItem, setEditingItem] = useState<DiningOrderItem | null>(null);
    const [showCustomerSearch, setShowCustomerSearch] = useState(false);
    const [showPayment, setShowPayment] = useState(false);

    const activeTable = tables.find(t => t.id === activeTableId);

    // Helpers to update persistent state
    const updateOrderItems = (newItems: DiningOrderItem[]) => {
        if (activeTableId) {
            onUpdateTableOrder(activeTableId, { items: newItems, guests });
        }
    };

    const updateGuests = (newGuests: {id: number, name?: string}[]) => {
        if (activeTableId) {
            onUpdateTableOrder(activeTableId, { items: orderItems, guests: newGuests });
        }
    };

    const generateUniqueOrderId = () => {
        const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
        let result = '';
        for (let i = 0; i < 10; i++) {
            result += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return result;
    };

    const handleTableClick = (e: React.MouseEvent, table: DiningTable) => {
        if (!table.isSeatable) return;

        const storedData = activeTableOrders[table.id];

        if (table.status === 'Available' && !storedData) {
            // New Order: Create Table State + ID
            const orderId = generateUniqueOrderId();
            const updated = { 
                ...table, 
                status: 'Occupied' as const, 
                employeeId: currentUser.id, 
                assignedToName: currentUser.name, 
                timeSeated: new Date().toISOString(),
                orderId: orderId 
            };

            // Sync status back to App
            onUpdateTableStatus(updated);

            // Init empty order state in parent
            onUpdateTableOrder(table.id, { items: [], guests: [{ id: 1 }] });
        }

        setActiveTableId(table.id);
    };

    // Canvas Interaction Handlers
    const handleMouseDown = (e: React.MouseEvent) => {
        setIsPanning(true);
        setPanStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (isPanning) {
            setPan({ x: e.clientX - panStart.x, y: e.clientY - panStart.y });
        }
    };

    const handleMouseUp = () => {
        setIsPanning(false);
    };

    const addToOrder = (item: InventoryItem) => {
        const newItem: DiningOrderItem = {
            ...item,
            cartId: `din-${Date.now()}-${Math.random()}`,
            quantity: 1,
            seatNumber: activeSeat,
            fired: false,
            modifiers: [],
            course: 'Entree', 
            color: 'bg-white'
        };
        const updatedItems = [...orderItems, newItem];
        updateOrderItems(updatedItems);
    };

    const handleUpdateItem = (updated: DiningOrderItem) => {
        const updatedItems = orderItems.map(i => i.cartId === updated.cartId ? updated : i);
        updateOrderItems(updatedItems);
    };

    const handleFire = () => {
        // 1. Identify unfired items
        const unfiredItems = orderItems.filter(i => !i.fired && !i.isVoided);

        if (unfiredItems.length > 0 && onFireToKitchen && activeTable) {
            // 2. Construct Kitchen Ticket
            const ticket: KitchenTicket = {
                id: `TKT-${Date.now()}`,
                orderId: activeTable.orderId || `ORD-${Date.now()}`, // Use generated 10-char ID
                type: 'Dine-in',
                status: 'Pending',
                timeIn: new Date().toISOString(),
                table: `Table ${activeTable.name}`,
                server: currentUser.name,
                serverEmployeeId: currentUser.id,
                items: unfiredItems.map(i => {
                    const guest = guests.find(g => g.id === i.seatNumber);
                    const guestName = i.seatNumber === 0 ? 'Shared' : (guest?.name || `Guest ${i.seatNumber}`);

                    return {
                        name: i.name,
                        qty: i.quantity,
                        modifiers: i.modifiers || [],
                        seatNumber: i.seatNumber,
                        guestName: guestName,
                        printerLabels: i.printerLabels
                    };
                })
            };

            // 3. Send to App state
            onFireToKitchen(ticket);
        }

        // 4. Mark local items as fired
        const updatedItems = orderItems.map(i => ({ ...i, fired: true }));
        updateOrderItems(updatedItems);
    };

    const handleCloseCheck = (paymentMethod: string) => {
        // 1. Process Sale (Save to Orders History)
        if (onProcessSale && activeTable) {
            const subtotal = orderItems.reduce((acc, i) => i.isVoided ? acc : acc + (i.price * i.quantity), 0);
            const tax = subtotal * 0.0825;
            const total = subtotal + tax;

            onProcessSale(orderItems, total, paymentMethod, activeTable.orderId);
        }

        // 2. Clear Table Status in Global State
        const updated = { 
            ...activeTable!, 
            status: 'Available' as const, 
            assignedToName: undefined, 
            timeSeated: undefined, 
            orderId: undefined 
        };
        onUpdateTableStatus(updated);

        // Clear Persistence via Prop
        if (activeTableId) {
            onUpdateTableOrder(activeTableId, undefined);
        }

        setActiveTableId(null);
        setActiveCustomer(null);
        setShowPayment(false);
    };

    const subtotal = orderItems.reduce((acc, i) => i.isVoided ? acc : acc + (i.price * i.quantity), 0);
    const tax = subtotal * 0.0825;
    const total = subtotal + tax;

    const filteredMenu = inventory.filter(i => 
        (activeCategory === 'All' || i.category === activeCategory) &&
        i.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Sections derived from current tables
    const floorSections = Array.from(new Set(tables.map(t => t.section))).sort();

    const renderCategories = () => {
        const cats = ['All', ...categories.map(c => c.name)];
        return cats.map(cat => (
            <button 
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`
                    font-bold text-xs uppercase tracking-widest transition-all
                    ${categoryLayout === 'TOP' 
                        ? `px-6 py-2 rounded-full whitespace-nowrap ${activeCategory === cat ? 'bg-indigo-600 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-200'}`
                        : `w-full text-left px-4 py-4 border-b border-slate-100 last:border-0 ${activeCategory === cat ? 'bg-white border-l-4 border-l-indigo-600 text-indigo-700 shadow-sm' : 'text-slate-500 hover:bg-white/50 hover:text-slate-700'}`
                    }
                `}
            >
                {cat}
            </button>
        ));
    };

    if (!activeTableId) {
        return (
            <div className="h-full flex flex-col bg-slate-100 animate-fade-in relative">
                {/* Header */}
                <div className="bg-white p-4 border-b border-slate-200 flex justify-between items-center shadow-sm z-20">
                    <div>
                        <h2 className="text-xl font-bold text-slate-800">Dining Floor</h2>
                        <p className="text-xs text-slate-500 font-medium">Logged in as {currentUser.name}</p>
                    </div>
                    <div className="flex gap-2">
                        {floorSections.map(sec => (
                            <button 
                                key={sec} 
                                onClick={() => setActiveSection(sec)} 
                                className={`px-4 py-2 rounded-full text-xs font-bold transition-all ${activeSection === sec ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                            >
                                {sec}
                            </button>
                        ))}
                    </div>
                    <button onClick={onExit} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X size={24} className="text-slate-500 hover:text-slate-800"/></button>
                </div>

                {/* Canvas Area */}
                <div 
                    ref={canvasRef} 
                    className="flex-1 relative overflow-hidden bg-slate-200/50 cursor-grab active:cursor-grabbing"
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                >
                    <div style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${scale})`, transformOrigin: '0 0', width: '100%', height: '100%' }}>
                        {tables.filter(t => t.section === activeSection).map(table => {
                            // Find active ticket for this table
                            let kitchenStatus = null;
                            if (kitchenTickets) {
                                // Find tickets for this table that aren't delivered
                                const tableTicket = kitchenTickets.find(ticket => 
                                    ticket.table === `Table ${table.name}` && 
                                    ticket.status !== 'Delivered'
                                );

                                if (tableTicket) {
                                    // Calculate queue position if pending
                                    let queuePosition = 0;
                                    if (tableTicket.status === 'Pending') {
                                        // Count pending tickets created before this one
                                        queuePosition = kitchenTickets.filter(t => 
                                            t.status === 'Pending' && 
                                            // Simple timestamp check assuming ISO strings sort correctly
                                            t.timeIn < tableTicket.timeIn
                                        ).length + 1;
                                    }

                                    kitchenStatus = {
                                        status: tableTicket.status,
                                        queuePosition: queuePosition,
                                        ticketId: tableTicket.id
                                    };
                                }
                            }

                            return (
                                <InteractiveTable 
                                    key={table.id}
                                    table={table}
                                    onClick={(e, t) => handleTableClick(e, t)}
                                    isEditing={false}
                                    isSelected={false}
                                    kitchenStatus={kitchenStatus}
                                />
                            );
                        })}
                    </div>
                </div>

                {/* Zoom Controls */}
                <div className="absolute bottom-6 right-6 z-20 flex flex-col bg-white border border-slate-200 rounded-lg shadow-lg">
                    <button onClick={() => setScale(s => Math.min(s + 0.1, 3))} className="p-3 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><ZoomIn size={20} /></button>
                    <button onClick={() => { setScale(1); setPan({x:0, y:0}); }} className="p-3 text-slate-600 hover:bg-slate-50 border-b border-slate-100"><Maximize size={20} /></button>
                    <button onClick={() => setScale(s => Math.max(s - 0.1, 0.5))} className="p-3 text-slate-600 hover:bg-slate-50"><ZoomOut size={20} /></button>
                </div>
            </div>
        );
    }

    return (
        <div className="flex h-full bg-slate-100 animate-fade-in">
            {editingItem && <TableItemModal item={editingItem} onClose={() => setEditingItem(null)} onSave={handleUpdateItem} seatId={editingItem.seatNumber} />}

            {showCustomerSearch && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm">
                    <div className="bg-white w-full max-w-md rounded-2xl shadow-xl p-6">
                        <div className="flex justify-between mb-4">
                            <h3 className="font-bold text-lg">Assign Customer</h3>
                            <button onClick={() => setShowCustomerSearch(false)}><X size={20} /></button>
                        </div>
                        <div className="space-y-2 max-h-80 overflow-y-auto">
                            {MOCK_CUSTOMERS.map(c => (
                                <button key={c.id} onClick={() => { setActiveCustomer(c.name); setShowCustomerSearch(false); }} className="w-full text-left p-3 hover:bg-slate-50 rounded-lg font-medium text-slate-700">
                                    {c.name}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* Left: Table Order Invoice Section */}
            <div className="w-[450px] bg-white border-r border-slate-200 flex flex-col shadow-xl z-20 shrink-0">
                {/* Header */}
                <div className="p-4 border-b border-slate-200 bg-slate-50">
                    <div className="flex items-center gap-2 mb-2">
                        <button onClick={() => setActiveTableId(null)} className="p-2 hover:bg-slate-200 rounded-full text-slate-500 transition-colors">
                            <ArrowLeft size={20} />
                        </button>
                        <div>
                            <h2 className="text-2xl font-black text-slate-800">Table {activeTable?.name}</h2>
                            <p className="text-xs text-slate-400 font-mono">Order ID: {activeTable?.orderId || 'PENDING'}</p>
                        </div>
                    </div>
                    <div className="flex justify-end">
                        <div className="text-right">
                            <span className="block text-xs font-bold text-slate-400 uppercase tracking-widest">Server</span>
                            <span className="font-bold text-slate-700">{activeTable?.assignedToName}</span>
                        </div>
                    </div>
                    {/* Seat Tabs */}
                    <div className="flex gap-2 overflow-x-auto pb-1 mt-2 no-scrollbar">
                        <button onClick={() => setActiveSeat(0)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase whitespace-nowrap transition-colors ${activeSeat === 0 ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>Shared</button>
                        {guests.map(g => (
                            <button key={g.id} onClick={() => setActiveSeat(g.id)} className={`px-4 py-2 rounded-lg text-xs font-black uppercase whitespace-nowrap transition-colors ${activeSeat === g.id ? 'bg-indigo-600 text-white' : 'bg-white border border-slate-200 text-slate-600'}`}>Guest {g.id}</button>
                        ))}
                        <button onClick={() => updateGuests([...guests, { id: guests.length + 1 }])} className="p-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300"><Plus size={14} /></button>
                    </div>
                </div>

                {/* Order List */}
                <div className="flex-1 overflow-y-auto p-4 space-y-6">
                    {/* Render Shared Items */}
                    {orderItems.filter(i => i.seatNumber === 0).length > 0 && (
                        <div>
                            <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 pl-1">Shared Items</div>
                            <div className="space-y-2">
                                {orderItems.filter(i => i.seatNumber === 0).map(item => (
                                    <OrderItemRow key={item.cartId} item={item} onClick={() => setEditingItem(item)} />
                                ))}
                            </div>
                        </div>
                    )}
                    {/* Render Guests */}
                    {guests.map(g => {
                        const items = orderItems.filter(i => i.seatNumber === g.id);
                        if (items.length === 0 && activeSeat !== g.id) return null;
                        return (
                            <div key={g.id} className={`rounded-xl p-3 border-2 transition-all ${activeSeat === g.id ? 'border-indigo-100 bg-indigo-50/30' : 'border-transparent'}`}>
                                <div className="flex justify-between items-center mb-2">
                                    <span className="text-xs font-black text-indigo-900 uppercase tracking-widest">Guest {g.id}</span>
                                    <span className="text-xs font-bold text-slate-500">${items.reduce((a,b) => a + (b.isVoided ? 0 : b.price * b.quantity), 0).toFixed(2)}</span>
                                </div>
                                <div className="space-y-2">
                                    {items.map(item => (
                                        <OrderItemRow key={item.cartId} item={item} onClick={() => setEditingItem(item)} />
                                    ))}
                                    {items.length === 0 && <div className="text-xs text-slate-400 italic text-center py-2">No items</div>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Footer Actions */}
                <div className="bg-white border-t border-slate-200 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                    <div className="flex justify-between items-end mb-4">
                        <div className="text-xs font-medium text-slate-500 space-y-1">
                            <div className="flex justify-between w-32"><span>Subtotal</span><span>${subtotal.toFixed(2)}</span></div>
                            <div className="flex justify-between w-32"><span>Tax</span><span>${tax.toFixed(2)}</span></div>
                        </div>
                        <div className="text-right">
                            <span className="block text-xs font-black text-slate-400 uppercase tracking-widest">Total Due</span>
                            <span className="text-3xl font-black text-slate-900">${total.toFixed(2)}</span>
                        </div>
                    </div>
                    <div className="grid grid-cols-4 gap-2">
                        <button onClick={() => alert("Split Check")} className="flex flex-col items-center justify-center p-2 rounded-lg bg-slate-50 hover:bg-slate-100 text-slate-600 border border-slate-200">
                            <SplitSquareHorizontal size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Split</span>
                        </button>
                        <button onClick={() => alert("Discount")} className="flex flex-col items-center justify-center p-2 rounded-lg bg-slate-50 hover:bg-slate-100 text-slate-600 border border-slate-200">
                            <Tag size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Disc</span>
                        </button>
                        <button onClick={handleFire} className="flex flex-col items-center justify-center p-2 rounded-lg bg-orange-50 hover:bg-orange-100 text-orange-600 border border-orange-200">
                            <Flame size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Fire</span>
                        </button>
                        <button onClick={() => setShowPayment(true)} className="flex flex-col items-center justify-center p-2 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white shadow-md">
                            <CreditCard size={18} className="mb-1" />
                            <span className="text-[9px] font-bold uppercase">Pay</span>
                        </button>
                    </div>
                </div>
            </div>

            {/* Right: Menu */}
            <div className="flex-1 flex flex-col bg-slate-100 overflow-hidden">
                <div className="p-4 bg-white border-b border-slate-200 flex gap-4 items-center shrink-0 shadow-sm z-10">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input type="text" placeholder="Search menu items..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
                    </div>
                    <button 
                        onClick={() => setCategoryLayout(prev => prev === 'TOP' ? 'SIDE' : 'TOP')}
                        className="p-2.5 bg-slate-100 text-slate-600 hover:bg-indigo-50 hover:text-indigo-600 rounded-lg transition-colors border border-slate-200"
                        title="Toggle Category Layout"
