            {!isEditing && table.assignedToName && (
                <div 
                    className="absolute -top-10 bg-white/95 backdrop-blur-sm px-3 py-1.5 rounded-full shadow-lg text-xs font-bold text-slate-800 border border-slate-200 whitespace-nowrap z-50 flex items-center gap-1 animate-fade-in-up"
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    <User size={10} className="text-indigo-500" />
                    {table.assignedToName}
                </div>
            )}

            {renderVectorContent()}

            {/* Timer Ring */}
            {table.status !== 'Available' && table.isSeatable && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <svg className="w-2/3 h-2/3 transform -rotate-90" viewBox="0 0 100 100">
                        <circle cx="50" cy="50" r={radius} stroke="#e2e8f0" strokeWidth="6" fill="transparent" opacity="0.8" />
                        <circle cx="50" cy="50" r={radius} stroke={ringColor} strokeWidth="6" fill="transparent"
                            strokeDasharray={circumference} strokeDashoffset={strokeDashoffset} strokeLinecap="round"
                            className="transition-all duration-1000 ease-linear drop-shadow-sm"
                        />
                    </svg>
                </div>
            )}

            {/* Labels and Internal Status */}
            {table.isSeatable && (
                <div className="absolute inset-0 flex flex-col items-center justify-center z-10 pointer-events-none">
                    <span className={`font-black text-lg leading-none ${labelColor} drop-shadow-sm`} style={{ transform: `rotate(-${table.rotation || 0}deg)` }}>
                        {table.name}
                    </span>
                    {!isEditing && (
                        <div style={{ transform: `rotate(-${table.rotation || 0}deg)` }} className="mt-1 flex flex-col items-center gap-1">
                            <span className="text-[9px] text-slate-600 font-bold bg-white/90 px-1.5 py-0.5 rounded-full flex items-center gap-0.5 shadow-sm backdrop-blur-sm border border-slate-100">
                                {table.status === 'Available' ? <><User size={8} />{table.seats}</> : <><Clock size={8} /> {elapsedMinutes}m</>}
                            </span>
                            {/* Kitchen Status inside the label container, under the timer */}
                            {kitchenStatus && (
                                <span className={`text-[8px] font-black px-1.5 py-0.5 rounded-full flex items-center gap-1 shadow-sm backdrop-blur-sm border uppercase tracking-wider
                                    ${kitchenStatus.status === 'Pending' ? 'bg-amber-100 text-amber-700 border-amber-200' :
                                      kitchenStatus.status === 'Prep' ? 'bg-indigo-100 text-indigo-700 border-indigo-200' :
                                      kitchenStatus.status === 'Ready' ? 'bg-emerald-500 text-white border-emerald-600' : ''}
                                `}>
                                    {kitchenStatus.status === 'Pending' && <><Hourglass size={8} /> Q#{kitchenStatus.queuePosition}</>}
                                    {kitchenStatus.status === 'Prep' && <><ChefHat size={8} /> PREP</>}
                                    {kitchenStatus.status === 'Ready' && <><Check size={8} /> READY</>}
                                </span>
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Editing Handles */}
            {isEditing && isSelected && (
                <>
                    <div 
                        onMouseDown={(e) => { e.stopPropagation(); onClick(e, table, true); }}
                        className="absolute -bottom-3 -right-3 w-6 h-6 bg-white border-2 border-indigo-600 rounded-full cursor-nwse-resize z-50 flex items-center justify-center shadow-lg hover:scale-110 transition-transform"
                    >
                        <MoveDiagonal size={12} className="text-indigo-600" />
                    </div>
                </>
            )}

            {/* Hover Tooltip */}
            {isHovered && !isEditing && table.isSeatable && table.status !== 'Available' && (
                <div 
                    className="absolute top-full mt-4 bg-slate-900/95 backdrop-blur text-white text-xs p-3 rounded-xl shadow-xl w-40 z-50 pointer-events-none animate-fade-in border border-white/10"
                    style={{ transform: `rotate(-${table.rotation || 0}deg)` }}
                >
                    <p className="font-bold text-sm mb-1 text-white">{table.assignedToName || 'Guest'}</p>
                    <div className="space-y-1.5 opacity-90">
                        <p className="flex justify-between border-b border-white/10 pb-1"><span>Size:</span> <span className="font-mono">{table.seats} ppl</span></p>
                        <p className="flex justify-between"><span>Seated:</span> <span className="font-mono">{table.timeSeated ? new Date(table.timeSeated).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--'}</span></p>
                    </div>
                    {elapsedMinutes > expected && (
                        <div className="bg-red-500/20 text-red-200 px-2 py-1 rounded-lg mt-2 font-bold flex items-center gap-2 border border-red-500/30 text-[10px] uppercase tracking-wide">
                            <AlertCircle size={12} /> Overdue
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default InteractiveTable;

import React, { useState, useEffect } from 'react';
import { DiningTable } from '../types';
import { User, Clock, AlertCircle, MoveDiagonal, Check, RotateCw, ChefHat, Hourglass } from 'lucide-react';

interface KitchenStatus {
    status: 'Pending' | 'Prep' | 'Ready' | 'Delivered';
    queuePosition?: number;
    ticketId?: string;
}

interface InteractiveTableProps {
    table: DiningTable;
    onClick: (e: React.MouseEvent, table: DiningTable, isResizeHandle: boolean) => void;
    isEditing?: boolean;
    isSelected?: boolean;
    kitchenStatus?: KitchenStatus | null;
}

const InteractiveTable: React.FC<InteractiveTableProps> = ({ table, onClick, isEditing, isSelected, kitchenStatus }) => {
    const [elapsedMinutes, setElapsedMinutes] = useState(0);
    const [isHovered, setIsHovered] = useState(false);

    useEffect(() => {
        if (table.status !== 'Available' && table.timeSeated) {
            const calculateTime = () => {
                const seatedTime = new Date(table.timeSeated!).getTime();
                const now = new Date().getTime();
                const diffMins = Math.floor((now - seatedTime) / 60000);
                setElapsedMinutes(Math.max(0, diffMins));
            };

            calculateTime();
            const interval = setInterval(calculateTime, 60000);
            return () => clearInterval(interval);
        } else {
            setElapsedMinutes(0);
        }
    }, [table.status, table.timeSeated]);

    const expected = table.expectedDuration || 60;
    const progress = Math.min(100, (elapsedMinutes / expected) * 100);
    const radius = 24; 
    const circumference = 2 * Math.PI * radius;
    const strokeDashoffset = circumference - (progress / 100) * circumference;

    // --- VISUAL LOGIC ---
    let tableFill = 'fill-amber-100'; // Wood-like base
    let tableStroke = 'stroke-amber-800';
    let tableShadow = 'drop-shadow-md';
    let chairFill = 'fill-slate-700';
    let chairStroke = 'stroke-slate-900';
    let ringColor = '#cbd5e1'; 
    let labelColor = 'text-slate-700';

    // Status Overrides
    if (table.isSeatable) {
        if (table.highlight) {
            tableFill = 'fill-yellow-100';
            tableStroke = 'stroke-yellow-600';
        } else if (table.status === 'Available') {
            tableFill = 'fill-white';
            tableStroke = 'stroke-slate-300';
            chairFill = 'fill-slate-600';
            chairStroke = 'stroke-slate-700';
            labelColor = 'text-slate-500';
        } else if (table.status === 'Occupied') {
            tableFill = 'fill-blue-50';
            tableStroke = 'stroke-blue-400';
            chairFill = 'fill-blue-600';
            chairStroke = 'stroke-blue-800';
            labelColor = 'text-blue-800';
            ringColor = '#3b82f6';
        } else if (table.status === 'Overdue' || (elapsedMinutes > expected)) {
            tableFill = 'fill-red-50';
            tableStroke = 'stroke-red-400';
            chairFill = 'fill-red-600';
            chairStroke = 'stroke-red-800';
            labelColor = 'text-red-800';
            ringColor = '#ef4444';
        } else if (table.status === 'Dirty') {
            tableFill = 'fill-orange-50';
            tableStroke = 'stroke-orange-400';
            labelColor = 'text-orange-800';
        } else if (table.status === 'Payment') {
            tableFill = 'fill-emerald-50';
            tableStroke = 'stroke-emerald-400';
            labelColor = 'text-emerald-800';
        }
    }

    const renderChairs = () => {
        if (!table.isSeatable || table.seats === 0) return null;

        const chairs = [];
        const seatW = 28; 
        const seatH = 24; 
        const backD = 6;  

        if (table.type === 'TABLE_ROUND') {
            const r = 48; 
            const offset = 18; 

            for (let i = 0; i < table.seats; i++) {
                const angle = (i / table.seats) * 2 * Math.PI;
                const degrees = (angle * 180) / Math.PI;
                const cx = 50 + (r + offset) * Math.cos(angle); 
                const cy = 50 + (r + offset) * Math.sin(angle);

                chairs.push(
                    <g key={i} transform={`translate(${cx}, ${cy}) rotate(${degrees + 90})`}>
                        <rect x={-seatW/2 + 3} y={-seatH/2 + 3} width={seatW} height={seatH} rx="6" fill="black" opacity="0.15" />
                        <rect x={-seatW/2} y={-seatH/2} width={seatW} height={seatH} rx="6" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                        <path d={`M ${-seatW/2} ${seatH/2} Q 0 ${seatH/2 + 8} ${seatW/2} ${seatH/2}`} fill="none" stroke={chairStroke.replace('stroke-', '#')} strokeWidth="2.5" />
                        <rect x={-seatW/2} y={seatH/2 + 2} width={seatW} height={backD} rx="3" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                    </g>
                );
            }
        } else {
            const perSide = Math.ceil(table.seats / 2);
            for(let i=0; i<table.seats; i++) {
                const side = i % 2; 
                const idxInSide = Math.floor(i / 2);
                const availableSpace = 100;
                const step = availableSpace / perSide;
                const x = (step * idxInSide) + (step / 2);
                const y = side === 0 ? -20 : 120; 
                const rot = side === 0 ? 180 : 0;

                chairs.push(
                    <g key={i} transform={`translate(${x}, ${y}) rotate(${rot})`}>
                        <rect x={-seatW/2 + 3} y={-seatH + 3} width={seatW} height={seatH} rx="6" fill="black" opacity="0.15" />
                        <rect x={-seatW/2} y={-seatH} width={seatW} height={seatH} rx="6" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                        <rect x={-seatW/2} y={2} width={seatW} height={backD} rx="3" className={`${chairFill} ${chairStroke}`} strokeWidth="1" />
                        <path d={`M ${-seatW/2} ${-seatH/2} L ${-seatW/2 - 4} ${-seatH/2} L ${-seatW/2 - 4} 4`} fill="none" stroke={chairStroke.replace('stroke-', '#')} strokeWidth="2" opacity="0.4"/>
                        <path d={`M ${seatW/2} ${-seatH/2} L ${seatW/2 + 4} ${-seatH/2} L ${seatW/2 + 4} 4`} fill="none" stroke={chairStroke.replace('stroke-', '#')} strokeWidth="2" opacity="0.4"/>
                    </g>
                );
            }
        }
        return chairs;
    };

    const renderVectorContent = () => {
        switch(table.type) {
            case 'TABLE_ROUND':
                return (
                    <svg viewBox="-50 -50 200 200" className="w-full h-full overflow-visible pointer-events-none">
                        {renderChairs()}
                        <circle cx="53" cy="53" r="48" fill="black" opacity="0.15" />
                        <circle cx="50" cy="50" r="48" className={`${tableFill} ${tableStroke} ${tableShadow}`} strokeWidth="2" />
                        <path d="M 20 30 Q 50 60 80 30" stroke="black" strokeWidth="0.5" opacity="0.05" fill="none"/>
                        <path d="M 15 50 Q 50 80 85 50" stroke="black" strokeWidth="0.5" opacity="0.05" fill="none"/>
                        <path d="M 25 70 Q 50 40 75 70" stroke="black" strokeWidth="0.5" opacity="0.05" fill="none"/>
                        <circle cx="50" cy="50" r="8" fill="black" opacity="0.05" />
                    </svg>
                );
            case 'TABLE_SQUARE':
            case 'TABLE_RECT':
                return (
                    <svg viewBox="-40 -40 180 180" className="w-full h-full overflow-visible pointer-events-none">
                        {renderChairs()}
                        <rect x="5" y="5" width="96" height="96" rx="6" fill="black" opacity="0.15" />
                        <rect x="2" y="2" width="96" height="96" rx="6" className={`${tableFill} ${tableStroke} ${tableShadow}`} strokeWidth="2" />
                        <line x1="10" y1="20" x2="90" y2="20" stroke="black" strokeWidth="0.5" opacity="0.05" />
                        <line x1="5" y1="50" x2="95" y2="50" stroke="black" strokeWidth="0.5" opacity="0.05" />
                        <line x1="10" y1="80" x2="90" y2="80" stroke="black" strokeWidth="0.5" opacity="0.05" />
                        <rect x="40" y="2" width="20" height="96" fill="black" opacity="0.03" />
                    </svg>
                );
            case 'BOOTH_SINGLE':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none drop-shadow-md">
                        <path d="M5 20 Q5 5 20 5 L80 5 Q95 5 95 20 L95 90 Q95 95 90 95 L10 95 Q5 95 5 90 Z" fill="#64748b" stroke="#334155" strokeWidth="2" />
                        <path d="M15 15 L15 90" stroke="#475569" strokeWidth="1" />
                        <path d="M30 10 L30 90" stroke="#475569" strokeWidth="1" />
                        <path d="M50 10 L50 90" stroke="#475569" strokeWidth="1" />
                        <path d="M70 10 L70 90" stroke="#475569" strokeWidth="1" />
                        <path d="M85 15 L85 90" stroke="#475569" strokeWidth="1" />
                        <path d="M10 25 L90 25 L90 45 L10 45 Z" fill="#94a3b8" stroke="#475569" strokeWidth="1" />
                        <rect x="15" y="45" width="70" height="40" rx="4" className={`${tableFill} ${tableStroke}`} strokeWidth="2" />
                    </svg>
                );
            case 'BOOTH_DOUBLE':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none drop-shadow-md">
                        <rect x="15" y="35" width="70" height="30" rx="4" className={`${tableFill} ${tableStroke}`} strokeWidth="2" />
                        <rect x="5" y="5" width="90" height="25" rx="6" fill="#64748b" stroke="#334155" strokeWidth="2" />
                        <rect x="10" y="22" width="80" height="8" rx="4" fill="#94a3b8" />
                        <line x1="25" y1="5" x2="25" y2="22" stroke="#475569" strokeWidth="1" />
                        <line x1="50" y1="5" x2="50" y2="22" stroke="#475569" strokeWidth="1" />
                        <line x1="75" y1="5" x2="75" y2="22" stroke="#475569" strokeWidth="1" />
                        <rect x="5" y="70" width="90" height="25" rx="6" fill="#64748b" stroke="#334155" strokeWidth="2" />
                        <rect x="10" y="70" width="80" height="8" rx="4" fill="#94a3b8" />
                        <line x1="25" y1="78" x2="25" y2="95" stroke="#475569" strokeWidth="1" />
                        <line x1="50" y1="78" x2="50" y2="95" stroke="#475569" strokeWidth="1" />
                        <line x1="75" y1="78" x2="75" y2="95" stroke="#475569" strokeWidth="1" />
                    </svg>
                );
            case 'COUCH_STRAIGHT':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full pointer-events-none drop-shadow-md">
                        <rect x="5" y="20" width="90" height="60" rx="12" fill="#e2e8f0" stroke="#94a3b8" strokeWidth="2" />
                        <rect x="10" y="15" width="80" height="15" rx="6" fill="#cbd5e1" stroke="#94a3b8" strokeWidth="1" />
                        <line x1="50" y1="35" x2="50" y2="80" stroke="#cbd5e1" strokeWidth="1" />
                        <rect x="5" y="35" width="12" height="45" rx="6" fill="#cbd5e1" />
                        <rect x="83" y="35" width="12" height="45" rx="6" fill="#cbd5e1" />
                        {table.seats > 0 && <rect x="30" y="90" width="40" height="15" rx="4" className={`${tableFill} ${tableStroke}`} />}
                    </svg>
                );
            case 'PLANT_MONSTERA':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-lg pointer-events-none">
                        <circle cx="50" cy="50" r="15" fill="#3f2e18" /> 
                        <circle cx="50" cy="50" r="18" stroke="#78350f" strokeWidth="4" fill="none" /> 
                        {[0, 60, 120, 180, 240, 300].map(deg => (
                            <g key={deg} transform={`rotate(${deg} 50 50)`}>
                                <path d="M50 50 Q30 20 50 2 Q70 20 50 50" fill="#15803d" stroke="#14532d" strokeWidth="1" />
                                <path d="M50 50 Q35 25 50 10" fill="none" stroke="#22c55e" strokeWidth="1" opacity="0.4" />
                            </g>
                        ))}
                    </svg>
                );
            case 'PLANT_BANANA':
                return (
                    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-lg pointer-events-none">
                        <circle cx="50" cy="50" r="12" fill="#3f2e18" />
                        <circle cx="50" cy="50" r="14" stroke="#a8a29e" strokeWidth="3" fill="none" />
                        {[0, 120, 240].map(deg => (
                            <g key={deg} transform={`rotate(${deg} 50 50)`}>
                                <path d="M50 50 C20 50 10 10 50 0 C90 10 80 50 50 50" fill="#4d7c0f" stroke="#365314" strokeWidth="1" />
                                <line x1="50" y1="50" x2="50" y2="5" stroke="#65a30d" strokeWidth="1" />
                            </g>
                        ))}
                    </svg>
                );
            case 'DECOR_BILLIARDS':
                return (
                    <svg viewBox="0 0 200 100" className="w-full h-full drop-shadow-xl pointer-events-none">
                        <defs>
                            <linearGradient id="feltGrad" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="0%" stopColor="#166534" />
