                                </div>
                                <div className="space-y-2">
                                    {items.map(item => (
                                        <OrderItemRow key={item.cartId} item={item} onClick={() => setEditingItem(item)} />
                                    ))}
                                    {items.length === 0 && <div className="text-xs text-slate-400 italic text-center py-2">No items</div>}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* Footer Actions */}
                <div className="bg-white border-t border-slate-200 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
