import React, { useState } from 'react';
import { 
    DetailedOrder, Transaction, Customer, Employee, InventoryItem, 
    Table, Reservation, Schedule, Category, PaymentSplit, Receipt, 
    DiscountCode, DiningTable, KDSSettings, UserRole, CartItem, GlobalTaxConfig, TipConfig, KitchenTicket, Notification, DiningOrderItem
} from '../types';
import { LayoutGrid, Lock, ShieldAlert, Monitor, ChevronRight, Search, Settings, CreditCard, ShoppingBag, Box, ArrowRight, Bell, CheckCircle, X } from 'lucide-react';
import PosLauncher, { PosAppType } from './POS/PosLauncher';
import PosRegister from './POS/PosRegister';
import ReservationsApp from './ReservationsApp';
import SchedulingApp from './SchedulingApp';
import TableServiceApp from './TableServiceApp';
import KitchenDisplay from './KitchenDisplay';
import ExpeditorScreen from './POS/ExpeditorScreen';
import InventoryScanner from './POS/InventoryScanner';
import CashierCloseout from './POS/CashierCloseout';
import PasscodeLock from './PasscodeLock';

interface CashierPOSProps {
  onLogout: () => void;
  onProcessSale: (cart: CartItem[], total: number, paymentMethod: string, existingOrderId?: string) => void;
  currentUser: Employee;
  sharedOrders: DetailedOrder[];
  sharedTransactions: Transaction[];
  sharedCustomers: Customer[];
  sharedEmployees: Employee[];
  sharedInventory: InventoryItem[];
  sharedCategories: Category[];
  sharedDiscounts?: DiscountCode[];
  sharedTables: Table[];
  sharedReservations: Reservation[];
  sharedSchedules: Schedule[];
  onSeatReservation: (resId: string, tableId: string) => void;
  integrationConfig: { reservation_pos: boolean; scheduling_pos: boolean; kdsEnabled: boolean };
  floorPlanTables?: DiningTable[];
  kdsSettings?: KDSSettings;
  receiptSettings?: any;
  onFireToKitchen?: (ticket: KitchenTicket) => void;
  taxConfig?: GlobalTaxConfig;
  tipConfig?: TipConfig;
  onNavigate?: (tab: string) => void;
  notifications?: Notification[];
  onDismissNotification?: (id: string) => void;
  kitchenTickets?: KitchenTicket[];
  onKitchenStatusChange?: (id: string, status: KitchenTicket['status']) => void;

  // Persistent State Props
  activeTableOrders: Record<string, { items: DiningOrderItem[], guests: {id: number, name?: string}[] }>;
  onUpdateTableOrder: (tableId: string, data: { items: DiningOrderItem[], guests: {id: number, name?: string}[] } | undefined) => void;
  onUpdateTableStatus: (table: DiningTable) => void;
  activeRegisterCart: CartItem[];
  onUpdateRegisterCart: (cart: CartItem[]) => void;
  onAddCustomer?: (customer: Customer) => void;
}

const CashierPOS: React.FC<CashierPOSProps> = (props) => {
  const [currentApp, setCurrentApp] = useState<PosAppType>('LAUNCHER');
  const [authenticatedPosUser, setAuthenticatedPosUser] = useState<Employee | null>(null);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);

  if (!authenticatedPosUser) {
      return (
        <PasscodeLock 
            employees={props.sharedEmployees} 
            onAuthenticated={(user) => setAuthenticatedPosUser(user)}
            onCancel={props.onLogout}
        />
      );
  }

  const myNotifications = props.notifications?.filter(n => n.targetEmployeeId === authenticatedPosUser.id) || [];

  const searchResults = [
      { id: 'settings', label: 'Settings', sub: 'System Configuration', icon: Settings, action: () => props.onNavigate && props.onNavigate('Settings') },
      { id: 'inventory', label: 'Inventory', sub: 'Item Library', icon: Box, action: () => props.onNavigate && props.onNavigate('Item Library') },
      { id: 'orders', label: 'Orders', sub: 'Transaction History', icon: ShoppingBag, action: () => props.onNavigate && props.onNavigate('Orders') },
      { id: 'register', label: 'Register', sub: 'New Sale', icon: CreditCard, action: () => setCurrentApp('REGISTER') },
  ].filter(item => item.label.toLowerCase().includes(searchQuery.toLowerCase()) || item.sub.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="h-full flex flex-col overflow-hidden bg-slate-50 font-sans text-slate-900 relative">

        {/* User Notifications Overlay */}
        {myNotifications.length > 0 && (
            <div className="absolute top-24 right-8 z-[60] flex flex-col gap-2">
                {myNotifications.map(notif => (
                    <div key={notif.id} className="bg-white border-l-4 border-emerald-500 rounded-lg shadow-xl p-4 flex items-start gap-4 w-80 animate-fade-in-down">
                        <div className="bg-emerald-100 p-2 rounded-full text-emerald-600">
                            <CheckCircle size={20} />
                        </div>
                        <div className="flex-1">
                            <h4 className="font-bold text-slate-800 text-sm">Order Ready!</h4>
                            <p className="text-xs text-slate-600 mt-1">{notif.message}</p>
                            <p className="text-[10px] text-slate-400 mt-2">{new Date(notif.timestamp).toLocaleTimeString()}</p>
                        </div>
                        <button onClick={() => props.onDismissNotification && props.onDismissNotification(notif.id)} className="text-slate-400 hover:text-slate-600">
                            <X size={16} />
                        </button>
                    </div>
                ))}
            </div>
        )}

        <header className="h-20 bg-white text-slate-800 flex items-center justify-between px-8 shrink-0 shadow-sm z-30 border-b border-slate-200">
            <div className="flex items-center gap-6">
                <button onClick={() => setCurrentApp('LAUNCHER')} className="flex items-center gap-3 group">
                    <div className="h-10 w-10 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform">
                        <LayoutGrid size={20} className="text-white" />
                    </div>
                    <div className="text-left">
                        <p className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.2em] leading-none mb-1">Terminal Mode</p>
                        <h1 className="font-black text-xl tracking-tighter uppercase leading-none">Omni COMMAND</h1>
                    </div>
                </button>
                {currentApp !== 'LAUNCHER' && (
                    <div className="flex items-center gap-4 animate-fade-in">
                        <ChevronRight size={18} className="text-slate-300" />
                        <h2 className="font-black text-sm uppercase tracking-widest text-indigo-600 bg-indigo-50 px-3 py-1.5 rounded-xl border border-indigo-100">
                            {currentApp.replace('_', ' ')}
                        </h2>
                    </div>
                )}
            </div>

            {/* Global POS Search */}
            <div className="flex-1 max-w-lg mx-auto relative z-50 hidden lg:block">
                <div className="relative group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors" size={20} />
                    <input 
                        type="text" 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        onFocus={() => setIsSearchFocused(true)}
                        onBlur={() => setTimeout(() => setIsSearchFocused(false), 200)}
                        placeholder="Search settings, apps, or commands..." 
                        className="w-full pl-12 pr-16 py-3 bg-slate-100 border border-transparent rounded-2xl focus:bg-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all font-medium text-sm text-slate-700 placeholder:text-slate-400 shadow-inner focus:shadow-lg"
                    />
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 flex gap-1 pointer-events-none">
                        <span className="bg-white border border-slate-200 rounded px-1.5 py-0.5 text-[10px] font-bold text-slate-400">⌘</span>
                        <span className="bg-white border border-slate-200 rounded px-1.5 py-0.5 text-[10px] font-bold text-slate-400">K</span>
                    </div>
                </div>

                {/* Search Dropdown */}
                {isSearchFocused && searchQuery && (
                    <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden animate-fade-in-up">
                        <div className="p-2">
                            {searchResults.length > 0 ? searchResults.map((result) => (
                                <button
                                    key={result.id}
                                    onClick={() => {
                                        result.action();
                                        setSearchQuery('');
                                    }}
                                    className="w-full flex items-center justify-between p-3 hover:bg-slate-50 rounded-xl transition-colors group"
                                >
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-slate-100 text-slate-500 rounded-lg group-hover:bg-indigo-100 group-hover:text-indigo-600 transition-colors">
                                            <result.icon size={18} />
                                        </div>
                                        <div className="text-left">
                                            <p className="font-bold text-slate-800 text-sm group-hover:text-indigo-700">{result.label}</p>
                                            <p className="text-xs text-slate-400 font-medium">{result.sub}</p>
                                        </div>
                                    </div>
                                    <ArrowRight size={16} className="text-slate-300 group-hover:text-indigo-400 -translate-x-2 group-hover:translate-x-0 transition-all opacity-0 group-hover:opacity-100" />
                                </button>
                            )) : (
                                <div className="p-4 text-center text-slate-400 text-sm italic">
                                    No results found for "{searchQuery}"
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>

            <div className="flex items-center gap-6">
                <div className="flex items-center gap-3 bg-slate-50 px-5 py-2.5 rounded-2xl border border-slate-100">
                    <div className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
                    <div className="text-left leading-none">
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Authenticated</p>
                        <p className="text-xs font-black uppercase text-slate-700">{authenticatedPosUser.name}</p>
                    </div>
                </div>
                <div className="relative">
                    <button className="p-3 hover:bg-slate-100 rounded-2xl text-slate-400 hover:text-indigo-600 transition-colors">
                        <Bell size={20} />
                        {myNotifications.length > 0 && <span className="absolute top-2 right-2 h-2.5 w-2.5 bg-red-500 rounded-full border-2 border-white" />}
                    </button>
                </div>
                <button onClick={() => setAuthenticatedPosUser(null)} className="p-3 hover:bg-slate-100 rounded-2xl text-slate-400 hover:text-indigo-600 transition-colors" title="Lock Terminal">
                    <Lock size={20} />
                </button>
            </div>
        </header>

        <main className="flex-1 overflow-hidden flex flex-col relative">
            {currentApp === 'LAUNCHER' && (
                <PosLauncher user={authenticatedPosUser} onAppSelect={setCurrentApp} />
            )}
            {currentApp === 'REGISTER' && (
                <PosRegister 
                    inventory={props.sharedInventory} 
                    categories={props.sharedCategories} 
                    discounts={props.sharedDiscounts || []} 
                    activeCart={props.activeRegisterCart}
                    onUpdateCart={props.onUpdateRegisterCart}
                    onFinish={(cart, total, payments) => {
                        props.onProcessSale(cart, total, payments[0]?.method || 'Card');
                        props.onUpdateRegisterCart([]); // Clear persistent cart on successful sale
                        setCurrentApp('LAUNCHER');
                    }}
                    currentUser={authenticatedPosUser}
                    taxConfig={props.taxConfig}
                    tipConfig={props.tipConfig}
                    onFireToKitchen={(ticket) => props.onFireToKitchen && props.onFireToKitchen({...ticket, serverEmployeeId: authenticatedPosUser.id})}
                    onAddCustomer={props.onAddCustomer}
                />
            )}
            {currentApp === 'TABLE_SERVICE' && (
                <TableServiceApp 
                    tables={props.floorPlanTables || []}
                    inventory={props.sharedInventory}
                    categories={props.sharedCategories}
                    currentUser={authenticatedPosUser}
                    activeTableOrders={props.activeTableOrders}
                    onUpdateTableOrder={props.onUpdateTableOrder}
                    onUpdateTableStatus={props.onUpdateTableStatus}
                    onExit={() => setCurrentApp('LAUNCHER')}
                    onFireToKitchen={(ticket) => props.onFireToKitchen && props.onFireToKitchen(ticket)}
                    onProcessSale={props.onProcessSale}
                    kitchenTickets={props.kitchenTickets}
                />
            )}
            {currentApp === 'KITCHEN' && (
                <KitchenDisplay 
                    settings={props.kdsSettings} 
                    liveTickets={props.kitchenTickets}
                    onUpdateStatus={props.onKitchenStatusChange}
                />
            )}
            {currentApp === 'EXPEDITOR' && (
                <ExpeditorScreen 
                    tickets={props.kitchenTickets}
                    onUpdateStatus={props.onKitchenStatusChange}
                />
            )}
            {currentApp === 'INVENTORY_SCANNER' && <InventoryScanner items={props.sharedInventory} />}
            {currentApp === 'CLOSEOUT' && <CashierCloseout />}
            {currentApp === 'RESERVATIONS' && (
                <ReservationsApp 
                    reservations={props.sharedReservations} 
                    tables={[]} 
                    floorPlanTables={props.floorPlanTables || []}
                    onSeatReservation={props.onSeatReservation} 
                    isConnectedToPos={props.integrationConfig.reservation_pos} 
                />
            )}
            {currentApp === 'SCHEDULING' && <SchedulingApp schedules={props.sharedSchedules} />}
        </main>
    </div>
  );
};

