        const newLog = { 
            msg: `Adjusted ${scannedItem.name} stock level.`, 
            time: new Date().toLocaleTimeString() 
        };
        setLog([newLog, ...log]);

        // Actually update item (assuming we just log it for now as quantity isn't strictly tracked in InventoryItem interface yet, but let's pretend we update state)
        if (onUpdateItem) {
            onUpdateItem({ ...scannedItem }); // Trigger update in parent
        }

        setScannedItem(null);
        setAdjustValue('');
