interface RegisterProps {
    inventory: InventoryItem[];
    categories: Category[];
    discounts: DiscountCode[];
    activeCart: CartItem[]; // Prop for persistence
    onUpdateCart: (cart: CartItem[]) => void; // Update prop
    onFinish: (cart: CartItem[], total: number, payments: PaymentSplit[]) => void;
